  CREATE OR REPLACE FUNCTION "DBO"."F_CONVERT_TO_SCRAP" (p_sheet_skid_num IN sheet_skid.sheet_skid_num%TYPE)
  RETURN INTEGER IS

  RESULT INTEGER := 1;

  CURSOR cur_ss IS
    SELECT * FROM sheet_skid ss WHERE ss.sheet_skid_num = p_sheet_skid_num;

  CURSOR cur_pps IS
    SELECT *
      FROM process_partial_skid pps
     WHERE pps.sheet_skid_num = p_sheet_skid_num;

  CURSOR cur_ssd IS
    SELECT *
      FROM sheet_skid_detail ssd
     WHERE ssd.sheet_skid_num = p_sheet_skid_num;

  CURSOR cur_psi IS
    SELECT psi.*
      FROM production_sheet_item psi, sheet_skid_detail ssd
     WHERE psi.prod_item_num = ssd.prod_item_num
       AND ssd.sheet_skid_num = p_sheet_skid_num;

  CURSOR cur_pin IS
    SELECT ssd.prod_item_num
      FROM sheet_skid_detail ssd
     WHERE sheet_skid_num = p_sheet_skid_num;

  li_scrap_skid_num	  INT;
  li_return_scrap_item_id INT;
  li_customer_id	  INT;
  ls_alloy2		  VARCHAR2(8);
  ls_temper		  VARCHAR2(8);
  ls_customer_po	  customer_order.orig_customer_po%TYPE;
  li_ab_job		  INT;
  li_net_wt		  INT;
  li_tare_wt		  INT;

  t INT := 0;
BEGIN
  SELECT scrap_skid_num_seq.nextval INTO li_scrap_skid_num FROM dual;

  --create new scrap skid
  SELECT co.orig_customer_id, co.orig_customer_po
    INTO li_customer_id, ls_customer_po
    FROM customer_order co, sheet_skid ss
   WHERE co.order_abc_num = ss.ref_order_abc_num
     AND ss.sheet_skid_num = p_sheet_skid_num;

  SELECT oi.alloy2, oi.temper, aj.ab_job_num
    INTO ls_alloy2, ls_temper, li_ab_job
    FROM order_item oi, ab_job aj, sheet_skid ss
   WHERE oi.order_item_num = aj.order_item_num
     AND oi.order_abc_num = aj.order_abc_num
     AND aj.ab_job_num = ss.ab_job_num
     AND ss.sheet_skid_num = p_sheet_skid_num;

  SELECT ss.sheet_net_wt, ss.sheet_tare_wt
    INTO li_net_wt, li_tare_wt
    FROM sheet_skid ss
   WHERE ss.sheet_skid_num = p_sheet_skid_num;

  INSERT INTO scrap_skid
    (scrap_skid_num,
     customer_id,
     scrap_type,
     scrap_temper,
     scrap_net_wt,
     scrap_tare_wt,
     scrap_cust_po,
     scrap_ab_job_num,
     scrap_date,
     skid_scrap_status,
     scrap_notes,
     scrap_alloy2)
  VALUES
    (li_scrap_skid_num,
     li_customer_id,
     1,
     ls_temper,
     li_net_wt,
     li_tare_wt,
     ls_customer_po,
     li_ab_job,
     SYSDATE,
     2,
     'SK # ' || p_sheet_skid_num,
     ls_alloy2);
  --commit;

  --copy sheet_skid_num.* to scraped_sheet_skid_num
  FOR rec_ss IN cur_ss LOOP
    INSERT INTO scraped_sheet_skid
      (sheet_skid_num,
       ab_job_num,
       sheet_net_wt,
       sheet_tare_wt,
       skid_edi856_date,
       skid_location,
       skid_date,
       skid_sheet_status,
       skid_pieces,
       sheet_theoretical_wt,
       skid_from_if_whed,
       skid_ticket_if_whed,
       ref_order_abc_num,
       skid_type_if_whed,
       ref_order_abc_item,
       skid_sheet_status_held_by_qc,
       scrap_skid_num)
    VALUES
      (rec_ss.sheet_skid_num,
       rec_ss.ab_job_num,
       rec_ss.sheet_net_wt,
       rec_ss.sheet_tare_wt,
       rec_ss.skid_edi856_date,
       rec_ss.skid_location,
       rec_ss.skid_date,
       rec_ss.skid_sheet_status,
       rec_ss.skid_pieces,
       rec_ss.sheet_theoretical_wt,
       rec_ss.skid_from_if_whed,
       rec_ss.skid_ticket_if_whed,
       rec_ss.ref_order_abc_num,
       rec_ss.skid_type_if_whed,
       rec_ss.ref_order_abc_item,
       rec_ss.skid_sheet_status_held_by_qc,
       li_scrap_skid_num);
    --commit;
  END LOOP;

  --copy production_sheet_item.* to scraped_production_sheet_item.
  FOR rec_psi IN cur_psi LOOP
    INSERT INTO scraped_production_sheet_item
      (prod_item_num,
       coil_abc_num,
       ab_job_num,
       prod_item_status,
       prod_item_pieces,
       prod_item_net_wt,
       prod_item_theoretical_wt,
       prod_item_edi870_date,
       prod_item_date,
       prod_item_note,
       prod_item_placement,
       scrap_skid_num)
    VALUES
      (rec_psi.prod_item_num,
       rec_psi.coil_abc_num,
       rec_psi.ab_job_num,
       rec_psi.prod_item_status,
       rec_psi.prod_item_pieces,
       rec_psi.prod_item_net_wt,
       rec_psi.prod_item_theoretical_wt,
       rec_psi.prod_item_edi870_date,
       rec_psi.prod_item_date,
       rec_psi.prod_item_note,
       rec_psi.prod_item_placement,
       li_scrap_skid_num);

    SELECT return_scrap_item_id_seq.nextval
      INTO li_return_scrap_item_id
      FROM dual;

    INSERT INTO return_scrap_item
      (return_scrap_item_num,
       coil_abc_num,
       ab_job_num,
       return_item_net_wt,
       return_item_date)
    VALUES
      (li_return_scrap_item_id,
       rec_psi.coil_abc_num,
       rec_psi.ab_job_num,
       rec_psi.prod_item_net_wt,
       SYSDATE);
    INSERT INTO scrap_skid_detail
      (scrap_skid_num, return_scrap_item_num)
    VALUES
      (li_scrap_skid_num, li_return_scrap_item_id);
    --commit;
  END LOOP;

  --copy process_partial_skid.* to scraped_process_partial_skid.
  FOR rec_pps IN cur_pps LOOP
    INSERT INTO scraped_process_partial_skid
      (ab_job_num,
       sheet_skid_num,
       partial_skid_ab_job_num,
       partial_sheet_net_wt,
       partial_skid_location,
       partial_skid_date,
       partial_skid_pieces,
       partial_sheet_theoretical_wt,
       scrap_skid_num)
    VALUES
      (rec_pps.ab_job_num,
       rec_pps.sheet_skid_num,
       rec_pps.partial_skid_ab_job_num,
       rec_pps.partial_sheet_net_wt,
       rec_pps.partial_skid_location,
       rec_pps.partial_skid_date,
       rec_pps.partial_skid_pieces,
       rec_pps.partial_sheet_theoretical_wt,
       li_scrap_skid_num);
    --commit;
  END LOOP;

  --copy sheet_skid_detail.* to scraped_sheet_skid_detail.
  FOR rec_ssd IN cur_ssd LOOP
    INSERT INTO scraped_sheet_skid_detail
      (prod_item_num, sheet_skid_num, scrap_skid_num)
    VALUES
      (rec_ssd.prod_item_num, rec_ssd.sheet_skid_num, li_scrap_skid_num);
    --commit;
  END LOOP;

  --delete records from sheet skid tables.
  FOR rec_pin IN cur_pin LOOP
    DELETE FROM sheet_skid_detail
     WHERE prod_item_num = rec_pin.prod_item_num;

    DELETE FROM production_sheet_item
     WHERE prod_item_num = rec_pin.prod_item_num;
  END LOOP;
  --commit;

  DELETE FROM process_partial_skid WHERE sheet_skid_num = p_sheet_skid_num;
  --commit;

  DELETE FROM sheet_skid WHERE sheet_skid_num = p_sheet_skid_num;
  COMMIT;

  RETURN(RESULT);

EXCEPTION
  WHEN dup_val_on_index THEN
    ROLLBACK;
    RETURN - 100;
  WHEN OTHERS THEN
    ROLLBACK;
    RETURN - 1;

END f_convert_to_scrap;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_CREATE_EDI_861_BY_BOL" (par_bol in inbound_shipment.bol%type, par_edi_file_id in inbound_shipment.edi_file_id%type, par_received_time in varchar2) return integer is

  li_return integer :=1;
 /* Returns:   Integer
	       1 = if it succeeds
	      -1 = if system error occurs
	      -2 = if errors with UTL_FILE

 */
  li_gs_log INTEGER;
  li_st_log INTEGER;
  ls_today_short VARCHAR2(20) := to_char(SYSDATE, 'yymmdd');
  ls_today VARCHAR2(20) := to_char(SYSDATE, 'yyyymmdd');
  ls_now VARCHAR2(20) := to_char(SYSDATE, 'hh24mi');
  ls_received_time varchar2(13);
  ld_received_time date;

  type edi_861_tabletype is table of varchar2(32767) index by binary_integer;
  edi_861 edi_861_tabletype;
  j binary_integer := 0;
  i integer;
  coil_count integer :=0;
  li_customer_id integer;
  ls_po varchar2(20);
  ls_coil_number varchar2(40);
  ls_ps_coil_number varchar2(40);
  ls_temper varchar2(8);
  ln_net_weight number(8,0);
  ln_gross_weight number(8,0);
  ln_lineal_feed number(7,2);
  ln_coil_width number(7,2);
  ln_coil_gauge number(5,4);
  ln_density number;
  ls_lot varchar2(40);
  ls_pack_id varchar2(40);
  ls_alloy varchar2(40);
  ln_damage_fault number(1);
  ln_damage_code number(3);

  cursor bol_cursor is	   --this cursor collect all coils under the po# and edi_file_id.
  select a.coil_number, a.temper, a.net_weight, a.gross_weight, a.lineal_feed, a.coil_width, a.coil_gauge, a.density, a.lot, a.pack_id, a.alloy, a.ps_coil_number, b.damaged_code, b.damaged_fault
  from inbound_coil a, inbound_coil_status b
  where a.bol = par_bol and a.edi_file_id = par_edi_file_id and
	a.bol = b.bol and a.edi_file_id = b.edi_file_id and
	a.item_num = b.item_num;

  edi_location varchar2(50):='/templar/templar/incoming/senddata';
  edi_file varchar2 (50) := 'edi_out.txt';
  edi_file_handle UTL_FILE.FILE_TYPE;
  li_edi_861_id integer;
  ls_dun varchar2(32);	--duns# will be determined by ship_from customer.
  ls_ship_from varchar2(40);	--getting from inbound_shipment.

begin
  /*SELECT EDI_ST_LOG_SEQ.NEXTVAL INTO li_st_log FROM dual;
  SELECT EDI_GS_LOG_SEQ.NEXTVAL INTO li_gs_log FROM dual;

  select po into ls_po from inbound_shipment
  where bol = par_bol and edi_file_id = par_edi_file_id;

  --will be used in edi file at 'yyyymmddhrmi' format.
  ld_received_time := to_date(par_received_time, 'mm/dd/yyyy hh24:mi');--will be inserted into inbound_shipment table.
  --change it to "yyyymmdd*hr24mi" format.
  ls_received_time := substr(par_received_time, 7, 4)||substr(par_received_time, 1, 2)||substr(par_received_time, 4, 2)||'*'||substr(par_received_time, 12, 2)||substr(par_received_time, 15, 2);

  edi_861(j):= 'ISA*00* 	 *00*	       *01*039630926T	  *09*0015049350011G *'
  || ls_today_short ||'*'|| ls_now ||'*U*00200*'||LPAD(to_char(li_gs_log),9,'0')||'*0*P**'; j := j + 1;
  edi_861(j):= 'GS*RC*039630926T*0015049350011G*'|| ls_today ||'*'||ls_now||'*'||li_gs_log||'*X*004010'   ; j :=j + 1;
  edi_861(j):= 'ST*861*'||li_st_log ; j :=j + 1;
  edi_861(j):= 'BRA*'||par_bol||'*'||ls_today ||'*00*1*'||ls_now; j := j + 1;
  edi_861(j):= 'DTM*050*'||ls_received_time||'*ED'; j := j + 1;
  edi_861(j):= 'N1*OU**1*039630926'; j := j + 1;

  select ship_from into ls_ship_from from inbound_shipment
  where edi_file_id = par_edi_file_id and bol = par_bol;
  select customer_id into li_customer_id from inbound_shipment_customer
  where ship_from = ls_ship_from;
  if li_customer_id = 1153 then
     ls_dun := '241003755';--'Novelis Kingston'
  elsif  li_customer_id = 1459 then
     ls_dun := '003980216';--'Novelis Oswego'
  else
     ls_dun := '241003755';
  end if;

  edi_861(j):= 'N1*SU**1*'||ls_dun; j := j + 1;

  for cloop in bol_cursor loop	    --get coil's data.
      ls_coil_number := cloop.coil_number;
      ls_temper := cloop.temper;
      ln_net_weight := cloop.net_weight;
      ln_gross_weight := cloop.gross_weight;
      ln_lineal_feed := cloop.lineal_feed;
      ln_coil_width := cloop.coil_width;
      ln_coil_gauge := cloop.coil_gauge;
      ln_density := cloop.density;
      ls_lot := cloop.lot;
      ls_pack_id := cloop.pack_id;
      ls_alloy := cloop.alloy;
      ls_ps_coil_number := cloop.ps_coil_number;
      ln_damage_fault := cloop.damaged_fault;
      ln_damage_code := cloop.damaged_code;

      if (ls_ps_coil_number is null)then
	 ls_ps_coil_number := ls_coil_number;
      end if;

      edi_861(j):= 'RCD**1*CX'; j := j + 1;
      edi_861(j):= 'LIN**VO*'||ls_po||'*SN*'||ls_coil_number||'*HN*'||ls_lot||'*PK*'||ls_pack_id; j := j + 1;
      edi_861(j):= 'PID*S*MAC*ST*01'; j := j + 1;
      edi_861(j):= 'PID*S*MA*ST*7'; j := j + 1;

      --add these two segment only for damaged coils
      if ln_damage_code <> 0 then
	 edi_861(j):= 'PID*S*DAC*ST*'||ln_damage_code; j := j + 1;
      end if;
      if ln_damage_fault <> 0 then
      \* DAF??? *\
	 edi_861(j):= 'PID*S*DAF*ST*'||ln_damage_fault; j := j + 1;
      end if;

      edi_861(j):= 'PID*S*QAS*ST*2'; j := j + 1;
      edi_861(j):= 'REF*SE*'||ls_coil_number; j := j + 1;
      edi_861(j):= 'REF*BM*'||par_bol; j := j + 1;
      edi_861(j):= 'REF*RV*'||ls_ps_coil_number; j := j + 1;
      edi_861(j):= 'PRF*'||ls_po; j := j + 1;
      edi_861(j):= 'MEA*WT**'||ln_net_weight||'*01'; j := j + 1;
      edi_861(j):= 'MEA*WT**'||ln_gross_weight||'*24'; j := j + 1;
      edi_861(j):= 'MEA*PD*TH*'||to_char(ln_coil_gauge,'FM90.0000')||'*IN'; j := j + 1;
      edi_861(j):= 'MEA*PD*WD*'||to_char(ln_coil_width,'FM99990.0000')||'*IN'; j := j + 1;
      edi_861(j):= 'MEA*CT**'||ln_lineal_feed||'*LF'; j := j + 1;

      coil_count := coil_count + 1;
  end loop;

  edi_861(j):= 'CTT*'||coil_count; j := j + 1;
  edi_861(j):= 'SE*'||to_char(j-1)||'*'||li_st_log; j := j + 1;
  edi_861(j):= 'GE*1*'||li_gs_log; j := j + 1;
  edi_861(j):= 'IEA*1*'||LPAD(to_char(li_gs_log),9,'0');

  SELECT edi_file_id_seq.NEXTVAL INTO li_edi_861_id FROM DUAL;

  edi_file := 'S_alcan_'||to_char(li_edi_861_id)||'.861';
  edi_file_handle :=utl_file.fopen(edi_location,edi_file,'W');

  --write edi to file
  FOR i IN 0..j LOOP
    utl_file.put_line(edi_file_handle,edi_861(i));
  END LOOP;

  utl_file.fclose(edi_file_handle);

 \*--added by Victor Huang on 06/05 for funtion aknowlegement
  INSERT INTO edi_fa(gs_num, duns_num, send_time,edi_file_name)
  VALUES(li_gs_log, ls_dun, sysdate, edi_file);
  COMMIT;*\

  --added by Victor Huang on 12/07 for verifying 997
  INSERT INTO outbound_edi_transaction(edi_file_id,duns_from,duns_to,interchange_control_number,
  group_control_number,transaction_time,edi_file_name,fa_receive_status,customer_id,set_control_num,transaction_type_id)
  VALUES(li_edi_861_id,'039630926',ls_dun,li_gs_log,li_gs_log, sysdate, edi_file,0,li_customer_id,li_st_log,'861');
  COMMIT;

  edi_file := 'send_edi_log';
  edi_file_handle :=utl_file.fopen(edi_location,edi_file,'a');
  utl_file.put_line(edi_file_handle,'Type: 861');
  utl_file.put_line(edi_file_handle,'Sending Time: '||to_char(sysdate, 'MM/DD/YY HH24:MI'));
  utl_file.put_line(edi_file_handle,'Interchange Control #: '||li_gs_log);
  utl_file.put_line(edi_file_handle,'Group Control #: '||li_gs_log);
  utl_file.put_line(edi_file_handle,'Set Control #: '||li_st_log);
  utl_file.put_line(edi_file_handle,'');
  utl_file.put_line(edi_file_handle,'');
  utl_file.fclose(edi_file_handle);

  UPDATE "INBOUND_SHIPMENT_STATUS"
    SET "RECEIVED_TIME" = ld_received_time,
	"STATUS" = 1
	 where "BOL" = par_bol AND "EDI_FILE_ID" = par_edi_file_id;*/

  return li_return;

  EXCEPTION
     WHEN UTL_FILE.INVALID_PATH THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN -2;
     WHEN UTL_FILE.INVALID_MODE THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN -2;
    WHEN UTL_FILE.INVALID_OPERATION THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN -2;
    WHEN UTL_FILE.WRITE_ERROR THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN -2;
    WHEN OTHERS THEN
     UTL_FILE.FCLOSE_ALL;
      RETURN -1;


end F_CREATE_EDI_861_BY_BOL;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_CREATE_EDI_863_FILE" (test_file_string varchar2,
test_type integer, n integer, r integer) return integer is
 /* Returns:   Integer
	       1 = if it succeeds
	      -100 = if a duplication on index occurs
	      -2 = if errors with UTL_FILE

 */
  li_return integer;

 i integer;

 li_test_type integer; --Test type : 1.First Test
		       --	     2.First Test Redo
		       --	     3.First Full Test
		       --	     4.Full Test
 li_n integer;
 li_r integer;

 --Variables for table Imported_file_863
 ls_test_file_string varchar2(32767);
 li_file_id integer;
 ls_sample_id varchar2(20);
 ld_created_date date;
 ls_notes varchar2(255);

 -- Variables for splitting to header line and data line
 type data_line_type is table of varchar2(32767) index by binary_integer;
 ls_data_line data_line_type;

 ls_header_line varchar2(32767);
 li_data_line_num integer; -- the number of data lines in each instron test file
 temp_pos1 integer;
 temp_pos2 integer;

 --Variables for table Processing_string_863
 ls_coil_org_num varchar2(32);
 li_test_line_num integer;
 li_send_status integer;
 ls_data_string varchar2(32767);
 ls_coil_pos varchar2(100);

 ls_operator varchar2(20);

 cursor distinct_coil_org_num_cursor(sampleid varchar2) is
  select distinct coil_org_num
  from processing_string_863
  where sample_id = sampleid and send_status =0;

begin
 li_test_type := test_type;
 li_n := n;
 li_r := r;

 -- Create a record in table Imported_file_863.
 select edi_863_imported_file_id_seq.nextval into li_file_id from dual;
 ls_test_file_string := test_file_string;
 ls_sample_id := to_char(sysdate,'yyyy')||f_get_substring_comma(ls_test_file_string, 1);
 ld_created_date :=sysdate;

 insert into imported_file_863 (file_id, file_string, sample_id, created_date, notes)
 values (li_file_id, ls_test_file_string, ls_sample_id, ld_created_date, null);

 --commit;

 ls_operator := f_get_substring_comma(test_file_string, 10);

--Split test file string into one header string and data strings;
 temp_pos1 := instr(ls_test_file_string, '|', 1, 1); --'|' is the seperator between every two lines in the importing instron test file.
 ls_header_line := substr(ls_test_file_string, 1, temp_pos1 - 1);

 li_data_line_num := to_number(f_get_substring_comma(ls_header_line, 4));

 for i in 1..li_data_line_num loop
  temp_pos1 := instr(ls_test_file_string, '|',1, i);--the position of ith '|'
  temp_pos2 := instr(ls_test_file_string, '|',1, i+1);-- the position of (i+1)th '|'
  ls_data_line(i) := substr(ls_test_file_string, temp_pos1 + 1, temp_pos2 - temp_pos1 - 1);
 end loop;

 --Create records in table Processsing_string_863
 for i in 1..li_data_line_num loop
  li_test_line_num := to_number(f_get_substring_comma(ls_data_line(i),4));
  ls_coil_pos :=f_get_substring_comma(ls_data_line(i),40);
  ls_coil_org_num := f_get_coil_num(ls_coil_pos);

  insert into processing_string_863(sample_id, test_num, send_status, data_string, coil_org_num,test_type,created_date)
  values(ls_sample_id, li_test_line_num, 0, ls_data_line(i), ls_coil_org_num, li_test_type, sysdate);

  end loop;

 --commit;

 --Create edi 863 file by coil number
 open distinct_coil_org_num_cursor(ls_sample_id);
 for i in 1..li_data_line_num loop
  fetch distinct_coil_org_num_cursor into ls_coil_org_num;
  exit when (distinct_coil_org_num_cursor%notfound or li_return <>1 );

 li_return := f_create_edi_863_file_by_coil(ls_sample_id, ls_coil_org_num, ls_operator, li_file_id, li_test_type, li_n, li_r);

 end loop;

 if li_return =1 then
  update processing_string_863
  set send_status = 1
  where sample_id = ls_sample_id;
 else
  delete processing_string_863
  where send_status =0 and sample_id = ls_sample_id;
 end if;

 commit;

 return li_return;

exception
 when dup_val_on_index then
 rollback;
 return -100;


end f_create_edi_863_file;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_CREATE_EDI_863_FILE_BY_COIL"
(par_sample_id varchar2,par_coil_org_num varchar2,par_operator varchar2, par_file_id integer,
par_test_type integer, par_n integer, par_r integer)
return integer is
/* Returns:   Integer
	       1 = if it succeeds
	      -1 = if system error occurs
	      -2 = if errors with UTL_FILE

 */
  li_need_retest_date integer :=0;
  li_test_type integer;--Test type : 1.First Test
		       --	     2.First Test Redo
		       --	     3.First Full Test
		       --	     4.Full Test
  li_n integer;
  li_r integer;

  ln_r number := 0;
  ln_n number := 0;

  ls_sample_id varchar2(20) := par_sample_id;
  ls_coil_org_num varchar2(32) := par_coil_org_num;
  li_file_id integer := par_file_id;
  ls_operator VARCHAR2(20) := par_operator;

  cursor data_string_cursor is
   select data_string from processing_string_863
   where sample_id = ls_sample_id and coil_org_num = ls_coil_org_num and send_status = 0;

  type edi_863_tabletype is table of varchar2(32767) index by binary_integer;
  edi_863 edi_863_tabletype;
  j binary_integer := 0;
  k integer; -- edi_863(k) for holding the value of retest day

  li_customer_id INTEGER;
  ls_duns VARCHAR2(20);
  ln_coil_width NUMBER(2,0) := 0;
  ln_coil_thickness NUMBER(17,16) :=0;

  ls_today_short VARCHAR2(20) := to_char(SYSDATE, 'yymmdd');
  ls_today VARCHAR2(20) := to_char(SYSDATE, 'yyyymmdd');
  ls_now VARCHAR2(20) := to_char(SYSDATE, 'hh24mi');

  li_gs_log INTEGER;
  li_st_log INTEGER;

  i INTEGER;

  ls_action_coil_pos VARCHAR2(255); --these variables handling the action string
  ls_action_ps1 CHAR(1);
  ls_action_ps2 CHAR(1);
  ln_action_thickness NUMBER(17,16);
  ln_action_yts NUMBER;
  ln_action_uts NUMBER;
  ln_action_elongation NUMBER;
  ls_action_string VARCHAR2(32767);
  ls_tmp CHAR(2);
  ls_tmd CHAR(3);
  ls_pos CHAR(2);


  li_edi_863_id INTEGER; --for table edi_863_data and the id of each edi_863 sending file
  ls_edi_data_file_send VARCHAR2(32767);--holding the send edi_863_file string
  li_coil_abc_num integer;

  ls_coil_alloy varchar2(8);--for calculating retest date
  ls_coil_temper varchar2(8);
  ld_retest_date DATE;
  ld_test_date DATE;

  edi_location varchar2(50):='/templar/templar/incoming/senddata';
  edi_file varchar2 (50) := 'edi_out.txt';
  edi_file_handle UTL_FILE.FILE_TYPE;

  li_source_customer_id int;
  li_lube_weight_ready integer := 0; -- if >0 ready
  ln_lube_weight number;

  li_count integer;

  --ls_process_by varchar2(32);
  --li_lw_required int := 1;


  BEGIN
  li_test_type := par_test_type;
  li_n := par_n;
  li_r := par_r;
  ld_test_date := to_date(par_sample_id, 'yyyymmddhh24mi');

  --* creat edi8683 files here
  SELECT EDI_ST_LOG_SEQ.NEXTVAL INTO li_st_log FROM dual;
  SELECT EDI_GS_LOG_SEQ.NEXTVAL INTO li_gs_log FROM dual;

  SELECT customer_id INTO li_customer_id FROM coil
	 WHERE ( (coil_org_num = ls_coil_org_num ) and (coil_status != 20) and customer_id in (1153,1459));
  SELECT customer_duns_number_string INTO ls_duns FROM customer
	 WHERE customer_id = li_customer_id ;

  SELECT coil_abc_num INTO li_coil_abc_num
  FROM coil
  WHERE ( (coil_org_num = ls_coil_org_num ) and (coil_status != 20) );--assign coil_abc_number according to coil_org_num

  select coil_alloy2, upper(coil_temper) into
  ls_coil_alloy, ls_coil_temper from coil
  where coil_abc_num = li_coil_abc_num;


  edi_863(j):= 'ISA*00* 	 *00*	       *01*039630926T	  *09*0015049350011G *'
  || ls_today_short ||'*'|| ls_now ||'*U*00401*'||LPAD(to_char(li_gs_log),9,'0')|| '*0*P**'; j := j + 1;
  edi_863(j) :='GS*RT*039630926T*0015049350011W*' || ls_today ||'*'||ls_now||'*'||li_gs_log||'*X*004010'   ; j :=j + 1;
  edi_863(j) :='ST*863*'||li_st_log ; j :=j + 1;
  edi_863(j) :='BTR*00*'||ls_today||'*'||ls_now ; j :=j + 1;
  edi_863(j) :='NTE*SPH*I CERTIFY THAT THE MATERIALS DETAILED HEREIN HAVE BEEN SELEC'; j :=j + 1;
  edi_863(j) :='NTE*SPH*TED FROM PROPERLY CLASSIFIED STOCK, OF WHICH REPRESENTATIVE'; j :=j + 1;
  edi_863(j) :='NTE*SPH*SAMPLES HAVE BEEN TESTED TO PROVE CONFORNITY WITH THE APPROP'; j :=j + 1;
  edi_863(j) :='NTE*SPH*RIATE SPECIFICATION, AND THAT DOCUMENTARY EVIDENCE OF THE TE'; j :=j + 1;
  edi_863(j) :='NTE*SPH*ST OF RELEASE CERTIFICATION IS ON FILE IN THE OFFICES OF ALCAN'; j :=j + 1;
  edi_863(j) :='NTE*SPH*ALUMINUM CORPORATION.'; j :=j + 1;
  edi_863(j) :='REF*MI*000000000'; j :=j + 1;
  edi_863(j) :='REF*BM*000000000'; j :=j + 1;

  -- modified by victor huang on 02/2004 as per ALCAN's request
  -- F: Full Test, P: Partial Test
  if li_test_type in (3,4,5) then
     edi_863(j) :='REF*SI*'||ls_coil_org_num||'*F'; j :=j + 1;
  else
     edi_863(j) :='REF*SI*'||ls_coil_org_num||'*P'; j :=j + 1;
  end if;
  --edi_863(j) :='REF*SI*'||ls_coil_org_num; j :=j + 1;

  edi_863(j) :='DTM*011*'||ls_today||'*'||ls_now; j :=j + 1;
  edi_863(j) :='N1*SU*NOVELIS INC.*1*'||ls_duns; j :=j + 1;
  edi_863(j) :='N3*6060 PARKLAND BLVD.'; j :=j + 1;
  edi_863(j) :='N4*MAYFIELD HTS.*OH*441244185'; j :=j + 1;
  edi_863(j) :='N1*PV*'||ls_operator||'*1*039630926'; j :=j + 1;
  edi_863(j) :='LIN**VO*00000*BP*00000*VN*001*VS*'||ls_coil_org_num||'*SN*00000*VU*'||to_char(li_coil_abc_num); j :=j + 1;
  edi_863(j) :='PID*F*16*AA*O'; j :=j + 1;
  edi_863(j) :='PID*F*11*AA*081131DDD000*ALCAN'; j :=j + 1;
  edi_863(j) :='PID*F*38*AA*5182'; j :=j + 1;
  edi_863(j) :='PID*S*PR*ST*20'; j :=j + 1;
  edi_863(j) :='DTM*009*'||ls_today||'*'||ls_now; j :=j + 1;
  edi_863(j) :='DTM*222*'||ls_today||'*'||ls_now; j :=j + 1;

  if li_test_type in (1,2,3) and  ls_coil_alloy = '6111' and
   ls_coil_temper in ('T4P','T4PB','T4PD') then
   edi_863(j) :=''; k := j; j := j+1; -- edi_863(k) for holding the value of retest day
   li_need_retest_date :=1;
  end if;

  OPEN data_string_cursor;

  LOOP
  FETCH data_string_cursor INTO ls_action_string;
  EXIT WHEN data_string_cursor%NOTFOUND;

  if li_n = 0 and li_r = 0 then
   ln_coil_width := to_number(f_get_substring_comma(ls_action_string, 63))/25.4;
   ln_coil_thickness := to_number(f_get_substring_comma(ls_action_string, 67))/25.4;
