	 FROM SCRAP_SKID_DETAIL
	 WHERE SCRAP_SKID_NUM = scrap_skid_id;

begin
  --Result := 1;
  --return Result;
  --Result := 0;
  --IF NOT C_Scrap_Detail%ISOPEN THEN
  --	  OPEN c_scrap_detail;
  --END IF;
  /*
  SELECT NVL(PACKING_LIST, 0) into packing_list
	    FROM SCRAP_PACKING_ITEM
	    WHERE SCRAP_SKID_NUM = scrap_skid_id;
  --//IF not SQL%FOUND THEN  RETURN PACKING_LIST; END IF;
  if packing_list <> 0 then return packing_list; end if;

  IF packing_list is not null then
     Return packing_list;
  end if;

  */
  OPEN packing;
  FETCH packing into packing_rec;
  IF packing%FOUND then
     return packing_rec.packing_list;
  END IF;
  CLOSE packing;

  FOR all_items IN c_Scrap_Detail LOOP
      --all_items.RETURN_SCRAP_ITEM_NUM := 0;
      DELETE FROM SCRAP_SKID_DETAIL
