  END LOOP;

  DELETE FROM quality_scrap_worksheet
  WHERE quality_scrap_worksheet.scrap_skid_num = scrap_skid_id;

  DELETE FROM SCRAP_SKID
	     WHERE SCRAP_SKID.SCRAP_SKID_NUM = scrap_skid_id;
      commit;


  --CLOSE c_scrap_detail;

  --Result := 1;
  return(1);
end F_DELETE_SCRAP_SKID;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_DELETE_SHEET_SKID" (sheet_skid_id sheet_skid_detail.sheet_skid_num%type) return sheet_packing_item.packing_list%type is
  Result sheet_packing_item.packing_list%type;
  --packing_list long;
  cursor packing IS
	 SELECT packing_list FROM SHEET_PACKING_ITEM
	 WHERE SHEET_SKID_NUM = sheet_skid_id;
  packing_rec packing%ROWTYPE;
  CURSOR c_sheet_detail IS
	 SELECT prod_item_num
	 FROM sheet_SKID_DETAIL
	 WHERE sheet_SKID_NUM = sheet_skid_id;
begin
  --Result := 1;
  --return Result;
  --Result := 0;
  --IF NOT C_Scrap_Detail%ISOPEN THEN
  --	  OPEN c_scrap_detail;
  --END IF;
  /*
  SELECT NVL(PACKING_LIST, 0) into packing_list
	    FROM SCRAP_PACKING_ITEM
	    WHERE SCRAP_SKID_NUM = scrap_skid_id;
  --//IF not SQL%FOUND THEN  RETURN PACKING_LIST; END IF;
  if packing_list <> 0 then return packing_list; end if;

  IF packing_list is not null then
     Return packing_list;
  end if;

  */
  OPEN packing;
  FETCH packing into packing_rec;
  IF packing%FOUND then
     return packing_rec.packing_list;
  END IF;
  CLOSE packing;

  DELETE FROM PROCESS_PARTIAL_SKID
	 WHERE SHEET_SKID_NUM = sheet_skid_id;

  FOR all_items IN c_sheet_Detail LOOP
      --all_items.RETURN_SCRAP_ITEM_NUM := 0;
      DELETE FROM SHEET_SKID_DETAIL
	     WHERE prod_item_num = all_items.prod_item_num;
      --commit;
      DELETE FROM PRODUCTION_SHEET_ITEM
	     WHERE prod_item_num = all_items.prod_item_num;
      --commit;

  END LOOP;
  DELETE FROM SHEET_SKID
	     WHERE SHEET_SKID.SHEET_SKID_NUM = sheet_skid_id;
      commit;


  --CLOSE c_scrap_detail;

  --Result := 1;
  return(1);
end F_DELETE_SHEET_SKID;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_DELETE_SHIFT" (al_id shift.shift_num%type) return integer is
  Result integer;
  Cursor c_instance IS
	 SELECT INSTANCE_NUM FROM DT_INSTANCE
	 WHERE SHIFT_NUM = al_id;

begin
  FOR instances IN c_instance LOOP
      DELETE FROM DT_INSTANCE_DETAIL
      WHERE DT_INSTANCE_DETAIL.INSTANCE_NUM = instances.instance_num;
      DELETE FROM DT_INSTANCE
      WHERE DT_INSTANCE.INSTANCE_NUM = instances.instance_num;
  END LOOP;

  DELETE FROM SHIFT
  WHERE SHIFT.SHIFT_NUM = al_id;
  commit;

  return(1);
end F_DELETE_SHIFT;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_EDI_856" (packing_list_no shipment.packing_list%TYPE)
  RETURN INTEGER IS
  /*
  Returns:   Integer
		 1 = if it succeeds
		-1 = if a system error occurs
	       100 = EDI had aleady been sent
	       200 = No EDI defined

  Customer: ALCAN(34,35,10)
  Alcan Rolled Product	  X.121       0015049350011G
  End User: Ford (ZZ F159B)
	    Ford Chicago Stamping Plant(51) MS02A
	    Ford Walton Hills Stamping Plant(77) MS03A
	    Ford Woodhaven Stamping Plant(71) AF30A MS09A
	    Ford Maumee Stamping Plant(78)    AF06A MS08A
	    Republic same as Ford WoodHaven
	    Ford Ogihara  (1579)	   F7BFC

	    (not in use)Ford Monroe Stamping		  AP06A

	    (not in use) Warehouses: IDS(41)		   R5G3B
	    (not in use) Wayne Steel Distribution Center(79) RWSDC


  Customer Alcan for GM send EDIFACT DESADV
      End user: Grand Rapid
		Pontiac plant 14
		Pontiac Plant 15
		GM Lansing Stamping 1840

  Customer Kaiser(45) send x12
      End User: Kaiser
		Capital Tech
		Hayes
		Hayes/Northville
		Lorbec (Scrap)
  Customer Alcoa Texacana(1188) End User Hayes(45) send X12 4010
  */

  --l_return number(5);
  exce_des_sh_cust_id EXCEPTION;
  exce_nodata	      EXCEPTION;
  exce_sent	      EXCEPTION;

  l_customer_id    INTEGER;
  l_des_sh_cust_id INTEGER;
  l_enduser_id	   INTEGER;
  rr		   INTEGER;
  scrap_item	   INTEGER;
  l_ship_date	   DATE;

  ll_bol	   shipment.bill_of_lading%TYPE;

  rr_856		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  rr_desadv		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  rr_ford		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  ll_des_sh_cust_id	    shipment.des_sh_cust_id%TYPE;	--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  ls_customer_short_name    customer.customer_short_name%TYPE;	--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

  ll_count		    integer;				--Alex Gerlants. novelis testing
  li_coil_status	    coil.coil_status%TYPE;		--Alex Gerlants. 02/05/2019. Added for Novelis
  rr_rejcoil		    integer;				--Alex Gerlants. 02/05/2019. Added for Novelis
  li_is_constellium	    integer;				--Alex Gerlants. Constellium EDI 856

  CURSOR packing_list_same_bol IS
    SELECT packing_list
      FROM shipment
     WHERE shipment.bill_of_lading = ll_bol
       AND shipment.shipment_status <> 3;
  ll_temp INTEGER;
BEGIN

  delete from dbo.error_message; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

  edi_alcan_870;

  SELECT shipment.bill_of_lading,
	 customer_id,
	 des_sh_cust_id,
	 shipment_enduser_id,
	 shipment_status
    INTO ll_bol, l_customer_id, l_des_sh_cust_id, l_enduser_id, ll_temp
    FROM shipment
   WHERE shipment.packing_list = packing_list_no;
  IF NOT SQL%FOUND THEN
    RETURN - 1;
  END IF;

  IF ll_temp <> 0 THEN
    RETURN packing_list_no;
  END IF;

  --Alex Gerlants. 01/12/2023. 1778_TWB project
  --Alex Gerlants. 02/15/2023. Added "2998 - TWB-ANTIOCH" as per Dan Polkinhorne's email received on Wed 2/15/2023 9:09 AM.
  if (l_customer_id in (2992, 2998)) then
    return edi_twb_856_X12_3(packing_list_no);
  end if;
  --Alex Gerlants. 06/13/2019. Arconic EDI. Added IF statement below for 2784-Arconic-TN

  --Alex Gerlants. 06/13/2019. Arconic EDI. Added IF statement below for 2784-Arconic-TN
  if (l_customer_id in (2784)) then
    return edi_arconic_856_X12(packing_list_no);
  end if;

  --Alex Gerlants. Constellium EDI 856. Begin
  select dbo.f_is_constellium(packing_list_no)
  into	 li_is_constellium
  from	 dual;

  if li_is_constellium = 1 then --Customer is Constellium
    return edi_const_856_X12(packing_list_no);
  end if;
  --Alex Gerlants. Constellium EDI 856. End

  --Alex Gerlants. 10/22/2019. Begin
  --This is a temporary measure to help Arconic Davenport.
  --It is commented out in Production until they tell us to activate it.
  /*
  if (l_customer_id in (50)) then --Arconic Davenport
     if l_des_sh_cust_id in (69, 70, 2850, 72, 1840, 2079, 2164, 2181, 2360, 1648, 2495, 2611, 2680, 2814) then

       return f_edi_desadv2_arconic_davenprt(packing_list_no); --Send GM EDIFACT
     end if;
  end if; --if (l_customer_id in (50) then
  */
  --Alex Gerlants. 10/22/2019. End

  --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
  --Alex Gerlants. 12/04/2017. Added "2776" to the line below. Shipping to GM
  IF (l_customer_id in (1429, 2795, 2830, 2776)) THEN
    --SAMUEL-HAMILTON, SAMUEL-TENN, SAMUEL-COLUMBIA
    rr_desadv := f_edi_desadv_bolt(packing_list_no);

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin
    --rr_desadv := 200; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY

    if rr_desadv = 1 or rr_desadv = 100 then --"EDI generated successfully" or "EDI previously sent."
      return rr_desadv;
    else
      if rr_desadv = -1 then
	 insert into dbo.error_message values('f_edi_desadv_bolt. Packing list ' || to_char(packing_list_no) || ' does not exist');
	 commit;
	 return -14;
      elsif rr_desadv = -3 then
	 select  shipment.des_sh_cust_id, customer.customer_short_name
	 into	 ll_des_sh_cust_id, ls_customer_short_name
	 from	 shipment
	 join	 customer on customer.customer_id = shipment.des_sh_cust_id
	 where	 shipment.packing_list = packing_list_no;

	 insert into dbo.error_message values('f_edi_desadv_bolt. Communication code is NOT set up in table customer_system for Destination Customer ' || to_char(l_des_sh_cust_id) || '-' || ls_customer_short_name);
	 commit;
	 return -13;
       elsif rr_desadv = 200 then
	 insert into dbo.error_message values('f_edi_desadv_bolt. Customer DUNS not set up in table customer.');
	 commit;
	 return -12;
       else
	  return rr_desadv;
       end if;
     end if;
     --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  END IF;

  --Alex Gerlants. 03/03/2021. Added '2950'  to the list below <== NOVELIS-GUTHRIE
  IF NOT (l_customer_id IN (10, 34, 35, 188, 1153, 1188, 1364, 1459, 1980, 2505, 2582, 2950)) THEN
    --1459 Alcan Oswego, 1364 Wise Alloys
    RETURN 200;
  END IF;

  SELECT shipment_edi856_date
    INTO l_ship_date
    FROM shipment
   WHERE shipment.packing_list = packing_list_no;
  IF NOT (l_ship_date IS NULL) THEN
    RETURN 100;
  END IF;

  --Check all packing_lists are done or cancel against a BOL
  FOR pl_rec IN packing_list_same_bol LOOP
    SELECT shipment.shipment_status
      INTO ll_temp
      FROM shipment
     WHERE shipment.packing_list = pl_rec.packing_list;
    IF ll_temp <> 0 THEN
      RETURN pl_rec.packing_list;
    END IF;
  END LOOP;
  --End of packing list checking

  --------------------------------------------------------------------------

  --Alex Gerlants. 02/05/2019. Added for Novelis
  select count(*)
  into	 ll_count
  from	 reject_coil_packing_item
	 join coil on coil.coil_abc_num = reject_coil_packing_item.coil_abc_num
	 join shipment on shipment.packing_list = reject_coil_packing_item.packing_list
	 join customer on customer.customer_id = shipment.customer_id
  where  shipment.packing_list = packing_list_no;

  if ll_count > 0 then
    select distinct customer.customer_short_name, coil.coil_status
    into   ls_customer_short_name, li_coil_status
    from   reject_coil_packing_item
	   join coil on coil.coil_abc_num = reject_coil_packing_item.coil_abc_num
	   join shipment on shipment.packing_list = reject_coil_packing_item.packing_list
	   join customer on customer.customer_id = shipment.customer_id
    where  shipment.packing_list = packing_list_no;

    if lower(ls_customer_short_name) like '%novelis%' then
      if li_coil_status in (3, 6, 14) then --Rejected coil (3), Return coil (6), Scrap coil (14)
	   rr_rejcoil := edi_novelis_rejcoil_856_x12(packing_list_no);
	   return rr_rejcoil;
      else --coi_status is other than Rejected coil (3), Return coil (6), Scrap coil (14)
	return 100; --"EDI previously sent.".
		    --Should not happen though
		    --because this validation "IF NOT (l_ship_date IS NULL) THEN"
		    --is done above.
      end if;
    else--Not Novelis. We send ASN for these coils to Novelis only.
      return 1; --Nothing to do here
    end if;
  end if;

  --------------------------------------------------------------------------

  scrap_item := 0;

  --add by Victor Huang for "Wise Alloys"
  IF (l_customer_id = 1364) THEN
    --1364 Wise Alloys
    RETURN edi_wise_856(packing_list_no);
  END IF;


   --add by James Ni for "Aleris"
  IF (l_customer_id = 1980) THEN
     RETURN edi_aleris_856_x12_multi_po(packing_list_no);
  END IF;

  --Alex Gerlants. 06/10/2025. Removed ', 2950' to create 856 for BOL 132889
  --Alex Gerlants. 06/10/2025. Added '3047 - SIGNAL MACHINE COMPANY, INC'. Email from Dan received on Tue 6/10/2025 7:20 AM.
  --Alex Gerlants. 03/20/2025. Added '3044- This is GENERAL MOTORS CORP/METAL FAB DIV'
  --Alex Gerlants. 02/11/2025. Added '3040- This is DIVERSIFIED TECH INTL'
  --Alex Gerlants. 00/15/2024. Added '3036' to the list below. This is 3036 - NUMIT LLC'.
  --Alex Gerlants. 09/27/2024. Added '3034' to the list below. This is 3034 - ROYAL EG NORTH AMERICA INC. Email from Dan received on Fri 9/27/2024 @10:42 AM.
  --Alex Gerlants. 09/20/2017. Added '2850' to the list below
  --Alex Gerlants. 05/13/2019. Added '2903' to the list below
  --Alex Gerlants. 05/14/2019. Added '2906' to the list below
  --Alex Gerlants. 03/03/2021. Added '2950'  to the list below <== NOVELIS-GUTHRIE. In case if we ship to there.
  --Alex Gerlants. 05/10/2021. Added '2955'  to the list below
  --Alex Gerlants. 09/13/2021. Added 1532 - NOVELIS-NOVI, 1749 - NOVELIS-NOVI A.F.
  --Alex Gerlants. 06/28/2023. Added 3010 - A PHASE II to the list below
  IF ((l_des_sh_cust_id IN -- if the destination we are shipping to is in this list...
     (69, 70, 2850, 72, 1840, 2079, 2164, 2181, 2360, 2495, 2611, 2680, 2814, 2903, 2906, 2955, 1532, 1749, 3010, 3034, 3036, 3040, 3044, 3047)) OR (l_customer_id = 2505)) THEN
    --GM

    rr_856 := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
    rr_desadv := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

    IF (l_customer_id != 2505) THEN
      --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "rr" with "rr_856"
	--rr_856 := edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
	rr_856 := edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis
    END IF;

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
    --Alex Gerlants. 04/09/2019. Do not run f_edi_desadv2 for Novelis.
    select distinct customer.customer_short_name
    into   ls_customer_short_name
    from   shipment
	   join customer on customer.customer_id = shipment.customer_id
    where  shipment.packing_list = packing_list_no;

    if lower(ls_customer_short_name) not like '%novelis%' then
       rr_desadv := f_edi_desadv2(packing_list_no); --Send GM EDIFACT
    end if;
    --								    Republic(1104 shipment as as woodhaven, and Gerstenslager 1401
    --								    Karmax(1149),WindsorMatchPlate(1388)
    --elsif l_des_sh_cust_id in (51,77,71,78,41,79, 1347, 1382, 1383, 1104, 1401, 1388, 1149, 1579) then  --Ford
    --Delete 1382 per Alcan 03/29/04  by Tony

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin

    --rr_856 := 100; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY
    --rr_desadv := 500; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY


    if rr_856 = 1 and rr_desadv = 1 then
       return 1;
    elsif rr_desadv = 100 then --"EDI previously sent.".
			       --Should not happen though
			       --because this validation "IF NOT (l_ship_date IS NULL) THEN"
			       --is done above.
       return 100;
    elsif rr_desadv = 200 then --Not the right customer.
			       --Should not happent though because this check is done
			       --in this function above, just before edi_alcan_alcan_856_x12() is called
       return 200;
    else
       if rr_856 = -1 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_desadv = -1 then
	  insert into dbo.error_message values('f_edi_desadv2. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_desadv = 500 then
	  insert into dbo.error_message values('f_edi_desadv2. Customer DUNS not set up in table customer. Please set it up.');
       end if;

       if rr_856 = 100 then
	   insert into dbo.error_message values('edi_alcan_alcan_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
	end if;

       if rr_desadv = -3 then
	  select  shipment.des_sh_cust_id, customer.customer_short_name
	  into	  ll_des_sh_cust_id, ls_customer_short_name
	  from	  shipment
	  join	  customer on customer.customer_id = shipment.des_sh_cust_id
	  where   shipment.packing_list = packing_list_no;

	  insert into dbo.error_message values('f_edi_desadv2. Communication code is NOT set up in table customer_system for Destination Customer ' || to_char(l_des_sh_cust_id) || '-' || ls_customer_short_name);
       end if;

       commit; --This commit is for table dbo.error_message that is populated above

       if rr_856 <> 1 and rr_desadv <> 1 then
	  if rr_desadv <> 500 then
	     return -8; --Both, customer 856 and OEM files not created
	  else
	     return -15; --Only customer file not created. OEM file is created, but customer.customer_duns_number_string not set up for customer
	  end if;
       else --one of them is not 1
	  if rr_856 <> 1 then
	     return -7;
	  else --rr_desadv <> 1
	     if rr_desadv = 500 then
		return -16; --OEM file is created, but customer.customer_duns_number_string not set up for customer
	     else
		return -6; --OEM file not created
	     end if;
	  end if;
       end if;
    end if;
    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  ELSIF l_des_sh_cust_id IN
	(51, 77, 71, 78, 41, 79, 1347, 1383, 1104, 1401, 1388, 1149, 1579) THEN
    --Ford

    rr_ford := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
    rr_856 := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "rr" with "rr_856"
    rr_856 := edi_alcan_ford_856_x12(packing_list_no); --Send Ford

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
    --rr_desadv := edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    rr_856 := edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin
    if rr_ford = 1 and rr_856 = 1 then
       return 1;
    else --rr_ford <> 1 or rr_856 <> 1
       if rr_ford = -1 then
	  insert into dbo.error_message values('edi_alcan_ford_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_856 = -1 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_ford = 200 then
	  insert into dbo.error_message values('edi_alcan_ford_856_x12. Customer does NOT require EDI transaction. Customer or destination customer DUNS not set up in table customer.');
       end if;

       if rr_856 = 200 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Customer does NOT require EDI transaction. Customer or destination customer DUNS not set up in table customer.');
       end if;

       if rr_856 = 100 then
	   insert into dbo.error_message values('edi_alcan_alcan_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
       end if;

       if rr_ford = 100 then
	   insert into dbo.error_message values('edi_alcan_ford_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
       end if;

       commit; --This commit is for table dbo.error_message that is populated above

       if rr_ford <> 1 and rr_856 <> 1 then
	  return -11;
       else --one of them is not 1
	  if rr_ford <> 1 then
	     return -10;
	  else
	     return -9;
	  end if;
       end if;
    end if;
    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  ELSIF l_customer_id = 188 THEN
    --Kaiser
    RETURN edi_kaiser_856(packing_list_no);

  ELSIF l_des_sh_cust_id = 1096 THEN
    --BUDD Company or Eagle Steel
    --	      return edi_alcan_ford_856_x12(packing_list_no);
    --rr:=edi_alcan_budd_856(packing_list_no);		 --Send Budd per budd and eagle, they no longer receive ASN from ABC
    --rr:= edi_alcan_ford_856_x12(packing_list_no);  --Send Eagle using Ford code
    --RETURN edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    return edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Noveli

  ELSIF l_des_sh_cust_id = 1251 THEN
    --Eagle steel, send to Budd and Eagle(ford format)
    --rr:=edi_alcan_budd_856(packing_list_no);	-- per budd and eagle, they no longer receive ASN from ABC
    --rr:= edi_alcan_ford_856_x12(packing_list_no);  --Send Eagle using Ford code
    --return rr;
    --RETURN edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    return edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis

    --elsif l_des_sh_cust_id = 79 then			--WSDC send Alcan only
    --	    return edi_alcan_alcan_856_x12(packing_list_no);

  --Alex Gerlants. 09/27/2021. Added 2950 - Novelis-Guthrey
  ELSIF l_customer_id IN (35, 10, 1153, 1459, 2582, 2950) THEN
    SELECT MAX(sc_packing_item)
      INTO scrap_item
      FROM scrap_packing_item
     WHERE packing_list = packing_list_no;
    IF scrap_item > 0 THEN
      --RETURN edi_alcan_alcan_scrap_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
      return edi_novelis_scrap_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis
    ELSE -- All else destination send Alcan only
      --RETURN edi_alcan_alcan_856_x12(packing_list_no);  --Alex Gerlants. 02/05/2019. Commented out
      return edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis
    END IF;

  ELSIF l_des_sh_cust_id = 45 THEN
    RETURN edi_alcoa_hayes_856_x12(packing_list_no);
  ELSE
    RETURN 200;
  END IF;

EXCEPTION
  WHEN exce_sent THEN
    --	  raise_application_error(-20101,'STOP! EDI had been sent');
    RETURN 100;
  WHEN exce_nodata THEN
    --	   raise_application_error(-20101,'No shipment data found!');
    RETURN - 1;
  WHEN exce_des_sh_cust_id THEN
    --	  raise_application_error(-20101,'This shipment does not required EDIFACT DESADV EDI!');
    RETURN 200;
  WHEN OTHERS THEN
    --	  raise_application_error(-20101,'INTERNAL ERROR! PLEASE CALL 1519.');
    RETURN - 1;

  --   return l_return;
END;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_EDI_856_08072025" (packing_list_no shipment.packing_list%TYPE)
  RETURN INTEGER IS
  /*
  Returns:   Integer
		 1 = if it succeeds
		-1 = if a system error occurs
	       100 = EDI had aleady been sent
	       200 = No EDI defined

  Customer: ALCAN(34,35,10)
  Alcan Rolled Product	  X.121       0015049350011G
  End User: Ford (ZZ F159B)
	    Ford Chicago Stamping Plant(51) MS02A
	    Ford Walton Hills Stamping Plant(77) MS03A
	    Ford Woodhaven Stamping Plant(71) AF30A MS09A
	    Ford Maumee Stamping Plant(78)    AF06A MS08A
	    Republic same as Ford WoodHaven
	    Ford Ogihara  (1579)	   F7BFC

	    (not in use)Ford Monroe Stamping		  AP06A

	    (not in use) Warehouses: IDS(41)		   R5G3B
	    (not in use) Wayne Steel Distribution Center(79) RWSDC


  Customer Alcan for GM send EDIFACT DESADV
      End user: Grand Rapid
		Pontiac plant 14
		Pontiac Plant 15
		GM Lansing Stamping 1840

  Customer Kaiser(45) send x12
      End User: Kaiser
		Capital Tech
		Hayes
		Hayes/Northville
		Lorbec (Scrap)
  Customer Alcoa Texacana(1188) End User Hayes(45) send X12 4010
  */

  --l_return number(5);
  exce_des_sh_cust_id EXCEPTION;
  exce_nodata	      EXCEPTION;
  exce_sent	      EXCEPTION;

  l_customer_id    INTEGER;
  l_des_sh_cust_id INTEGER;
  l_enduser_id	   INTEGER;
  --rr		     INTEGER;
  scrap_item	   INTEGER;
  l_ship_date	   DATE;

  ll_bol	   shipment.bill_of_lading%TYPE;

  rr_856		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  rr_desadv		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  rr_ford		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  ll_des_sh_cust_id	    shipment.des_sh_cust_id%TYPE;	--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  ls_customer_short_name    customer.customer_short_name%TYPE;	--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

  ll_count		    integer;				--Alex Gerlants. novelis testing
  li_coil_status	    coil.coil_status%TYPE;		--Alex Gerlants. 02/05/2019. Added for Novelis
  rr_rejcoil		    integer;				--Alex Gerlants. 02/05/2019. Added for Novelis
  li_is_constellium	    integer;				--Alex Gerlants. Constellium EDI 856
  ls_rtn		    char(5);

  CURSOR li_count_sheet IS
    SELECT packing_list
      FROM shipment
     WHERE shipment.bill_of_lading = ll_bol
       AND shipment.shipment_status <> 3;
  ll_temp INTEGER;
BEGIN

  delete from dbo.error_message; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

  edi_alcan_870;

  SELECT shipment.bill_of_lading,
	 customer_id,
	 des_sh_cust_id,
	 shipment_enduser_id,
	 shipment_status
    INTO ll_bol, l_customer_id, l_des_sh_cust_id, l_enduser_id, ll_temp
    FROM shipment
   WHERE shipment.packing_list = packing_list_no;
  IF NOT SQL%FOUND THEN
    RETURN - 1;
  END IF;

  IF ll_temp <> 0 THEN
    RETURN packing_list_no;
  END IF;

  --Alex Gerlants. 01/12/2023. 1778_TWB project
  --Alex Gerlants. 02/15/2023. Added "2998 - TWB-ANTIOCH" as per Dan Polkinhorne's email received on Wed 2/15/2023 9:09 AM.
  if (l_customer_id in (2992, 2998)) then
    return edi_twb_856_X12_3(packing_list_no);
  end if;
  --Alex Gerlants. 06/13/2019. Arconic EDI. Added IF statement below for 2784-Arconic-TN

  --Alex Gerlants. 06/13/2019. Arconic EDI. Added IF statement below for 2784-Arconic-TN
  if (l_customer_id in (2784)) then
    return edi_arconic_856_X12(packing_list_no);
  end if;

  --Alex Gerlants. Constellium EDI 856. Begin
  select dbo.f_is_constellium(packing_list_no)
  into	 li_is_constellium
  from	 dual;

  if li_is_constellium = 1 then --Customer is Constellium
    return edi_const_856_X12(packing_list_no);
  end if;
  --Alex Gerlants. Constellium EDI 856. End

  --Alex Gerlants. 10/22/2019. Begin
  --This is a temporary measure to help Arconic Davenport.
  --It is commented out in Production until they tell us to activate it.
  /*
  if (l_customer_id in (50)) then --Arconic Davenport
     if l_des_sh_cust_id in (69, 70, 2850, 72, 1840, 2079, 2164, 2181, 2360, 1648, 2495, 2611, 2680, 2814) then

       return f_edi_desadv2_arconic_davenprt(packing_list_no); --Send GM EDIFACT
     end if;
  end if; --if (l_customer_id in (50) then
  */
  --Alex Gerlants. 10/22/2019. End

  --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
  --Alex Gerlants. 12/04/2017. Added "2776" to the line below. Shipping to GM
  IF (l_customer_id in (1429, 2795, 2830, 2776)) THEN
    --SAMUEL-HAMILTON, SAMUEL-TENN, SAMUEL-COLUMBIA
    rr_desadv := f_edi_desadv_bolt(packing_list_no);

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin
    --rr_desadv := 200; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY

    if rr_desadv = 1 or rr_desadv = 100 then --"EDI generated successfully" or "EDI previously sent."
      return rr_desadv;
    else
      if rr_desadv = -1 then
	 insert into dbo.error_message values('f_edi_desadv_bolt. Packing list ' || to_char(packing_list_no) || ' does not exist');
	 commit;
	 return -14;
      elsif rr_desadv = -3 then
	 select  shipment.des_sh_cust_id, customer.customer_short_name
	 into	 ll_des_sh_cust_id, ls_customer_short_name
	 from	 shipment
	 join	 customer on customer.customer_id = shipment.des_sh_cust_id
	 where	 shipment.packing_list = packing_list_no;

	 insert into dbo.error_message values('f_edi_desadv_bolt. Communication code is NOT set up in table customer_system for Destination Customer ' || to_char(l_des_sh_cust_id) || '-' || ls_customer_short_name);
	 commit;
	 return -13;
       elsif rr_desadv = 200 then
	 insert into dbo.error_message values('f_edi_desadv_bolt. Customer DUNS not set up in table customer.');
	 commit;
	 return -12;
       else
	  return rr_desadv;
       end if;
     end if;
     --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  END IF;

  --Alex Gerlants. 03/03/2021. Added '2950'  to the list below <== NOVELIS-GUTHRIE
  IF NOT (l_customer_id IN (10, 34, 35, 188, 1153, 1188, 1364, 1459, 1980, 2505, 2582, 2950)) THEN
    --1459 Alcan Oswego, 1364 Wise Alloys
    RETURN 200;
  END IF;

  SELECT shipment_edi856_date
    INTO l_ship_date
    FROM shipment
   WHERE shipment.packing_list = packing_list_no;
  IF NOT (l_ship_date IS NULL) THEN
    RETURN 100;
  END IF;

  --Check all packing_lists are done or cancel against a BOL
  FOR pl_rec IN li_count_sheet LOOP
    SELECT shipment.shipment_status
      INTO ll_temp
      FROM shipment
     WHERE shipment.packing_list = pl_rec.packing_list;
    IF ll_temp <> 0 THEN
      RETURN pl_rec.packing_list;
    END IF;
  END LOOP;
  --End of packing list checking

  --------------------------------------------------------------------------

  --Alex Gerlants. 02/05/2019. Added for Novelis
  select count(*)
  into	 ll_count
  from	 reject_coil_packing_item
	 join coil on coil.coil_abc_num = reject_coil_packing_item.coil_abc_num
	 join shipment on shipment.packing_list = reject_coil_packing_item.packing_list
	 join customer on customer.customer_id = shipment.customer_id
  where  shipment.packing_list = packing_list_no;

  if ll_count > 0 then
    select distinct customer.customer_short_name, coil.coil_status
    into   ls_customer_short_name, li_coil_status
    from   reject_coil_packing_item
	   join coil on coil.coil_abc_num = reject_coil_packing_item.coil_abc_num
	   join shipment on shipment.packing_list = reject_coil_packing_item.packing_list
	   join customer on customer.customer_id = shipment.customer_id
    where  shipment.packing_list = packing_list_no;

    if lower(ls_customer_short_name) like '%novelis%' then
      if li_coil_status in (3, 6, 14) then --Rejected coil (3), Return coil (6), Scrap coil (14)
	   rr_rejcoil := edi_novelis_rejcoil_856_x12(packing_list_no);
	   return rr_rejcoil;
      else --coi_status is other than Rejected coil (3), Return coil (6), Scrap coil (14)
	return 100; --"EDI previously sent.".
		    --Should not happen though
		    --because this validation "IF NOT (l_ship_date IS NULL) THEN"
		    --is done above.
      end if;
    else--Not Novelis. We send ASN for these coils to Novelis only.
      return 1; --Nothing to do here
    end if;
  end if;

  --------------------------------------------------------------------------

  scrap_item := 0;

  --add by Victor Huang for "Wise Alloys"
  IF (l_customer_id = 1364) THEN
    --1364 Wise Alloys
    RETURN edi_wise_856(packing_list_no);
  END IF;


   --add by James Ni for "Aleris"
  IF (l_customer_id = 1980) THEN
     RETURN edi_aleris_856_x12_multi_po(packing_list_no);
  END IF;

  --Alex Gerlants. 06/10/2025. Removed ', 2950' to create 856 for BOL 132889
  --Alex Gerlants. 06/10/2025. Added '3047 - SIGNAL MACHINE COMPANY, INC'. Email from Dan received on Tue 6/10/2025 7:20 AM.
  --Alex Gerlants. 03/20/2025. Added '3044- This is GENERAL MOTORS CORP/METAL FAB DIV'
  --Alex Gerlants. 02/11/2025. Added '3040- This is DIVERSIFIED TECH INTL'
  --Alex Gerlants. 00/15/2024. Added '3036' to the list below. This is 3036 - NUMIT LLC'.
  --Alex Gerlants. 09/27/2024. Added '3034' to the list below. This is 3034 - ROYAL EG NORTH AMERICA INC. Email from Dan received on Fri 9/27/2024 @10:42 AM.
  --Alex Gerlants. 09/20/2017. Added '2850' to the list below
  --Alex Gerlants. 05/13/2019. Added '2903' to the list below
  --Alex Gerlants. 05/14/2019. Added '2906' to the list below
  --Alex Gerlants. 03/03/2021. Added '2950'  to the list below <== NOVELIS-GUTHRIE. In case if we ship to there.
  --Alex Gerlants. 05/10/2021. Added '2955'  to the list below
  --Alex Gerlants. 09/13/2021. Added 1532 - NOVELIS-NOVI, 1749 - NOVELIS-NOVI A.F.
  --Alex Gerlants. 06/28/2023. Added 3010 - A PHASE II to the list below
  IF ((l_des_sh_cust_id IN -- if the destination we are shipping to is in this list...
     (69, 70, 2850, 72, 1840, 2079, 2164, 2181, 2360, 2495, 2611, 2680, 2814, 2903, 2906, 2955, 1532, 1749, 3010, 3034, 3036, 3040, 3044, 3047, 2950)) OR (l_customer_id = 2505)) THEN
    --GM

    rr_856 := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
    rr_desadv := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

    IF (l_customer_id != 2505) THEN
      --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "rr" with "rr_856"
	--rr_856 := edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
	--rr_856 := edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 08/06/2025. 2404_Novelis_856_EDI_Sheets_and_Scrap. Comment out.

	--Alex Gerlants. 08/06/2025. 2404_Novelis_856_EDI_Sheets_and_Scrap. Begin
	ls_rtn := f_sheet_or_scrap_shipment(packing_list_no);

	if ls_rtn = 'SHEET' then
	  rr_856 := edi_novelis_856_X12(packing_list_no);
	elsif ls_rtn = 'SCRAP' then
	  if l_customer_id IN (35, 10, 1153, 1459, 2582, 2950) then
	    rr_856 := edi_novelis_scrap_856_x12(packing_list_no);
	  end if;
	--else --'BOTH'
	  --return edi_novelis_856_sheets_scrap(packing_list_no)
	end if;
	--Alex Gerlants. 08/06/2025. 2404_Novelis_856_EDI_Sheets_and_Scrap. End

    END IF;

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
    --Alex Gerlants. 04/09/2019. Do not run f_edi_desadv2 for Novelis.
    select distinct customer.customer_short_name
    into   ls_customer_short_name
    from   shipment
	   join customer on customer.customer_id = shipment.customer_id
    where  shipment.packing_list = packing_list_no;

    if lower(ls_customer_short_name) not like '%novelis%' then
       rr_desadv := f_edi_desadv2(packing_list_no); --Send GM EDIFACT
    end if;
    --								    Republic(1104 shipment as as woodhaven, and Gerstenslager 1401
    --								    Karmax(1149),WindsorMatchPlate(1388)
    --elsif l_des_sh_cust_id in (51,77,71,78,41,79, 1347, 1382, 1383, 1104, 1401, 1388, 1149, 1579) then  --Ford
    --Delete 1382 per Alcan 03/29/04  by Tony

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin

    --rr_856 := 100; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY
    --rr_desadv := 500; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY


    if rr_856 = 1 and rr_desadv = 1 then
       return 1;
    elsif rr_desadv = 100 then --"EDI previously sent.".
			       --Should not happen though
			       --because this validation "IF NOT (l_ship_date IS NULL) THEN"
			       --is done above.
       return 100;
    elsif rr_desadv = 200 then --Not the right customer.
			       --Should not happent though because this check is done
			       --in this function above, just before edi_alcan_alcan_856_x12() is called
       return 200;
    else
       if rr_856 = -1 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_desadv = -1 then
	  insert into dbo.error_message values('f_edi_desadv2. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_desadv = 500 then
	  insert into dbo.error_message values('f_edi_desadv2. Customer DUNS not set up in table customer. Please set it up.');
       end if;

       if rr_856 = 100 then
	   insert into dbo.error_message values('edi_alcan_alcan_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
	end if;

       if rr_desadv = -3 then
	  select  shipment.des_sh_cust_id, customer.customer_short_name
	  into	  ll_des_sh_cust_id, ls_customer_short_name
	  from	  shipment
	  join	  customer on customer.customer_id = shipment.des_sh_cust_id
	  where   shipment.packing_list = packing_list_no;

	  insert into dbo.error_message values('f_edi_desadv2. Communication code is NOT set up in table customer_system for Destination Customer ' || to_char(l_des_sh_cust_id) || '-' || ls_customer_short_name);
       end if;

       commit; --This commit is for table dbo.error_message that is populated above

       if rr_856 <> 1 and rr_desadv <> 1 then
	  if rr_desadv <> 500 then
	     return -8; --Both, customer 856 and OEM files not created
	  else
	     return -15; --Only customer file not created. OEM file is created, but customer.customer_duns_number_string not set up for customer
	  end if;
       else --one of them is not 1
	  if rr_856 <> 1 then
	     return -7;
	  else --rr_desadv <> 1
	     if rr_desadv = 500 then
		return -16; --OEM file is created, but customer.customer_duns_number_string not set up for customer
	     else
		return -6; --OEM file not created
	     end if;
	  end if;
       end if;
    end if;
    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  ELSIF l_des_sh_cust_id IN
	(51, 77, 71, 78, 41, 79, 1347, 1383, 1104, 1401, 1388, 1149, 1579) THEN
    --Ford

    rr_ford := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
    rr_856 := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "rr" with "rr_856"
    rr_856 := edi_alcan_ford_856_x12(packing_list_no); --Send Ford

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
    --rr_desadv := edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    rr_856 := edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin
    if rr_ford = 1 and rr_856 = 1 then
       return 1;
    else --rr_ford <> 1 or rr_856 <> 1
       if rr_ford = -1 then
	  insert into dbo.error_message values('edi_alcan_ford_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_856 = -1 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_ford = 200 then
	  insert into dbo.error_message values('edi_alcan_ford_856_x12. Customer does NOT require EDI transaction. Customer or destination customer DUNS not set up in table customer.');
       end if;

       if rr_856 = 200 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Customer does NOT require EDI transaction. Customer or destination customer DUNS not set up in table customer.');
       end if;

       if rr_856 = 100 then
	   insert into dbo.error_message values('edi_alcan_alcan_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
       end if;

       if rr_ford = 100 then
	   insert into dbo.error_message values('edi_alcan_ford_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
       end if;

       commit; --This commit is for table dbo.error_message that is populated above

       if rr_ford <> 1 and rr_856 <> 1 then
	  return -11;
       else --one of them is not 1
	  if rr_ford <> 1 then
	     return -10;
	  else
	     return -9;
	  end if;
       end if;
    end if;
    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  ELSIF l_customer_id = 188 THEN
    --Kaiser
    RETURN edi_kaiser_856(packing_list_no);

  ELSIF l_des_sh_cust_id = 1096 THEN
    --BUDD Company or Eagle Steel
    --	      return edi_alcan_ford_856_x12(packing_list_no);
    --rr:=edi_alcan_budd_856(packing_list_no);		 --Send Budd per budd and eagle, they no longer receive ASN from ABC
    --rr:= edi_alcan_ford_856_x12(packing_list_no);  --Send Eagle using Ford code
    --RETURN edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    return edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Noveli

  ELSIF l_des_sh_cust_id = 1251 THEN
    --Eagle steel, send to Budd and Eagle(ford format)
    --rr:=edi_alcan_budd_856(packing_list_no);	-- per budd and eagle, they no longer receive ASN from ABC
    --rr:= edi_alcan_ford_856_x12(packing_list_no);  --Send Eagle using Ford code
    --return rr;
    --RETURN edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    return edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis

    --elsif l_des_sh_cust_id = 79 then			--WSDC send Alcan only
    --	    return edi_alcan_alcan_856_x12(packing_list_no);

  --Alex Gerlants. 09/27/2021. Added 2950 - Novelis-Guthrey
  ELSIF l_customer_id IN (35, 10, 1153, 1459, 2582, 2950) THEN
    SELECT MAX(sc_packing_item)
      INTO scrap_item
      FROM scrap_packing_item
     WHERE packing_list = packing_list_no;
    IF scrap_item > 0 THEN
      --RETURN edi_alcan_alcan_scrap_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
      return edi_novelis_scrap_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis
    ELSE -- All else destination send Alcan only
      --RETURN edi_alcan_alcan_856_x12(packing_list_no);  --Alex Gerlants. 02/05/2019. Commented out
      return edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis
    END IF;

  ELSIF l_des_sh_cust_id = 45 THEN
    RETURN edi_alcoa_hayes_856_x12(packing_list_no);
  ELSE
    RETURN 200;
  END IF;

EXCEPTION
  WHEN exce_sent THEN
    --	  raise_application_error(-20101,'STOP! EDI had been sent');
    RETURN 100;
  WHEN exce_nodata THEN
    --	   raise_application_error(-20101,'No shipment data found!');
    RETURN - 1;
  WHEN exce_des_sh_cust_id THEN
    --	  raise_application_error(-20101,'This shipment does not required EDIFACT DESADV EDI!');
    RETURN 200;
  WHEN OTHERS THEN
    --	  raise_application_error(-20101,'INTERNAL ERROR! PLEASE CALL 1519.');
    RETURN - 1;

  --   return l_return;
END;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_EDI_856_11132017" (packing_list_no shipment.packing_list%TYPE)
  RETURN INTEGER IS
  /*
  Returns:   Integer
		 1 = if it succeeds
		-1 = if a system error occurs
	       100 = EDI had aleady been sent
	       200 = No EDI defined

  Customer: ALCAN(34,35,10)
  Alcan Rolled Product	  X.121       0015049350011G
  End User: Ford (ZZ F159B)
	    Ford Chicago Stamping Plant(51) MS02A
	    Ford Walton Hills Stamping Plant(77) MS03A
	    Ford Woodhaven Stamping Plant(71) AF30A MS09A
	    Ford Maumee Stamping Plant(78)    AF06A MS08A
	    Republic same as Ford WoodHaven
	    Ford Ogihara  (1579)	   F7BFC

	    (not in use)Ford Monroe Stamping		  AP06A

	    (not in use) Warehouses: IDS(41)		   R5G3B
	    (not in use) Wayne Steel Distribution Center(79) RWSDC


  Customer Alcan for GM send EDIFACT DESADV
      End user: Grand Rapid
		Pontiac plant 14
		Pontiac Plant 15
		GM Lansing Stamping 1840

  Customer Kaiser(45) send x12
      End User: Kaiser
		Capital Tech
		Hayes
		Hayes/Northville
		Lorbec (Scrap)
  Customer Alcoa Texacana(1188) End User Hayes(45) send X12 4010
  */

  --l_return number(5);
  exce_des_sh_cust_id EXCEPTION;
  exce_nodata	      EXCEPTION;
  exce_sent	      EXCEPTION;

  l_customer_id    INTEGER;
  l_des_sh_cust_id INTEGER;
  l_enduser_id	   INTEGER;
  rr		   INTEGER;
  scrap_item	   INTEGER;
  l_ship_date	   DATE;
--  ll_packing_list  shipment.packing_list%TYPE;
  ll_bol	   shipment.bill_of_lading%TYPE;
  CURSOR packing_list_same_bol IS
    SELECT packing_list
      FROM shipment
     WHERE shipment.bill_of_lading = ll_bol
       AND shipment.shipment_status <> 3;
  ll_temp INTEGER;
BEGIN
  edi_alcan_870;

--   ll_packing_list := packing_list_no;
  SELECT shipment.bill_of_lading,
	 customer_id,
	 des_sh_cust_id,
	 shipment_enduser_id,
	 shipment_status
    INTO ll_bol, l_customer_id, l_des_sh_cust_id, l_enduser_id, ll_temp
    FROM shipment
   WHERE shipment.packing_list = packing_list_no;
  IF NOT SQL%FOUND THEN
    RETURN - 1;
  END IF;

  IF ll_temp <> 0 THEN
    RETURN packing_list_no;
  END IF;

  IF (l_customer_id in (1429, 2795, 2830)) THEN
    --SAMUEL-HAMILTON, SAMUEL-TENN, SAMUEL-COLUMBIA
    RETURN f_edi_desadv_bolt(packing_list_no);
  END IF;

  IF NOT (l_customer_id IN (10, 34, 35, 188, 1153, 1188, 1364, 1459, 1980, 2505, 2582)) THEN
    --1459 Alcan Oswego, 1364 Wise Alloys
    RETURN 200;
  END IF;

  SELECT shipment_edi856_date
    INTO l_ship_date
    FROM shipment
   WHERE shipment.packing_list = packing_list_no;
  IF NOT (l_ship_date IS NULL) THEN
    RETURN 100;
  END IF;

  --Check all packing_lists are done or cancel against a BOL
  FOR pl_rec IN packing_list_same_bol LOOP
    SELECT shipment.shipment_status
      INTO ll_temp
      FROM shipment
     WHERE shipment.packing_list = pl_rec.packing_list;
    IF ll_temp <> 0 THEN
      RETURN pl_rec.packing_list;
    END IF;
  END LOOP;
  --End of packing list checking

  scrap_item := 0;

  --add by Victor Huang for "Wise Alloys"
  IF (l_customer_id = 1364) THEN
    --1364 Wise Alloys
    RETURN edi_wise_856(packing_list_no);
  END IF;


   --add by James Ni for "Aleris"
  IF (l_customer_id = 1980) THEN
     RETURN edi_aleris_856_x12_multi_po(packing_list_no);
  END IF;

  --Alex Gerlants. 09/20/2017. Added '2850' to the list below
  IF ((l_des_sh_cust_id IN -- if the destination we are shipping to is in this list...
     (69, 70, 2850, 72, 1840, 2079, 2164, 2181, 2360, 2495, 2611, 2680, 2814)) OR (l_customer_id = 2505)) THEN
    --GM
    IF (l_customer_id != 2505) THEN
	rr := edi_alcan_alcan_856_x12(packing_list_no); --Send Alcan X12
    END IF;
    RETURN f_edi_desadv2(packing_list_no); --Send GM EDIFACT
    --								    Republic(1104 shipment as as woodhaven, and Gerstenslager 1401
    --								    Karmax(1149),WindsorMatchPlate(1388)
    --elsif l_des_sh_cust_id in (51,77,71,78,41,79, 1347, 1382, 1383, 1104, 1401, 1388, 1149, 1579) then  --Ford
    --Delete 1382 per Alcan 03/29/04  by Tony
  ELSIF l_des_sh_cust_id IN
	(51, 77, 71, 78, 41, 79, 1347, 1383, 1104, 1401, 1388, 1149, 1579) THEN
    --Ford

    rr := edi_alcan_ford_856_x12(packing_list_no); --Send Ford
    RETURN edi_alcan_alcan_856_x12(packing_list_no); --Send Alcan

  ELSIF l_customer_id = 188 THEN
    --Kaiser
    RETURN edi_kaiser_856(packing_list_no);

  ELSIF l_des_sh_cust_id = 1096 THEN
    --BUDD Company or Eagle Steel
    --	      return edi_alcan_ford_856_x12(packing_list_no);
    --rr:=edi_alcan_budd_856(packing_list_no);		 --Send Budd per budd and eagle, they no longer receive ASN from ABC
    --rr:= edi_alcan_ford_856_x12(packing_list_no);  --Send Eagle using Ford code
    RETURN edi_alcan_alcan_856_x12(packing_list_no); --Send Alcan

  ELSIF l_des_sh_cust_id = 1251 THEN
    --Eagle steel, send to Budd and Eagle(ford format)
    --rr:=edi_alcan_budd_856(packing_list_no);	-- per budd and eagle, they no longer receive ASN from ABC
    --rr:= edi_alcan_ford_856_x12(packing_list_no);  --Send Eagle using Ford code
    --return rr;
    RETURN edi_alcan_alcan_856_x12(packing_list_no); --Send Alcan

    --elsif l_des_sh_cust_id = 79 then			--WSDC send Alcan only
    --	    return edi_alcan_alcan_856_x12(packing_list_no);

  ELSIF l_customer_id IN (35, 10, 1153, 1459, 2582) THEN
    SELECT MAX(sc_packing_item)
      INTO scrap_item
      FROM scrap_packing_item
     WHERE packing_list = packing_list_no;
    IF scrap_item > 0 THEN
      RETURN edi_alcan_alcan_scrap_856_x12(packing_list_no);
    ELSE
      RETURN edi_alcan_alcan_856_x12(packing_list_no); -- All else destination send Alcan only
    END IF;

  ELSIF l_des_sh_cust_id = 45 THEN
    RETURN edi_alcoa_hayes_856_x12(packing_list_no);
  ELSE
    RETURN 200;
  END IF;

EXCEPTION
  WHEN exce_sent THEN
    --	  raise_application_error(-20101,'STOP! EDI had been sent');
    RETURN 100;
  WHEN exce_nodata THEN
    --	   raise_application_error(-20101,'No shipment data found!');
    RETURN - 1;
  WHEN exce_des_sh_cust_id THEN
    --	  raise_application_error(-20101,'This shipment does not required EDIFACT DESADV EDI!');
    RETURN 200;
  WHEN OTHERS THEN
    --	  raise_application_error(-20101,'INTERNAL ERROR! PLEASE CALL 1519.');
    RETURN - 1;

  --   return l_return;
END;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_EDI_856_RERUN" (packing_list_no shipment.packing_list%TYPE)
  RETURN INTEGER IS
  /*
  Returns:   Integer
		 1 = if it succeeds
		-1 = if a system error occurs
	       100 s_novelis_scrap_142118.edi= EDI had aleady been sent
	       200 = No EDI defined

  Customer: ALCAN(34,35,10)
  Alcan Rolled Product	  X.121       0015049350011G
  End User: Ford (ZZ F159B)
	    Ford Chicago Stamping Plant(51) MS02A
	    Ford Walton Hills Stamping Plant(77) MS03A
	    Ford Woodhaven Stamping Plant(71) AF30A MS09A
	    Ford Maumee Stamping Plant(78)    AF06A MS08A
	    Republic same as Ford WoodHaven
	    Ford Ogihara  (1579)	   F7BFC

	    (not in use)Ford Monroe Stamping		  AP06A

	    (not in use) Warehouses: IDS(41)		   R5G3B
	    (not in use) Wayne Steel Distribution Center(79) RWSDC


  Customer Alcan for GM send EDIFACT DESADV
      End user: Grand Rapid
		Pontiac plant 14
		Pontiac Plant 15
		GM Lansing Stamping 1840

  Customer Kaiser(45) send x12
      End User: Kaiser
		Capital Tech
		Hayes
		Hayes/Northville
		Lorbec (Scrap)
  Customer Alcoa Texacana(1188) End User Hayes(45) send X12 4010
  */

  --l_return number(5);
  exce_des_sh_cust_id EXCEPTION;
  exce_nodata	      EXCEPTION;
  exce_sent	      EXCEPTION;

  l_customer_id    INTEGER;
  l_des_sh_cust_id INTEGER;
  l_enduser_id	   INTEGER;
  rr		   INTEGER;
  scrap_item	   INTEGER;
  l_ship_date	   DATE;

  ll_bol	   shipment.bill_of_lading%TYPE;

  rr_856		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  rr_desadv		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  rr_ford		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  ll_des_sh_cust_id	    shipment.des_sh_cust_id%TYPE;	--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  ls_customer_short_name    customer.customer_short_name%TYPE;	--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

  ll_count		    integer;				--Alex Gerlants. novelis testing
  li_coil_status	    coil.coil_status%TYPE;		--Alex Gerlants. 02/05/2019. Added for Novelis
  li_coil_status_count	    integer;				--Alex Gerlants. 07/17/2020. 856 rerun
  rr_rejcoil		    integer;				--Alex Gerlants. 02/05/2019. Added for Novelis
  li_is_constellium	    integer;				--Alex Gerlants. Constellium EDI 856

  CURSOR packing_list_same_bol IS
    SELECT packing_list
      FROM shipment
     WHERE shipment.bill_of_lading = ll_bol
       AND shipment.shipment_status <> 3;
  ll_temp INTEGER;
BEGIN

  --delete from dbo.error_message; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

  --edi_alcan_870;

  SELECT shipment.bill_of_lading,
	 customer_id,
	 des_sh_cust_id,
	 shipment_enduser_id,
	 shipment_status
    INTO ll_bol, l_customer_id, l_des_sh_cust_id, l_enduser_id, ll_temp
    FROM shipment
   WHERE shipment.packing_list = packing_list_no;
  IF NOT SQL%FOUND THEN
    RETURN - 1;
  END IF;

  IF ll_temp <> 0 THEN
    RETURN packing_list_no;
  END IF;

  --Alex Gerlants. 06/13/2019. Arconic EDI. Added IF statement below for 2784-Arconic-TN
  if (l_customer_id in (2784)) then
    return edi_arconic_856_X12_rerun(packing_list_no);
  end if;

  --Alex Gerlants. Constellium EDI 856. Begin
  select dbo.f_is_constellium(packing_list_no)
  into	 li_is_constellium
  from	 dual;

  if li_is_constellium = 1 then --Customer is Constellium
    return edi_const_856_X12_rerun(packing_list_no);
  end if;
  --Alex Gerlants. Constellium EDI 856. End

  --Alex Gerlants. 10/22/2019. Begin
  --This is a temporary measure to help Arconic Davenport.
  --It is commented out in Production until they tell us to activate it.
  /*
  if (l_customer_id in (50)) then --Arconic Davenport
     if l_des_sh_cust_id in (69, 70, 2850, 72, 1840, 2079, 2164, 2181, 2360, 1648, 2495, 2611, 2680, 2814) then

       return f_edi_desadv2_arconic_davenprt(packing_list_no); --Send GM EDIFACT
     end if;
  end if; --if (l_customer_id in (50) then
  */
  --Alex Gerlants. 10/22/2019. End

  --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
  --Alex Gerlants. 12/04/2017. Added "2776" to the line below. Shipping to GM
  IF (l_customer_id in (1429, 2795, 2830, 2776)) THEN
    --SAMUEL-HAMILTON, SAMUEL-TENN, SAMUEL-COLUMBIA
    --rr_desadv := f_edi_desadv_bolt(packing_list_no); --Alex Gerlants. 07/17/2020. 856 rerun. Comment out

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin
    --rr_desadv := 200; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY

    if rr_desadv = 1 or rr_desadv = 100 then --"EDI generated successfully" or "EDI previously sent."
      return rr_desadv;
    else
      if rr_desadv = -1 then
	 insert into dbo.error_message values('f_edi_desadv_bolt. Packing list ' || to_char(packing_list_no) || ' does not exist');
	 commit;
	 return -14;
      elsif rr_desadv = -3 then
	 select  shipment.des_sh_cust_id, customer.customer_short_name
	 into	 ll_des_sh_cust_id, ls_customer_short_name
	 from	 shipment
	 join	 customer on customer.customer_id = shipment.des_sh_cust_id
	 where	 shipment.packing_list = packing_list_no;

	 insert into dbo.error_message values('f_edi_desadv_bolt. Communication code is NOT set up in table customer_system for Destination Customer ' || to_char(l_des_sh_cust_id) || '-' || ls_customer_short_name);
	 commit;
	 return -13;
       elsif rr_desadv = 200 then
	 insert into dbo.error_message values('f_edi_desadv_bolt. Customer DUNS not set up in table customer.');
	 commit;
	 return -12;
       else
	  return rr_desadv;
       end if;
     end if;
     --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  END IF;

  IF NOT (l_customer_id IN (10, 34, 35, 188, 1153, 1188, 1364, 1459, 1980, 2505, 2582)) THEN
    --1459 Alcan Oswego, 1364 Wise Alloys
    RETURN 200;
  END IF;

  /*
  SELECT shipment_edi856_date
    INTO l_ship_date
    FROM shipment
   WHERE shipment.packing_list = packing_list_no;
  IF NOT (l_ship_date IS NULL) THEN
    RETURN 100;
  END IF;
  */

  --Check all packing_lists are done or cancel against a BOL
  /*
  FOR pl_rec IN packing_list_same_bol LOOP
    SELECT shipment.shipment_status
      INTO ll_temp
      FROM shipment
     WHERE shipment.packing_list = pl_rec.packing_list;
    IF ll_temp <> 0 THEN
      RETURN pl_rec.packing_list;
    END IF;
  END LOOP;
  */
  --End of packing list checking

  --------------------------------------------------------------------------


  --Alex Gerlants. 02/05/2019. Added for Novelis
  select count(*)
  into	 ll_count
  from	 reject_coil_packing_item
	 join coil on coil.coil_abc_num = reject_coil_packing_item.coil_abc_num
	 join shipment on shipment.packing_list = reject_coil_packing_item.packing_list
	 join customer on customer.customer_id = shipment.customer_id
  where  shipment.packing_list = packing_list_no;

  if ll_count > 0 then

    /*
    select customer.customer_short_name, max(coil.coil_status)
    into   ls_customer_short_name, li_coil_status
    from   reject_coil_packing_item
	   join coil on coil.coil_abc_num = reject_coil_packing_item.coil_abc_num
	   join shipment on shipment.packing_list = reject_coil_packing_item.packing_list
	   join customer on customer.customer_id = shipment.customer_id
    where  shipment.packing_list = packing_list_no
    group by customer.customer_short_name;
    */

    select customer.customer_short_name, max(coil_track.coil_pre_status)
    into   ls_customer_short_name, li_coil_status
    from   reject_coil_packing_item
	   join coil on coil.coil_abc_num = reject_coil_packing_item.coil_abc_num
	   join shipment on shipment.packing_list = reject_coil_packing_item.packing_list
	   join coil_track on coil.coil_abc_num = coil_track.coil_abc_num
	   join customer on customer.customer_id = shipment.customer_id
    where  shipment.packing_list = packing_list_no
    and    coil_track_date = (select max(coil_track_date) from coil_track where coil_abc_num = coil.coil_abc_num)
    group by customer.customer_short_name;

    if lower(ls_customer_short_name) like '%novelis%' then
      if li_coil_status in (3, 6, 14) then --Rejected coil (3), Return coil (6), Scrap coil (14)
	   rr_rejcoil := edi_novelis_rejcoil_856_rerun(packing_list_no);
	   return rr_rejcoil;
      else --coi_status is other than Rejected coil (3), Return coil (6), Scrap coil (14)
	return 100; --"EDI previously sent.".
		    --Should not happen though
		    --because this validation "IF NOT (l_ship_date IS NULL) THEN"
		    --is done above.
      end if;
    else--Not Novelis. We send ASN for these coils to Novelis only.
      return 1; --Nothing to do here
    end if;
  end if;

  --------------------------------------------------------------------------

  scrap_item := 0;

  --add by Victor Huang for "Wise Alloys"
  --Alex Gerlants. 07/17/2020. 856 rerun. Comment out begin
  --IF (l_customer_id = 1364) THEN
    --1364 Wise Alloys
  --  RETURN edi_wise_856(packing_list_no);
  --END IF;
  --Alex Gerlants. 07/17/2020. 856 rerun. Comment out end


   --add by James Ni for "Aleris"
  --Alex Gerlants. 07/17/2020. 856 rerun. Comment out begin
  --IF (l_customer_id = 1980) THEN
  --   RETURN edi_aleris_856_x12_multi_po(packing_list_no);
  --END IF;
  --Alex Gerlants. 07/17/2020. 856 rerun. Comment out end

  --Alex Gerlants. 09/20/2017. Added '2850' to the list below
  --Alex Gerlants. 05/13/2019. Added '2903' to the list below
  --Alex Gerlants. 05/14/2019. Added '2906' to the list below
  IF ((l_des_sh_cust_id IN -- if the destination we are shipping to is in this list...
     (69, 70, 2850, 72, 1840, 2079, 2164, 2181, 2360, 2495, 2611, 2680, 2814, 2903, 2906)) OR (l_customer_id = 2505)) THEN
    --GM

    rr_856 := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
    rr_desadv := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

    IF (l_customer_id != 2505) THEN
      --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "rr" with "rr_856"
	--rr_856 := edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
	rr_856 := edi_novelis_856_rerun(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis
    END IF;

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
    --Alex Gerlants. 04/09/2019. Do not run f_edi_desadv2 for Novelis.
    select distinct customer.customer_short_name
    into   ls_customer_short_name
    from   shipment
	   join customer on customer.customer_id = shipment.customer_id
    where  shipment.packing_list = packing_list_no;

    --Alex Gerlants. 07/17/2020. 856 rerun. Comment out begin
    --if lower(ls_customer_short_name) not like '%novelis%' then
    --	 rr_desadv := f_edi_desadv2(packing_list_no); --Send GM EDIFACT
    --end if;
    --Alex Gerlants. 07/17/2020. 856 rerun. Comment out end
    --								    Republic(1104 shipment as as woodhaven, and Gerstenslager 1401
    --								    Karmax(1149),WindsorMatchPlate(1388)
    --elsif l_des_sh_cust_id in (51,77,71,78,41,79, 1347, 1382, 1383, 1104, 1401, 1388, 1149, 1579) then  --Ford
    --Delete 1382 per Alcan 03/29/04  by Tony

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin

    --rr_856 := 100; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY
    --rr_desadv := 500; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY


    if rr_856 = 1 and rr_desadv = 1 then
       return 1;
    elsif rr_desadv = 100 then --"EDI previously sent.".
			       --Should not happen though
			       --because this validation "IF NOT (l_ship_date IS NULL) THEN"
			       --is done above.
       return 100;
    elsif rr_desadv = 200 then --Not the right customer.
			       --Should not happent though because this check is done
			       --in this function above, just before edi_alcan_alcan_856_x12() is called
       return 200;
    else
       if rr_856 = -1 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_desadv = -1 then
	  insert into dbo.error_message values('f_edi_desadv2. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_desadv = 500 then
	  insert into dbo.error_message values('f_edi_desadv2. Customer DUNS not set up in table customer. Please set it up.');
       end if;

       if rr_856 = 100 then
	   insert into dbo.error_message values('edi_alcan_alcan_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
	end if;

       if rr_desadv = -3 then
	  select  shipment.des_sh_cust_id, customer.customer_short_name
	  into	  ll_des_sh_cust_id, ls_customer_short_name
	  from	  shipment
	  join	  customer on customer.customer_id = shipment.des_sh_cust_id
	  where   shipment.packing_list = packing_list_no;

	  insert into dbo.error_message values('f_edi_desadv2. Communication code is NOT set up in table customer_system for Destination Customer ' || to_char(l_des_sh_cust_id) || '-' || ls_customer_short_name);
       end if;

       commit; --This commit is for table dbo.error_message that is populated above

       if rr_856 <> 1 and rr_desadv <> 1 then
	  if rr_desadv <> 500 then
	     return -8; --Both, customer 856 and OEM files not created
	  else
	     return -15; --Only customer file not created. OEM file is created, but customer.customer_duns_number_string not set up for customer
	  end if;
       else --one of them is not 1
	  if rr_856 <> 1 then
	     return -7;
	  else --rr_desadv <> 1
	     if rr_desadv = 500 then
		return -16; --OEM file is created, but customer.customer_duns_number_string not set up for customer
	     else
		return -6; --OEM file not created
	     end if;
	  end if;
       end if;
    end if;
    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  ELSIF l_des_sh_cust_id IN
	(51, 77, 71, 78, 41, 79, 1347, 1383, 1104, 1401, 1388, 1149, 1579) THEN
    --Ford

    rr_ford := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
    rr_856 := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "rr" with "rr_856"
    --rr_856 := edi_alcan_ford_856_x12(packing_list_no); --Send Ford

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
    --rr_desadv := edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    rr_856 := edi_novelis_856_rerun(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin
    if rr_ford = 1 and rr_856 = 1 then
       return 1;
    else --rr_ford <> 1 or rr_856 <> 1
       if rr_ford = -1 then
	  insert into dbo.error_message values('edi_alcan_ford_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_856 = -1 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_ford = 200 then
	  insert into dbo.error_message values('edi_alcan_ford_856_x12. Customer does NOT require EDI transaction. Customer or destination customer DUNS not set up in table customer.');
       end if;

       if rr_856 = 200 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Customer does NOT require EDI transaction. Customer or destination customer DUNS not set up in table customer.');
       end if;

       if rr_856 = 100 then
	   insert into dbo.error_message values('edi_alcan_alcan_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
       end if;

       if rr_ford = 100 then
	   insert into dbo.error_message values('edi_alcan_ford_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
       end if;

       commit; --This commit is for table dbo.error_message that is populated above

       if rr_ford <> 1 and rr_856 <> 1 then
	  return -11;
       else --one of them is not 1
	  if rr_ford <> 1 then
	     return -10;
	  else
	     return -9;
	  end if;
       end if;
    end if;
    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  --ELSIF l_customer_id = 188 THEN
    --Kaiser
    --RETURN edi_kaiser_856(packing_list_no);

  ELSIF l_des_sh_cust_id = 1096 THEN
    --BUDD Company or Eagle Steel
    --	      return edi_alcan_ford_856_x12(packing_list_no);
    --rr:=edi_alcan_budd_856(packing_list_no);		 --Send Budd per budd and eagle, they no longer receive ASN from ABC
    --rr:= edi_alcan_ford_856_x12(packing_list_no);  --Send Eagle using Ford code
    --RETURN edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    return edi_novelis_856_rerun(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Noveli

  ELSIF l_des_sh_cust_id = 1251 THEN
    --Eagle steel, send to Budd and Eagle(ford format)
    --rr:=edi_alcan_budd_856(packing_list_no);	-- per budd and eagle, they no longer receive ASN from ABC
    --rr:= edi_alcan_ford_856_x12(packing_list_no);  --Send Eagle using Ford code
    --return rr;
    --RETURN edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    return edi_novelis_856_rerun(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis

    --elsif l_des_sh_cust_id = 79 then			--WSDC send Alcan only
    --	    return edi_alcan_alcan_856_x12(packing_list_no);

  ELSIF l_customer_id IN (35, 10, 1153, 1459, 2582) THEN
    SELECT MAX(sc_packing_item)
      INTO scrap_item
      FROM scrap_packing_item
     WHERE packing_list = packing_list_no;
    IF scrap_item > 0 THEN
      --RETURN edi_alcan_alcan_scrap_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
      return edi_novelis_scrap_856_rerun(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis
    ELSE -- All else destination send Alcan only
      --RETURN edi_alcan_alcan_856_x12(packing_list_no);  --Alex Gerlants. 02/05/2019. Commented out
      return edi_novelis_856_rerun(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis
    END IF;

  --ELSIF l_des_sh_cust_id = 45 THEN
  --  RETURN edi_alcoa_hayes_856_x12(packing_list_no);
  ELSE
    RETURN 200;
  END IF;

EXCEPTION
  WHEN exce_sent THEN
    --	  raise_application_error(-20101,'STOP! EDI had been sent');
    RETURN 100;
  WHEN exce_nodata THEN
    --	   raise_application_error(-20101,'No shipment data found!');
    RETURN - 1;
  WHEN exce_des_sh_cust_id THEN
    --	  raise_application_error(-20101,'This shipment does not required EDIFACT DESADV EDI!');
    RETURN 200;
  WHEN OTHERS THEN
    --	  raise_application_error(-20101,'INTERNAL ERROR! PLEASE CALL 1519.');
    RETURN - 1;

  --   return l_return;
END;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_EDI_856_TEST" (packing_list_no shipment.packing_list%TYPE)
  RETURN INTEGER IS
  /*
  Returns:   Integer
		 1 = if it succeeds
		-1 = if a system error occurs
	       100 = EDI had aleady been sent
	       200 = No EDI defined

  Customer: ALCAN(34,35,10)
  Alcan Rolled Product	  X.121       0015049350011G
  End User: Ford (ZZ F159B)
	    Ford Chicago Stamping Plant(51) MS02A
	    Ford Walton Hills Stamping Plant(77) MS03A
	    Ford Woodhaven Stamping Plant(71) AF30A MS09A
	    Ford Maumee Stamping Plant(78)    AF06A MS08A
	    Republic same as Ford WoodHaven
	    Ford Ogihara  (1579)	   F7BFC

	    (not in use)Ford Monroe Stamping		  AP06A

	    (not in use) Warehouses: IDS(41)		   R5G3B
	    (not in use) Wayne Steel Distribution Center(79) RWSDC


  Customer Alcan for GM send EDIFACT DESADV
      End user: Grand Rapid
		Pontiac plant 14
		Pontiac Plant 15
		GM Lansing Stamping 1840

  Customer Kaiser(45) send x12
      End User: Kaiser
		Capital Tech
		Hayes
		Hayes/Northville
		Lorbec (Scrap)
  Customer Alcoa Texacana(1188) End User Hayes(45) send X12 4010
  */

  --l_return number(5);
  exce_des_sh_cust_id EXCEPTION;
  exce_nodata	      EXCEPTION;
  exce_sent	      EXCEPTION;

  l_customer_id    INTEGER;
  l_des_sh_cust_id INTEGER;
  l_enduser_id	   INTEGER;
  rr		   INTEGER;
  scrap_item	   INTEGER;
  l_ship_date	   DATE;

  ll_bol	   shipment.bill_of_lading%TYPE;

  rr_856		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  rr_desadv		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  rr_ford		    integer;				--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  ll_des_sh_cust_id	    shipment.des_sh_cust_id%TYPE;	--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
  ls_customer_short_name    customer.customer_short_name%TYPE;	--Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

  ll_count		    integer;				--Alex Gerlants. novelis testing
  li_coil_status	    coil.coil_status%TYPE;		--Alex Gerlants. 02/05/2019. Added for Novelis
  rr_rejcoil		    integer;				--Alex Gerlants. 02/05/2019. Added for Novelis
  li_is_constellium	    integer;				--Alex Gerlants. Constellium EDI 856

  CURSOR packing_list_same_bol IS
    SELECT packing_list
      FROM shipment
     WHERE shipment.bill_of_lading = ll_bol
       AND shipment.shipment_status <> 3;
  ll_temp INTEGER;
BEGIN

  delete from dbo.error_message; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

  edi_alcan_870;

  SELECT shipment.bill_of_lading,
	 customer_id,
	 des_sh_cust_id,
	 shipment_enduser_id,
	 shipment_status
    INTO ll_bol, l_customer_id, l_des_sh_cust_id, l_enduser_id, ll_temp
    FROM shipment
   WHERE shipment.packing_list = packing_list_no;
  IF NOT SQL%FOUND THEN
    RETURN - 1;
  END IF;

  IF ll_temp <> 0 THEN
    RETURN packing_list_no;
  END IF;

  --Alex Gerlants. 06/13/2019. Arconic EDI. Added IF statement below for 2784-Arconic-TN
  if (l_customer_id in (2784)) then
    return edi_arconic_856_X12(packing_list_no);
  end if;

  --Alex Gerlants. Constellium EDI 856. Begin
  select dbo.f_is_constellium(packing_list_no)
  into	 li_is_constellium
  from	 dual;

  if li_is_constellium = 1 then --Customer is Constellium
    return edi_const_856_X12(packing_list_no);
  end if;
  --Alex Gerlants. Constellium EDI 856. End

  --Alex Gerlants. 10/22/2019. Begin
  --This is a temporary measure to help Arconic Davenport.
  --It is commented out in Production until they tell us to activate it.
  /*
  if (l_customer_id in (50)) then --Arconic Davenport
     if l_des_sh_cust_id in (69, 70, 2850, 72, 1840, 2079, 2164, 2181, 2360, 1648, 2495, 2611, 2680, 2814) then

       return f_edi_desadv2_arconic_davenprt(packing_list_no); --Send GM EDIFACT
     end if;
  end if; --if (l_customer_id in (50) then
  */
  --Alex Gerlants. 10/22/2019. End

  --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
  --Alex Gerlants. 12/04/2017. Added "2776" to the line below. Shipping to GM
  IF (l_customer_id in (1429, 2795, 2830, 2776)) THEN
    --SAMUEL-HAMILTON, SAMUEL-TENN, SAMUEL-COLUMBIA
    rr_desadv := f_edi_desadv_bolt(packing_list_no);

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin
    --rr_desadv := 200; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY

    if rr_desadv = 1 or rr_desadv = 100 then --"EDI generated successfully" or "EDI previously sent."
      return rr_desadv;
    else
      if rr_desadv = -1 then
	 insert into dbo.error_message values('f_edi_desadv_bolt. Packing list ' || to_char(packing_list_no) || ' does not exist');
	 commit;
	 return -14;
      elsif rr_desadv = -3 then
	 select  shipment.des_sh_cust_id, customer.customer_short_name
	 into	 ll_des_sh_cust_id, ls_customer_short_name
	 from	 shipment
	 join	 customer on customer.customer_id = shipment.des_sh_cust_id
	 where	 shipment.packing_list = packing_list_no;

	 insert into dbo.error_message values('f_edi_desadv_bolt. Communication code is NOT set up in table customer_system for Destination Customer ' || to_char(l_des_sh_cust_id) || '-' || ls_customer_short_name);
	 commit;
	 return -13;
       elsif rr_desadv = 200 then
	 insert into dbo.error_message values('f_edi_desadv_bolt. Customer DUNS not set up in table customer.');
	 commit;
	 return -12;
       else
	  return rr_desadv;
       end if;
     end if;
     --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  END IF;

  IF NOT (l_customer_id IN (10, 34, 35, 188, 1153, 1188, 1364, 1459, 1980, 2505, 2582)) THEN
    --1459 Alcan Oswego, 1364 Wise Alloys
    RETURN 200;
  END IF;

  SELECT shipment_edi856_date
    INTO l_ship_date
    FROM shipment
   WHERE shipment.packing_list = packing_list_no;
  IF NOT (l_ship_date IS NULL) THEN
    RETURN 100;
  END IF;

  --Check all packing_lists are done or cancel against a BOL
  FOR pl_rec IN packing_list_same_bol LOOP
    SELECT shipment.shipment_status
      INTO ll_temp
      FROM shipment
     WHERE shipment.packing_list = pl_rec.packing_list;
    IF ll_temp <> 0 THEN
      RETURN pl_rec.packing_list;
    END IF;
  END LOOP;
  --End of packing list checking

  --Alex Gerlants. 06/30/2020. Begin
  /*
  select  shipment.shipment_status
  into	  ll_temp
  from	  shipment
  where   shipment.packing_list = packing_list_no;

  if ll_temp <> 0 then
    return -15; --Script in Clicked event for cb_edi and cb_1 on w_shipping_2 will issue an error code
  end if;
  */
  --Alex Gerlants. 06/30/2020. End

  --------------------------------------------------------------------------

  --Alex Gerlants. 02/05/2019. Added for Novelis
  select count(*)
  into	 ll_count
  from	 reject_coil_packing_item
	 join coil on coil.coil_abc_num = reject_coil_packing_item.coil_abc_num
	 join shipment on shipment.packing_list = reject_coil_packing_item.packing_list
	 join customer on customer.customer_id = shipment.customer_id
  where  shipment.packing_list = packing_list_no;

  if ll_count > 0 then
    select distinct customer.customer_short_name, coil.coil_status
    into   ls_customer_short_name, li_coil_status
    from   reject_coil_packing_item
	   join coil on coil.coil_abc_num = reject_coil_packing_item.coil_abc_num
	   join shipment on shipment.packing_list = reject_coil_packing_item.packing_list
	   join customer on customer.customer_id = shipment.customer_id
    where  shipment.packing_list = packing_list_no;

    if lower(ls_customer_short_name) like '%novelis%' then
      if li_coil_status in (3, 6, 14) then --Rejected coil (3), Return coil (6), Scrap coil (14)
	   rr_rejcoil := edi_novelis_rejcoil_856_x12(packing_list_no);
	   return rr_rejcoil;
      else --coi_status is other than Rejected coil (3), Return coil (6), Scrap coil (14)
	return 100; --"EDI previously sent.".
		    --Should not happen though
		    --because this validation "IF NOT (l_ship_date IS NULL) THEN"
		    --is done above.
      end if;
    else--Not Novelis. We send ASN for these coils to Novelis only.
      return 1; --Nothing to do here
    end if;
  end if;

  --------------------------------------------------------------------------

  scrap_item := 0;

  --add by Victor Huang for "Wise Alloys"
  IF (l_customer_id = 1364) THEN
    --1364 Wise Alloys
    RETURN edi_wise_856(packing_list_no);
  END IF;


   --add by James Ni for "Aleris"
  IF (l_customer_id = 1980) THEN
     RETURN edi_aleris_856_x12_multi_po(packing_list_no);
  END IF;

  --Alex Gerlants. 09/20/2017. Added '2850' to the list below
  --Alex Gerlants. 05/13/2019. Added '2903' to the list below
  --Alex Gerlants. 05/14/2019. Added '2906' to the list below
  IF ((l_des_sh_cust_id IN -- if the destination we are shipping to is in this list...
     (69, 70, 2850, 72, 1840, 2079, 2164, 2181, 2360, 2495, 2611, 2680, 2814, 2903, 2906)) OR (l_customer_id = 2505)) THEN
    --GM

    rr_856 := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
    rr_desadv := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

    IF (l_customer_id != 2505) THEN
      --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "rr" with "rr_856"
	--rr_856 := edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
	rr_856 := edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis
    END IF;

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
    --Alex Gerlants. 04/09/2019. Do not run f_edi_desadv2 for Novelis.
    select distinct customer.customer_short_name
    into   ls_customer_short_name
    from   shipment
	   join customer on customer.customer_id = shipment.customer_id
    where  shipment.packing_list = packing_list_no;

    if lower(ls_customer_short_name) not like '%novelis%' then
       rr_desadv := f_edi_desadv2(packing_list_no); --Send GM EDIFACT
    end if;
    --								    Republic(1104 shipment as as woodhaven, and Gerstenslager 1401
    --								    Karmax(1149),WindsorMatchPlate(1388)
    --elsif l_des_sh_cust_id in (51,77,71,78,41,79, 1347, 1382, 1383, 1104, 1401, 1388, 1149, 1579) then  --Ford
    --Delete 1382 per Alcan 03/29/04  by Tony

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin

    --rr_856 := 100; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY
    --rr_desadv := 500; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY


    if rr_856 = 1 and rr_desadv = 1 then
       return 1;
    elsif rr_desadv = 100 then --"EDI previously sent.".
			       --Should not happen though
			       --because this validation "IF NOT (l_ship_date IS NULL) THEN"
			       --is done above.
       return 100;
    elsif rr_desadv = 200 then --Not the right customer.
			       --Should not happent though because this check is done
			       --in this function above, just before edi_alcan_alcan_856_x12() is called
       return 200;
    else
       if rr_856 = -1 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_desadv = -1 then
	  insert into dbo.error_message values('f_edi_desadv2. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_desadv = 500 then
	  insert into dbo.error_message values('f_edi_desadv2. Customer DUNS not set up in table customer. Please set it up.');
       end if;

       if rr_856 = 100 then
	   insert into dbo.error_message values('edi_alcan_alcan_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
	end if;

       if rr_desadv = -3 then
	  select  shipment.des_sh_cust_id, customer.customer_short_name
	  into	  ll_des_sh_cust_id, ls_customer_short_name
	  from	  shipment
	  join	  customer on customer.customer_id = shipment.des_sh_cust_id
	  where   shipment.packing_list = packing_list_no;

	  insert into dbo.error_message values('f_edi_desadv2. Communication code is NOT set up in table customer_system for Destination Customer ' || to_char(l_des_sh_cust_id) || '-' || ls_customer_short_name);
       end if;

       commit; --This commit is for table dbo.error_message that is populated above

       if rr_856 <> 1 and rr_desadv <> 1 then
	  if rr_desadv <> 500 then
	     return -8; --Both, customer 856 and OEM files not created
	  else
	     return -15; --Only customer file not created. OEM file is created, but customer.customer_duns_number_string not set up for customer
	  end if;
       else --one of them is not 1
	  if rr_856 <> 1 then
	     return -7;
	  else --rr_desadv <> 1
	     if rr_desadv = 500 then
		return -16; --OEM file is created, but customer.customer_duns_number_string not set up for customer
	     else
		return -6; --OEM file not created
	     end if;
	  end if;
       end if;
    end if;
    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  ELSIF l_des_sh_cust_id IN
	(51, 77, 71, 78, 41, 79, 1347, 1383, 1104, 1401, 1388, 1149, 1579) THEN
    --Ford

    rr_ford := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017
    rr_856 := 1; --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "rr" with "rr_856"
    rr_856 := edi_alcan_ford_856_x12(packing_list_no); --Send Ford

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Replaced "RETURN" with "rr_desadv :="
    --rr_desadv := edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    rr_856 := edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis

    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. Begin
    if rr_ford = 1 and rr_856 = 1 then
       return 1;
    else --rr_ford <> 1 or rr_856 <> 1
       if rr_ford = -1 then
	  insert into dbo.error_message values('edi_alcan_ford_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_856 = -1 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Packing List ' || to_char(packing_list_no) || ' does not exist.');
       end If;

       if rr_ford = 200 then
	  insert into dbo.error_message values('edi_alcan_ford_856_x12. Customer does NOT require EDI transaction. Customer or destination customer DUNS not set up in table customer.');
       end if;

       if rr_856 = 200 then
	  insert into dbo.error_message values('edi_alcan_alcan_856_x12. Customer does NOT require EDI transaction. Customer or destination customer DUNS not set up in table customer.');
       end if;

       if rr_856 = 100 then
	   insert into dbo.error_message values('edi_alcan_alcan_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
       end if;

       if rr_ford = 100 then
	   insert into dbo.error_message values('edi_alcan_ford_856_x12. This shipment ' || to_char(packing_list_no) || ' has zero piece count.');
       end if;

       commit; --This commit is for table dbo.error_message that is populated above

       if rr_ford <> 1 and rr_856 <> 1 then
	  return -11;
       else --one of them is not 1
	  if rr_ford <> 1 then
	     return -10;
	  else
	     return -9;
	  end if;
       end if;
    end if;
    --Alex Gerlants. Communication_Code_Error_Message. 11/01/2017. End

  ELSIF l_customer_id = 188 THEN
    --Kaiser
    RETURN edi_kaiser_856(packing_list_no);

  ELSIF l_des_sh_cust_id = 1096 THEN
    --BUDD Company or Eagle Steel
    --	      return edi_alcan_ford_856_x12(packing_list_no);
    --rr:=edi_alcan_budd_856(packing_list_no);		 --Send Budd per budd and eagle, they no longer receive ASN from ABC
    --rr:= edi_alcan_ford_856_x12(packing_list_no);  --Send Eagle using Ford code
    --RETURN edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    return edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Noveli

  ELSIF l_des_sh_cust_id = 1251 THEN
    --Eagle steel, send to Budd and Eagle(ford format)
    --rr:=edi_alcan_budd_856(packing_list_no);	-- per budd and eagle, they no longer receive ASN from ABC
    --rr:= edi_alcan_ford_856_x12(packing_list_no);  --Send Eagle using Ford code
    --return rr;
    --RETURN edi_alcan_alcan_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
    return edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis

    --elsif l_des_sh_cust_id = 79 then			--WSDC send Alcan only
    --	    return edi_alcan_alcan_856_x12(packing_list_no);

  ELSIF l_customer_id IN (35, 10, 1153, 1459, 2582) THEN
    SELECT MAX(sc_packing_item)
      INTO scrap_item
      FROM scrap_packing_item
     WHERE packing_list = packing_list_no;
    IF scrap_item > 0 THEN
      --RETURN edi_alcan_alcan_scrap_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Commented out
      return edi_novelis_scrap_856_x12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis
    ELSE -- All else destination send Alcan only
      --RETURN edi_alcan_alcan_856_x12(packing_list_no);  --Alex Gerlants. 02/05/2019. Commented out
      return edi_novelis_856_X12(packing_list_no); --Alex Gerlants. 02/05/2019. Added for Novelis
    END IF;

  ELSIF l_des_sh_cust_id = 45 THEN
    RETURN edi_alcoa_hayes_856_x12(packing_list_no);
  ELSE
    RETURN 200;
  END IF;

EXCEPTION
  WHEN exce_sent THEN
    --	  raise_application_error(-20101,'STOP! EDI had been sent');
    RETURN 100;
  WHEN exce_nodata THEN
    --	   raise_application_error(-20101,'No shipment data found!');
    RETURN - 1;
  WHEN exce_des_sh_cust_id THEN
    --	  raise_application_error(-20101,'This shipment does not required EDIFACT DESADV EDI!');
    RETURN 200;
  WHEN OTHERS THEN
    --	  raise_application_error(-20101,'INTERNAL ERROR! PLEASE CALL 1519.');
    RETURN - 1;

  --   return l_return;
END;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_EDI_861_FOR_ALL" RETURN NUMBER IS
  RESULT NUMBER := 1;
BEGIN

  p_create_edi_861_for_all;

  RETURN RESULT;

END f_edi_861_for_all;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_EDI_870_COIL_STATUS_NOVELIS" (al_coil_abc_num coil.coil_abc_num%TYPE,
							 adt_date	 edi_870_coil_status.coil_status_change_date%TYPE)
  RETURN INTEGER IS
  RESULT INTEGER := 1;

  ls_dun VARCHAR2(32);

  li_customer_id  INTEGER := 0;
  ls_coil_org_num VARCHAR2(32);
  ln_cur_net_wt   NUMBER(8, 0);
  ln_width	  NUMBER(10, 5);
  --ln_length number(10,5);
  ln_gauge NUMBER(10, 5);
  ls_po    VARCHAR2(32);
  ls_vo    VARCHAR2(32);

  ls_today_short VARCHAR2(20) := to_char(SYSDATE, 'yymmdd');
  ls_today	 VARCHAR2(20) := to_char(SYSDATE, 'yyyymmdd');
  ls_now	 VARCHAR2(20) := to_char(SYSDATE, 'hh24mi');

  li_gs_log INTEGER;
  li_st_log INTEGER;
  li_hl_num INTEGER := 0;

  TYPE edi_870_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  edi_870 edi_870_tabletype;
  j	  BINARY_INTEGER := 0;
  --k	    BINARY_INTEGER := 0;

  edi_location	  VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 'S_novelis_coil_status_';
  edi_file_handle utl_file.file_type;
  li_edi_870_id   INTEGER;

BEGIN
  SELECT edi_st_log_seq.nextval INTO li_st_log FROM dual;
  SELECT edi_gs_log_seq.nextval INTO li_gs_log FROM dual;

  SELECT c. customer_id,
	 c.coil_org_num,
	 nvl(c.purchase_order_num, 'NA'),
	 nvl(c.supplier_sales_num, 'NA'),
	 c.coil_gauge,
	 c.coil_width
    INTO li_customer_id, ls_coil_org_num, ls_po, ls_vo, ln_gauge, ln_width
    FROM coil c
   WHERE c.coil_abc_num = al_coil_abc_num;

  /*edi_870(j):= 'ISA*00*	   *00* 	 *01*039630926T     *09*0015049350011G *'
  || ls_today_short ||'*'|| ls_now ||'*U*00401*'||LPAD(to_char(li_gs_log),9,'0')|| '*0*P**'; j := j + 1;*/
  edi_870(j) := 'ISA*00*	  *00*		*01*039630926T	   *09*0015049350011G *' ||
		ls_today_short || '*' || ls_now || '*U*00401*' ||
		lpad(to_char(li_gs_log), 9, '0') || '*0*T**';
  j := j + 1;
  edi_870(j) := 'GS*RS*039630926T*001504935001*' || ls_today || '*' ||
		ls_now || '*' || li_gs_log || '*X*004010';
  j := j + 1;
  edi_870(j) := 'ST*870*' || li_st_log;
  j := j + 1;
  edi_870(j) := 'BSR*2*PP*' || li_st_log || '*' || ls_today || '***' ||
		ls_now;
  j := j + 1;
  edi_870(j) := 'DTM*009*' || ls_today || '*' || ls_now;
  j := j + 1;
  IF li_customer_id = 1153 THEN
    ls_dun := '241003755'; --'Novelis Kingston'
  ELSIF li_customer_id = 1459 THEN
    ls_dun := '003980216'; --'Novelis Oswego'
  ELSE
    ls_dun := '241003755';
  END IF;
  edi_870(j) := 'N1*SU**1*' || ls_dun;
  j := j + 1;
  edi_870(j) := 'N1*OU**1*039630926';
  j := j + 1;

  -- need to get ln_cur_net_wt from table: EDI_870_COIL_STATUS
  SELECT e.coil_cur_wt
    INTO ln_cur_net_wt
    FROM edi_870_coil_status e
   WHERE e.coil_abc_num = al_coil_abc_num
     AND e.coil_status_change_date = adt_date;

  li_hl_num := li_hl_num + 1;
  edi_870(j) := 'HL*' || li_hl_num || '**I';
  j := j + 1;
  edi_870(j) := 'PRF*' || ls_po || '****NA';
  j := j + 1;
  edi_870(j) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
  j := j + 1;
  edi_870(j) := 'REF*SE*' || al_coil_abc_num;
  j := j + 1;
  edi_870(j) := 'REF*MI*' || ls_po;
  j := j + 1;
  edi_870(j) := 'REF*RV*' || al_coil_abc_num || '*NA';
  j := j + 1;
  edi_870(j) := 'PO1**1*UN***VO*' || ls_vo || '*HN*' || ls_coil_org_num ||
		'*SN*' || ls_coil_org_num;
  j := j + 1;
  edi_870(j) := 'PID*S*MAC*ST*01';
  j := j + 1;
  edi_870(j) := 'PID*S*MA*ST*7*' || ls_coil_org_num;
  j := j + 1;
  edi_870(j) := 'PID*S*PR*ST*59';
  j := j + 1;
  edi_870(j) := 'MEA*PD*TH*' || to_char(ln_gauge, 'FM90.0000') || '*IN';
  j := j + 1;
  edi_870(j) := 'MEA*PD*WD*' || to_char(ln_width, 'FM99990.0000') || '*IN';
  j := j + 1;
  edi_870(j) := 'MEA*WT*N*' || ln_cur_net_wt || '*01';
  j := j + 1;
  edi_870(j) := 'MEA*WT*G*' || ln_cur_net_wt || '*01';
  j := j + 1;
  edi_870(j) := 'MEA*CT*NA*1*PC';
  j := j + 1;
  edi_870(j) := 'CTT*' || li_hl_num;
  j := j + 1;
  edi_870(j) := 'SE*' || to_char(j - 1) || '*' || to_char(li_st_log);
  j := j + 1;
  edi_870(j) := 'GE*1*' || to_char(li_gs_log);
  j := j + 1;
  edi_870(j) := 'IEA*1*' || lpad(to_char(li_gs_log), 9, '0');

  SELECT edi_file_id_seq.nextval INTO li_edi_870_id FROM dual;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
-- edi_file	   := 's_novelis_coil_status_' || li_edi_870_id || '.870';
  edi_file	  := edi_file_prefix || li_edi_870_id || '.edi';
  edi_file_handle := utl_file.fopen(edi_location, edi_file, 'W');
  --write edi to file
  FOR i IN 0 .. j LOOP
    utl_file.put_line(edi_file_handle, edi_870(i));
  END LOOP;

  utl_file.fclose(edi_file_handle);

  --Update edi_870_coil_status.
  UPDATE edi_870_coil_status e
     SET e.edi_870_date = SYSDATE, e.transaction_num = li_gs_log
   WHERE e.coil_abc_num = al_coil_abc_num
     AND e.coil_status_change_date = adt_date;

  COMMIT;

  RETURN(RESULT);

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN - 2;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN - 2;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN - 2;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN - 2;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN - 2;

END f_edi_870_coil_status_novelis;
/


