  CREATE OR REPLACE FUNCTION "DBO"."F_GET_ALLOY_STRING_4SKID"
(
       al_scrap_skid_num in scrap_skid.scrap_skid_num%type
)
return varchar2
is

  FunctionResult varchar2(40);
  ls_alloy2	 order_item.alloy2%type;

  cursor alloy2_cur is
  select 	 distinct order_item.alloy2
  from	   scrap_skid_detail
	   join return_scrap_item on scrap_skid_detail.return_scrap_item_num = return_scrap_item.return_scrap_item_num
	   join ab_job on ab_job.ab_job_num = return_scrap_item.ab_job_num
	   join order_item on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
  where    scrap_skid_detail.scrap_skid_num = al_scrap_skid_num
  ;

  alloy2_rec  alloy2_cur%ROWTYPE;

begin
  for alloy2_rec in alloy2_cur loop
    ls_alloy2 := alloy2_rec.alloy2;

    if FunctionResult is null then
      FunctionResult := ls_alloy2;
    else
      FunctionResult := FunctionResult || ' , ' || ls_alloy2;
    end if;
  end loop;

  return(FunctionResult);
end f_get_alloy_string_4skid;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_COIL_BALANCE_IN_JOB" (a_coil_id in coil.coil_abc_num%type, a_job_num in ab_job.ab_job_num%type) return  INTEGER is
  Result Integer;
  Skid_wt Integer;
  Scrap_wt Integer;
  Coil_wt Integer;
begin
  SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0) into Skid_wt
		FROM production_sheet_item
		WHERE (production_sheet_item.ab_job_num = a_job_num) and
		      (production_sheet_item.coil_abc_num = a_coil_id);

  SELECT NVL(sum(return_scrap_item.return_item_net_wt),0) into Scrap_wt
		FROM return_scrap_item
		WHERE (return_scrap_item.ab_job_num= a_job_num) and
		      (return_scrap_item.coil_abc_num =a_coil_id)   ;

  select ( process_coil.process_quantity - NVL(process_coil.process_end_wt, process_coil.process_quantity) )into Coil_wt
  from process_coil
  where process_coil.ab_job_num = a_job_num and process_coil.coil_abc_num = a_coil_id;

  Result := -(Coil_wt - Skid_wt - Scrap_wt);
  return(Result);
end F_GET_COIL_BALANCE_IN_JOB;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_COIL_BAL_PERCENT_JOB" (a_coil_id in coil.coil_abc_num%type, a_job_num in ab_job.ab_job_num%type) return number is
  Result number (6,3);
  coil_init_wt coil.net_wt%type;
begin
  --Result := 0;
  select coil.net_wt into coil_init_wt
  from coil
  where coil.coil_abc_num = a_coil_id;
  result := (f_get_coil_balance_in_job(a_coil_id, a_job_num )) / coil_init_wt * 100;
  return(Result);
end F_GET_COIL_BAL_PERCENT_JOB;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_COIL_CERT_RECEVD" (as_coil_org_num in varchar2) return char
is

  result	   char(1);
  li_counter	   number(2);
  li_counter_863   number(2);

begin
  -- Author: Alex Gerlants
  -- Date: May 1, 2019

  select   count(*)
  into	   li_counter_863
  from	   cert_label_customers
  where    customer_id =
  (
     select max(customer_id) from coil where coil_org_num = as_coil_org_num
  );

  if li_counter_863 <= 0 then --863 not required for customer
    result := null;
    return(result);
  end if;

  select count(*)
  into	 li_counter
  from	 data_in_863
  where  coil_num = as_coil_org_num;

  --if li_counter_863 > 0 then --863 required for customer
    if li_counter > 0 then
	result := 'Y';
    else
	result := 'N';
    end if;
  --else --863 not required for customer
  --   result := null;
  --end if;

  return(result);
end f_get_coil_cert_recevd;

/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_COIL_DATE_RECEIVED" (i_coil_id in coil.coil_org_num%type) return date is
  Result	   date;
  temp		   date;
  li_coil_status   coil.coil_status%type;
  li_counter	   integer; --Alex Gerlants, 05/17/2019. Transfer_Coil_Duration_Calculation
  ld_transfer_date date; --Alex Gerlants, 05/17/2019. Transfer_Coil_Duration_Calculation
  ll_coil_abc_num  coil.coil_abc_num%type;
  ld_date_received coil.date_received%type;

begin

  select count(*)
  into	 li_counter
  from	 dbo.coil_ownership_transfer
  where  coil_org_num = i_coil_id;

  if li_counter > 0 then --Coil has been transferred
    select  max(coil_abc_num_new), max(transfer_datetime)
    into    ll_coil_abc_num, ld_transfer_date
    from    dbo.coil_ownership_transfer
    where  coil_org_num = i_coil_id;
  end if;

  /*
  select coil_status, date_received
  into	 li_coil_status, ld_date_received
  from	 coil
  where  coil_org_num =  i_coil_id;
  */

  select max(date_received), max(coil_status)
  into	 ld_date_received, li_coil_status
  from	 coil
  where  coil_org_num =  i_coil_id;
  --group by date_received;

  if li_counter > 0 then --Coil has been transferred
    Result := ld_transfer_date;
  else
    Result := ld_date_received;
  end if;

  return(Result);
end f_get_coil_date_received;

--create or replace public synonym f_get_coil_date_received for dbo.f_get_coil_date_received;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_COIL_DURATION" (i_coil_id in coil.coil_abc_num%type) return integer is
  Result integer;
  temp date;
  coilstatus integer;
begin
  SELECT COIL_STATUS, DATE_RECEIVED into coilstatus, temp
  FROM COIL
  WHERE COIL_ABC_NUM =	i_coil_id;

  if (coilstatus = 10) or (coilstatus = 0) then Result := 0;
  else
       select (sysdate - NVL(max(coil_track_date), temp)) into Result from coil_track
       WHERE COIL_ABC_NUM =  i_coil_id;
  end if;

  return(Result);
end f_get_coil_duration;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_COIL_DURATION_2" (i_coil_id in coil.coil_abc_num%type) return integer is
  Result	   integer;
  temp		   date;
  coilstatus	   integer;
  li_counter	   integer; --Alex Gerlants, 05/17/2019. Transfer_Coil_Duration_Calculation
  ld_transfer_date date; --Alex Gerlants, 05/17/2019. Transfer_Coil_Duration_Calculation

begin

--Alex Gerlants, 05/17/2019. Transfer_Coil_Duration_Calculation. Begin
  select count(*)
  into	 li_counter
  from	 dbo.coil_ownership_transfer
  where  coil_abc_num_new = i_coil_id;

  if li_counter > 0 then --Coil has been transferred
      select  transfer_datetime
      into    ld_transfer_date
      from    dbo.coil_ownership_transfer
      where  coil_abc_num_new = i_coil_id;
   end if;
   --Alex Gerlants, 05/17/2019. Transfer_Coil_Duration_Calculation. End

  SELECT COIL_STATUS, DATE_RECEIVED into coilstatus, temp
  FROM COIL
  WHERE COIL_ABC_NUM =	i_coil_id;

  if (coilstatus = 10) or (coilstatus = 0) then Result := 0;
  else
     if li_counter > 0 then --Coil has been transferred
	 select (sysdate - ld_transfer_date)
	 into	Result
	 from	dual;
     else
     --Alex Gerlants, 05/17/2019. Transfer_Coil_Duration_Calculation. End
	 select (sysdate - NVL(max(coil_track_date), temp)) into Result from coil_track
	 WHERE COIL_ABC_NUM =  i_coil_id;
     end if; --Alex Gerlants, 05/17/2019. Transfer_Coil_Duration_Calculation
  end if;

  return(Result);
