  CREATE OR REPLACE FUNCTION "DBO"."F_GET_MATERIAL" (coil_alloy2 in varchar2, coil_temper in varchar2) return varchar2 is
--   temp    varchar2(30);
  Result  varchar2(30);
BEGIN
  -- Author: Alex Gerlants
  -- Date: May 16, 2016
  -- Concatenate coil_alloy2, ' -', and and coil_temper
  -- If resulting string = ' -', make result = ''
  select coil_alloy2 || ' -' || coil_temper into Result from dual;

  if Result = ' -' then
    Result := '';
  end if;

  -- Result := temp;

  return(Result);
END f_get_material;

/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_MATERIAL_4SKID" (al_sheet_skid_num in sheet_skid.sheet_skid_num%type)
return varchar2

is

  Result      varchar2(30);

BEGIN
  -- Author: Alex Gerlants
  -- Date: 11/10/2023
  -- Concatenate order_item.alloy2, ' -', and order_item.temper
  -- If resulting string = ' -', make result = ''

  select  f_get_order_item_alloy_4skid(al_sheet_skid_num)
	  || ' - ' ||
	  f_get_order_item_temper_4skid(al_sheet_skid_num)
  into	  Result
  from	  dual;

  --select coil_alloy2 || ' -' || coil_temper into Result from dual;

  if Result = ' -' then
    Result := '';
  end if;

  -- Result := temp;

  return(Result);
END f_get_material_4skid;

/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_NUM_OF_COIL_PER_JOB" (al_job_id in ab_job.ab_job_num%type) return integer is
  Result integer;
begin

select COUNT(DISTINCT coil_abc_num) INTO Result FROM Process_coil
where ab_job_num = al_job_id;

  return(Result);
end f_get_num_of_coil_per_job;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_ONHOLD_DATE" (i_coil_id in coil.coil_abc_num%type) return date is
  Result date;
begin
  select min(coil_track_date) into Result from coil_track where (coil_abc_num = i_coil_id) and (coil_cur_status = 4);

  return(Result);
end f_get_onhold_date;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_ORDER_ITEM_ALLOY_4SKID"
(
   ai_skid_id in sheet_skid.sheet_skid_num%type
) return varchar

is

ls_skid_ticket_if_whed		 sheet_skid.skid_ticket_if_whed%type;
ll_sheet_skid_num_orig		 sheet_skid.sheet_skid_num%type;
li_count			 number;
result				 varchar(8);

begin
  select    nvl(skid_ticket_if_whed, '')
  into	    ls_skid_ticket_if_whed
  from	    sheet_skid
  where     sheet_skid.sheet_skid_num = ai_skid_id;

  if length(ls_skid_ticket_if_whed) > 0 then --WH return skid
    --The statement below applies to Novelis WH skids that have skid_ticket_if_whed with suffix 'T1"
    --This applies to non-Novelis skids where sheet_skid_display_num is the same as sheet_skid_num
    select   sheet_skid_num
    into     ll_sheet_skid_num_orig
    from     sheet_skid
    where    sheet_skid_display_num = ls_skid_ticket_if_whed;

    select   count(*)
    into     li_count
    from     sheet_skid
	     join ab_job on ab_job.ab_job_num = sheet_skid.ab_job_num
	     join order_item on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
    where    sheet_skid.sheet_skid_num = ll_sheet_skid_num_orig;

    if li_count > 0 then
      select   nvl(order_item.alloy2, 'N/A')
      into     result
      from     sheet_skid
	       join ab_job on ab_job.ab_job_num = sheet_skid.ab_job_num
	       join order_item on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
      where    sheet_skid.sheet_skid_num = ll_sheet_skid_num_orig;
    else
      result := 'N/A';
    end if;
  else
    select   nvl(order_item.alloy2, 'N/A')
    into     result
    from     sheet_skid
	     join ab_job on ab_job.ab_job_num = sheet_skid.ab_job_num
	     join order_item on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
    where    sheet_skid.sheet_skid_num = ai_skid_id;
  end if;

  return(Result);
end f_get_order_item_alloy_4skid;

--create or replace public synonym f_get_order_item_alloy_4skid for dbo.f_get_order_item_alloy_4skid;

/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_ORDER_ITEM_DESC_4SKID" (ai_skid_id in sheet_skid.sheet_skid_num%type) return varchar is
  Result varchar(255);
begin
  select     order_item.order_item_desc
  into	     Result
  from	     sheet_skid
	     join ab_job on ab_job.ab_job_num = sheet_skid.ab_job_num
	     join order_item on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
  where      (sheet_skid.sheet_skid_num = ai_skid_id);

  return(Result);
end f_get_order_item_desc_4skid;
/


