  CREATE OR REPLACE FUNCTION "DBO"."F_GET_PART_DIMS_4ORDER_ITEM"
(
    al_order_abc_num  in order_item.order_abc_num%type,
    al_order_item_num in order_item.order_item_num%type,
    as_what_2return   in varchar2
)
return number

is

  ls_sheet_type     varchar2(18);
  ll_length	    number(10,5);
  ll_width	    number(10,5);
  ll_return	    number(10,5);

begin

  ll_length := 0;

  select trim(lower(sheet_type))
  into	 ls_sheet_type
  from	 order_item
  where  order_abc_num = al_order_abc_num
  and	 order_item_num = al_order_item_num;

  if ls_sheet_type = 'rectangle' then
      select  nvl(rt_length, 0), nvl(rt_width, 0)
      into    ll_length, ll_width
      from    rectangle
      where   order_abc_num = al_order_abc_num
      and     order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'parallelogram' then
      select   nvl(p_length_minus, 0), nvl(p_width_minus, 0)
      into     ll_length, ll_width
      from     parallelogram
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'fender' then
      select   nvl(fe_length, 0), nvl(fe_side, 0)
      into     ll_length, ll_width
      from     fender
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'chevron' then
      select  nvl(ch_length, 0), nvl(ch_width, 0)
      into     ll_length, ll_width
      from     chevron
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

    elsif ls_sheet_type = 'circle' then
      select   nvl(c_diameter, 0), nvl(c_diameter, 0)
      into     ll_length, ll_width
      from     circle
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

    elsif ls_sheet_type = 'trapezoid' then
      select   nvl(tr_long_length, 0), nvl(tr_width, 0)
      into     ll_length, ll_width
      from     trapezoid
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

  elsif ls_sheet_type = 'l.trapezoid' then
      select   nvl(ltr_long_length, 0), nvl(ltr_width, 0)
      into     ll_length, ll_width
      from     left_trapezoid
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

  elsif ls_sheet_type = 'r.trapezoid' then
      select   nvl(rtr_long_length, 0), nvl(rtr_width, 0)
      into     ll_length, ll_width
      from     right_trapezoid
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

    elsif ls_sheet_type = 'reinforcement' then
      select   nvl(re_length, 0), nvl(re_width, 0)
      into     ll_length, ll_width
      from     reinforcement
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'liftgate' then
      select   nvl(li_length, 0), nvl(li_width, 0)
      into     ll_length, ll_width
      from     liftgate_shape
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'other' then
       select  nvl(x_1, 0), nvl(x_2, 0)
       into    ll_length, ll_width
       from    x1_shape
       where   order_abc_num = al_order_abc_num
       and     order_item_num = al_order_item_num;

   else
      ll_length := 0;
      ll_width := 0;
   end if;

   if lower(as_what_2return) = 'length' then
     ll_return := ll_length;
   elsif lower(as_what_2return) = 'width' then
     ll_return := ll_width;
   else
     ll_return := 0;
   end if;

   return ll_return;

end f_get_part_dims_4order_item;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_PART_LENGTH_PER_JOB" (al_job in ab_job.ab_job_num%type) return  rectangle.rt_length%type is
  Result rectangle.rt_length%type ;
  s_type order_item.sheet_type%type;
  abc_order_id order_item.order_abc_num%type;
  abc_order_item order_item.order_item_num%type;
begin

  select order_item.sheet_type, order_item.order_abc_num, order_item.order_item_num into s_type, abc_order_id, abc_order_item
  from order_item, ab_job
  where ab_job.order_item_num = order_item.order_item_num and
	ab_job.order_abc_num = order_item.order_abc_num and
	ab_job.ab_job_num = al_job;

  s_type := Upper(Trim(s_type));
  case s_type
       when 'RECTANGLE' then
--	      dbms_output.put_line('RECTANGLE');
	    select rectangle.rt_length into Result from rectangle
	    where rectangle.order_abc_num = abc_order_id and
		  rectangle.order_item_num = abc_order_item;
       when 'CHEVRON' then
--	      dbms_output.put_line('CHEVRON');
	    select chevron.ch_length into Result from chevron
	    where chevron.order_abc_num = abc_order_id and
		  chevron.order_item_num = abc_order_item;
       when 'CIRCLE' then
--	      dbms_output.put_line('CIRCLE');
	    select circle.c_diameter into Result from circle
	    where circle.order_abc_num = abc_order_id and
		  circle.order_item_num = abc_order_item;
       when 'FENDER' then
--	      dbms_output.put_line('FENDER');
	    select fender.fe_length into Result from fender
	    where fender.order_abc_num = abc_order_id and
		  fender.order_item_num = abc_order_item;
       when 'LIFTGATE' then
--	      dbms_output.put_line('LIFTGATE');
	    select liftgate_shape.li_length into Result from liftgate_shape
	    where liftgate_shape.order_abc_num = abc_order_id and
		  liftgate_shape.order_item_num = abc_order_item;
       when 'OTHER' then
--	      dbms_output.put_line('OTHER');
	    select x1_shape.x_2  into Result from x1_shape
	    where x1_shape.order_abc_num = abc_order_id and
		  x1_shape.order_item_num = abc_order_item;
       when 'PARALLELOGRAM' then
--	      dbms_output.put_line('PARALLELOGRAM');
	    select parallelogram.p_length  into Result from parallelogram
	    where parallelogram.order_abc_num = abc_order_id and
		  parallelogram.order_item_num = abc_order_item;
       when 'REINFORCEMENT' then
--	    dbms_output.put_line('REINFORCEMENT');
	    select reinforcement.re_length  into Result from reinforcement
	    where reinforcement.order_abc_num = abc_order_id and
		  reinforcement.order_item_num = abc_order_item;
       when 'TRAPEZOID' then
--	      dbms_output.put_line('TRAPEZOID');
	    select trapezoid.tr_long_length into Result from trapezoid
	    where trapezoid.order_abc_num = abc_order_id and
		  trapezoid.order_item_num = abc_order_item;
  end case;

  return(Result);
end f_get_part_length_per_job;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_PART_WIDTH_PER_JOB" (al_job in ab_job.ab_job_num%type) return  rectangle.rt_width%type is
  Result rectangle.rt_width%type;
  s_type order_item.sheet_type%type;
  abc_order_id order_item.order_abc_num%type;
  abc_order_item order_item.order_item_num%type;
begin

  select order_item.sheet_type, order_item.order_abc_num, order_item.order_item_num into s_type, abc_order_id, abc_order_item
  from order_item, ab_job
  where ab_job.order_item_num = order_item.order_item_num and
	ab_job.order_abc_num = order_item.order_abc_num and
	ab_job.ab_job_num = al_job;

  s_type := Upper(Trim(s_type));
  case s_type
       when 'RECTANGLE' then
--	      dbms_output.put_line('RECTANGLE');
	    select rectangle.rt_width into Result from rectangle
	    where rectangle.order_abc_num = abc_order_id and
		  rectangle.order_item_num = abc_order_item;
       when 'CHEVRON' then
--	      dbms_output.put_line('CHEVRON');
	    select chevron.ch_width into Result from chevron
	    where chevron.order_abc_num = abc_order_id and
		  chevron.order_item_num = abc_order_item;
       when 'CIRCLE' then
--	      dbms_output.put_line('CIRCLE');
	    select circle.c_diameter into Result from circle
	    where circle.order_abc_num = abc_order_id and
		  circle.order_item_num = abc_order_item;
       when 'FENDER' then
--	      dbms_output.put_line('FENDER');
	    select fender.fe_side into Result from fender
	    where fender.order_abc_num = abc_order_id and
		  fender.order_item_num = abc_order_item;
       when 'LIFTGATE' then
--	      dbms_output.put_line('LIFTGATE');
	    select liftgate_shape.li_width into Result from liftgate_shape
	    where liftgate_shape.order_abc_num = abc_order_id and
		  liftgate_shape.order_item_num = abc_order_item;
       when 'OTHER' then
--	      dbms_output.put_line('OTHER');
	    select x1_shape.x_1  into Result from x1_shape
	    where x1_shape.order_abc_num = abc_order_id and
		  x1_shape.order_item_num = abc_order_item;
       when 'PARALLELOGRAM' then
--	      dbms_output.put_line('PARALLELOGRAM');
	    select parallelogram.p_width into Result from parallelogram
	    where parallelogram.order_abc_num = abc_order_id and
		  parallelogram.order_item_num = abc_order_item;
       when 'REINFORCEMENT' then
--	    dbms_output.put_line('REINFORCEMENT');
	    select reinforcement.re_width into Result from reinforcement
	    where reinforcement.order_abc_num = abc_order_id and
		  reinforcement.order_item_num = abc_order_item;
       when 'TRAPEZOID' then
--	      dbms_output.put_line('TRAPEZOID');
	    select trapezoid.tr_width into Result from trapezoid
	    where trapezoid.order_abc_num = abc_order_id and
		  trapezoid.order_item_num = abc_order_item;
  end case;

  return(Result);
end f_get_part_width_per_job;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_PIECE_COUNT_PER_COIL" (al_coil_id in coil.coil_abc_num%type) return integer is
