  CREATE OR REPLACE FUNCTION "DBO"."F_GET_REBANDED_DATE" (i_coil_id in coil.coil_abc_num%type) return date is
  Result date;
begin
  Result := null;
  select min(coil_track_date) into Result from coil_track where (coil_abc_num = i_coil_id) and (coil_cur_status = 7);
  --group by coil_abc_num;

  return(Result);
end f_get_rebanded_date;
