  CREATE OR REPLACE FUNCTION "DBO"."F_GET_REJECTED_COIL_WT_PER_JOB"
 (
    al_ab_job_num  ab_job.ab_job_num%type
 )
  return integer

is

  ll_cur_coil		       coil.coil_abc_num%type;
  ll_rowcount		       number(8);
  ll_total_rej_coil_wt_4job    number(8);
  ll_wt1		       number(8);
  ll_wt2		       number(8);
  ll_wt 		       number(8);
  ll_shift_end_wt	       number(8);

--------------------------------------------------------------------------------------------------
------------------------------------ Cursors Begin -----------------------------------------------
--------------------------------------------------------------------------------------------------

  cursor coil_cur is
  select distinct coil.coil_abc_num
  from	 coil
	 join process_coil on coil.coil_abc_num = process_coil.coil_abc_num
  where  process_coil.process_coil_status = 3
  and	 process_coil.ab_job_num = al_ab_job_num
  order by
	 process_coil.coil_abc_num;

  coil_rec  coil_cur%ROWTYPE;

--------------------------------------------------------------------------------------------------
------------------------------------- Cursors End ------------------------------------------------
--------------------------------------------------------------------------------------------------

begin

  select count(distinct coil.coil_abc_num)
  into	 ll_rowcount
  from	 coil
	 join process_coil on coil.coil_abc_num = process_coil.coil_abc_num
  where  process_coil.process_coil_status = 3
  and	 process_coil.ab_job_num = al_ab_job_num;

  if ll_rowcount > 0 then

    ll_total_rej_coil_wt_4job := 0;

    for coil_rec in coil_cur loop --Coil loop
       ll_cur_coil := coil_rec.coil_abc_num;
-------------

       select nvl(process_quantity, 0), nvl(process_end_wt, 0)
       into   ll_wt, ll_shift_end_wt
       from   process_coil
       where  coil_abc_num = ll_cur_coil
       and    ab_job_num = al_ab_job_num;

       --if ll_wt is null then
       --  ll_wt := 0;
       --end if;

       if ll_shift_end_wt = 0 then
	 select nvl(net_wt_balance , 0)
	 into	ll_wt1
	 from	coil
	 where	coil_abc_num = ll_cur_coil;
       else
	 ll_wt1 := ll_shift_end_wt;
       end if;

       if ll_wt1 <> 0 then
	 ll_wt1 := ll_shift_end_wt;
       end if;

       select nvl(max(process_quantity) , 0)
       into   ll_wt2
       from   process_coil
       where  coil_abc_num = ll_cur_coil
       and    process_quantity < ll_wt;

       --if ll_wt2 is null then
       --  ll_wt2 := 0;
       --end if;

       if ll_wt1 > ll_wt2 then
	 ll_total_rej_coil_wt_4job := ll_total_rej_coil_wt_4job + ll_wt1;
       else
	 ll_total_rej_coil_wt_4job := ll_total_rej_coil_wt_4job + ll_wt2;
       end if;

-------------

    end loop; --for coil_rec in coil_cur loop. Coil loop
  end if; --end if in select count(*)

  ll_total_rej_coil_wt_4job := nvl(ll_total_rej_coil_wt_4job, 0);
  return ll_total_rej_coil_wt_4job;

end f_get_rejected_coil_wt_per_job;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_REJECTED_DATE" (i_coil_id in coil.coil_abc_num%type) return date is
  Result date;
begin
  select min(coil_track_date) into Result from coil_track where (coil_abc_num = i_coil_id) and (coil_cur_status = 3);

  return(Result);
end f_get_rejected_date;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SCRAP_ACT_WT_PER_JOB"
 (
    al_ab_job_num  ab_job.ab_job_num%type
 )
  return integer

is

  ll_total_act_scrap_wt_4job   number(8);

begin

   select    nvl(sum(return_item_net_wt), 0)
   into      ll_total_act_scrap_wt_4job
   from      return_scrap_item
   where     ab_job_num = al_ab_job_num;

  return ll_total_act_scrap_wt_4job;

end f_get_scrap_act_wt_per_job;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SCRAP_DURATION" (i_skid_id in scrap_skid.scrap_skid_num%type) return integer is
  Result integer;
  temp date;
  skidstatus integer;
begin
  SELECT skid_scrap_status, scrap_date into skidstatus, temp
  FROM scrap_skid
  WHERE scrap_skid_num =  i_skid_id;

  if skidstatus = 0 then Result := 0;
  else
       select (sysdate - NVL(max(log_date), temp)) into Result from scrap_track
       WHERE scrap_track.scrap_skid_no =  i_skid_id;
  end if;

  return(Result);
end f_get_scrap_duration;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SCRAP_SKID_DATE" (i_skid_id in scrap_skid.scrap_skid_num%type)
return date

is

result		date;
ld_scrap_date	scrap_skid.scrap_date%type;
li_skidstatus	integer;

begin
  select   skid_scrap_status, scrap_date
  into	   li_skidstatus, ld_scrap_date
  from	   scrap_skid
  where    scrap_skid_num =  i_skid_id;


  select nvl(max(log_date), ld_scrap_date)
  into	 result
  from	 scrap_track
  where  scrap_skid_no =  i_skid_id;

  return(result);
end f_get_scrap_skid_date;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SCRAP_SKID_DURATION" (i_skid_id in scrap_skid.scrap_skid_num%type) return integer is
  Result	  integer;
  ld_scrap_date   scrap_skid.scrap_date%type;
  li_skidstatus   integer;
begin
  SELECT   skid_scrap_status, scrap_date
  into	   li_skidstatus, ld_scrap_date
  FROM	   scrap_skid
  WHERE    scrap_skid_num =  i_skid_id;

  if li_skidstatus = 0 then Result := 0;
  else
       select (sysdate - scrap_date)
       into   Result
       from   scrap_skid
       where  scrap_skid.scrap_skid_num =  i_skid_id;
  end if;

  return(Result);
end f_get_scrap_skid_duration;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SCRAP_WT_PER_JOB"
 (
    al_ab_job_num  ab_job.ab_job_num%type
 )
  return integer

is

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc		 varchar2(50) := get_edi_destination('EDI_DIR');

  edi_file		       varchar2(50) := 'edi_out.txt';
  --edi_file_prefix		 varchar2(50) := 'S_novelis_870_'; --production
  edi_file_prefix	       varchar2(50) := 's_novelis_870_'; --development
  edi_file_handle	       utl_file.file_type;
  su_duns		       varchar2(10);
  ll_customer_id	       customer.customer_id%type;
  ll_cur_coil		       coil.coil_abc_num%type;
  ll_gs_log		       integer;
  ll_st_log		       integer;
  ls_today		       varchar2(20) := to_char(sysdate, 'YYYYMMDD');
  ls_today_4		       varchar2(20) := to_char(sysdate, 'YYMMDD');
  ls_now		       varchar2(20) := to_char(sysdate, 'HH24MI');
  ls_po 		       varchar2(20);
  ls_finished_goods	       varchar2(32);
  ls_cust_prod_line	       varchar2(8);
  ld_scrap_870_date	       process_coil.scrap_870_date%type;
  ls_coil_org_num	       coil.coil_org_num%type;
  ls_heat		       coil.lot_num%type;
  ll_prime_nw		       coil.net_wt%type;
  ll_scrap_nw		       coil.net_wt%type;
  ll_item_count 	       integer;
  li_hl01		       integer;
  li_hllin		       integer;
  ll_rowcount		       number(8);
  ll_edi_file_id_870	       integer;
  ld_edi_date_870	       ab_job.edi_date_870%type;
  --ls_sheet_skid_exists	 char(1);
  ls_consumed_coil_num	       coil.consumed_coil_num%type;
  ls_customer_short_name       customer.customer_short_name%type;
  ll_sheet_skid_count_4coil    number(8);
  ll_total_act_scrap_wt_4job   number(8);
  ll_total_theo_scrap_wt_4job  number(8);
  ll_heavy_light	       number(8);

--------------------------------------------------------------------------------------------------
------------------------------------ Cursors Begin -----------------------------------------------
--------------------------------------------------------------------------------------------------

  cursor coil_cur is
  select distinct process_coil.coil_abc_num
  from	 process_coil
	 left outer join production_sheet_item on production_sheet_item.coil_abc_num = process_coil.coil_abc_num and production_sheet_item.ab_job_num = process_coil.ab_job_num
	 left outer join sheet_skid_detail on sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num
	 left outer join sheet_skid on sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num
  where  process_coil.ab_job_num = al_ab_job_num
  and	 (
	      sheet_skid.skid_sheet_status in (0, 2, 4, 13, 12, 16)
	   or sheet_skid.skid_sheet_status is null --This is for rejected coils without sheets
	 )
  order by process_coil.coil_abc_num;

  coil_rec  coil_cur%ROWTYPE;

  --Cursor skid_coil_cur will select data for ab_job and coil_abc_num with skids.
  --If there is a reject coil without sheet skids, this cursor will not select it.
  cursor skid_coil_cur is
  select coil.coil_abc_num,
	 coil.lot_num,
	 coil.coil_org_num,
	 coil.coil_mid_num,
	 nvl(coil.consumed_coil_num, ' ') consumed_coil,
	 nvl(coil.material_num, ' ') material_num,
	 coil.net_wt,
	 sheet_skid.sheet_tare_wt,
	 sheet_skid.sheet_net_wt,
	 sheet_skid.skid_pieces,
	 production_sheet_item.prod_item_pieces,
	 production_sheet_item.prod_item_num,
	 sheet_skid.skid_sheet_status,
	 sheet_skid.sheet_skid_num,
	 production_sheet_item.prod_item_note,
	 sheet_skid.sheet_theoretical_wt,
	 production_sheet_item.prod_item_placement,
	 process_coil.process_quantity,
	 production_sheet_item.prod_item_net_wt,
	 sheet_skid.sheet_skid_display_num,
	 nvl(customer_order.sales_order, ' ') sales_order,
	 nvl(customer_order.orig_customer_po, 'NA') orig_customer_po,
	 nvl(order_item.enduser_part_num, ' ') enduser_part_num,
	 nvl(order_item.cust_prod_line_id, 'NA') cust_prod_line_id,
	 nvl(order_item.finished_goods_material_num, 'NA') finished_goods_material_num,
	 (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	 NULL done
  from	 coil
	 join process_coil on coil.coil_abc_num = process_coil.coil_abc_num
	 join ab_job on ab_job.ab_job_num = process_coil.ab_job_num
	 join order_item on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
	 join customer_order on customer_order.order_abc_num = order_item.order_abc_num
	 left outer join production_sheet_item on coil.coil_abc_num = production_sheet_item.coil_abc_num and production_sheet_item.ab_job_num = process_coil.ab_job_num
	 left outer join sheet_skid_detail on sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num
	 left outer join sheet_skid on sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num
  where  ab_job.ab_job_num = al_ab_job_num
  and	 coil.coil_abc_num = ll_cur_coil
  order by
	 production_sheet_item.coil_abc_num,
	 sheet_skid.sheet_skid_display_num;

  skid_coil_rec  skid_coil_cur%rowtype;

  cursor scrap_cur is
  select process_coil.coil_abc_num,
	 process_coil.process_coil_status,
	 process_coil.process_quantity,
	 nvl(process_coil.process_end_wt, 0),
	 sum(nvl(process_coil.process_end_wt, 0)),
	 sum(nvl(production_sheet_item.prod_item_net_wt, 0)),
	 case process_coil.process_coil_status
	    when 7 then --Rebanded coils
	       --(process_coil.process_quantity - sum(production_sheet_item.prod_item_net_wt) - (select process_end_wt from process_coil pc where pc.ab_job_num = 101143 and pc.coil_abc_num = process_coil.coil_abc_num))
	       (process_coil.process_quantity - sum(nvl(production_sheet_item.prod_item_net_wt, 0)) - nvl(process_coil.process_end_wt, 0))
	    when 3 then --Rejected coils
	       case (select count(*) from production_sheet_item psi where psi.ab_job_num = al_ab_job_num and psi.coil_abc_num = process_coil.coil_abc_num)
		 when 0 then --Rejected coils without sheets
		   (process_coil.process_quantity - sum(nvl(process_coil.process_end_wt, 0)))
		 else --Rejected coils with sheets
		   (process_coil.process_quantity - nvl(process_coil.process_end_wt, 0) - sum(nvl(production_sheet_item.prod_item_net_wt, 0)))
		end
	     else
	       (process_coil.process_quantity - sum(nvl(production_sheet_item.prod_item_net_wt, 0)) - sum(nvl(process_coil.process_end_wt, 0)))
	 end scrap_net_wt
  from	 process_coil
	 join coil on coil.coil_abc_num = process_coil.coil_abc_num
	 join ab_job on ab_job.ab_job_num = process_coil.ab_job_num and coil.coil_abc_num = process_coil.coil_abc_num
	 left outer join production_sheet_item on production_sheet_item.ab_job_num = process_coil.ab_job_num and production_sheet_item.coil_abc_num = process_coil.coil_abc_num
  where  process_coil.ab_job_num = al_ab_job_num
  and	 coil.coil_abc_num = ll_cur_coil
  group by
	 process_coil.coil_abc_num,
	 process_coil.process_coil_status,
	 process_coil.process_quantity,
	 process_coil.process_end_wt
  order by
	 process_coil.coil_abc_num;

  scrap_rec  scrap_cur%rowtype;

--------------------------------------------------------------------------------------------------
------------------------------------- Cursors End ------------------------------------------------
--------------------------------------------------------------------------------------------------

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

BEGIN

  i		 := 0;
  k		 := 0;
  p		 := 0;

  select count(distinct process_coil.coil_abc_num)
  into	 ll_rowcount
  from	 process_coil
	 left outer join production_sheet_item on production_sheet_item.coil_abc_num = process_coil.coil_abc_num and production_sheet_item.ab_job_num = process_coil.ab_job_num
	 left outer join sheet_skid_detail on sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num
	 left outer join sheet_skid on sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num
  where  process_coil.ab_job_num = al_ab_job_num
  and	 (
	      sheet_skid.skid_sheet_status in (0, 2, 4, 13, 12, 16)
	   or sheet_skid.skid_sheet_status is null --This is for rejected coils without sheets
	 );

  if ll_rowcount > 0 then

    select    nvl(sum(return_item_net_wt),0)
    into      ll_total_act_scrap_wt_4job
    from      return_scrap_item
    where     ab_job_num = al_ab_job_num;

    ll_total_theo_scrap_wt_4job := 0;

    for coil_rec in coil_cur loop --Coil loop
       ll_cur_coil := coil_rec.coil_abc_num;

       for scrap_rec in scrap_cur loop --Scrap loop

	  --Scrap info
	  ll_scrap_nw := scrap_rec.scrap_net_wt;

	  if ll_scrap_nw > 0 then --Theo scrap weight

	     --ll_total_theo_scrap_wt_4job := 0;

	     select    nvl(sum(return_item_net_wt),0)
	     into      ll_total_act_scrap_wt_4job
	     from      return_scrap_item
	     where     ab_job_num = al_ab_job_num;

	     ll_total_theo_scrap_wt_4job := ll_total_theo_scrap_wt_4job + ll_scrap_nw;

	   end if; --if ll_scrap_nw > 0 then
	end loop; --for scrap_rec in alcan_scrap_870_cur loop scrap loop

	--ll_heavy_light := ll_total_act_scrap_wt_4job - ll_total_theo_scrap_wt_4job;
    end loop; --for coil_rec in coil_cur loop. Coil loop

    ll_heavy_light := ll_total_act_scrap_wt_4job - ll_total_theo_scrap_wt_4job;

  end if; --end if in select count(*)

  --return ll_total_act_scrap_wt_4job;
  return ll_total_theo_scrap_wt_4job;
end f_get_scrap_wt_per_job;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SCRAP_WT_PER_JOB_COIL"
 (
    al_ab_job_num    ab_job.ab_job_num%type,
    al_coil_abc_num  coil.coil_abc_num%type
 )
  return integer

is
  ll_scrap_wt_per_job_coil  number(8);

BEGIN

  select case process_coil.process_coil_status
	    when 7 then --Rebanded coils
	       --(process_coil.process_quantity - sum(production_sheet_item.prod_item_net_wt) - (select process_end_wt from process_coil pc where pc.ab_job_num = 101143 and pc.coil_abc_num = process_coil.coil_abc_num))
	       (process_coil.process_quantity - sum(nvl(production_sheet_item.prod_item_net_wt, 0)) - nvl(process_coil.process_end_wt, 0))
	    when 3 then --Rejected coils
	       case (select count(*) from production_sheet_item psi where psi.ab_job_num = al_ab_job_num and psi.coil_abc_num = process_coil.coil_abc_num)
		 when 0 then --Rejected coils without sheets
		   (process_coil.process_quantity - sum(nvl(process_coil.process_end_wt, 0)))
		 else --Rejected coils with sheets
		   (process_coil.process_quantity - nvl(process_coil.process_end_wt, 0) - sum(nvl(production_sheet_item.prod_item_net_wt, 0)))
		end
	     else
	       (process_coil.process_quantity - sum(nvl(production_sheet_item.prod_item_net_wt, 0)) - sum(nvl(process_coil.process_end_wt, 0)))
	 end scrap_net_wt
  into	 ll_scrap_wt_per_job_coil
  from	 process_coil
	 join coil on coil.coil_abc_num = process_coil.coil_abc_num
	 join ab_job on ab_job.ab_job_num = process_coil.ab_job_num and coil.coil_abc_num = process_coil.coil_abc_num
	 left outer join production_sheet_item on production_sheet_item.ab_job_num = process_coil.ab_job_num and production_sheet_item.coil_abc_num = process_coil.coil_abc_num
  where  process_coil.ab_job_num = al_ab_job_num
  and	 coil.coil_abc_num = al_coil_abc_num
  group by
	 process_coil.coil_abc_num,
	 process_coil.process_coil_status,
	 process_coil.process_quantity,
	 process_coil.process_end_wt
  order by
	 process_coil.coil_abc_num;

  if ll_scrap_wt_per_job_coil is null then
    ll_scrap_wt_per_job_coil := 0;
  end if;

  return ll_scrap_wt_per_job_coil;

end f_get_scrap_wt_per_job_coil;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SHEET_WT_PER_JOB_COIL"
 (
    al_ab_job_num    ab_job.ab_job_num%type,
    al_coil_abc_num  coil.coil_abc_num%type

 )
  return integer

is

ll_sheet_wt_accum	     integer;

begin

  select   nvl(sum(production_sheet_item.prod_item_net_wt), 0)
  into	   ll_sheet_wt_accum
  from	    coil
	   join production_sheet_item on coil.coil_abc_num = production_sheet_item.coil_abc_num
	   join sheet_skid_detail on sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num
	   join sheet_skid on sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num
	   join process_coil on coil.coil_abc_num = process_coil.coil_abc_num and production_sheet_item.ab_job_num = process_coil.ab_job_num
  where    production_sheet_item.ab_job_num = al_ab_job_num
	   and production_sheet_item.coil_abc_num = al_coil_abc_num;

  return ll_sheet_wt_accum;

end f_get_sheet_wt_per_job_coil;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SHIPMENT_GROSSW" (PACKING_ID in shipment.packing_list%type) return  sheet_skid.sheet_net_wt%type is
  Result sheet_skid.sheet_net_wt%type;
begin
  SELECT SUM(sheet_skid.sheet_net_wt)+SUM(sheet_skid.sheet_tare_wt)
INTO Result FROM sheet_skid, sheet_packing_item, shipment
WHERE SHIPMENT.PACKING_LIST =SHEET_PACKING_ITEM.PACKING_LIST and
      SHEET_PACKING_ITEM.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM and
      SHIPMENT.PACKING_LIST = PACKING_ID;

  return(Result);
end F_GET_SHIPMENT_GROSSW;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SHIPMENT_GROSSW_ALL" (PACKING_ID in shipment.packing_list%type) return  sheet_skid.sheet_net_wt%type is
  Result sheet_skid.sheet_net_wt%type :=0;

skid_sum sheet_skid.sheet_net_wt%type :=0;
scrap_sum scrap_skid.scrap_net_wt%type :=0;
coil_sum coil.net_wt%type :=0;

begin

SELECT NVL(SUM(sheet_skid.sheet_net_wt),0)+NVL(SUM(sheet_skid.sheet_tare_wt),0)
INTO skid_sum FROM sheet_skid, sheet_packing_item, shipment
WHERE SHIPMENT.PACKING_LIST =SHEET_PACKING_ITEM.PACKING_LIST and
      SHEET_PACKING_ITEM.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM and
      SHIPMENT.PACKING_LIST = PACKING_ID;

SELECT NVL(SUM(scrap_skid.scrap_net_wt),0)+NVL(SUM(scrap_skid.scrap_tare_wt),0)
INTO scrap_sum FROM scrap_skid, scrap_packing_item, shipment
WHERE SHIPMENT.PACKING_LIST =SCRAP_PACKING_ITEM.PACKING_LIST and
      SCRAP_PACKING_ITEM.SCRAP_SKID_NUM = SCRAP_SKID.SCRAP_SKID_NUM and
      SHIPMENT.PACKING_LIST = PACKING_ID;

SELECT NVL(SUM(coil.net_wt),0)
INTO coil_sum FROM coil, reject_coil_packing_item, shipment
WHERE SHIPMENT.PACKING_LIST =REJECT_COIL_PACKING_ITEM.PACKING_LIST and
      REJECT_COIL_PACKING_ITEM.COIL_ABC_NUM = COIL.COIL_ABC_NUM and
      SHIPMENT.PACKING_LIST = PACKING_ID;

 Result := skid_sum + scrap_sum + coil_sum;

return(Result);
end F_GET_SHIPMENT_GROSSW_ALL;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SHIPMENT_NETW" (PACKING_ID in shipment.packing_list%type) return  sheet_skid.sheet_net_wt%type is
  Result sheet_skid.sheet_net_wt%type;
begin
  SELECT SUM(sheet_skid.sheet_net_wt)
INTO Result FROM sheet_skid, sheet_packing_item, shipment
WHERE SHIPMENT.PACKING_LIST =SHEET_PACKING_ITEM.PACKING_LIST and
      SHEET_PACKING_ITEM.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM and
      SHIPMENT.PACKING_LIST = PACKING_ID;


  return(Result);
end F_GET_SHIPMENT_NETW;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SHIPMENT_NETW_ALL" (PACKING_ID in shipment.packing_list%type) return	sheet_skid.sheet_net_wt%type is
  Result sheet_skid.sheet_net_wt%type;

skid_sum sheet_skid.sheet_net_wt%type :=0;
scrap_sum scrap_skid.scrap_net_wt%type :=0;
coil_sum coil.net_wt%type :=0;

begin

SELECT NVL(SUM(sheet_skid.sheet_net_wt),0)
INTO skid_sum FROM sheet_skid, sheet_packing_item, shipment
WHERE SHIPMENT.PACKING_LIST =SHEET_PACKING_ITEM.PACKING_LIST and
      SHEET_PACKING_ITEM.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM and
      SHIPMENT.PACKING_LIST = PACKING_ID;

SELECT NVL(SUM(scrap_skid.scrap_net_wt),0)
INTO scrap_sum FROM scrap_skid, scrap_packing_item, shipment
WHERE SHIPMENT.PACKING_LIST =SCRAP_PACKING_ITEM.PACKING_LIST and
      SCRAP_PACKING_ITEM.SCRAP_SKID_NUM = SCRAP_SKID.SCRAP_SKID_NUM and
      SHIPMENT.PACKING_LIST = PACKING_ID;

SELECT NVL(SUM(coil.net_wt),0)
INTO coil_sum FROM coil, reject_coil_packing_item, shipment
WHERE SHIPMENT.PACKING_LIST =REJECT_COIL_PACKING_ITEM.PACKING_LIST and
      REJECT_COIL_PACKING_ITEM.COIL_ABC_NUM = COIL.COIL_ABC_NUM and
      SHIPMENT.PACKING_LIST = PACKING_ID;

  Result := skid_sum + scrap_sum + coil_sum;
  return(Result);
end F_GET_SHIPMENT_NETW_ALL;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SHIPMENT_NUM_OF_SKIDS" (packing_id in shipment.packing_list%type)
return	integer is

result number(4) :=0;

skid_count   number(4) :=0;
scrap_count  number(4) :=0;
coil_count   number(4) :=0;

begin

--Alex Gerlants. 04/27/2017

    select count(distinct sheet_skid.sheet_skid_num)
    into   skid_count
    from   shipment
	   join sheet_packing_item on sheet_packing_item.packing_list = shipment.packing_list
	   join sheet_skid on sheet_skid.sheet_skid_num = sheet_packing_item.sheet_skid_num
    where  shipment.packing_list = packing_id;

    select count(distinct scrap_skid.scrap_skid_num)
    into   scrap_count
    from   shipment
	   join scrap_packing_item on scrap_packing_item.packing_list = shipment.packing_list
	   join scrap_skid on scrap_skid.scrap_skid_num = scrap_packing_item.scrap_skid_num
    where  shipment.packing_list = packing_id;

    select count(reject_coil_packing_item.coil_abc_num)
    into   coil_count
    from   shipment
	   join reject_coil_packing_item on reject_coil_packing_item.packing_list = shipment.packing_list
	   join coil on coil.coil_abc_num = reject_coil_packing_item.coil_abc_num
    where  shipment.packing_list = packing_id;

    result := skid_count + scrap_count + coil_count;

    return(Result);

end f_get_shipment_num_of_skids;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SHORT_LENGTH_4ORDER_ITEM"
(
    al_order_abc_num  in order_item.order_abc_num%type,
    al_order_item_num in order_item.order_item_num%type
)
return number

is

  ls_sheet_type     varchar2(18);
  ll_short_length    number(10,5);

begin

  ll_short_length := 0;

  select trim(lower(sheet_type))
  into	 ls_sheet_type
  from	 order_item
  where  order_abc_num = al_order_abc_num
  and	 order_item_num = al_order_item_num;

  if ls_sheet_type = 'rectangle' then
      select  nvl(rt_width, 0)
      into    ll_short_length
      from    rectangle
      where   order_abc_num = al_order_abc_num
      and     order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'parallelogram' then
      select   nvl(p_width, 0)
      into     ll_short_length
      from     parallelogram
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'fender' then
      select   nvl(fe_side, 0)
      into     ll_short_length
      from     fender
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'chevron' then
       select  nvl(ch_width, 0)
      into     ll_short_length
      from     chevron
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

    elsif ls_sheet_type = 'circle' then
       select  nvl(c_diameter, 0)
      into     ll_short_length
      from     circle
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

    elsif ls_sheet_type = 'trapezoid' then
      select   nvl(tr_short_length, 0)
      into     ll_short_length
      from     trapezoid
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

  elsif ls_sheet_type = 'l.trapezoid' then
      select   nvl(ltr_short_length, 0)
      into     ll_short_length
      from     left_trapezoid
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

  elsif ls_sheet_type = 'r.trapezoid' then
      select   nvl(rtr_short_length, 0)
      into     ll_short_length
      from     right_trapezoid
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'reinforcement' then
      select   nvl(re_width, 0)
      into     ll_short_length
      from     reinforcement
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'liftgate' then
      select   nvl(li_width, 0)
      into     ll_short_length
      from     liftgate_shape
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'other' then
       select  nvl(x_2, 0)
       into    ll_short_length
       from    x1_shape
       where   order_abc_num = al_order_abc_num
       and     order_item_num = al_order_item_num;

   else
      ll_short_length := 0;
   end if;

   return ll_short_length;

end f_get_short_length_4order_item;
/


