  CREATE OR REPLACE FUNCTION "DBO"."F_GET_SUBSTRING_COMMA" (string_input varchar2, comma_pos integer ) return varchar2 is
  /* This function gets a substring according the position of the comma
  */
  ls_string_input varchar2(32767);
  ls_string_output varchar2(32767);
  li_comma_pos integer;
  li_pos_previous integer;
  li_pos_current integer;

begin

  ls_string_input := string_input;
  li_comma_pos := comma_pos;

  if comma_pos > 1 then
  li_pos_previous := instr(ls_string_input, ',', 1, li_comma_pos - 1);
  li_pos_current := instr(ls_string_input, ',', 1, li_comma_pos);

  ls_string_output := substr(string_input, li_pos_previous + 1, li_pos_current - li_pos_previous - 1 );
  end if;

  if comma_pos = 1 then
  li_pos_current := instr(ls_string_input, ',', 1, li_comma_pos);
  ls_string_output := substr(string_input, 1, li_pos_current - 1);
  end if;

  ls_string_output := ltrim(ls_string_output);
  ls_string_output := rtrim(ls_string_output);

  return ls_string_output;

end f_get_substring_comma;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_TEMPER_STRING_4SKID"
(
       al_scrap_skid_num in scrap_skid.scrap_skid_num%type
)
return varchar2
is

  FunctionResult varchar2(40);
  ls_temper	 order_item.temper%type;

  cursor temper_cur is
  select 	 distinct order_item.temper
  from	   scrap_skid_detail
	   join return_scrap_item on scrap_skid_detail.return_scrap_item_num = return_scrap_item.return_scrap_item_num
	   join ab_job on ab_job.ab_job_num = return_scrap_item.ab_job_num
	   join order_item on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
  where    scrap_skid_detail.scrap_skid_num = al_scrap_skid_num
  ;

  temper_rec  temper_cur%ROWTYPE;

begin
  for temper_rec in temper_cur loop
    ls_temper := temper_rec.temper;

    if FunctionResult is null then
      FunctionResult := ls_temper;
    else
      FunctionResult := FunctionResult || ' , ' || ls_temper;
    end if;
  end loop;

  return(FunctionResult);
end f_get_temper_string_4skid;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_TOTAL_DOWNTIME_BY_SHIFT" ( shift_id in shift.shift_num%type ) return integer is
  Result integer;
begin
  select 86400 * sum(dt_instance.ending_time - dt_instance.starting_time) into Result
  from dt_instance
  where dt_instance.shift_num = shift_id;

  return(Result);
end F_GET_TOTAL_DOWNTIME_BY_SHIFT;
/


