   elsif ls_sheet_type = 'liftgate' then
      select   nvl(li_width_minus, 0)
      into     ll_width_minus
      from     liftgate_shape
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'other' then
       select  nvl(x_4, 0)
       into    ll_width_minus
       from    x1_shape
       where   order_abc_num = al_order_abc_num
       and     order_item_num = al_order_item_num;

   else
      ll_width_minus := 0;
   end if;

   return ll_width_minus;

end f_get_width_minus_4order_item;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_GET_WIDTH_PLUS_4ORDER_ITEM"
(
    al_order_abc_num  in order_item.order_abc_num%type,
    al_order_item_num in order_item.order_item_num%type
)
return number

is

  ls_sheet_type varchar2(18);
  ll_width_plus      number(10,5);

begin

  ll_width_plus := 0;

  select trim(lower(sheet_type))
  into	 ls_sheet_type
  from	 order_item
  where  order_abc_num = al_order_abc_num
  and	 order_item_num = al_order_item_num;

  if ls_sheet_type = 'rectangle' then
      select  nvl(rt_width_plus, 0)
      into    ll_width_plus
      from    rectangle
      where   order_abc_num = al_order_abc_num
      and     order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'parallelogram' then
      select   nvl(p_width_plus, 0)
      into     ll_width_plus
      from     parallelogram
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'fender' then
      select   nvl(fe_side_plus, 0)
      into     ll_width_plus
      from     fender
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'chevron' then
       select  nvl(ch_width_plus, 0)
      into     ll_width_plus
      from     chevron
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

    elsif ls_sheet_type = 'circle' then
       select  nvl(c_diameter_plus, 0)
      into     ll_width_plus
      from     circle
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

    elsif ls_sheet_type = 'trapezoid' then
      select   nvl(tr_width_plus, 0)
      into     ll_width_plus
      from     trapezoid
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

  elsif ls_sheet_type = 'l.trapezoid' then
      select   nvl(ltr_width_plus, 0)
      into     ll_width_plus
      from     left_trapezoid
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

  elsif ls_sheet_type = 'r.trapezoid' then
      select   nvl(rtr_width_plus, 0)
      into     ll_width_plus
      from     right_trapezoid
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'reinforcement' then
      select   nvl(re_width_plus, 0)
      into     ll_width_plus
      from     reinforcement
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'liftgate' then
      select   nvl(li_width_plus, 0)
      into     ll_width_plus
      from     liftgate_shape
      where    order_abc_num = al_order_abc_num
      and      order_item_num = al_order_item_num;

   elsif ls_sheet_type = 'other' then
       select  nvl(x_3, 0)
       into    ll_width_plus
       from    x1_shape
       where   order_abc_num = al_order_abc_num
       and     order_item_num = al_order_item_num;

   else
      ll_width_plus := 0;
   end if;

   return ll_width_plus;

end f_get_width_plus_4order_item;
/


