  CREATE OR REPLACE FUNCTION "DBO"."F_SHEET_OR_SCRAP_SHIPMENT" (al_packing_list shipment.packing_list%type)
  return varchar2

  is

  li_count_sheet	number;
  li_count_scrap	number;
  FunctionResult	varchar2(5);

begin
  select count(*)
  into	 li_count_sheet
  from	 customer_order
	 join order_item on customer_order.order_abc_num = order_item.order_abc_num
	 join ab_job on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
	 join sheet_skid on ab_job.ab_job_num = sheet_skid.ab_job_num
	 join sheet_packing_item on sheet_skid.sheet_skid_num = sheet_packing_item.sheet_skid_num
	 join shipment on shipment.packing_list = sheet_packing_item.packing_list
  where  shipment.packing_list = al_packing_list;

  select count(*)
  into	 li_count_scrap
  from	 scrap_skid
	 join scrap_packing_item on scrap_skid.scrap_skid_num = scrap_packing_item.scrap_skid_num
	 join shipment on shipment.packing_list = scrap_packing_item.packing_list
  where  shipment.packing_list = al_packing_list;

  if li_count_sheet > 0 and li_count_scrap > 0 then
    FunctionResult := 'BOTH';
  elsif li_count_sheet > 0 then
    FunctionResult := 'SHEET';
  else --li_count_scrap > 0
    FunctionResult := 'SCRAP';
  end if;

  return(FunctionResult);
end f_sheet_or_scrap_shipment;

--create or replace public synonym f_sheet_or_scrap_shipment for dbo.f_sheet_or_scrap_shipment;
/


  CREATE OR REPLACE FUNCTION "DBO"."F_UNIX_FILE_EXISTS" (as_directory in varchar2, as_file_name in varchar2)
  return number is

/*

utl.fgetattr(
   location    IN VARCHAR2,
   filename    IN VARCHAR2,
   exists      OUT BOOLEAN,
   file_length OUT NUMBER,
   blocksize   OUT NUMBER);

Parameters     Description
----------     -----------
location       Directory location of the source file, a DIRECTORY_NAME from the ALL_DIRECTORIES view (case sensitive)
filename	     The name of the source file to be copied
exists	       A BOOLEAN for whether or not the file exists
file_length	   The length of the file in bytes. NULL if file does not exist.
blocksize	     The file system block size in bytes. NULL if the file does not exist.

edi_loc        varchar2(50) := '/templar/templar/incoming/senddata';

*/

lb_exists	   boolean;
li_file_length	   integer;
ln_blocksize	   number;

ln_result	   number;

begin

  utl_file.fgetattr(as_directory, as_file_name, lb_exists, li_file_length, ln_blocksize);


  if lb_exists then
      ln_result := 1;
   else
      ln_result := 0;
   end if;

   --return nvl(li_file_length, 0);
   return ln_result;

end f_unix_file_exists;
/* Alex Gerlants. 09/07/2016. End */
/


