  CREATE OR REPLACE FUNCTION "DBO"."UPDATE_SHIFT_DT_TOTAL" (p_shift_id shift.shift_num%type) return integer is
  Result integer;
  total shift.dt_total%type;
  cursor mid is
  select shift.shift_num from shift
  where shift.schedule_type = 3 and shift.line_num = 6;
begin
  /*
  for test in mid loop
      select 86400 * sum(dt_instance.ending_time - dt_instance.starting_time) into total
      from dt_instance
      where dt_instance.shift_num = test.shift_num;

      update shift set shift.dt_total = total
      where shift.shift_num = test.shift_num;



  end loop;
  commit;
  */

  select 86400 * sum(dt_instance.ending_time - dt_instance.starting_time) into total
  from dt_instance
  where dt_instance.shift_num = p_shift_id;

  update shift set shift.dt_total = total
  where shift.shift_num = p_shift_id;
  commit;

  return(total);
end update_shift_dt_total;
/


  CREATE OR REPLACE PROCEDURE "DBO"."ALEX_870_REBAND_COILS"
     (
	al_customer_id	customer.customer_id%type
     )
is

  /*
  /*
   aluminum blanking: duns:039630926	 edi id:039630926t	  qualifier: 01
   */



  --alex gerlants. 11/15/2016. commented out, and added the line after.
  --edi_loc varchar2(50) := '/templar/templar/incoming/senddata';
  edi_loc varchar2(50) := dbo.get_edi_destination('EDI_DIR');

  edi_file	  varchar2(50) := 'edi_out.txt';
  --edi_file_prefix varchar2(50) := 'S_alcan_870_reband_'; --Production
  edi_file_prefix varchar2(50) := 's_alcan_870_reband_'; --Development
  edi_file_handle utl_file.file_type;
  su_duns	  varchar2(10);
  --al_customer_id  customer.customer_id%type;
  ll_cur_coil	  coil.coil_abc_num%type;

  ll_cur_job ab_job.ab_job_num%type;

  ll_gs_log integer;
  ll_st_log integer;

  ls_today   varchar2(20) := to_char(sysdate, 'YYYYMMDD');
  ls_today_4 varchar2(20) := to_char(sysdate, 'YYMMDD');
  ls_now     varchar2(20) := to_char(sysdate, 'HH24MI');

  ls_po varchar2(20);
  ls_finished_goods varchar2(32);
  ls_cust_prod_line varchar2(8);

  ld_scrap_870_date ab_job.scrap_870_date%type;
  ld_job_scrap_870_date ab_job.scrap_870_date%type;

  ls_coil_org_num coil.coil_org_num%type;
  ls_heat coil.lot_num%type;
  ls_scrap_coil_org_num coil.coil_org_num%type;

  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%type;
  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%type;
  ls_sheet_type order_item.sheet_type%type;

  ll_prime_nw coil.net_wt%type;
  ll_scrap_start_nw coil.net_wt%type;
  ll_scrap_end_nw coil.net_wt%type;
  ll_scrap_nw coil.net_wt%type;
  ll_process_quantity  coil.net_wt%type;
  ll_process_end_wt  coil.net_wt%type;
  lr_theo_unit_wt order_item.theoretical_unit_wt%type;

  --ll_edi_file_id integer;
  ll_edi_file_id integer;

  ll_item_count integer;

  li_hl01 integer;
  li_hllin integer;
  li_coil_status coil.coil_status%type;

  cursor cust_cur is
    select customer_id from customer where customer_id in (1153,1459,2582); ---add customer id here if you want to send 870 for more customers

  cursor coil_cur is
  select unique coil.coil_abc_num, ab_job.ab_job_num
    from ab_job,
	 coil,
	 production_sheet_item,
	 sheet_skid,
	 sheet_skid_detail,
	 customer_order,
	 process_coil
   where ( sheet_skid_detail.sheet_skid_num = sheet_skid.sheet_skid_num ) and
	 ( sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num ) and
	 ( coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
	 ( ab_job.ab_job_num = sheet_skid.ab_job_num ) and
	 ( coil.coil_abc_num = process_coil.coil_abc_num ) and
	 ( ab_job.ab_job_num = process_coil.ab_job_num ) and
	 ( ab_job.order_abc_num = customer_order.order_abc_num ) and
	 ( ab_job.job_status = 0 ) and
	 (  coil.coil_status = 7 ) and
	 ( customer_order.orig_customer_id = al_customer_id ) and
	 ( production_sheet_item.prod_item_edi870_date is null ) and
	 ( process_coil.scrap_870_date is null ) and
	 ( coil.scrap_870_date is null ) and
	 ( sheet_skid.skid_sheet_status in (0, 2, 4, 12, 13, 16) );

  cursor alcan_870_cur is
   select production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   null done
      from sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     where (sheet_skid.skid_sheet_status in (0, 2, 4, 12, 13, 16)) -- 2: ready; 8: warehouse ready; 13: partial ready; 7: partial; 12: sample; 4: onhold; hold_for_cert:16
       and (production_sheet_item.prod_item_edi870_date is null)
       and (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       and (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       and (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       and (coil.customer_id = al_customer_id)
       and (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
 		   and (production_sheet_item.ab_job_num = ab_job.ab_job_num)
		   and (ab_job.order_abc_num = order_item.order_abc_num)
		   and (ab_job.order_item_num = order_item.order_item_num)
      and (production_sheet_item.coil_abc_num = ll_cur_coil)
      and (production_sheet_item.ab_job_num = ll_cur_job);


  type store_tabletype is table of varchar2(32767) index by binary_integer;
  x12_table store_tabletype;
  i	    binary_integer := 0;

  item_rec  alcan_870_cur%rowtype;
  coil_rec  coil_cur%rowtype;

  type prod_item_type is table of production_sheet_item.prod_item_num%type index by binary_integer;
  item_num prod_item_type;
  k	   binary_integer := 0;


begin

  --for cust_rec in cust_cur loop
    --- outer loop of customer_id
    --al_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;

  select count(coil.coil_abc_num)
  into ll_item_count
    from ab_job,
	 coil,
	 production_sheet_item,
	 sheet_skid,
	 sheet_skid_detail,
	 customer_order,
	 process_coil
   where ( sheet_skid_detail.sheet_skid_num = sheet_skid.sheet_skid_num ) and
	 ( sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num ) and
	 ( coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
	 ( coil.coil_abc_num = process_coil.coil_abc_num ) and
	 ( ab_job.ab_job_num = process_coil.ab_job_num ) and
	 ( ab_job.ab_job_num = sheet_skid.ab_job_num ) and
	 ( ab_job.order_abc_num = customer_order.order_abc_num ) and
	 ( ab_job.job_status = 0 ) and
	 (  coil.coil_status = 7 ) and
	 ( customer_order.orig_customer_id = al_customer_id ) and
	 ( production_sheet_item.prod_item_edi870_date is null ) and
	 ( process_coil.scrap_870_date is null ) and
	 ( coil.scrap_870_date is null ) and
	 ( sheet_skid.skid_sheet_status in (0, 2, 4, 12, 13, 16) );

    if (ll_item_count <> 0) then


      select edi_st_log_seq.nextval into ll_st_log from dual;
      select edi_gs_log_seq.nextval into ll_gs_log from dual;

      select customer.customer_duns_number_string
	into su_duns
	from customer
       where customer.customer_id = al_customer_id;

      --Production
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*0015049350011G *' ||
      --		ls_today_4 || '*' || ls_now || '*U*00401*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';

      --Development
      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*NOVLSTEST      *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*T**';

      i := i + 1;
      --Production
      --x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
      --		ls_today || '*' || ls_now || '*' ||
      --		to_char(ll_gs_log) || '*X*' || '004010';

      --Development
      x12_table(i) := 'GS*RS*2NDSFTP*' || 'NOVLSTEST' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';

      i := i + 1;

      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      for coil_rec in coil_cur loop    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;
	  ll_cur_job := coil_rec.ab_job_num;

	  for item_rec in alcan_870_cur loop   -- item loop

	     li_hl01 := li_hl01 + 1;

	     x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	     i := i + 1;

	     select nvl(customer_order.orig_customer_po, 'NA'),
		    nvl(order_item.cust_prod_line_id, 'NA'),
		    nvl(order_item.finished_goods_material_num, 'NA')
	     into   ls_po, ls_cust_prod_line, ls_finished_goods
	     from   order_item,
		    ab_job,
		    customer_order
	     where  (ab_job.order_abc_num = customer_order.order_abc_num)
	     and    (ab_job.order_abc_num = order_item.order_abc_num)
	     and    (ab_job.order_item_num = order_item.order_item_num)
	     and    (ab_job.ab_job_num = ll_cur_job);

	     if (ls_po <> ls_finished_goods) and (ls_po <> 'NA' ) then
		 x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		 i := i + 1;
	     end if;

	     x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	     i := i + 1;

	     x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	     i := i + 1;


	     x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	     i := i + 1;

	     x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			      '*NA';
	     i := i + 1;

	     x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	     i := i + 1;

	     x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
				item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	     i := i + 1;

	     if item_rec.skid_sheet_status = 2 then
		 x12_table(i) := 'PID*S*MA*ST*1*' ||
				to_char(item_rec.sheet_skid_display_num);
		i := i + 1;
	     elsif item_rec.skid_sheet_status = 4 then
		x12_table(i) := 'PID*S*MA*ST*3*' ||
				to_char(item_rec.sheet_skid_display_num);
		i := i + 1;
	     elsif item_rec.skid_sheet_status = 13 then
		x12_table(i) := 'PID*S*MA*ST*8*' ||
				to_char(item_rec.sheet_skid_display_num);
		i := i + 1;
	     else
		x12_table(i) := 'PID*S*MA*ST*4*' ||
				to_char(item_rec.sheet_skid_display_num);
		i := i + 1;
	     end if;

	     x12_table(i) := 'PID*S*MAC*ST*01';
	     i := i + 1;
	     x12_table(i) := 'PID*S*PR*ST*19';
	     i := i + 1;
	     x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			      '*LB*01';
	     i := i + 1;
	     x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			      '*LB*01';
	     i := i + 1;
	     x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			      '*PC';
	     i := i + 1;

	     item_num(k) := item_rec.prod_item_num;
	     k := k + 1;

	  end loop;  -- item loop


	  select scrap_870_date, coil_org_num, lot_num
	  into ld_scrap_870_date, ls_coil_org_num, ls_heat
	  from coil
	  where coil_abc_num = ll_cur_coil;

	  select scrap_870_date
	  into	 ld_job_scrap_870_date
	  from	 process_coil
	  where  (coil_abc_num = ll_cur_coil) and (ab_job_num = ll_cur_job);

	  if (ld_scrap_870_date is null) and (ld_job_scrap_870_date is null) then  -- scrap not sent

	    select b.coil_org_num,
		   nvl(a.process_quantity, 0) process_quan,
		   nvl(a.process_end_wt, 0) process_end_wt
	    into   ls_scrap_coil_org_num, ll_scrap_start_nw, ll_scrap_end_nw
	    from   process_coil a, coil b
	    where  (b.coil_abc_num = ll_cur_coil)
	    and    (a.coil_abc_num = b.coil_abc_num)
	    and    (a.ab_job_num = ll_cur_job);

	    --scrap info

	    select  nvl(sum(production_sheet_item.prod_item_net_wt),0)
	    into    ll_prime_nw
	    from    production_sheet_item
	    where   (production_sheet_item.ab_job_num = ll_cur_job) and
		    (production_sheet_item.coil_abc_num = ll_cur_coil);

	    ll_scrap_nw := ll_scrap_start_nw - ll_scrap_end_nw - ll_prime_nw;

	    if ll_scrap_nw > 0 then

	       li_hl01 := li_hl01 + 1;

	       x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
	       i := i + 1;

	       if (ls_po <> ls_finished_goods) and (ls_po <> 'NA' ) then
		  x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		  i := i + 1;
	       end if;

	       x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	       i := i + 1;

	       x12_table(i) := 'PO1**1*UN****' || '***SN*' || ls_scrap_coil_org_num ;
	       i := i + 1;

	       x12_table(i) := 'PID*S*MA*ST*S';
	       i := i + 1;

	       x12_table(i) := 'PID*S*MAC*ST*05';
		i := i + 1;

	       x12_table(i) := 'PID*S*PR*ST*19';
		i := i + 1;

	       x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
	       i := i+1;
	    end if; --if ll_scrap_nw > 0 then

       end if;	-- scrap not sent
    end loop;	-- coil loop

      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- write edi to file

      if li_hl01 > 1 then -- write edi file only if item > 0
	select edi_file_id_seq.nextval
	into   ll_edi_file_id
	from   dual;

	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id) || '.edi';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	for j in 0 .. i loop
	  utl_file.put_line(edi_file_handle, x12_table(j));
	end loop;

	utl_file.fclose(edi_file_handle);
      end if; -- end writing edi file

      edi_file	      := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle, 'Sending Time: ' || to_char(sysdate, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle, 'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

/*
      insert into outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	values
	  (ll_edi_file_id,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   sysdate,
	   edi_file,
	   0,
	   al_customer_id,
	   ll_st_log,
	   '870');

      for coil_rec in coil_cur loop    -- coil loop date
	  select  coil.scrap_870_date
	  into	  ld_scrap_870_date
	  from	  coil
	  where   coil.coil_abc_num = coil_rec.coil_abc_num;


	  --coil.scrap_870_date and process_coil.scrap_870_date are updated in edi_alcan_870
	  --thus if it already updated, do not update here
	  if ld_scrap_870_date is null then
	    update  coil
	    set     coil.scrap_870_date = sysdate,
		    coil.edi_file_id_870_reject = ll_edi_file_id;

	    update  process_coil
	    set     scrap_870_date = sysdate
	    where   coil_abc_num = coil_rec.coil_abc_num;
	  else --ld_scrap_870_date is not null, update edi_file_id only
	    update  coil
	    set     coil.edi_file_id_870_reject = ll_edi_file_id
	    where   coil.coil_abc_num = coil_rec.coil_abc_num;
	  end if;

      end loop;   -- coil loop date

      --commit;

      for m in 0 .. k - 1 loop
	 update production_sheet_item
	     set prod_item_edi870_date = sysdate,
		 edi_file_id_870 = ll_edi_file_id
	   where production_sheet_item.prod_item_num = item_num(m);
      end loop;

      commit;
*/

    end if; --end if in select count(*)

  --end loop; ------ end of outer loop customer_id

exception
  when utl_file.invalid_path then
    utl_file.fclose_all;
    return;
  when utl_file.invalid_mode then
    utl_file.fclose_all;
    return;
  when utl_file.invalid_operation then
    utl_file.fclose_all;
    return;
  when utl_file.write_error then
    utl_file.fclose_all;
    return;
  when others then
    utl_file.fclose_all;
    return;
end;
/


  CREATE OR REPLACE PROCEDURE "DBO"."ALEX_870_REJ_COILS"
     (
	al_customer_id	customer.customer_id%TYPE
     )
IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  --edi_file_prefix VARCHAR2(50) := 'S_alcan_'; --This is for Production
  edi_file_prefix VARCHAR2(50) := 'alex_870_novelis_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(20); /* Alex Gerlants. Changed from (10) to (20) */
  --ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil		 coil.coil_abc_num%TYPE;
  ll_cur_job		 ab_job.ab_job_num%TYPE;
  ls_scrap_coil_org_num  coil.coil_org_num%TYPE;
  ll_scrap_start_nw	 process_coil.process_quantity%TYPE;
  ll_scrap_end_nw	 process_coil.process_end_wt%TYPE;
  ll_prime_nw		 production_sheet_item.prod_item_net_wt%TYPE;
  ls_cust_prod_line	 varchar2(8);

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  --ls_cust_prod_line VARCHAR2(8);

  --ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  --ls_coil_org_num coil.coil_org_num%TYPE;
  --ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

 -- ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  --ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  --li_coil_status   coil.coil_status%TYPE; /* Alex Gerlants. New variable */

  ll_rejected_coils	integer; /* Alex Gerlants. 07/25/2017 */
  --ls_isa_header_created char(1) := 'N'; /* Alex Gerlants. 07/25/2017 */

  consumed_coil_num coil.consumed_coil_num%TYPE;
  li_coil_status    coil.coil_status%TYPE;

  ld_scrap_870_date ab_job.scrap_870_date%type;
  ld_job_scrap_870_date ab_job.scrap_870_date%type;
  ls_coil_org_num	coil.coil_org_num%type;
  ls_heat		coil.lot_num%type;

   /* Alex Gerlants. 07/25/2017. Begin */
   cursor reject_coils_cur is
   select coil.coil_abc_num coil_abc_num,
	  coil.coil_org_num coil_org_num,
	  ab_job.ab_job_num ab_job_num,
	  nvl(coil.material_num, ' ') material_num,
	  nvl(coil.net_wt, 0) net_wt,
	  nvl(coil.net_wt_balance, 0) net_wt_balance,
	  nvl(customer_order.orig_customer_po, 'NA') orig_customer_po,
	  nvl(order_item.cust_prod_line_id, 'NA') cust_prod_line_id,
	  nvl(order_item.finished_goods_material_num, 'NA') finished_goods_material_num,
	  nvl(coil.consumed_coil_num, ' ') consumed_coil_num
   from   reject_coil
	  join coil on coil.coil_abc_num = reject_coil.coil_abc_num
	  join ab_job on reject_coil.ab_job_num = ab_job.ab_job_num
	  join customer_order on ab_job.order_abc_num = customer_order.order_abc_num
	  join order_item on ab_job.order_abc_num = order_item.order_abc_num and ab_job.order_item_num = order_item.order_item_num
   where  coil.customer_id = al_customer_id
   and	  ab_job.job_status = 0
   and	  coil.scrap_870_date is null;

   reject_rec  reject_coils_cur%ROWTYPE;

   /* Alex Gerlants. 07/25/2017. End */


  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  /*
  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;
  */

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;


BEGIN

  --FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
  --  ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    --k 	     := 0;
    --p 	     := 0;

  --Check for rejected coils
    select count(*)
    into   ll_rejected_coils
    from   reject_coil
	   join coil on coil.coil_abc_num = reject_coil.coil_abc_num
	   join ab_job on reject_coil.ab_job_num = ab_job.ab_job_num
	   join customer_order on ab_job.order_abc_num = customer_order.order_abc_num
	   join order_item on ab_job.order_abc_num = order_item.order_abc_num and ab_job.order_item_num = order_item.order_item_num
    where  coil.customer_id = al_customer_id
    and    ab_job.job_status = 0
    and    coil.scrap_870_date is null;

    if (ll_rejected_coils > 0) then

      select edi_st_log_seq.nextval into ll_st_log from dual;
      select edi_gs_log_seq.nextval into ll_gs_log from dual;


      select customer.customer_duns_number_string
	into su_duns
	from customer
       where customer.customer_id = al_customer_id;

      /* Alex Gerlants. '*0*P**' for PRODUCTION */
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*0015049350011G *' ||
      --		ls_today_4 || '*' || ls_now || '*U*00401*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';

      /* Alex Gerlants. '*0*T**' for TEST */
      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*NOVLSTEST      *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*T**';

      i := i + 1;
      x12_table(i) := 'GS*RS*2NDSFTP*' || 'NOVLSTEST' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';

      --x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
      --		ls_today || '*' || ls_now || '*' ||
      --		to_char(ll_gs_log) || '*X*' || '004010';

      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      --ls_isa_header_created := 'Y'; /* Alex Gerlants. 07/25/2017 */

      li_hl01 := 0;

      ----------------------------------------------------------------------

      for reject_rec in reject_coils_cur loop

	ll_cur_coil := reject_rec.coil_abc_num;
	ll_cur_job := reject_rec.ab_job_num;


	select nvl(customer_order.orig_customer_po, 'NA'),
	       nvl(order_item.cust_prod_line_id, 'NA'),
	       nvl(order_item.finished_goods_material_num, 'NA')
	into   ls_po, ls_cust_prod_line, ls_finished_goods
	from   order_item,
	       ab_job,
	       customer_order
	where  (ab_job.order_abc_num = customer_order.order_abc_num)
	and    (ab_job.order_abc_num = order_item.order_abc_num)
	and    (ab_job.order_item_num = order_item.order_item_num)
	and    (ab_job.ab_job_num = ll_cur_job);


	coil_num(p) := ll_cur_coil;
	p := p + 1;

	ls_po := reject_rec.orig_customer_po;
	ls_finished_goods := reject_rec.finished_goods_material_num;
	consumed_coil_num := reject_rec.consumed_coil_num;

	ll_scrap_nw := reject_rec.net_wt - reject_rec.net_wt_balance;

	IF ll_scrap_nw > 0 then

	   li_hl01 := li_hl01 + 1;

	   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
	   i := i + 1;

	   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	      x12_table(i) := 'PRF*' || reject_rec.orig_customer_po || '****' || reject_rec.cust_prod_line_id;
	      i := i + 1;
	   END IF;

	   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	    i := i + 1;

	   x12_table(i) := 'REF*IX*' || to_char(consumed_coil_num);
	    i := i + 1;

	   x12_table(i) := 'PO1**1*UN****' || '***SN*' || reject_rec.coil_org_num ;
	    i := i + 1;

	   x12_table(i) := 'PID*S*MA*ST*S';
	    i := i + 1;
	   x12_table(i) := 'PID*S*MAC*ST*05';
	     i := i + 1;
	   x12_table(i) := 'PID*S*PR*ST*19';
	     i := i + 1;

	   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
	    i := i+1;
	end if; --IF ll_scrap_nw > 0 then

	-----------------------------------------

	select scrap_870_date, coil_org_num, lot_num
	into ld_scrap_870_date, ls_coil_org_num, ls_heat
	from coil
	where coil_abc_num = ll_cur_coil;

	select scrap_870_date
	into   ld_job_scrap_870_date
	from   process_coil
	where  (coil_abc_num = ll_cur_coil) and (ab_job_num = ll_cur_job);

	if (ld_scrap_870_date is null) and (ld_job_scrap_870_date is null) then  -- scrap not sent

	  select b.coil_org_num,
		 nvl(a.process_quantity, 0) process_quan,
		 nvl(a.process_end_wt, 0) process_end_wt
	  into	 ls_scrap_coil_org_num, ll_scrap_start_nw, ll_scrap_end_nw
	  from	 process_coil a, coil b
	  where  (b.coil_abc_num = ll_cur_coil)
	  and	 (a.coil_abc_num = b.coil_abc_num)
	  and	 (a.ab_job_num = ll_cur_job);

	  --scrap info

	  select  nvl(sum(production_sheet_item.prod_item_net_wt),0)
	  into	  ll_prime_nw
	  from	  production_sheet_item
	  where   (production_sheet_item.ab_job_num = ll_cur_job) and
		  (production_sheet_item.coil_abc_num = ll_cur_coil);

	  ll_scrap_nw := ll_scrap_start_nw - ll_scrap_end_nw - ll_prime_nw;

	  if ll_scrap_nw > 0 then

	     li_hl01 := li_hl01 + 1;

	     x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
	     i := i + 1;

	     if (ls_po <> ls_finished_goods) and (ls_po <> 'NA' ) then
		x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		i := i + 1;
	     end if;

	     x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	     i := i + 1;

	     x12_table(i) := 'PO1**1*UN****' || '***SN*' || ls_scrap_coil_org_num ;
	     i := i + 1;

	     x12_table(i) := 'PID*S*MA*ST*S';
	     i := i + 1;

	     x12_table(i) := 'PID*S*MAC*ST*05';
	      i := i + 1;

	     x12_table(i) := 'PID*S*PR*ST*19';
	      i := i + 1;

	     x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
	     i := i+1;
	  end if; --if ll_scrap_nw > 0 then

	end if; --if (ld_scrap_870_date is null) and (ld_job_scrap_870_date is null) then  -- scrap not sent

	-----------------------------------------

      end loop; --for reject_rec in reject_coils_cur loop

      ----------------------------------------------------------------------


      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      if li_hl01 > 0 then  --Alex Gerlants. Changed from "> 1" to "> 0"
	-- WRITE EDI FILE ONLY IF ITEM > 0
	select edi_file_id_seq.nextval
	  into ll_edi_file_id_aleris
	  from dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id_aleris) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
      /*
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   al_customer_id,
	   ll_st_log,
	   '870');

	   --update    coil
	   --set       coil.scrap_870_date = sysdate
	   --where     coil.coil_abc_num = ll_cur_coil;

	for m in 0..p - 1 loop
	    select  coil.coil_status
	    into    li_coil_status
	    from    coil
	    where   coil.coil_abc_num = coil_num(m);

	    if li_coil_status <> 7 then --Skip rebanded coils
		update	coil
		set	coil.scrap_870_date = sysdate
		where	coil.coil_abc_num = coil_num(m);

		update	process_coil
		set	scrap_870_date = sysdate
		where	coil_abc_num = coil_num(m)
		and	scrap_870_date is null;
	    end if;

	end loop;

	commit;
	*/

    end if; --if (ll_rejected_coils > 0) then


EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."DELETE_SHIFT" (al_id in shift.shift_num%type) is
	 Cursor c_instance IS
	 SELECT INSTANCE_NUM FROM DT_INSTANCE
	 WHERE SHIFT_NUM = al_id;

begin
  FOR instances IN c_instance LOOP
      DELETE FROM DT_INSTANCE_DETAIL
      WHERE DT_INSTANCE_DETAIL.INSTANCE_NUM = instances.instance_num;
      DELETE FROM DT_INSTANCE
      WHERE DT_INSTANCE.INSTANCE_NUM = instances.instance_num;
  END LOOP;

  DELETE FROM SHIFT_COIL
  WHERE SHIFT_COIL.SHIFT_NUM = al_id;

  DELETE FROM SHIFT
  WHERE SHIFT.SHIFT_NUM = al_id;
  commit;

end DELETE_SHIFT;
/


  CREATE OR REPLACE PROCEDURE "DBO"."DT_DROPUSEROBJECTBYID" ( PARAM_ID IN NUMBER ) AS BEGIN DELETE FROM MICROSOFTDTPROPERTIES WHERE OBJECTID = PARAM_ID; END DT_DROPUSEROBJECTBYID;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDIALCANSCRAP870BYJOB_BACKUP" IS

/*
		   DUNS: 01 039630926T
		   Customer: ALCAN(34,35,10,1153)
		   Alcan Rolled Product  	X.121  		  0015049350011G
		   Kingston Duns: 241003755
*/


edi_loc varchar2 (50) := '/templar/templar/incoming/senddata';

--v_edi_text_alcan varchar2(32767);
--edi_loc varchar2(50):='/tmp';
edi_file varchar2 (50) := 'edi_out.txt';
edi_file_prefix varchar2 (50) := 'S_alcan_scrap';
edi_file_handle UTL_FILE.FILE_TYPE;
su_duns varchar2(10);
ll_customer_id integer :=1153;

ll_gs_log integer;
ll_st_log integer;
--scrap_job_num ab_job.ab_job_num%type;
prime_nw coil.net_wt%type;
scrap_nw coil.net_wt%type;
--ll_bsn_log integer;


ls_today varchar2(20):= to_char(sysdate, 'YYYYMMDD');
ls_today_4 varchar2(20):= to_char(sysdate, 'YYMMDD');
ls_now varchar2(20) := to_char(sysdate, 'HH24MI'); -- time in 24 hours format....Tony

ls_po varchar2(20);
ls_so varchar2(30);
--ll_edi_file_id integer;
ll_edi_file_id_alcan integer;

ll_job_count integer;
--coil_of_the_job coil.coil_abc_num%type;
ll_ab_job ab_job.ab_job_num%type;

--ll_onhold_wt coil.net_wt%type;
--ll_reject_wt coil.net_wt%type;
--ll_reband_wt coil.net_wt%type;

--li_customer_id shipment.customer_id%TYPE;
--li_des_sh_cust_id shipment.des_sh_cust_id%TYPE;

--date1 date;
--date2 date;
--coil_ini_date date;


li_HL01 integer;

Cursor cust_cur is
SELECT customer_id from customer where customer_id in (1153,1459,2582);        ---Add customer id here if you want to send 870 for more customers


Cursor alcan_870_cur IS
       SELECT a.ab_job_num, b.orig_customer_po, nvl(b.sales_order, ' ') sales_order
       FROM ab_job a, customer_order b
       WHERE (a.order_abc_num = b.order_abc_num) and
	     (a.job_status = 0) and
	     (b.orig_customer_id = ll_customer_id) and
	     (a.scrap_870_date is null);

Cursor coil_info IS
       SELECT process_coil.coil_abc_num, process_coil.process_quantity, coil.coil_alloy2, coil.coil_org_num, nvl(coil.consumed_coil_num, ' ') consumed_coil_num , process_coil.process_end_wt
       FROM process_coil, coil
       WHERE (process_coil.ab_job_num = ll_ab_job) and
	     (process_coil.coil_abc_num = coil.coil_abc_num);


TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
 x12_table store_tabletype;
i binary_integer := 0;

TYPE job_num_type IS TABLE OF ab_job.ab_job_num%type INDEX BY BINARY_INTEGER;
job_num job_num_type;
j binary_integer :=0;

--item_rec alcan_870_cur%rowtype;

BEGIN

for cust_rec in cust_cur
loop --- Outer loop of customer_id
     ll_customer_id := cust_rec.customer_id;
     i:=0;
     j:=0;

     SELECT count(*) into ll_job_count
       FROM ab_job a, customer_order b
       WHERE (a.order_abc_num = b.order_abc_num) and
	     (a.job_status = 0) and
	     (b.orig_customer_id = ll_customer_id) and
	     (a.scrap_870_date is null);

 IF ll_job_count <> 0 THEN

    SELECT edi_st_log_seq.NEXTVAL INTO ll_st_log FROM DUAL;
    SELECT edi_gs_log_seq.NEXTVAL INTO ll_gs_log FROM DUAL;

    select customer.customer_duns_number_string into su_duns from customer where customer.customer_id = ll_customer_id;

    x12_table(i) := 'ISA*00*'||'	  *00*		*01*039630926T	   *09*0015049350011G *'||ls_today_4 ||'*'|| ls_now ||'*U*00401*'||LPAD(to_char(ll_gs_log),9,'0')||'*0*P**'; i := i + 1;
    x12_table(i) := 'GS*RS*039630926T*'||'001504935001' || '*' || ls_today ||'*' || ls_now || '*' ||to_char(ll_gs_log) || '*X*' || '004010'; i := i + 1;
    x12_table(i):= 'ST*870*' || to_char(ll_st_log); i := i +1;
    x12_table(i):= 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today || '***' || ls_now || '*****'; i := i +1;
    x12_table(i):= 'DTM*009*' || ls_today || '*' || ls_now; i := i +1;
    x12_table(i) := 'N1*SU**1*' || su_duns ||'*NA'; i := i +1;
    x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926T'; i := i + 1;


    --open alcan_870_cur;
    --fetch alcan_870_cur INTO item_rec;
    --close alcan_870_cur;

    li_HL01 := 1;

    for job_rec IN alcan_870_cur -- job loop
    loop
	ll_ab_job := job_rec.ab_job_num;
	ls_po := job_rec.orig_customer_po;
	ls_so := job_rec.sales_order;
	--ls_po := item_rec.customer_po;
	IF INSTR(ls_po,'-') > 0
	THEN
	    ls_po := substr(ls_po, 0, instr(ls_po,'-')-1);
	END IF;


	job_num(j) := ll_ab_job;
	j := j+1;

	for coil_rec IN coil_info   --coil loop
	loop
		SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0) into prime_nw
		FROM production_sheet_item
		WHERE (production_sheet_item.ab_job_num = ll_ab_job) and
		      (production_sheet_item.coil_abc_num = coil_rec.coil_abc_num);

		--ll_onhold_wt := NVL(f_get_coil_onhold_wt(coil_rec.coil_abc_num, coil_rec.process_quantity),0);
		--ll_reband_wt := NVL(f_get_coil_rebanded_wt(coil_rec.coil_abc_num, coil_rec.process_quantity),0);
		--ll_reject_wt := NVL(f_get_coil_rejected_wt(coil_rec.coil_abc_num, coil_rec.process_quantity),0);

		--scrap_nw := coil_rec.process_quantity - ll_onhold_wt - ll_reband_wt - ll_reject_wt - prime_nw;

		scrap_nw := coil_rec.process_quantity - coil_rec.process_end_wt - prime_nw;



		IF scrap_nw > 0 then
		   x12_table(i) := 'HL*'||to_char(li_HL01)||'**I'; i := i +1;

		   /*
		   SELECT NVL(ALLOY_TYPE.ALCAN_SCRAP_PO, '6800'||coil_rec.coil_alloy2) into ls_po
		       FROM ALLOY_TYPE
		       WHERE ALLOY_TYPE.ALLOY = coil_rec.coil_alloy2;
		   */
		   x12_table(i) := 'PRF*' || ls_po ||'****NA'; i := i+1;
		   x12_table(i) := 'DTM*206*' ||ls_today || '*' || ls_now ||'*ED'; i := i+1;
		   x12_table(i) := 'REF*SE*' || 'T1' ||coil_rec.coil_abc_num || '-' ||to_char(ll_ab_job) ; i := i+1;
		   --x12_table(i) := 'REF*SE*' ||coil_rec.coil_org_num; i := i+1;

		   --x12_table(i) := 'REF*IX*' || coil_rec.consumed_coil_num;
		   --i := i + 1;


		   x12_table(i) := 'REF*MI*' || to_char(ll_ab_job); i := i+1;
		   --x12_table(i) := 'REF*RV*' ||coil_rec.coil_org_num ||'*NA'; i := i+1;
		   x12_table(i) := 'REF*RV*' || 'T1' || coil_rec.coil_abc_num || '-' || to_char(ll_ab_job) || '*NA'; i := i+1;

		   --x12_table(i) := 'PO1**1*UN****' || '***SN*' ||coil_rec.coil_org_num; i := i+1;


		   IF ls_so = ' ' THEN
		      x12_table(i) := 'PO1**1*UN****' || '***SN*' || coil_rec.coil_org_num;
		      i := i + 1;
		   ELSE
		      x12_table(i) := 'PO1**1*UN***VO*' || ls_so || '***SN*' || coil_rec.coil_org_num;
		      i := i + 1;
		   END IF;


		   x12_table(i) := 'PID*S*MA*ST*S'; i := i+1; -- ST*S for scrap --Tony

		   x12_table(i) := 'PID*S*MAC*ST*05'; i := i+1;
		   --x12_table(i) := 'PID*S*MAC*ST*03'; i := i+1; or this one , need test

		   x12_table(i) := 'PID*S*PR*ST*19'; i := i+1;
		   x12_table(i) := 'MEA*WT*N*' || to_char(scrap_nw) || '*LB*01'; i := i+1;

		   li_HL01 := li_HL01 +1;
		end if; -- end if scrap_nw >0
	end loop; -- end of coil loop
    end loop;	  -- end of job loop



    x12_table(i) :=  'CTT*' || to_char(li_HL01 - 1); i := i+1;
    x12_table(i) :=  'SE*' || to_char (i-1) ||'*'|| to_char(ll_st_log); i := i+1;
    x12_table(i) :=  'GE*1*' || to_char (ll_gs_log); i := i+1;
    x12_table(i) :=  'IEA*1*' || LPAD(to_char(ll_gs_log),9,'0');


-- Write EDI to file

    IF li_HL01 > 1 then --write to file only if items > 0
	 SELECT edi_file_id_seq.NEXTVAL INTO ll_edi_file_id_alcan FROM DUAL;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--		  edi_file:= edi_file_prefix || to_char(ll_edi_file_id_alcan) ||'.870';
		edi_file:= edi_file_prefix || to_char(ll_edi_file_id_alcan) ||'.edi';
		edi_file_handle := UTL_FILE.FOPEN(edi_loc, edi_file, 'W');

		for j in 0..i loop
		    UTL_FILE.PUT_LINE(edi_file_handle, x12_table(j));
						       -- v_edi_text_alcan:=v_edi_text_alcan||x12_table(j)||CHR(10);
		end loop;
	 UTL_FILE.FCLOSE(edi_file_handle);
    END IF;

    /*--added by Victor Huang on 06/05 for function acknowlegement
    INSERT INTO edi_fa(gs_num, duns_num, send_time, edi_file_name)
    VALUES(ll_gs_log, su_duns, sysdate, edi_file);
    COMMIT;*/

    --added by Victor Huang on 12/07 for verifying 997
  INSERT INTO outbound_edi_transaction(edi_file_id,duns_from,duns_to,interchange_control_number,
  group_control_number,transaction_time,edi_file_name,fa_receive_status,customer_id,set_control_num,transaction_type_id)
  VALUES(ll_edi_file_id_alcan,'039630926',su_duns,ll_gs_log,ll_gs_log, sysdate, edi_file,0,ll_customer_id,ll_st_log,'870 Scrap');
  COMMIT;

    edi_file := 'send_edi_log';
    edi_file_handle :=utl_file.fopen(edi_loc,edi_file,'a');
    utl_file.put_line(edi_file_handle,'Type: 870 Scrap');
    utl_file.put_line(edi_file_handle,'Sending Time: '||to_char(sysdate, 'MM/DD/YY HH24:MI'));
    utl_file.put_line(edi_file_handle,'Interchange Control #: '||ll_gs_log);
    utl_file.put_line(edi_file_handle,'Group Control #: '||ll_gs_log);
    utl_file.put_line(edi_file_handle,'Set Control #: '||ll_st_log);
    utl_file.put_line(edi_file_handle,'');
    utl_file.put_line(edi_file_handle,'');
    utl_file.fclose(edi_file_handle);



	 FOR k in 0..j-1
	     LOOP
		UPDATE ab_job set ab_job.scrap_870_date = sysdate
		WHERE ab_job.ab_job_num = job_num(k);
	     END LOOP;

	 commit;


 END IF;       --end if in select count(*)



end loop; ------ End of outer loop customer_id


EXCEPTION
     WHEN NO_DATA_FOUND THEN
	  DBMS_OUTPUT.put_line('NO DATA FOUND!!!');
	  RETURN;
     WHEN UTL_FILE.INVALID_PATH THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
     WHEN UTL_FILE.INVALID_MODE THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN UTL_FILE.INVALID_OPERATION THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN UTL_FILE.WRITE_ERROR THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN OTHERS THEN
     UTL_FILE.FCLOSE_ALL;
     DBMS_OUTPUT.put_line('ERROR!!');
      RETURN;

 END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870" IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 'S_alcan_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers

  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    ( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID = ll_customer_id ) AND
    ( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    ( C.SCRAP_870_DATE is NULL ) AND
    ( SK.SKID_SHEET_STATUS in (0,2,4,12,13, 16) ); --Alex Gerlants. 03/22/2019. Added new status 16-Hold For Cert

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12, 16)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
								    --Alex Gerlants. 03/22/2019. Added new status 16-Hold For Cert
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = ll_cur_coil);

       CURSOR alcan_scrap_870_cur IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = ll_cur_coil)
	 AND (a.coil_abc_num = b.coil_abc_num)
	 AND (a.scrap_870_date is NULL);

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  return; --Alex Gerlants. 12/07/2020. Inserted this line to bypass the whole procedure as a part of 870 Novelis project.
	  --			       Novelis 870 will be created for a job, after the job is successfully saved in status 0-Done.
	  --			       Function dbo.f_edi_novelis_870_4job is responsible for this.

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;
    p		   := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 ( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 ( COIL.SCRAP_870_DATE is NULL ) AND
	 ( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13, 16) ); --Alex Gerlants. 03/22/2019. Added new status 16-Hold For Cert

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;

	  coil_num(p) := ll_cur_coil;
	  p := p + 1;


	FOR item_rec IN alcan_870_cur LOOP   -- item loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
		     ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	     AND (ab_job.order_abc_num = order_item.order_abc_num)
	     AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

      FOR scrap_rec IN alcan_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


		ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   END IF;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent
     END LOOP;	 -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id_aleris) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
--	   COMMIT;

     FOR m IN 0 .. k - 1 LOOP
       UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
	 WHERE production_sheet_item.prod_item_num = item_num(m);
    END LOOP;

--	COMMIT;

	FOR m in 0..p - 1 LOOP
		UPDATE coil
					SET coil.scrap_870_date = sysdate
		WHERE coil.coil_abc_num = coil_num(m);

	       UPDATE process_coil
					SET scrap_870_date = sysdate
		WHERE ( coil_abc_num = coil_num(m)) AND (scrap_870_date is NULL);

	     END LOOP;

	COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_06262017" IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 'S_alcan_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers

  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    ( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID = ll_customer_id ) AND
    ( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    ( C.SCRAP_870_DATE is NULL ) AND
    ( SK.SKID_SHEET_STATUS in (0,2,4,12,13) );

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = ll_cur_coil);

       CURSOR alcan_scrap_870_cur IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = ll_cur_coil)
	 AND (a.coil_abc_num = b.coil_abc_num)
	 AND (a.scrap_870_date is NULL);

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;
    p		   := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 ( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 ( COIL.SCRAP_870_DATE is NULL ) AND
	 ( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13) );

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;

	  coil_num(p) := ll_cur_coil;
	  p := p + 1;


	FOR item_rec IN alcan_870_cur LOOP   -- item loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
		     ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	     AND (ab_job.order_abc_num = order_item.order_abc_num)
	     AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

      FOR scrap_rec IN alcan_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


		ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   END IF;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent
     END LOOP;	 -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id_aleris) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
--	   COMMIT;

     FOR m IN 0 .. k - 1 LOOP
       UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
	 WHERE production_sheet_item.prod_item_num = item_num(m);
    END LOOP;

--	COMMIT;

	FOR m in 0..p - 1 LOOP
		UPDATE coil
					SET coil.scrap_870_date = sysdate
		WHERE coil.coil_abc_num = coil_num(m);

	       UPDATE process_coil
					SET scrap_870_date = sysdate
		WHERE ( coil_abc_num = coil_num(m)) AND (scrap_870_date is NULL);

	     END LOOP;

	COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_ALEX" IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  --edi_file_prefix VARCHAR2(50) := 'S_alcan_';
  edi_file_prefix VARCHAR2(50) := 'alex_alcan_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  ll_coil_abc_num INTEGER := 205955; --Alex Gerlants. 02/28/2017
  ll_ab_job_num   INTEGER := 97583; --Alex Gerlants. 02/28/2017


  CURSOR cust_cur IS
    --SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers
    SELECT customer_id FROM customer WHERE customer_id IN (1153); ---Add customer id here if you want to send 870 for more customers

/*
  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    ( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID = ll_customer_id ) AND
    ( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    ( C.SCRAP_870_DATE is NULL ) AND
    ( SK.SKID_SHEET_STATUS in (0,2,4,12,13) );
*/

  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    ( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID = ll_customer_id ) AND
    ( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    --( C.SCRAP_870_DATE is NULL ) AND
    ( SK.SKID_SHEET_STATUS in (0,2,4,12,13) )
    and ab.ab_job_num = ll_ab_job_num
    and C.COIL_ABC_NUM = ll_coil_abc_num
    and SKD.SHEET_SKID_NUM between 625038 and 625043;

/*
  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = ll_cur_coil);
*/

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = ll_coil_abc_num);



       CURSOR alcan_scrap_870_cur IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = ll_cur_coil)
	 AND (a.coil_abc_num = b.coil_abc_num);
	 --AND (a.scrap_870_date is NULL); --Alex Gerlants. 02/28/2017. Commented out.

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;
    p		   := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 ( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 --( COIL.SCRAP_870_DATE is NULL ) AND --Alex Gerlants. 02/28/2017. Commented out
	 ( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13) )
	 and AB_JOB.ab_job_num = ll_ab_job_num --Alex Gerlants. 02/28/2017
	 and COIL.COIL_ABC_NUM = ll_coil_abc_num --Alex Gerlants. 02/28/2017
	 and SHEET_SKID_DETAIL.SHEET_SKID_NUM between 625038 and 625043; --Alex Gerlants. 02/28/2017

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;

	  coil_num(p) := ll_cur_coil;
	  p := p + 1;


	FOR item_rec IN alcan_870_cur LOOP   -- item loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
		     ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	     AND (ab_job.order_abc_num = order_item.order_abc_num)
	     AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

      FOR scrap_rec IN alcan_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


		ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   END IF;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent
     END LOOP;	 -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id_aleris) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      edi_file	      := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
--	   COMMIT;

     FOR m IN 0 .. k - 1 LOOP
       UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
	 WHERE production_sheet_item.prod_item_num = item_num(m);
    END LOOP;

--	COMMIT;

	FOR m in 0..p - 1 LOOP
		UPDATE coil
	  SET coil.scrap_870_date = sysdate
		WHERE coil.coil_abc_num = coil_num(m);

	       UPDATE process_coil
	  SET scrap_870_date = sysdate
		WHERE ( coil_abc_num = coil_num(m)) AND (scrap_870_date is NULL);

	     END LOOP;

	COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_ALEX2" IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 's_alcan_alex_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers

  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    ( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID = 1153 ) AND
    --( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    --( C.SCRAP_870_DATE is NULL ) AND
    --( SK.SKID_SHEET_STATUS in (0,2,4,12,13) )
    ( c.coil_abc_num in (212673) ) and
    ( ab.ab_job_num = 102261 ) and
    ( sk.sheet_skid_num in (655859) ) and
    ( psi.prod_item_num = 1375681 )
    ;

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = ll_cur_coil);

       CURSOR alcan_scrap_870_cur IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = ll_cur_coil)
	 AND (a.coil_abc_num = b.coil_abc_num)
	 --AND (a.scrap_870_date is NULL)
	 ;

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;
    p		   := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = 1153 ) AND
	 ( production_sheet_item.prod_item_num = 1375681 )
	 --( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 --( COIL.SCRAP_870_DATE is NULL ) AND
	 --( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13) )
	 ;

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;

	  coil_num(p) := ll_cur_coil;
	  p := p + 1;


	FOR item_rec IN alcan_870_cur LOOP   -- item loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
		     ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	     AND (ab_job.order_abc_num = order_item.order_abc_num)
	     AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

      FOR scrap_rec IN alcan_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


		ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   END IF;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent
     END LOOP;	 -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id_aleris) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
--	   COMMIT;

     FOR m IN 0 .. k - 1 LOOP
       UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
	 WHERE production_sheet_item.prod_item_num = item_num(m);
    END LOOP;

--	COMMIT;

	FOR m in 0..p - 1 LOOP
		UPDATE coil
	  SET coil.scrap_870_date = sysdate
		WHERE coil.coil_abc_num = coil_num(m);

	       UPDATE process_coil
	  SET scrap_870_date = sysdate
		WHERE ( coil_abc_num = coil_num(m)) AND (scrap_870_date is NULL);

	     END LOOP;

	COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_BAK" IS

  /*
  Aluminum Blanking: Ford Suppler Code: ZZ R0P7A
		     DUNS: 01 039630926T
  Customer: ALCAN(34,35,10,1153)
  Alcan Rolled Product	  X.121       0015049350011G
  Kingston Duns: 241003755
  */

  edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  INTEGER := 1153;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;
  --ll_bsn_log integer;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI'); -- time in 24 hours format....Tony

  ls_po VARCHAR2(36);

  --ll_edi_file_id integer;
  ll_edi_file_id_alcan INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;

  CURSOR cust_cur IS
    SELECT customer_id
      FROM customer
     WHERE customer_id IN (1153, 1459, 2582); ---Add customer id here if you want to send 870 for more customers

  CURSOR alcan_870_cur IS
    SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   sheet_skid.sheet_skid_display_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   coil.coil_org_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,   --add james ni 10/22/2013
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   customer_order --,ab_job
     WHERE (sheet_skid.skid_sheet_status IN (2, 4, 8, 13))
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND -- Add Oswego id=1459 by Tony 04-29-03
	   (sheet_skid.ref_order_abc_num = customer_order.order_abc_num);
  --(production_sheet_item.ab_job_num = ab_job.ab_job_num) and
  --(ab_job.order_abc_num = customer_order.order_abc_num) ;

  --End of change by tony

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;
  item_rec  alcan_870_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

BEGIN

  FOR cust_rec IN cust_cur LOOP

    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;


    SELECT COUNT(*)
      INTO ll_item_count
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (2, 4, 8, 13))
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND -- Add Oswego id=1459 by Tony 04-29-03
	   (sheet_skid.ref_order_abc_num = customer_order.order_abc_num);
    -- if ll_item_count = 0 then return 100; end if;   -- nothing to send
    IF ll_item_count <> 0 THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
--	x12_table(i) := 'N1*SU**1*' || su_duns || '*NA'; - by james 11/6/2013
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926T';
      i := i + 1;

      --open alcan_870_cur;
      --fetch alcan_870_cur INTO item_rec;
      --close alcan_870_cur;

      li_hl01 := 1;

      FOR item_rec IN alcan_870_cur LOOP
	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	ls_po := item_rec.customer_po;

	x12_table(i) := 'PRF*' || ls_po || '****NA';
	i := i + 1;
	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;
	-- Nov 21 03, change per Alcan	---tony
	--x12_table(i) := 'REF*SE*' ||item_rec.coil_org_num ||'-'||to_char(item_rec.sheet_skid_num); i := i+1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;

	--add james ni 10/22/2013
 --	  x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
 --	  i := i + 1;

	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	-- Nov 21 03, change per Alcan	---tony
	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	--06/05/03 Don't send PO106 AND PO107 incase non sales order available as per Julia
	IF item_rec.sales_order = ' ' THEN
	  x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num;
	  i := i + 1;
	ELSE
	  x12_table(i) := 'PO1**1*UN***VO*' || item_rec.sales_order ||
			  '***SN*' || item_rec.coil_org_num;
	  i := i + 1;
	END IF;

	-- Added partial ready(13), On-hold(4) by Bing Feb-26-2002
	-- deleted || '*NA' from each line by james 11/6/2013
	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSE
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	li_hl01 := li_hl01 + 1;

	item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval INTO ll_edi_file_id_alcan FROM dual;
	edi_file	:= 'S_alcan_' || to_char(ll_edi_file_id_alcan) ||
			   '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --added by Victor Huang on 12/07 for verifying 997
      INSERT INTO outbound_edi_transaction
	(edi_file_id,
	 duns_from,
	 duns_to,
	 interchange_control_number,
	 group_control_number,
	 transaction_time,
	 edi_file_name,
	 fa_receive_status,
	 customer_id,
	 set_control_num,
	 transaction_type_id)
      VALUES
	(ll_edi_file_id_alcan,
	 '039630926',
	 su_duns,
	 ll_gs_log,
	 ll_gs_log,
	 SYSDATE,
	 edi_file,
	 0,
	 ll_customer_id,
	 ll_st_log,
	 '870');
      COMMIT;

      edi_file	      := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      FOR m IN 0 .. k - 1 LOOP
	UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE
	 WHERE production_sheet_item.prod_item_num = item_num(m);
      END LOOP;

      COMMIT;

    END IF; --end if in select count(*)


  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_ONE_JOB"
     (
	al_ab_job_num  ab_job.ab_job_num%type
     )


is

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 's_alcan_870_one_job_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  --CURSOR cust_cur IS
  --  SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers

  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    --( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID = ll_customer_id ) AND
    --( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    --( C.SCRAP_870_DATE is NULL ) AND
    --( SK.SKID_SHEET_STATUS in (0,2,4,12,13) );
    ( ab.ab_job_num = al_ab_job_num )
    --and ( sk.sheet_skid_num in (703642, 703643, 703644, 703645) )
    ;

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     --WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
     --  AND (production_sheet_item.prod_item_edi870_date IS NULL)
     where (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = ll_cur_coil)
       and ( ab_job.ab_job_num = al_ab_job_num )
       --and ( sheet_skid.sheet_skid_num in (703642, 703643, 703644, 703645) )
       ;


       CURSOR alcan_scrap_870_cur IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = ll_cur_coil)
	 AND (a.coil_abc_num = b.coil_abc_num);
	 --AND (a.scrap_870_date is NULL);

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  --FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    --ll_customer_id := cust_rec.customer_id;

  select      distinct customer_order.orig_customer_id
  into	      ll_customer_id
  from	      process_coil
	      join coil on coil.coil_abc_num = process_coil.coil_abc_num
	      join production_sheet_item on coil.coil_abc_num = production_sheet_item.coil_abc_num and process_coil.ab_job_num = production_sheet_item.ab_job_num
	      join sheet_skid_detail on production_sheet_item.prod_item_num = sheet_skid_detail.prod_item_num
	      join sheet_skid on sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num
	      join ab_job on ab_job.ab_job_num = process_coil.ab_job_num
	      join customer_order on customer_order.order_abc_num = ab_job.order_abc_num
  where       ab_job.ab_job_num = al_ab_job_num;

  i		 := 0;
  k		 := 0;
  p		 := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 --(  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 --( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 --( COIL.SCRAP_870_DATE is NULL ) AND
	 --( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13) );
	 ( ab_job.ab_job_num = al_ab_job_num )
	 --and ( sheet_skid.sheet_skid_num in (703642, 703643, 703644, 703645) )
	 ;

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;

	  coil_num(p) := ll_cur_coil;
	  p := p + 1;


	FOR item_rec IN alcan_870_cur LOOP   -- item loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
		     ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	     AND (ab_job.order_abc_num = order_item.order_abc_num)
	     AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     ld_scrap_870_date := null; --Alex Gerlants. 01/12/2019. Added to get through

     IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

      FOR scrap_rec IN alcan_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


		ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   END IF;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent
     END LOOP;	 -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id_aleris) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
/*
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
*/
--	   COMMIT;

     --FOR m IN 0 .. k - 1 LOOP
     --  UPDATE production_sheet_item
     --      SET prod_item_edi870_date = SYSDATE,
     -- 	 edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
     --    WHERE production_sheet_item.prod_item_num = item_num(m);
     --END LOOP;

--	COMMIT;

	/*
	FOR m in 0..p - 1 LOOP
		UPDATE coil
					SET coil.scrap_870_date = sysdate
		WHERE coil.coil_abc_num = coil_num(m);

	       UPDATE process_coil
					SET scrap_870_date = sysdate
		WHERE ( coil_abc_num = coil_num(m)) AND (scrap_870_date is NULL);

	 END LOOP;
	 */

	COMMIT;

    END IF; --end if in select count(*)

  --END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_ONE_SKID"
     (
	al_sheet_skid_num  sheet_skid.sheet_skid_num%type
     )
is


  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 's_alcan_870_one_skid_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers

  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    --( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID in (1459, 1153) ) AND
    --( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    --( C.SCRAP_870_DATE is NULL ) AND
    --( SK.SKID_SHEET_STATUS in (0,2,4,12,13) );
    ( sk.sheet_skid_num = al_sheet_skid_num
    --and ( c.coil_org_num in ('1726314', '1727530') )
    );

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     --WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
     --  AND (production_sheet_item.prod_item_edi870_date IS NULL)
     where (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id in (1459, 1153))
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = ll_cur_coil)
       --and ( ab_job.ab_job_num = 105057 );
       and  ( sheet_skid.sheet_skid_num = al_sheet_skid_num
       --and ( coil.coil_org_num in ('1726314', '1727530') )
       );



       CURSOR alcan_scrap_870_cur IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = ll_cur_coil)
	 AND (a.coil_abc_num = b.coil_abc_num);
	 --AND (a.scrap_870_date is NULL);

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  --FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    --ll_customer_id := cust_rec.customer_id;

  select      distinct customer_order.orig_customer_id
  into	      ll_customer_id
  from	      process_coil
	      join coil on coil.coil_abc_num = process_coil.coil_abc_num
	      join production_sheet_item on coil.coil_abc_num = production_sheet_item.coil_abc_num and process_coil.ab_job_num = production_sheet_item.ab_job_num
	      join sheet_skid_detail on production_sheet_item.prod_item_num = sheet_skid_detail.prod_item_num
	      join sheet_skid on sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num
	      join ab_job on ab_job.ab_job_num = process_coil.ab_job_num
	      join customer_order on customer_order.order_abc_num = ab_job.order_abc_num
  where       sheet_skid.sheet_skid_num = al_sheet_skid_num;

  i := 0;
  k := 0;
  p := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 --(  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID in (1459, 1153) ) AND
	 --( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 --( COIL.SCRAP_870_DATE is NULL ) AND
	 --( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13) );
	 ( SHEET_SKID.sheet_skid_num = al_sheet_skid_num
	 --and ( coil.coil_org_num in ('1726314', '1727530') )
	 );

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;

	  coil_num(p) := ll_cur_coil;
	  p := p + 1;


	FOR item_rec IN alcan_870_cur LOOP   -- item loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
		     ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	     AND (ab_job.order_abc_num = order_item.order_abc_num)
	     AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     ld_scrap_870_date := null; --Alex Gerlants. 01/12/2019. Added to get through

     IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

      FOR scrap_rec IN alcan_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


		ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   END IF;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent
     END LOOP;	 -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id_aleris) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
--	   COMMIT;

     --FOR m IN 0 .. k - 1 LOOP
     --  UPDATE production_sheet_item
     --      SET prod_item_edi870_date = SYSDATE,
     -- 	 edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
     --   WHERE production_sheet_item.prod_item_num = item_num(m);
     --END LOOP;

--	COMMIT;

       /*

	FOR m in 0..p - 1 LOOP
		UPDATE coil
					SET coil.scrap_870_date = sysdate
		WHERE coil.coil_abc_num = coil_num(m);

	       UPDATE process_coil
					SET scrap_870_date = sysdate
		WHERE ( coil_abc_num = coil_num(m)) AND (scrap_870_date is NULL);

	     END LOOP;
	*/

	COMMIT;

    END IF; --end if in select count(*)

  --END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_ORIG" IS

  /*
  Aluminum Blanking: Ford Suppler Code: ZZ R0P7A
		     DUNS: 01 039630926T
  Customer: ALCAN(34,35,10,1153)
  Alcan Rolled Product	  X.121       0015049350011G
  Kingston Duns: 241003755
  */

  edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';

  --v_edi_text_alcan varchar2(32767);
  -- edi_loc varchar2(50):='/tmp';
  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  INTEGER := 1153;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;
  --ll_bsn_log integer;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI'); -- time in 24 hours format....Tony

  ls_po VARCHAR2(20);

  --ll_edi_file_id integer;
  ll_edi_file_id_alcan INTEGER;

  ll_item_count INTEGER;

  --li_customer_id shipment.customer_id%TYPE;
  --li_des_sh_cust_id shipment.des_sh_cust_id%TYPE;

  li_hl01 INTEGER;
  /* Dec 23rd 02 changed by tony for re-assigned skid with other order
  Cursor alcan_870_cur IS
  SELECT   production_sheet_item.AB_JOB_NUM,
	   production_sheet_item.prod_item_pieces,
	   SHEET_SKID.SHEET_SKID_NUM,
	   production_sheet_item.prod_item_net_wt,
	   SHEET_SKID.SKID_SHEET_STATUS,
	   coil.coil_org_num,
	   NVL(customer_order.sales_order, 'NA') sales_order,
	   NVL(customer_order.orig_customer_po, 'NA') customer_po,
	   (SHEET_SKID.SHEET_NET_WT + SHEET_SKID.SHEET_TARE_WT) skid_gross_wt,
	   NULL Done
  FROM	  SHEET_SKID, production_sheet_item, sheet_skid_detail,coil,ab_job, customer_order
  WHERE        (sheet_skid.skid_sheet_status in ( 2, 4, 13)) and
	       (production_sheet_item.prod_item_edi870_date is NULL ) and
	       (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num) and
	       (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num) and
	       (coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
	       (coil.customer_id = 1153) and
	       (production_sheet_item.ab_job_num = ab_job.ab_job_num) and
	       (ab_job.order_abc_num = customer_order.order_abc_num) ;


  */

  --Begin of change

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (1153, 1459); ---Add customer id here if you want to send 870 for more customers

  CURSOR alcan_870_cur IS
    SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   coil.coil_org_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   customer_order --,ab_job
     WHERE (sheet_skid.skid_sheet_status IN (2, 4, 8, 13))
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND -- Add Oswego id=1459 by Tony 04-29-03
	   (sheet_skid.ref_order_abc_num = customer_order.order_abc_num);
  --(production_sheet_item.ab_job_num = ab_job.ab_job_num) and
  --(ab_job.order_abc_num = customer_order.order_abc_num) ;

  --End of change by tony

  --Type skidinfo_tabletype IS table of alcan_870_cur%ROWTYPE INDEX by binary_integer;
  --skidinfo_table skidinfo_tabletype;

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;
  item_rec  alcan_870_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;

    SELECT COUNT(*)
      INTO ll_item_count
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (2, 4, 8, 13))
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND -- Add Oswego id=1459 by Tony 04-29-03
	   (sheet_skid.ref_order_abc_num = customer_order.order_abc_num);
    -- if ll_item_count = 0 then return 100; end if;   -- nothing to send
    IF ll_item_count <> 0 THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns || '*NA';
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926T';
      i := i + 1;

      --open alcan_870_cur;
      --fetch alcan_870_cur INTO item_rec;
      --close alcan_870_cur;

      li_hl01 := 1;

      FOR item_rec IN alcan_870_cur LOOP
	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	-- No need for this part due to the change in alcan_870_cur   ---------By Tony 04-29-03

	-- Referece PO and Sales order via Ref_order due to coil reassigning	Bing on Sep 5, 2002
	/*
	  SELECT
	       NVL(customer_order.sales_order, 'NA') INTO item_rec.sales_order
	  FROM	 SHEET_SKID, customer_order
	  WHERE       (customer_order.order_abc_num = sheet_skid.ref_order_abc_num)  and
		      (sheet_skid.sheet_skid_num = item_rec.sheet_skid_num);

	  SELECT
	       NVL(customer_order.orig_customer_po, 'NA') INTO item_rec.customer_po
	  FROM	      SHEET_SKID, customer_order
	  WHERE       (customer_order.order_abc_num = sheet_skid.ref_order_abc_num)  and
		      (sheet_skid.sheet_skid_num = item_rec.sheet_skid_num);
	*/

	-- End of change tony 04-29-03

	-- Trunc PO by Bing on Jan 11, 2001
	ls_po := item_rec.customer_po;
	IF instr(item_rec.customer_po, '-') > 0 THEN
	  ls_po := substr(item_rec.customer_po,
			  0,
			  instr(item_rec.customer_po, '-') - 1);
	END IF;

	x12_table(i) := 'PRF*' || ls_po || '****NA';
	i := i + 1;
	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;
	-- Nov 21 03, change per Alcan	---tony
	--x12_table(i) := 'REF*SE*' ||item_rec.coil_org_num ||'-'||to_char(item_rec.sheet_skid_num); i := i+1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;

	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	-- Nov 21 03, change per Alcan	---tony
	--x12_table(i) := 'REF*RV*' ||item_rec.coil_org_num || to_char(item_rec.sheet_skid_num) ||'*NA'; i := i+1;
	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	--06/05/03 Don't send PO106 AND PO107 incase non sales order available as per Julia
	IF item_rec.sales_order = ' ' THEN
	  x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num;
	  i := i + 1;
	ELSE
	  x12_table(i) := 'PO1**1*UN***VO*' || item_rec.sales_order ||
			  '***SN*' || item_rec.coil_org_num;
	  i := i + 1;
	END IF;

	-- Added partial ready(13), On-hold(4) by Bing Feb-26-2002
	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_num) || '*NA';
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_num) || '*NA';
	  i := i + 1;
	ELSE
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_num) || '*NA';
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	li_hl01 := li_hl01 + 1;

	item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval INTO ll_edi_file_id_alcan FROM dual;
	edi_file	:= 'S_alcan_' || to_char(ll_edi_file_id_alcan) ||
			   '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));
	  -- v_edi_text_alcan:=v_edi_text_alcan||x12_table(j)||CHR(10);
	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      /* --added by Victor Huang on 06/05 for funtion aknowlegement
      INSERT INTO edi_fa(gs_num, duns_num, send_time,edi_file_name)
      VALUES(ll_gs_log, su_duns, sysdate, edi_file);
      COMMIT;*/

      --added by Victor Huang on 12/07 for verifying 997
      INSERT INTO outbound_edi_transaction
	(edi_file_id,
	 duns_from,
	 duns_to,
	 interchange_control_number,
	 group_control_number,
	 transaction_time,
	 edi_file_name,
	 fa_receive_status,
	 customer_id,
	 set_control_num,
	 transaction_type_id)
      VALUES
	(ll_edi_file_id_alcan,
	 '039630926',
	 su_duns,
	 ll_gs_log,
	 ll_gs_log,
	 SYSDATE,
	 edi_file,
	 0,
	 ll_customer_id,
	 ll_st_log,
	 '870');
      COMMIT;

      edi_file	      := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      /*
      UPDATE production_sheet_item
	 SET prod_item_edi870_date= SYSDATE

	 WHERE	production_sheet_item.prod_item_num in
	       ( select production_sheet_item.prod_item_num from SHEET_SKID, production_sheet_item, sheet_skid_detail,coil, customer_order
		  where
		 (production_sheet_item.prod_item_edi870_date is NULL ) and
		 (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num) and
		 (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num) and
		 (sheet_skid.skid_sheet_status in (2, 4, 13)) and
		 (coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
		 (coil.customer_id = ll_customer_id) and
		 (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
	       );

      */
      FOR m IN 0 .. k - 1 LOOP
	UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE
	 WHERE production_sheet_item.prod_item_num = item_num(m);
      END LOOP;

      COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_PER_JOB"
     (
	al_ab_job_num  ab_job.ab_job_num%type
     )
is

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  --edi_file_prefix VARCHAR2(50) := 'S_870_'; --Production
  edi_file_prefix VARCHAR2(50) := 's_870_'; --Development
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date process_coil.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_870 INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  ll_rowcount number(8);

--  CURSOR cust_cur IS
--    SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers
/*
  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    ( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID = ll_customer_id ) AND
    ( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    ( C.SCRAP_870_DATE is NULL ) AND
    ( SK.SKID_SHEET_STATUS in (0,2,4,12,13, 16) );

  coil_rec  coil_cur%ROWTYPE;
*/

/*
  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,

	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   nvl(customer_order.orig_customer_po, 'NA') orig_customer_po,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12, 16)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = ll_cur_coil);

     item_rec  alcan_870_cur%ROWTYPE;

     CURSOR alcan_scrap_870_cur IS
     SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = ll_cur_coil)
	 AND (a.coil_abc_num = b.coil_abc_num)
	 AND (a.scrap_870_date is NULL);
*/

--------------------------------------------------------------------------------------------------
------------------------------------ Cursors Begin -----------------------------------------------
--------------------------------------------------------------------------------------------------

  cursor coil_cur is
  select distinct process_coil.coil_abc_num
  from	 process_coil
	 left outer join production_sheet_item on production_sheet_item.coil_abc_num = process_coil.coil_abc_num and production_sheet_item.ab_job_num = process_coil.ab_job_num
	 left outer join sheet_skid_detail on sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num
	 left outer join sheet_skid on sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num
  where  process_coil.ab_job_num = al_ab_job_num
  and	 (
	      sheet_skid.skid_sheet_status in (0, 2, 4, 13, 12, 16)
	   or sheet_skid.skid_sheet_status is null --This is for rejected coils without sheets
	 );

  coil_rec  coil_cur%ROWTYPE;

  --Cursor skid_coil_cur will select data for ab_job and coil_abc_num with skids.
  --If there is a reject coil without sheet skids, this cursor will not select it.
  cursor skid_coil_cur is
  select coil.coil_abc_num,
	 coil.lot_num,
	 coil.coil_org_num,
	 coil.coil_mid_num,
	 nvl(coil.consumed_coil_num, ' ') consumed_coil,
	 nvl(coil.material_num, ' ') material_num,
	 coil.net_wt,
	 sheet_skid.sheet_tare_wt,
	 sheet_skid.sheet_net_wt,
	 sheet_skid.skid_pieces,
	 production_sheet_item.prod_item_pieces,
	 production_sheet_item.prod_item_num,
	 sheet_skid.skid_sheet_status,
	 sheet_skid.sheet_skid_num,
	 production_sheet_item.prod_item_note,
	 sheet_skid.sheet_theoretical_wt,
	 production_sheet_item.prod_item_placement,
	 process_coil.process_quantity,
	 production_sheet_item.prod_item_net_wt,
	 sheet_skid.sheet_skid_display_num,
	 nvl(customer_order.sales_order, ' ') sales_order,
	 nvl(customer_order.orig_customer_po, 'NA') orig_customer_po,
	 nvl(order_item.enduser_part_num, ' ') enduser_part_num,
	 nvl(order_item.cust_prod_line_id, 'NA') cust_prod_line_id,
	 nvl(order_item.finished_goods_material_num, 'NA') finished_goods_material_num,
	 (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	 NULL done
  from	 coil
	 join process_coil on coil.coil_abc_num = process_coil.coil_abc_num
	 join ab_job on ab_job.ab_job_num = process_coil.ab_job_num
	 join order_item on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
	 join customer_order on customer_order.order_abc_num = order_item.order_abc_num
	 left outer join production_sheet_item on coil.coil_abc_num = production_sheet_item.coil_abc_num and production_sheet_item.ab_job_num = process_coil.ab_job_num
	 left outer join sheet_skid_detail on sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num
	 left outer join sheet_skid on sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num
  where  ab_job.ab_job_num = al_ab_job_num
  and	 coil.coil_abc_num = ll_cur_coil
  order by
	 production_sheet_item.coil_abc_num,
	 sheet_skid.sheet_skid_display_num;

  skid_coil_rec  skid_coil_cur%rowtype;

  cursor scrap_cur is
  select process_coil.coil_abc_num,
	 process_coil.process_coil_status,
	 process_coil.process_quantity,
	 nvl(process_coil.process_end_wt, 0),
	 sum(nvl(process_coil.process_end_wt, 0)),
	 sum(nvl(production_sheet_item.prod_item_net_wt, 0)),
	 case process_coil.process_coil_status
	    when 7 then --Rebanded coils
	       --(process_coil.process_quantity - sum(production_sheet_item.prod_item_net_wt) - (select process_end_wt from process_coil pc where pc.ab_job_num = 101143 and pc.coil_abc_num = process_coil.coil_abc_num))
	       (process_coil.process_quantity - sum(nvl(production_sheet_item.prod_item_net_wt, 0)) - nvl(process_coil.process_end_wt, 0))
	    when 3 then --Rejected coils
	       case (select count(*) from production_sheet_item psi where psi.ab_job_num = al_ab_job_num and psi.coil_abc_num = process_coil.coil_abc_num)
		 when 0 then --Rejected coils without sheets
		   (process_coil.process_quantity - sum(nvl(process_coil.process_end_wt, 0)))
		 else --Rejected coils with sheets
		   (process_coil.process_quantity - nvl(process_coil.process_end_wt, 0) - sum(nvl(production_sheet_item.prod_item_net_wt, 0)))
		end
	     else
	       (process_coil.process_quantity - sum(nvl(production_sheet_item.prod_item_net_wt, 0)) - sum(nvl(process_coil.process_end_wt, 0)))
	 end scrap_net_wt
  from	 process_coil
	 join coil on coil.coil_abc_num = process_coil.coil_abc_num
	 join ab_job on ab_job.ab_job_num = process_coil.ab_job_num and coil.coil_abc_num = process_coil.coil_abc_num
	 left outer join production_sheet_item on production_sheet_item.ab_job_num = process_coil.ab_job_num and production_sheet_item.coil_abc_num = process_coil.coil_abc_num
  where  process_coil.ab_job_num = al_ab_job_num
  and	 coil.coil_abc_num = ll_cur_coil
  group by
	 process_coil.coil_abc_num,
	 process_coil.process_coil_status,
	 process_coil.process_quantity,
	 process_coil.process_end_wt
  order by
	 process_coil.coil_abc_num;

  scrap_rec  scrap_cur%rowtype;

--------------------------------------------------------------------------------------------------
------------------------------------- Cursors End ------------------------------------------------
--------------------------------------------------------------------------------------------------

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

BEGIN

  --FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    --ll_customer_id := cust_rec.customer_id;
  i		 := 0;
  k		 := 0;
  p		 := 0;

  --open coil_cur;
  --fetch coil_cur into coil_rec;
  --ll_rowcount := coil_cur%rowcount;

  select count(distinct process_coil.coil_abc_num)
  into	 ll_rowcount
  from	 process_coil
	 left outer join production_sheet_item on production_sheet_item.coil_abc_num = process_coil.coil_abc_num and production_sheet_item.ab_job_num = process_coil.ab_job_num
	 left outer join sheet_skid_detail on sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num
	 left outer join sheet_skid on sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num
  where  process_coil.ab_job_num = al_ab_job_num
  and	 (
	      sheet_skid.skid_sheet_status in (0, 2, 4, 13, 12, 16)
	   or sheet_skid.skid_sheet_status is null --This is for rejected coils without sheets
	 );

  if ll_rowcount > 0 then

/*
  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 ( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 ( COIL.SCRAP_870_DATE is NULL ) AND
	 ( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13, 16) ); --Alex Gerlants. 03/22/2019. Added new status 16-Hold For Cert

  IF (ll_item_count <> 0) THEN
*/
  select edi_st_log_seq.nextval into ll_st_log from dual;
  select edi_gs_log_seq.nextval into ll_gs_log from dual;

  select  customer_order.orig_customer_id
  into	  ll_customer_id
  from	  ab_job
	  join customer_order on customer_order.order_abc_num = ab_job.order_abc_num
  where   ab_job.ab_job_num = al_ab_job_num;

  select  customer.customer_duns_number_string
  into	  su_duns
  from	  customer
  where   customer.customer_id = ll_customer_id;

  --Production
  --x12_table(i) := 'ISA*00*' ||
  --		    '	       *00*	     *01*039630926T	*09*0015049350011G *' ||
  --		    ls_today_4 || '*' || ls_now || '*U*00401*' ||
  --		    lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';

  --Development
  x12_table(i) := 'ISA*00*' ||
		  '	     *00*	   *ZZ*2NDSFTP	      *ZZ*NOVLSTEST	 *' ||
		  ls_today_4 || '*' || ls_now || '*U*00401*' ||
		  lpad(to_char(ll_gs_log), 9, '0') || '*0*T**';

  i := i + 1;

  --Production
  --x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
  --		    ls_today || '*' || ls_now || '*' ||
  --		    to_char(ll_gs_log) || '*X*' || '004010';

  --Development
  x12_table(i) := 'GS*RS*2NDSFTP*' || 'NOVLSTEST' || '*' ||
		  ls_today || '*' || ls_now || '*' ||
		  to_char(ll_gs_log) || '*X*' || '004010';

  i := i + 1;

  x12_table(i) := 'ST*870*' || to_char(ll_st_log);
  i := i + 1;
  x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		  '***' || ls_now || '*****';
  i := i + 1;
  x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
  i := i + 1;
  x12_table(i) := 'N1*SU**1*' || su_duns;
  i := i + 1;
  x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
  i := i + 1;

  li_hl01 := 0;

  for coil_rec in coil_cur loop --Coil loop
     ll_cur_coil := coil_rec.coil_abc_num;

     coil_num(p) := ll_cur_coil;
     p := p + 1;

     select   coil.coil_org_num, coil.lot_num
     into     ls_coil_org_num, ls_heat
     from     coil
     where    coil.coil_abc_num = ll_cur_coil;


     for skid_coil_rec IN skid_coil_cur loop --Skid_coil loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

/*
	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
		     ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	     AND (ab_job.order_abc_num = order_item.order_abc_num)
	     AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = item_rec.ab_job_num);
*/
	ls_po := skid_coil_rec.orig_customer_po;
	ls_cust_prod_line := skid_coil_rec.cust_prod_line_id;
	ls_finished_goods := skid_coil_rec.finished_goods_material_num;

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(skid_coil_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(al_ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(skid_coil_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(skid_coil_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  ls_coil_org_num || '***VP*' || skid_coil_rec.finished_goods_material_num;
	i := i + 1;

	if skid_coil_rec.skid_sheet_status = 2 then
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(skid_coil_rec.sheet_skid_display_num);
	  i := i + 1;
	elsif skid_coil_rec.skid_sheet_status = 4 then
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(skid_coil_rec.sheet_skid_display_num);
	  i := i + 1;
	elsif skid_coil_rec.skid_sheet_status = 13 then
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(skid_coil_rec.sheet_skid_display_num);
	  i := i + 1;
	else
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(skid_coil_rec.sheet_skid_display_num);
	  i := i + 1;
	end if;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(skid_coil_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(skid_coil_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(skid_coil_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	item_num(k) := skid_coil_rec.prod_item_num;
	k := k + 1;

      end loop; --for skid_coil_rec IN skid_coil_cur loop

      /*
      select   process_coil.scrap_870_date, coil.coil_org_num, coil.lot_num
      into     ld_scrap_870_date, ls_coil_org_num, ls_heat
      from     coil
	       join process_coil on coil.coil_abc_num = process_coil.coil_abc_num
      where    coil.coil_abc_num = ll_cur_coil;
      */

      --if (ld_scrap_870_date is null) then --Scrap not sent

	 for scrap_rec in scrap_cur loop --Scrap loop

	    --Scrap info
	    /*
	    SELECT   NVL(sum(production_sheet_item.prod_item_net_wt),0)
	    into     ll_prime_nw
	    FROM     production_sheet_item
	    WHERE (  production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
		     (production_sheet_item.coil_abc_num = ll_cur_coil);
	    */

	    --ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;
	    ll_scrap_nw := scrap_rec.scrap_net_wt;

	    if ll_scrap_nw > 0 then

	       li_hl01 := li_hl01 + 1;

	       x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
	       i := i + 1;

	       IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		  x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		  i := i + 1;
	       END IF;

	       x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	       i := i + 1;

	       x12_table(i) := 'PO1**1*UN****' || '***SN*' || ls_coil_org_num ;
	       i := i + 1;

	       x12_table(i) := 'PID*S*MA*ST*S';
	       i := i + 1;

	       x12_table(i) := 'PID*S*MAC*ST*05';
	       i := i + 1;

	       x12_table(i) := 'PID*S*PR*ST*19';
	       i := i + 1;

	       x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
	       i := i+1;
	     end if; --if ll_scrap_nw > 0 then
	  end loop; --for scrap_rec in alcan_scrap_870_cur loop scrap loop
      --end if; --if (ld_scrap_870_date is null) then --Scrap not sent
  end loop; --for coil_rec in coil_cur loop. Coil loop

  x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
  i := i + 1;

  x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
  i := i + 1;

  x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
  i := i + 1;

  x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

  -- Write EDI to file

  if li_hl01 > 1 then
      -- WRITE EDI FILE ONLY IF ITEM > 0
      SELECT edi_file_id_seq.nextval
	INTO ll_edi_file_id_870
	FROM dual;
      edi_file	      := edi_file_prefix || to_char(ll_edi_file_id_870) || '.edi';
   -- edi_file	      := 's_alcan_' || to_char(ll_edi_file_id_870) || '.870';
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

      FOR j IN 0 .. i LOOP
	utl_file.put_line(edi_file_handle, x12_table(j));

      END LOOP;
      utl_file.fclose(edi_file_handle);
    END IF; -- END WRITING EDI FILE

    --edi_file	      := 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
    edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
    utl_file.put_line(edi_file_handle, 'Type: 870');
    utl_file.put_line(edi_file_handle,
		      'Sending Time: ' ||
		      to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
    utl_file.put_line(edi_file_handle,
		      'Interchange Control #: ' || ll_gs_log);
    utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
    utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
    utl_file.put_line(edi_file_handle, '');
    utl_file.put_line(edi_file_handle, '');
    utl_file.fclose(edi_file_handle);

    --For verifying 997
/*
    INSERT INTO outbound_edi_transaction
	(edi_file_id,
	 duns_from,
	 duns_to,
	 interchange_control_number,
	 group_control_number,
	 transaction_time,
	 edi_file_name,
	 fa_receive_status,
	 customer_id,
	 set_control_num,
	 transaction_type_id)
      VALUES
	(ll_edi_file_id_870,
	 '039630926',
	 su_duns,
	 ll_gs_log,
	 ll_gs_log,
	 SYSDATE,
	 edi_file,
	 0,
	 ll_customer_id,
	 ll_st_log,
	 '870');
*/

--	update	  ab_job
--	set	  edi_file_id_870 = ll_edi_file_id_870,  /* Alex Gerlants. 02/14/2020. New column */
--		  edi_date_870 = sysdate /* Alex Gerlants. 02/14/2020. New column */
--	where	  ab_job_num = al_ab_job_num;

/*
      for m in 0 .. k - 1 loop
	 update   production_sheet_item
	 set	  prod_item_edi870_date = sysdate,
		  edi_file_id_870 = ll_edi_file_id_870
	 where	  production_sheet_item.prod_item_num = item_num(m);
      end loop;

      for m in 0..p - 1 loop
	 update   coil
	 set	  coil.scrap_870_date = sysdate
	 where	  coil.coil_abc_num = coil_num(m);

	 update   process_coil
	 set	  scrap_870_date = sysdate
	 where	  ( coil_abc_num = coil_num(m)) and (scrap_870_date is null);

       end loop;

       commit;
*/
  end if; --end if in select count(*)

  --END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_REBAND" IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   */



  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := dbo.get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;
  ld_job_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;
   ls_scrap_coil_org_num coil.coil_org_num%TYPE;

  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_start_nw coil.net_wt%TYPE;
  ll_scrap_end_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
  ll_process_quantity  coil.net_wt%TYPE;
  ll_process_end_wt  coil.net_wt%TYPE;
  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers

  CURSOR coil_cur IS
  SELECT UNIQUE COIL.COIL_ABC_NUM, AB_JOB.AB_JOB_NUM
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER,
	 PROCESS_COIL
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( COIL.COIL_ABC_NUM = PROCESS_COIL.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = PROCESS_COIL.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS = 7 ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 ( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 ( PROCESS_COIL.SCRAP_870_DATE is NULL ) AND
	 ( COIL.SCRAP_870_DATE is NULL ) AND
	 ( SHEET_SKID.SKID_SHEET_STATUS in (2,4,12,13) );

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
 		   AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
		   AND (ab_job.order_abc_num = order_item.order_abc_num)
		   AND (ab_job.order_item_num = order_item.order_item_num)
      AND (production_sheet_item.coil_abc_num = ll_cur_coil)
      AND (production_sheet_item.ab_job_num = ll_cur_job);


  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;


BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER,
	 PROCESS_COIL
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( COIL.COIL_ABC_NUM = PROCESS_COIL.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = PROCESS_COIL.AB_JOB_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS = 7 ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 ( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 ( PROCESS_COIL.SCRAP_870_DATE is NULL ) AND
	 ( COIL.SCRAP_870_DATE is NULL ) AND
	 ( SHEET_SKID.SKID_SHEET_STATUS in (2,4,12,13) );

    IF (ll_item_count <> 0) THEN


      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;
	  ll_cur_job := coil_rec.ab_job_num;



	FOR item_rec IN alcan_870_cur LOOP   -- item loop


	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
				       ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
			 AND (ab_job.order_abc_num = order_item.order_abc_num)
			 AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = ll_cur_job);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop


     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     SELECT scrap_870_date
     INTO ld_job_scrap_870_date
     FROM process_coil
     WHERE (coil_abc_num = ll_cur_coil) AND (ab_job_num = ll_cur_job);

     IF (ld_scrap_870_date is NULL) AND (ld_job_scrap_870_date is NULL) THEN  -- scrap not sent

	     SELECT b.coil_org_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
	   INTO ls_scrap_coil_org_num, ll_scrap_start_nw, ll_scrap_end_nw
	   FROM process_coil a, coil b
	   WHERE (b.coil_abc_num = ll_cur_coil)
	   AND (a.coil_abc_num = b.coil_abc_num)
	    AND (a.ab_job_num = ll_cur_job);

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = ll_cur_job) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


		ll_scrap_nw := ll_scrap_start_nw - ll_scrap_end_nw - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   END IF;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || ls_scrap_coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 END IF;

       END IF;	-- scrap not sent
     END LOOP;	 -- coil loop

      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= 'S_alcan_' || to_char(ll_edi_file_id_aleris) ||
			   '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE


      --For verifying 997
      /*INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
	COMMIT;
      */
      edi_file	      := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      FOR coil_rec IN coil_cur LOOP    -- coil loop date
	  UPDATE process_coil set scrap_870_date = sysdate
	  WHERE (coil_abc_num = coil_rec.coil_abc_num) AND (ab_job_num = coil_rec.ab_job_num);
     END LOOP;	 -- coil loop date

     commit;

     FOR m IN 0 .. k - 1 LOOP
       UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
	 WHERE production_sheet_item.prod_item_num = item_num(m);
     END LOOP;

     COMMIT;


    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_REBAND_COILS2"
     (
	al_customer_id	customer.customer_id%type
     )
is

  /*
  /*
   Aluminum Blanking: duns:039630926	 edi id:039630926t	  qualifier: 01
   */



  --Alex Gerlants. 11/15/2016. commented out, and added the line after.
  --edi_loc varchar2(50) := '/templar/templar/incoming/senddata';
  edi_loc varchar2(50) := dbo.get_edi_destination('EDI_DIR');

  edi_file	  varchar2(50) := 'edi_out.txt';
  edi_file_handle utl_file.file_type;

  --edi_file_prefix varchar2(50) := 'S_alcan_870_reband_'; --Production
  edi_file_prefix varchar2(50) := 's_alcan_870_reband_'; --Development
  --edi_file_prefix varchar2(50) := 'Alex_alcan_';

  su_duns	  varchar2(10);
  --ll_customer_id  customer.customer_id%type;
  ll_cur_coil	  coil.coil_abc_num%type;

  ll_cur_job ab_job.ab_job_num%type;

  ll_gs_log integer;
  ll_st_log integer;

  ls_today   varchar2(20) := to_char(sysdate, 'YYYYMMDD');
  ls_today_4 varchar2(20) := to_char(sysdate, 'YYMMDD');
  ls_now     varchar2(20) := to_char(sysdate, 'HH24MI');

  ls_po varchar2(20);
  ls_finished_goods varchar2(32);
  ls_cust_prod_line varchar2(8);

  ld_scrap_870_date ab_job.scrap_870_date%type;
  ld_job_scrap_870_date ab_job.scrap_870_date%type;

  ls_coil_org_num coil.coil_org_num%type;
  ls_heat coil.lot_num%type;
   ls_scrap_coil_org_num coil.coil_org_num%type;

  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%type;
  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%type;
  ls_sheet_type order_item.sheet_type%type;

  ll_prime_nw coil.net_wt%type;
  ll_scrap_start_nw coil.net_wt%type;
  ll_scrap_end_nw coil.net_wt%type;
  ll_scrap_nw coil.net_wt%type;
  ll_process_quantity  coil.net_wt%type;
  ll_process_end_wt  coil.net_wt%type;
  lr_theo_unit_wt order_item.theoretical_unit_wt%type;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris integer;

  ll_item_count integer;

  li_hl01 integer;
  li_hllin integer;
  ll_cur_prod_item_num production_sheet_item.prod_item_num%type;

--  cursor cust_cur is
--    select customer_id from customer where customer_id in (1153,1459,2582); ---add customer id here if you want to send 870 for more customers

  cursor coil_cur is
  select distinct coil.coil_abc_num, ab_job.ab_job_num
    from ab_job,
	 coil,
	 production_sheet_item,
	 sheet_skid,
	 sheet_skid_detail,
	 customer_order,
	 process_coil
   where ( sheet_skid_detail.sheet_skid_num = sheet_skid.sheet_skid_num ) and
	 ( sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num ) and
	 ( coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
	 ( ab_job.ab_job_num = sheet_skid.ab_job_num ) and
	 ( coil.coil_abc_num = process_coil.coil_abc_num ) and
	 ( ab_job.ab_job_num = process_coil.ab_job_num ) and
	 ( ab_job.order_abc_num = customer_order.order_abc_num ) and
	 ( ab_job.job_status = 0 ) and
	 --( coil.coil_status = 7 ) and
	 ( process_coil.process_coil_status = 7 ) and
	 ( customer_order.orig_customer_id = al_customer_id ) and
	 ( production_sheet_item.prod_item_edi870_date is null ) and
	 ( process_coil.scrap_870_date is null ) and
	 ( coil.scrap_870_date is null ) and
	 ( sheet_skid.skid_sheet_status in (2,4,12,13) );

  cursor alcan_870_cur is
   select production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   null done
      from sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     where (sheet_skid.skid_sheet_status in (2, 4, 13, 12)) -- 2: ready; 8: warehouse ready; 13: partial ready; 7: partial; 12: sample; 4: onhold
       and (production_sheet_item.prod_item_edi870_date is null)
       and (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       and (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       and (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       and (coil.customer_id = al_customer_id)
       and (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
 		   and (production_sheet_item.ab_job_num = ab_job.ab_job_num)
		   and (ab_job.order_abc_num = order_item.order_abc_num)
		   and (ab_job.order_item_num = order_item.order_item_num)
      and (production_sheet_item.coil_abc_num = ll_cur_coil)
      and (production_sheet_item.ab_job_num = ll_cur_job);


  type store_tabletype is table of varchar2(32767) index by binary_integer;
  x12_table store_tabletype;
  i	    binary_integer := 0;

  item_rec  alcan_870_cur%rowtype;
  coil_rec  coil_cur%rowtype;

  type prod_item_type is table of production_sheet_item.prod_item_num%type index by binary_integer;
  item_num prod_item_type;
  k	   binary_integer := 0;


begin

  --for cust_rec in cust_cur loop
    --- outer loop of customer_id
    --ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;

  select count(coil.coil_abc_num)
  into ll_item_count
    from ab_job,
	 coil,
	 production_sheet_item,
	 sheet_skid,
	 sheet_skid_detail,
	 customer_order,
	 process_coil
   where ( sheet_skid_detail.sheet_skid_num = sheet_skid.sheet_skid_num ) and
	 ( sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num ) and
	 ( coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
	 ( coil.coil_abc_num = process_coil.coil_abc_num ) and
	 ( ab_job.ab_job_num = process_coil.ab_job_num ) and
	 ( ab_job.ab_job_num = sheet_skid.ab_job_num ) and
	 ( ab_job.order_abc_num = customer_order.order_abc_num ) and
	 ( ab_job.job_status = 0 ) and
	 --( coil.coil_status = 7 ) and
	 ( process_coil.process_coil_status = 7 ) and
	 ( customer_order.orig_customer_id = al_customer_id ) and
	 ( production_sheet_item.prod_item_edi870_date is null ) and
	 ( process_coil.scrap_870_date is null ) and
	 ( coil.scrap_870_date is null ) and
	 ( sheet_skid.skid_sheet_status in (2,4,12,13) );

    if (ll_item_count <> 0) then


      select edi_st_log_seq.nextval into ll_st_log from dual;
      select edi_gs_log_seq.nextval into ll_gs_log from dual;

      select customer.customer_duns_number_string
	into su_duns
	from customer
       where customer.customer_id = al_customer_id;

      --Production
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*0015049350011G *' ||
      --		ls_today_4 || '*' || ls_now || '*U*00401*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';

      --Development
      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*NOVLSTEST      *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*T**';

      i := i + 1;

      --Production
      --x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
      --		ls_today || '*' || ls_now || '*' ||
      --		to_char(ll_gs_log) || '*X*' || '004010';

      --Development
      x12_table(i) := 'GS*RS*2NDSFTP*' || 'NOVLSTEST' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';

      i := i + 1;

      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      for coil_rec in coil_cur loop    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;
	  ll_cur_job := coil_rec.ab_job_num;

	  for item_rec in alcan_870_cur loop   -- item loop
	    ll_cur_prod_item_num := item_rec.prod_item_num;

	    li_hl01 := li_hl01 + 1;

	    x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	    i := i + 1;

	    select nvl(customer_order.orig_customer_po, 'NA'),
		   nvl(order_item.cust_prod_line_id, 'NA'),
		   nvl(order_item.finished_goods_material_num, 'NA')
	    into   ls_po, ls_cust_prod_line, ls_finished_goods
	    from   order_item,
		   ab_job,
		   customer_order
	    where  (ab_job.order_abc_num = customer_order.order_abc_num)
	    and    (ab_job.order_abc_num = order_item.order_abc_num)
	    and    (ab_job.order_item_num = order_item.order_item_num)
	    and    (ab_job.ab_job_num = ll_cur_job);

	    if (ls_po <> ls_finished_goods) and (ls_po <> 'NA' ) then
	       x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	       i := i + 1;
	    end if;

	    x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	    i := i + 1;

	    x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	    i := i + 1;


	    x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	    i := i + 1;

	    x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			    '*NA';
	    i := i + 1;

	    x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	    i := i + 1;

	    x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			      item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	    i := i + 1;

	    if item_rec.skid_sheet_status = 2 then
	      x12_table(i) := 'PID*S*MA*ST*1*' ||
			      to_char(item_rec.sheet_skid_display_num);
	      i := i + 1;
	    elsif item_rec.skid_sheet_status = 4 then
	      x12_table(i) := 'PID*S*MA*ST*3*' ||
			      to_char(item_rec.sheet_skid_display_num);
	      i := i + 1;
	    elsif item_rec.skid_sheet_status = 13 then
	      x12_table(i) := 'PID*S*MA*ST*8*' ||
			      to_char(item_rec.sheet_skid_display_num);
	      i := i + 1;
	     else
	      x12_table(i) := 'PID*S*MA*ST*4*' ||
			      to_char(item_rec.sheet_skid_display_num);
	      i := i + 1;
	    end if;

	    x12_table(i) := 'PID*S*MAC*ST*01';
	    i := i + 1;
	    x12_table(i) := 'PID*S*PR*ST*19';
	    i := i + 1;
	    x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			    '*LB*01';
	    i := i + 1;
	    x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			    '*LB*01';
	    i := i + 1;
	    x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			    '*PC';
	    i := i + 1;

	     item_num(k) := item_rec.prod_item_num;
	    k := k + 1;

	  end loop;  -- item loop


     select scrap_870_date, coil_org_num, lot_num
     into ld_scrap_870_date, ls_coil_org_num, ls_heat
     from coil
     where coil_abc_num = ll_cur_coil;

     select scrap_870_date
     into ld_job_scrap_870_date
     from process_coil
     where (coil_abc_num = ll_cur_coil) and (ab_job_num = ll_cur_job);

     if (ld_scrap_870_date is null) and (ld_job_scrap_870_date is null) then  -- scrap not sent

	     select b.coil_org_num,
	       nvl(a.process_quantity, 0) process_quan,
	       nvl(a.process_end_wt, 0) process_end_wt
	   into ls_scrap_coil_org_num, ll_scrap_start_nw, ll_scrap_end_nw
	   from process_coil a, coil b
	   where (b.coil_abc_num = ll_cur_coil)
	   and (a.coil_abc_num = b.coil_abc_num)
	    and (a.ab_job_num = ll_cur_job);

	--scrap info

	select	 nvl(sum(production_sheet_item.prod_item_net_wt),0)
	into	 ll_prime_nw
	from	 production_sheet_item
	where	 production_sheet_item.ab_job_num = ll_cur_job
	and	 production_sheet_item.coil_abc_num = ll_cur_coil;
	--and	   production_sheet_item.prod_item_num = ll_cur_prod_item_num;


		ll_scrap_nw := ll_scrap_start_nw - ll_scrap_end_nw - ll_prime_nw;

		if ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   if (ls_po <> ls_finished_goods) and (ls_po <> 'NA' ) then
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   end if;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || ls_scrap_coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 end if;

       end if;	-- scrap not sent
     end loop;	 -- coil loop

      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- write edi to file

      if li_hl01 > 1 then
	-- write edi file only if item > 0
	select	 edi_file_id_seq.nextval
	into	 ll_edi_file_id_aleris
	from	 dual;

	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris);
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	for j in 0 .. i loop
	  utl_file.put_line(edi_file_handle, x12_table(j));

	end loop;

	utl_file.fclose(edi_file_handle);
      end if; -- end writing edi file


      --for verifying 997
/*
      insert into outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	values
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   sysdate,
	   edi_file,
	   0,
	   al_customer_id,
	   ll_st_log,
	   '870');
--	  commit;
*/

      edi_file	      := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(sysdate, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

/*
      for coil_rec in coil_cur loop
	 update   process_coil
	 set	  scrap_870_date = sysdate
	 where	  coil_abc_num = coil_rec.coil_abc_num
	 and	  ab_job_num = coil_rec.ab_job_num;
      end loop;


--	commit;


      for m in 0 .. k - 1 loop

	 update   production_sheet_item
	 set	  prod_item_edi870_date = sysdate,
		  edi_file_id_870 = ll_edi_file_id_aleris
	 where	  production_sheet_item.prod_item_num = item_num(m);

      end loop;

     commit; -- Just 1 commit for all updates above
*/
    end if; --end if in select count(*)

  --end loop; ------ end of outer loop customer_id

exception
  when utl_file.invalid_path then
    utl_file.fclose_all;
    return;
  when utl_file.invalid_mode then
    utl_file.fclose_all;
    return;
  when utl_file.invalid_operation then
    utl_file.fclose_all;
    return;
  when utl_file.write_error then
    utl_file.fclose_all;
    return;
  when others then
    utl_file.fclose_all;
    return;
end;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_REJ_COILS"
     (
	al_customer_id	customer.customer_id%type
     )
is

  --alex gerlants. 11/15/2016. commented out, and added the line after.
  --edi_loc varchar2(50) := '/templar/templar/incoming/senddata';
  edi_loc varchar2(50) := get_edi_destination('EDI_DIR');

  edi_file	  varchar2(50) := 'edi_out.txt';
  --edi_file_prefix varchar2(50) := 'S_alcan_870_reject_'; --Production
  edi_file_prefix varchar2(50) := 's_alcan_870_reject_'; --Development
  --edi_file_prefix varchar2(50) := 'Alex_alcan_';
  edi_file_handle utl_file.file_type;
  su_duns	  varchar2(20); /* alex gerlants. changed from (10) to (20) */
  ll_cur_coil	  coil.coil_abc_num%type;

  ll_gs_log integer;
  ll_st_log integer;

  ls_today   varchar2(20) := to_char(sysdate, 'YYYYMMDD');
  ls_today_4 varchar2(20) := to_char(sysdate, 'YYMMDD');
  ls_now     varchar2(20) := to_char(sysdate, 'HH24MI');

  ls_po varchar2(20);
  ls_finished_goods varchar2(32);
  --ls_cust_prod_line varchar2(8);

  --ld_scrap_870_date ab_job.scrap_870_date%type;

  --ls_coil_org_num coil.coil_org_num%type;
  --ls_heat coil.lot_num%type;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%type;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%type;
--  ls_sheet_type order_item.sheet_type%type;

 -- ll_prime_nw coil.net_wt%type;
  ll_scrap_nw coil.net_wt%type;
--  ll_process_quantity  coil.net_wt%type;
--  ll_process_end_wt  coil.net_wt%type;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%type;

  --ll_edi_file_id integer;
  ll_edi_file_id integer;

  --ll_item_count integer;

  li_hl01 integer;
  li_hllin integer;

  --li_coil_status   coil.coil_status%type; /* alex gerlants. new variable */

  ll_rejected_coils	integer; /* alex gerlants. 07/25/2017 */
  --ls_isa_header_created char(1) := 'N'; /* alex gerlants. 07/25/2017 */

  consumed_coil_num coil.consumed_coil_num%type;
  li_coil_status    coil.coil_status%type;
  ld_scrap_870_date coil.scrap_870_date%type;

   /* alex gerlants. 07/25/2017. begin */
   cursor rejected_coils_cur is
   select coil.coil_abc_num coil_abc_num,
	  coil.coil_org_num coil_org_num,
	  ab_job.ab_job_num ab_job_num,
	  nvl(coil.material_num, ' ') material_num,
	  nvl(coil.net_wt, 0) net_wt,
	  nvl(coil.net_wt_balance, 0) net_wt_balance,
	  nvl(customer_order.orig_customer_po, 'NA') orig_customer_po,
	  nvl(order_item.cust_prod_line_id, 'NA') cust_prod_line_id,
	  nvl(order_item.finished_goods_material_num, 'NA') finished_goods_material_num,
	  nvl(coil.consumed_coil_num, ' ') consumed_coil_num,
	  coil.coil_status,
	  coil.scrap_870_date
   from   reject_coil
	  join coil on coil.coil_abc_num = reject_coil.coil_abc_num
	  join ab_job on reject_coil.ab_job_num = ab_job.ab_job_num
	  join customer_order on ab_job.order_abc_num = customer_order.order_abc_num
	  join order_item on ab_job.order_abc_num = order_item.order_abc_num and ab_job.order_item_num = order_item.order_item_num
   where  coil.customer_id = al_customer_id
   and	  ab_job.job_status = 0
   and	  coil.scrap_870_date is null;

   reject_rec  rejected_coils_cur%rowtype;

   /* alex gerlants. 07/25/2017. end */


  type store_tabletype is table of varchar2(32767) index by binary_integer;
  x12_table store_tabletype;
  i	    binary_integer := 0;

  /*
  item_rec  alcan_870_cur%rowtype;
  coil_rec  coil_cur%rowtype;

  type prod_item_type is table of production_sheet_item.prod_item_num%type index by binary_integer;
  item_num prod_item_type;
  k	   binary_integer := 0;
  */

  type coil_num_type is table of coil.coil_abc_num%type index by binary_integer;
  coil_num coil_num_type;
  p binary_integer :=0;


begin

  --for cust_rec in cust_cur loop
    --- outer loop of customer_id
  --  ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    --k 	     := 0;
    --p 	     := 0;

  --check for rejected coils
    select count(*)
    into   ll_rejected_coils
    from   reject_coil
	   join coil on coil.coil_abc_num = reject_coil.coil_abc_num
	   join ab_job on reject_coil.ab_job_num = ab_job.ab_job_num
	   join customer_order on ab_job.order_abc_num = customer_order.order_abc_num
	   join order_item on ab_job.order_abc_num = order_item.order_abc_num and ab_job.order_item_num = order_item.order_item_num
    where  coil.customer_id = al_customer_id
    and    ab_job.job_status = 0
    and    coil.scrap_870_date is null;

    if (ll_rejected_coils > 0) then

      select edi_st_log_seq.nextval into ll_st_log from dual;
      select edi_gs_log_seq.nextval into ll_gs_log from dual;


      select customer.customer_duns_number_string
	into su_duns
	from customer
       where customer.customer_id = al_customer_id;

      --Production
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*0015049350011G *' ||
      --		ls_today_4 || '*' || ls_now || '*U*00401*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';

      --Development
      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*NOVLSTEST      *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*T**';

      i := i + 1;
      --Production
      --x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
      --		ls_today || '*' || ls_now || '*' ||
      --		to_char(ll_gs_log) || '*X*' || '004010';

      --Development
      x12_table(i) := 'GS*RS*2NDSFTP*' || 'NOVLSTEST' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';

      i := i + 1;

      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      --ls_isa_header_created := 'Y'; /* alex gerlants. 07/25/2017 */

      li_hl01 := 0;

      ----------------------------------------------------------------------

      for reject_rec in rejected_coils_cur loop

	ll_cur_coil := reject_rec.coil_abc_num;

	coil_num(p) := ll_cur_coil;
	p := p + 1;

	ls_po := reject_rec.orig_customer_po;
	ls_finished_goods := reject_rec.finished_goods_material_num;
	consumed_coil_num := reject_rec.consumed_coil_num;

	ll_scrap_nw := reject_rec.net_wt - reject_rec.net_wt_balance;

	if ll_scrap_nw > 0 then

	   li_hl01 := li_hl01 + 1;

	   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
	   i := i + 1;

	   if (ls_po <> ls_finished_goods) and (ls_po <> 'NA' ) then
	      x12_table(i) := 'PRF*' || reject_rec.orig_customer_po || '****' || reject_rec.cust_prod_line_id;
	      i := i + 1;
	   end if;

	   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	    i := i + 1;

	   x12_table(i) := 'REF*IX*' || to_char(consumed_coil_num);
	    i := i + 1;

	   x12_table(i) := 'PO1**1*UN****' || '***SN*' || reject_rec.coil_org_num ;
	    i := i + 1;

	   x12_table(i) := 'PID*S*MA*ST*S';
	    i := i + 1;
	   x12_table(i) := 'PID*S*MAC*ST*05';
	     i := i + 1;
	   x12_table(i) := 'PID*S*PR*ST*19';
	     i := i + 1;

	   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
	    i := i+1;
	 end if;
      end loop;

      ----------------------------------------------------------------------


      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- write edi to file

      if li_hl01 > 0 then  --alex gerlants. changed from "> 1" to "> 0"
	-- write edi file only if item > 0
	select edi_file_id_seq.nextval
	  into ll_edi_file_id
	  from dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	for j in 0 .. i loop
	  utl_file.put_line(edi_file_handle, x12_table(j));

	end loop;
	utl_file.fclose(edi_file_handle);
      end if; -- end writing edi file

      --edi_file	:= 'send_edi_log'; /* alex gerlants. 04/14/2017. commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(sysdate, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --for verifying 997
      /*
      insert into outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	values
	  (ll_edi_file_id,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   sysdate,
	   edi_file,
	   0,
	   al_customer_id,
	   ll_st_log,
	   '870');

	for m in 0..p - 1 loop
	    select  coil.coil_status, coil.scrap_870_date
	    into    li_coil_status, ld_scrap_870_date
	    from    coil
	    where   coil.coil_abc_num = coil_num(m);

	    if li_coil_status <> 7 then --skip rebanded coils
	      --coil.scrap_870_date and process_coil.scrap_870_date are updated in edi_alcan_870
	      --thus if it already updated, do not update here
	      if ld_scrap_870_date is null then
		update	coil
		set	coil.scrap_870_date = sysdate,
			coil.edi_file_id_870_reject = ll_edi_file_id;

		update	process_coil
		set	scrap_870_date = sysdate
		where	coil_abc_num = coil_num(m);
	      else --ld_scrap_870_date is not null, update edi_file_id only
		update	coil
		set	coil.edi_file_id_870_reject = ll_edi_file_id
		where	coil.coil_abc_num = coil_num(m);
	      end if;
	    end if; --if li_coil_status <> 7 then
	end loop; --for m in 0..p - 1 loop

	commit;
	*/

    end if; --if (ll_rejected_coils > 0) then


exception
  when utl_file.invalid_path then
    utl_file.fclose_all;
    return;
  when utl_file.invalid_mode then
    utl_file.fclose_all;
    return;
  when utl_file.invalid_operation then
    utl_file.fclose_all;
    return;
  when utl_file.write_error then
    utl_file.fclose_all;
    return;
  when others then
    utl_file.fclose_all;
    return;
end;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_REJ_COILS2"
     (
	al_customer_id	customer.customer_id%type
     )
is

  --Alex Gerlants. 11/15/2016. commented out, and added the line after.
  --edi_loc varchar2(50) := '/templar/templar/incoming/senddata';
  edi_loc varchar2(50) := get_edi_destination('EDI_DIR');

  edi_file	  varchar2(50) := 'edi_out.txt';
  --edi_file_prefix varchar2(50) := 'S_alcan_870_reject_'; --Production
  edi_file_prefix varchar2(50) := 's_alcan_870_reject_'; --Development
  --edi_file_prefix varchar2(50) := 'Alex_alcan_';
  edi_file_handle utl_file.file_type;
  su_duns	  varchar2(20); /* alex gerlants. changed from (10) to (20) */
  ll_cur_coil	  coil.coil_abc_num%type;

  ll_gs_log integer;
  ll_st_log integer;

  ls_today   varchar2(20) := to_char(sysdate, 'YYYYMMDD');
  ls_today_4 varchar2(20) := to_char(sysdate, 'YYMMDD');
  ls_now     varchar2(20) := to_char(sysdate, 'HH24MI');

  ls_po varchar2(20);
  ls_finished_goods varchar2(32);
  ll_scrap_nw coil.net_wt%type;
  ll_edi_file_id integer;
  li_hl01 integer;
  li_hllin integer;

  --li_coil_status   coil.coil_status%type; /* alex gerlants. new variable */

  ll_rejected_coils	integer; /* alex gerlants. 07/25/2017 */
  --ls_isa_header_created char(1) := 'N'; /* alex gerlants. 07/25/2017 */

  consumed_coil_num coil.consumed_coil_num%type;
  li_coil_status    coil.coil_status%type;
  ld_scrap_870_date coil.scrap_870_date%type;

  ll_count	    number(8); --Alex Gerlants. 02/03/2020
  ll_count_2process number(8); --Alex Gerlants. 02/03/2020

   /* alex gerlants. 07/25/2017. begin */
   /*
   cursor rejected_coils_cur is
   select coil.coil_abc_num coil_abc_num,
	  coil.coil_org_num coil_org_num,
	  ab_job.ab_job_num ab_job_num,
	  nvl(coil.material_num, ' ') material_num,
	  nvl(coil.net_wt, 0) net_wt,
	  nvl(coil.net_wt_balance, 0) net_wt_balance,
	  nvl(customer_order.orig_customer_po, 'NA') orig_customer_po,
	  nvl(order_item.cust_prod_line_id, 'NA') cust_prod_line_id,
	  nvl(order_item.finished_goods_material_num, 'NA') finished_goods_material_num,
	  nvl(coil.consumed_coil_num, ' ') consumed_coil_num,
	  coil.coil_status,
	  coil.scrap_870_date
   from   reject_coil
	  join coil on coil.coil_abc_num = reject_coil.coil_abc_num
	  join ab_job on reject_coil.ab_job_num = ab_job.ab_job_num
	  join customer_order on ab_job.order_abc_num = customer_order.order_abc_num
	  join order_item on ab_job.order_abc_num = order_item.order_abc_num and ab_job.order_item_num = order_item.order_item_num
   where  coil.customer_id = al_customer_id
   and	  ab_job.job_status = 0
   and	  coil.scrap_870_date is null;

   reject_rec  rejected_coils_cur%rowtype;
   */
   /* alex gerlants. 07/25/2017. end */

   --Alex Gerlants. 02/03/2020. Begin
   cursor rejected_coils_cur is
   select coil.coil_abc_num coil_abc_num,
	  coil.coil_org_num coil_org_num,
	  ab_job.ab_job_num ab_job_num,
	  nvl(coil.material_num, ' ') material_num,
	  nvl(coil.net_wt, 0) net_wt,
	  nvl(coil.net_wt_balance, 0) net_wt_balance,
	  nvl(customer_order.orig_customer_po, 'NA') orig_customer_po,
	  nvl(order_item.cust_prod_line_id, 'NA') cust_prod_line_id,
	  nvl(order_item.finished_goods_material_num, 'NA') finished_goods_material_num,
	  nvl(coil.consumed_coil_num, ' ') consumed_coil_num,
	  coil.coil_status,
	  coil.scrap_870_date coil_scrap_870_date,
	  process_coil.scrap_870_date process_coil_scrap_870_date,
	  nvl(process_coil.process_quantity, 0) process_quan,
	  nvl(process_coil.process_end_wt, 0) process_end_wt
   from   reject_coil
	  join coil on coil.coil_abc_num = reject_coil.coil_abc_num
	  join process_coil on coil.coil_abc_num = process_coil.coil_abc_num
	  join ab_job on reject_coil.ab_job_num = ab_job.ab_job_num
	  join customer_order on ab_job.order_abc_num = customer_order.order_abc_num
	  join order_item on ab_job.order_abc_num = order_item.order_abc_num and ab_job.order_item_num = order_item.order_item_num
   where  coil.customer_id = al_customer_id
   and	  coil.coil_status = 3
   and	  ab_job.job_status = 0
   and	  coil.scrap_870_date is null
   and	  process_coil.scrap_870_date is null;

   reject_rec  rejected_coils_cur%rowtype;
   --Alex Gerlants. 02/03/2020. End

  type store_tabletype is table of varchar2(32767) index by binary_integer;
  x12_table store_tabletype;
  i	    binary_integer := 0;

  /*
  item_rec  alcan_870_cur%rowtype;
  coil_rec  coil_cur%rowtype;

  type prod_item_type is table of production_sheet_item.prod_item_num%type index by binary_integer;
  item_num prod_item_type;
  k	   binary_integer := 0;
  */

  type coil_num_type is table of coil.coil_abc_num%type index by binary_integer;
  coil_num coil_num_type;
  p binary_integer :=0;


begin

    i		      := 0;
    ll_count_2process := 0;

    --First, determine if any coil in rejected_coils_cur is rejected without sheets,
    --and these coils have not been process before
    for reject_rec in rejected_coils_cur loop

	ll_cur_coil := reject_rec.coil_abc_num;

	select	 count(*)
	into	 ll_count
	from	 production_sheet_item
	where	 coil_abc_num = ll_cur_coil;

	if ll_count > 0 or ( reject_rec.coil_scrap_870_date is not null or reject_rec.process_coil_scrap_870_date is not null ) then
	  continue; --Rejected coils in production_sheet_item produced sheets,
		    --and they are picked up in edi_alcan_870
	end if;

	--if reject_rec.coil_scrap_870_date is not null or reject_rec.process_coil_scrap_870_date is not null then
	--  continue;
	--end if;

	ll_count_2process := ll_count_2process + 1;
    end loop;

  --check for rejected coils
/*
    select count(*)
    into   ll_rejected_coils
    from   reject_coil
	   join coil on coil.coil_abc_num = reject_coil.coil_abc_num
	   join ab_job on reject_coil.ab_job_num = ab_job.ab_job_num
	   join customer_order on ab_job.order_abc_num = customer_order.order_abc_num
	   join order_item on ab_job.order_abc_num = order_item.order_abc_num and ab_job.order_item_num = order_item.order_item_num
    where  coil.customer_id = al_customer_id
    and    ab_job.job_status = 0
    and    coil.scrap_870_date is null;

    if (ll_rejected_coils > 0) then
*/
    if ll_count_2process > 0 then
      select edi_st_log_seq.nextval into ll_st_log from dual;
      select edi_gs_log_seq.nextval into ll_gs_log from dual;

      select   customer.customer_duns_number_string
      into     su_duns
      from     customer
      where    customer.customer_id = al_customer_id;

      --Production
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*0015049350011G *' ||
      --		ls_today_4 || '*' || ls_now || '*U*00401*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';

      --Development
      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*NOVLSTEST      *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*T**';

      i := i + 1;

      --Production
      --x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
      --		ls_today || '*' || ls_now || '*' ||
      --		to_char(ll_gs_log) || '*X*' || '004010';

      --Development
      x12_table(i) := 'GS*RS*2NDSFTP*' || 'NOVLSTEST' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';

      i := i + 1;

      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      --ls_isa_header_created := 'Y'; /* alex gerlants. 07/25/2017 */

      li_hl01 := 0;

      ----------------------------------------------------------------------

      for reject_rec in rejected_coils_cur loop

	ll_cur_coil := reject_rec.coil_abc_num;

	coil_num(p) := ll_cur_coil;
	p := p + 1;

	ls_po := reject_rec.orig_customer_po;
	ls_finished_goods := reject_rec.finished_goods_material_num;
	consumed_coil_num := reject_rec.consumed_coil_num;

	ll_scrap_nw := reject_rec.process_quan - reject_rec.process_end_wt;

	if ll_scrap_nw > 0 then

	   li_hl01 := li_hl01 + 1;

	   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
	   i := i + 1;

	   if (ls_po <> ls_finished_goods) and (ls_po <> 'NA' ) then
	      x12_table(i) := 'PRF*' || reject_rec.orig_customer_po || '****' || reject_rec.cust_prod_line_id;
	      i := i + 1;
	   end if;

	   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	    i := i + 1;

	   x12_table(i) := 'REF*IX*' || to_char(consumed_coil_num);
	    i := i + 1;

	   x12_table(i) := 'PO1**1*UN****' || '***SN*' || reject_rec.coil_org_num ;
	    i := i + 1;

	   x12_table(i) := 'PID*S*MA*ST*S';
	    i := i + 1;
	   x12_table(i) := 'PID*S*MAC*ST*05';
	     i := i + 1;
	   x12_table(i) := 'PID*S*PR*ST*19';
	     i := i + 1;

	   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
	    i := i+1;
	 end if;
      end loop;

      ----------------------------------------------------------------------


      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- write edi to file

      if li_hl01 > 0 then  --alex gerlants. changed from "> 1" to "> 0"
	-- write edi file only if item > 0
	select edi_file_id_seq.nextval
	  into ll_edi_file_id
	  from dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	for j in 0 .. i loop
	  utl_file.put_line(edi_file_handle, x12_table(j));

	end loop;
	utl_file.fclose(edi_file_handle);
      end if; -- end writing edi file

      --edi_file	:= 'send_edi_log'; /* alex gerlants. 04/14/2017. commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(sysdate, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --for verifying 997
/*
      insert into outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	values
	  (ll_edi_file_id,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   sysdate,
	   edi_file,
	   0,
	   al_customer_id,
	   ll_st_log,
	   '870');
*/

	for m in 0..p - 1 loop
	    select  coil.coil_status, coil.scrap_870_date
	    into    li_coil_status, ld_scrap_870_date
	    from    coil
	    where   coil.coil_abc_num = coil_num(m);
/*
	    if li_coil_status <> 7 then --skip rebanded coils...just in case
	      --coil.scrap_870_date and process_coil.scrap_870_date are updated in edi_alcan_870
	      --thus if it already updated, do not update here
	      if ld_scrap_870_date is null then
		update	coil
		set	coil.scrap_870_date = sysdate,
			coil.edi_file_id_870_reject = ll_edi_file_id;

		update	process_coil
		set	scrap_870_date = sysdate
		where	coil_abc_num = coil_num(m);
	      else --ld_scrap_870_date is not null, update edi_file_id only
		update	coil
		set	coil.edi_file_id_870_reject = ll_edi_file_id
		where	coil.coil_abc_num = coil_num(m);
	      end if;
	    end if; --if li_coil_status <> 7 then
*/
	end loop; --for m in 0..p - 1 loop

--	  commit;


    end if; --if (ll_rejected_coils > 0) then


exception
  when utl_file.invalid_path then
    utl_file.fclose_all;
    return;
  when utl_file.invalid_mode then
    utl_file.fclose_all;
    return;
  when utl_file.invalid_operation then
    utl_file.fclose_all;
    return;
  when utl_file.write_error then
    utl_file.fclose_all;
    return;
  when others then
    utl_file.fclose_all;
    return;
end;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_870_REWORK" is

--CREATE OR REPLACE PROCEDURE edi_alcan_870 IS

  /*
  Aluminum Blanking: Ford Suppler Code: ZZ R0P7A
		     DUNS: 01 039630926T
  Customer: ALCAN(34,35,10,1153)
  Alcan Rolled Product	  X.121       0015049350011G
  Kingston Duns: 241003755
  */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := dbo.get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  INTEGER := 1153;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;
  --ll_bsn_log integer;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI'); -- time in 24 hours format....Tony

  ls_po VARCHAR2(36);

  --ll_edi_file_id integer;
  ll_edi_file_id_alcan INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;

  CURSOR cust_cur IS
    SELECT customer_id
      FROM customer
     WHERE customer_id IN (1153, 1459, 2582); ---Add customer id here if you want to send 870 for more customers

  CURSOR alcan_870_cur IS
    SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   sheet_skid.sheet_skid_display_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   coil.coil_org_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,   --add james ni 10/22/2013
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   customer_order --,ab_job
     WHERE (sheet_skid.skid_sheet_status IN (2, 4, 8, 13))
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND -- Add Oswego id=1459 by Tony 04-29-03
	   (sheet_skid.ref_order_abc_num = customer_order.order_abc_num);
  --(production_sheet_item.ab_job_num = ab_job.ab_job_num) and
  --(ab_job.order_abc_num = customer_order.order_abc_num) ;

  --End of change by tony

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;
  item_rec  alcan_870_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;

    SELECT COUNT(*)
      INTO ll_item_count
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (2, 4, 8, 13))
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND -- Add Oswego id=1459 by Tony 04-29-03
	   (sheet_skid.ref_order_abc_num = customer_order.order_abc_num);
    -- if ll_item_count = 0 then return 100; end if;   -- nothing to send
    IF ll_item_count <> 0 THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns || '*NA';
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926T';
      i := i + 1;

      --open alcan_870_cur;
      --fetch alcan_870_cur INTO item_rec;
      --close alcan_870_cur;

      li_hl01 := 1;

      FOR item_rec IN alcan_870_cur LOOP
	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	ls_po := item_rec.customer_po;

	x12_table(i) := 'PRF*' || ls_po || '****NA';
	i := i + 1;
	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;
	-- Nov 21 03, change per Alcan	---tony
	--x12_table(i) := 'REF*SE*' ||item_rec.coil_org_num ||'-'||to_char(item_rec.sheet_skid_num); i := i+1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;

	--add james ni 10/22/2013
	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	-- Nov 21 03, change per Alcan	---tony
	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	--06/05/03 Don't send PO106 AND PO107 incase non sales order available as per Julia
	IF item_rec.sales_order = ' ' THEN
	  x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num;
	  i := i + 1;
	ELSE
	  x12_table(i) := 'PO1**1*UN***VO*' || item_rec.sales_order ||
			  '***SN*' || item_rec.coil_org_num;
	  i := i + 1;
	END IF;

	-- Added partial ready(13), On-hold(4) by Bing Feb-26-2002
	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num) || '*NA';
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num) || '*NA';
	  i := i + 1;

	ELSIF item_rec.skid_sheet_status = 4 THEN -- Add by Tony to handle rework status 10-28-13
	  x12_table(i) := 'PID*S*MA*ST*6*' ||
			  to_char(item_rec.sheet_skid_display_num) || '*NA';
	  i := i + 1;

	ELSE
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num) || '*NA';
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	li_hl01 := li_hl01 + 1;

	item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval INTO ll_edi_file_id_alcan FROM dual;
	edi_file	:= 'S_alcan_' || to_char(ll_edi_file_id_alcan) ||
			   '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --added by Victor Huang on 12/07 for verifying 997
      INSERT INTO outbound_edi_transaction
	(edi_file_id,
	 duns_from,
	 duns_to,
	 interchange_control_number,
	 group_control_number,
	 transaction_time,
	 edi_file_name,
	 fa_receive_status,
	 customer_id,
	 set_control_num,
	 transaction_type_id)
      VALUES
	(ll_edi_file_id_alcan,
	 '039630926',
	 su_duns,
	 ll_gs_log,
	 ll_gs_log,
	 SYSDATE,
	 edi_file,
	 0,
	 ll_customer_id,
	 ll_st_log,
	 '870');
      COMMIT;

      edi_file	      := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      FOR m IN 0 .. k - 1 LOOP
	UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id_alcan /* Alex Gerlants. 09/06/2016. New column */
	 WHERE production_sheet_item.prod_item_num = item_num(m);
      END LOOP;

      COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
end edi_alcan_870_rework;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALCAN_SCRAP_870_BY_JOB" IS

/*
		   DUNS: 01 039630926T
		   Customer: ALCAN(34,35,10,1153)
		   Alcan Rolled Product  	X.121  		  0015049350011G
		   Kingston Duns: 241003755
*/


edi_loc varchar2 (50) := '/templar/templar/incoming/senddata';

--v_edi_text_alcan varchar2(32767);
--edi_loc varchar2(50):='/tmp';
edi_file varchar2 (50) := 'edi_out.txt';
edi_file_prefix varchar2 (50) := 'S_alcan_scrap';
edi_file_handle UTL_FILE.FILE_TYPE;
su_duns varchar2(10);
ll_customer_id	INTEGER;

ll_gs_log integer;
ll_st_log integer;
--scrap_job_num ab_job.ab_job_num%type;
prime_nw coil.net_wt%type;
scrap_nw coil.net_wt%type;
--ll_bsn_log integer;


ls_today varchar2(20):= to_char(sysdate, 'YYYYMMDD');
ls_today_4 varchar2(20):= to_char(sysdate, 'YYMMDD');
ls_now varchar2(20) := to_char(sysdate, 'HH24MI'); -- time in 24 hours format....Tony

ls_po varchar2(20);
ls_so varchar2(30);
--ll_edi_file_id integer;
ll_edi_file_id_alcan integer;

ll_job_count integer;
--coil_of_the_job coil.coil_abc_num%type;
ll_ab_job ab_job.ab_job_num%type;

--ll_onhold_wt coil.net_wt%type;
--ll_reject_wt coil.net_wt%type;
--ll_reband_wt coil.net_wt%type;

--li_customer_id shipment.customer_id%TYPE;
--li_des_sh_cust_id shipment.des_sh_cust_id%TYPE;

--date1 date;
--date2 date;
--coil_ini_date date;


li_HL01 integer;

Cursor cust_cur is
--Add customer id here if you want to send 870 for more customers
SELECT customer_id from customer where customer_id in (1153,1459,2582);


Cursor alcan_870_cur IS
       SELECT a.ab_job_num, b.orig_customer_po, nvl(b.sales_order, ' ') sales_order
       FROM ab_job a, customer_order b
       WHERE (a.order_abc_num = b.order_abc_num) and
	     (a.job_status = 0) and
	     (b.orig_customer_id = ll_customer_id) and
	     (a.scrap_870_date is null);

Cursor coil_info IS
       SELECT process_coil.coil_abc_num, process_coil.process_quantity, coil.coil_alloy2, coil.coil_org_num, nvl(coil.consumed_coil_num, ' ') consumed_coil_num , process_coil.process_end_wt
       FROM process_coil, coil
       WHERE (process_coil.ab_job_num = ll_ab_job) and
	     (process_coil.coil_abc_num = coil.coil_abc_num);


TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
 x12_table store_tabletype;
i binary_integer := 0;

TYPE job_num_type IS TABLE OF ab_job.ab_job_num%type INDEX BY BINARY_INTEGER;
job_num job_num_type;
j binary_integer :=0;

--item_rec alcan_870_cur%rowtype;

BEGIN

for cust_rec in cust_cur

loop --- Outer loop of customer_id
     ll_customer_id := cust_rec.customer_id;
     i:=0;
     j:=0;
 --james
     SELECT count(*) into ll_job_count
       FROM ab_job a, customer_order b
       WHERE (a.order_abc_num = b.order_abc_num) and
	     (a.job_status = 0) and
	     (b.orig_customer_id = ll_customer_id) and
	     (a.scrap_870_date is null);

 IF ll_job_count <> 0 THEN

    SELECT edi_st_log_seq.NEXTVAL INTO ll_st_log FROM DUAL;
    SELECT edi_gs_log_seq.NEXTVAL INTO ll_gs_log FROM DUAL;

    select customer.customer_duns_number_string into su_duns from customer where customer.customer_id = ll_customer_id;

    x12_table(i) := 'ISA*00*'||'	  *00*		*01*039630926T	   *09*0015049350011G *'||ls_today_4 ||'*'|| ls_now ||'*U*00401*'||LPAD(to_char(ll_gs_log),9,'0')||'*0*P**'; i := i + 1;
    x12_table(i) := 'GS*RS*039630926T*'||'001504935001' || '*' || ls_today ||'*' || ls_now || '*' ||to_char(ll_gs_log) || '*X*' || '004010'; i := i + 1;
    x12_table(i):= 'ST*870*' || to_char(ll_st_log); i := i +1;
    x12_table(i):= 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today || '***' || ls_now || '*****'; i := i +1;
    x12_table(i):= 'DTM*009*' || ls_today || '*' || ls_now; i := i +1;
    x12_table(i) := 'N1*SU**1*' || su_duns ||'*NA'; i := i +1;
    x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926T'; i := i + 1;


    --open alcan_870_cur;
    --fetch alcan_870_cur INTO item_rec;
    --close alcan_870_cur;

    li_HL01 := 1;

    for job_rec IN alcan_870_cur -- job loop
    loop
	ll_ab_job := job_rec.ab_job_num;
	ls_po := job_rec.orig_customer_po;
	ls_so := job_rec.sales_order;
	--ls_po := item_rec.customer_po;
	IF INSTR(ls_po,'-') > 0
	THEN
	    ls_po := substr(ls_po, 0, instr(ls_po,'-')-1);
	END IF;


	job_num(j) := ll_ab_job;
	j := j+1;

	for coil_rec IN coil_info   --coil loop
	loop
		SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0) into prime_nw
		FROM production_sheet_item
		WHERE (production_sheet_item.ab_job_num = ll_ab_job) and
		      (production_sheet_item.coil_abc_num = coil_rec.coil_abc_num);

		--ll_onhold_wt := NVL(f_get_coil_onhold_wt(coil_rec.coil_abc_num, coil_rec.process_quantity),0);
		--ll_reband_wt := NVL(f_get_coil_rebanded_wt(coil_rec.coil_abc_num, coil_rec.process_quantity),0);
		--ll_reject_wt := NVL(f_get_coil_rejected_wt(coil_rec.coil_abc_num, coil_rec.process_quantity),0);

		--scrap_nw := coil_rec.process_quantity - ll_onhold_wt - ll_reband_wt - ll_reject_wt - prime_nw;

		scrap_nw := coil_rec.process_quantity - coil_rec.process_end_wt - prime_nw;



		IF scrap_nw > 0 then
		   x12_table(i) := 'HL*'||to_char(li_HL01)||'**I'; i := i +1;


		   --SELECT NVL(ALLOY_TYPE.ALCAN_SCRAP_PO, '6800'||coil_rec.coil_alloy2) into ls_po
		       --FROM ALLOY_TYPE
		     --  WHERE ALLOY_TYPE.ALLOY = coil_rec.coil_alloy2;


		   x12_table(i) := 'PRF*' || ls_po ||'****NA'; i := i+1;
		   x12_table(i) := 'DTM*206*' ||ls_today || '*' || ls_now ||'*ED'; i := i+1;
		   x12_table(i) := 'REF*SE*' || 'T1' ||coil_rec.coil_abc_num || '-' ||to_char(ll_ab_job) ; i := i+1;
		   --x12_table(i) := 'REF*SE*' ||coil_rec.coil_org_num; i := i+1;

		   x12_table(i) := 'REF*IX*' || coil_rec.consumed_coil_num;
		   i := i + 1;


		   x12_table(i) := 'REF*MI*' || to_char(ll_ab_job); i := i+1;
		   --x12_table(i) := 'REF*RV*' ||coil_rec.coil_org_num ||'*NA'; i := i+1;
		   x12_table(i) := 'REF*RV*' || 'T1' || coil_rec.coil_abc_num || '-' || to_char(ll_ab_job) || '*NA'; i := i+1;

		   --x12_table(i) := 'PO1**1*UN****' || '***SN*' ||coil_rec.coil_org_num; i := i+1;


		   IF ls_so = ' ' THEN
		      x12_table(i) := 'PO1**1*UN****' || '***SN*' || coil_rec.coil_org_num;
		      i := i + 1;
		   ELSE
		      x12_table(i) := 'PO1**1*UN***VO*' || ls_so || '***SN*' || coil_rec.coil_org_num;
		      i := i + 1;
		   END IF;


		   x12_table(i) := 'PID*S*MA*ST*S'; i := i+1; -- ST*S for scrap --Tony

		   x12_table(i) := 'PID*S*MAC*ST*05'; i := i+1;
		   --x12_table(i) := 'PID*S*MAC*ST*03'; i := i+1; or this one , need test

		   x12_table(i) := 'PID*S*PR*ST*19'; i := i+1;
		   x12_table(i) := 'MEA*WT*N*' || to_char(scrap_nw) || '*LB*01'; i := i+1;

		   li_HL01 := li_HL01 +1;
		end if; -- end if scrap_nw >0
	end loop; -- end of coil loop
    end loop;	  -- end of job loop



    x12_table(i) :=  'CTT*' || to_char(li_HL01 - 1); i := i+1;
    x12_table(i) :=  'SE*' || to_char (i-1) ||'*'|| to_char(ll_st_log); i := i+1;
    x12_table(i) :=  'GE*1*' || to_char (ll_gs_log); i := i+1;
    x12_table(i) :=  'IEA*1*' || LPAD(to_char(ll_gs_log),9,'0');


-- Write EDI to file

    IF li_HL01 > 1 then --write to file only if items > 0
	 SELECT edi_file_id_seq.NEXTVAL INTO ll_edi_file_id_alcan FROM DUAL;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--		  edi_file:= 's_alcan_scrap' || to_char(ll_edi_file_id_alcan) ||'.870';
		edi_file:= edi_file_prefix || to_char(ll_edi_file_id_alcan) ||'.edi';
		edi_file_handle := UTL_FILE.FOPEN(edi_loc, edi_file, 'W');

		for j in 0..i loop
		   UTL_FILE.PUT_LINE(edi_file_handle, x12_table(j));
				 -- v_edi_text_alcan:=v_edi_text_alcan||x12_table(j)||CHR(10);
		end loop;
	 UTL_FILE.FCLOSE(edi_file_handle);
    END IF;

    --added by Victor Huang on 06/05 for function acknowlegement
    --INSERT INTO edi_fa(gs_num, duns_num, send_time,edi_file_name)
    --VALUES(ll_gs_log, su_duns, sysdate, edi_file);
    --COMMIT;

    --added by Victor Huang on 12/07 for verifying 997

  INSERT INTO outbound_edi_transaction(edi_file_id,duns_from,duns_to,interchange_control_number,
  group_control_number,transaction_time,edi_file_name,fa_receive_status,customer_id,set_control_num,transaction_type_id)
  VALUES(ll_edi_file_id_alcan,'039630926',su_duns,ll_gs_log,ll_gs_log, sysdate, edi_file,0,ll_customer_id,ll_st_log,'870 Scrap');
  COMMIT;

    edi_file := 'send_edi_log';
    edi_file_handle :=utl_file.fopen(edi_loc,edi_file,'a');
    utl_file.put_line(edi_file_handle,'Type: 870 Scrap');
    utl_file.put_line(edi_file_handle,'Sending Time: '||to_char(sysdate, 'MM/DD/YY HH24:MI'));
    utl_file.put_line(edi_file_handle,'Interchange Control #: '||ll_gs_log);
    utl_file.put_line(edi_file_handle,'Group Control #: '||ll_gs_log);
    utl_file.put_line(edi_file_handle,'Set Control #: '||ll_st_log);
    utl_file.put_line(edi_file_handle,'');
    utl_file.put_line(edi_file_handle,'');
    utl_file.fclose(edi_file_handle);



	 FOR k in 0..j-1
	     LOOP
		UPDATE ab_job set ab_job.scrap_870_date = sysdate
		WHERE ab_job.ab_job_num = job_num(k);
	     END LOOP;

	 commit;


 END IF;       --end if in select count(*)

 --james

end loop; ------ End of outer loop customer_id


EXCEPTION
     WHEN NO_DATA_FOUND THEN
	  DBMS_OUTPUT.put_line('NO DATA FOUND!!!');
	  RETURN;
     WHEN UTL_FILE.INVALID_PATH THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
     WHEN UTL_FILE.INVALID_MODE THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN UTL_FILE.INVALID_OPERATION THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN UTL_FILE.WRITE_ERROR THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN OTHERS THEN
     UTL_FILE.FCLOSE_ALL;
     DBMS_OUTPUT.put_line('ERROR!!');
      RETURN;
 END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ALERIS_870" IS

  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ
   This version of the stored procedure was copied from production on
   May 23, 2016 by Patrick Reynolds.
   The only main difference between the DEV and PROD version of the stored prcedure is that
   the DEV version had the update section all commented out.
   There was also an additional index (p) variable in the PROD code
   that the DEV version did not have.
   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := dbo.get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 'S_aleris_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  INTEGER := 1980;
  li_scrap_job_done  INTEGER := 2;

  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(32);
   ls_enduser_po VARCHAR2(32);
   ls_enduser_item_po VARCHAR2(32);
  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;
  ln_coil_thickness coil.coil_gauge%TYPE;
  ln_width  rectangle.rt_width%TYPE;
  ln_length rectangle.rt_length%TYPE;

  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
  -- ll_process_quantity  coil.net_wt%TYPE;
  -- ll_process_end_wt	coil.net_wt%TYPE;
  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;
  ll_job_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;


  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (1980); ---Add customer id here if you want to send 870 for more customers

  CURSOR job_cur IS
   SELECT UNIQUE production_sheet_item.ab_job_num
    FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (2, 8))
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = 1980)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
   UNION
       SELECT UNIQUE a.ab_job_num
       FROM ab_job a, customer_order b
       WHERE (a.order_abc_num = b.order_abc_num) and
	     (a.job_status = 0) and
	     (b.orig_customer_id = 1980) and
	     (a.scrap_870_date is null);


  CURSOR aleris_870_cur IS
    SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(customer_order.enduser_po, 'NA') enduser_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
			     ab_job,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (2, 4, 7, 8, 13)) -- 2: Ready; 8: Warehouse Ready; 4: onhold 13: Partial Ready
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
 		   AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
		   AND (ab_job.order_abc_num = order_item.order_abc_num)
		   AND (ab_job.order_item_num = order_item.order_item_num)
      AND (production_sheet_item.ab_job_num = ll_cur_job);

      CURSOR aleris_scrap_870_cur IS
       SELECT coil_abc_num,
	       NVL(process_quantity, 0) process_quan,
	       NVL(process_end_wt, 0) process_end_wt
       FROM process_coil
       WHERE (process_coil.ab_job_num = ll_cur_job);

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;
  item_rec  aleris_870_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE job_num_type IS TABLE OF ab_job.ab_job_num%type INDEX BY BINARY_INTEGER;
  job_num job_num_type;
  p binary_integer :=0;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;
    p		   := 0;

    SELECT COUNT(*)
      INTO ll_item_count
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (2, 8)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num);

       SELECT count(a.ab_job_num)
       INTO ll_job_count
       FROM ab_job a, customer_order b
       WHERE (a.order_abc_num = b.order_abc_num) and
	     (a.job_status = 0) and
	     (b.orig_customer_id = 1980) and
	     (a.scrap_870_date is null);


    IF (ll_item_count <> 0) or (ll_job_count <> 0)THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *ZZ*964790856      *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P*>';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '964790856' || '*' || ls_today || '*' ||
		      ls_now || '*' || to_char(ll_gs_log) || '*X*' ||
		      '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;

      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926T';
      i := i + 1;

       x12_table(i) := 'N1*MF**1*' || su_duns;
      i := i + 1;

      li_hl01 := 0;


      FOR job_rec IN job_cur LOOP    -- job loop


	  ll_cur_job := job_rec.ab_job_num;

	  job_num(p) := ll_cur_job;
	  p := p + 1;

	     SELECT nvl(customer_order.orig_customer_po, 'NA'), nvl(customer_order.enduser_po, 'NA')
	      INTO ls_po, ls_enduser_po
	      FROM ab_job, customer_order
	      WHERE (ab_job.ab_job_num = ll_cur_job)
	      and (ab_job.order_abc_num = customer_order.order_abc_num);


	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**O*1';
	i := i + 1;

	x12_table(i) := 'PRF*' || ls_enduser_po || '***' || ls_today;
	i := i + 1;

	li_hl01 := li_hl01 + 1;

	 x12_table(i) := 'HL*' || to_char(li_hl01) || '*1*I*1';
	i := i + 1;

	x12_table(i) := 'PRF*RV*300578504';
	i := i + 1;

	li_hllin := li_hl01;



      FOR item_rec IN aleris_870_cur LOOP  -- item loop


	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*F';
	i := i + 1;

	ls_po := item_rec.customer_po;
	ls_enduser_item_po := item_rec.enduser_po;

	x12_table(i) := 'PRF*' || ls_enduser_item_po || '***' || ls_today;
	i := i + 1;

	x12_table(i) := 'REF*SE*' || item_rec.sheet_skid_num;
	 i := i + 1;

	x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now || '*ES';
	i := i + 1;

	x12_table(i) := 'DTM*206*' || ls_today;
	i := i + 1;


	x12_table(i) := 'PO1**1*UN***VO*' || ls_enduser_item_po ||
			  '*SN*' || item_rec.coil_org_num || '*HN*' || item_rec.lot_num || '***BP*' || item_rec.enduser_parts;
	 i := i + 1;


	 x12_table(i) := 'PID*S*MAC*ST*01***67';
	  i := i + 1;
	 x12_table(i) := 'PID*S*22*ST*20***22';
	  i := i + 1;

       IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1***70' ;
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8***70';
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*6***70';
	  i := i + 1;
	ELSE
	  x12_table(i) := 'PID*S*MA*ST*3***70';
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*PR*ST*19***66';
	  i := i + 1;


    SELECT MAX(coil_gauge)
      INTO ln_coil_thickness
      FROM coil
     WHERE coil.coil_abc_num IN
	   (SELECT coil_abc_num
	      FROM production_sheet_item
	     WHERE production_sheet_item.prod_item_num IN
		   (SELECT prod_item_num
		      FROM sheet_skid_detail
		     WHERE sheet_skid_detail.sheet_skid_num =
			   item_rec.sheet_skid_num));

    x12_table(i) := 'MEA*PD*TH*' ||
		    TRIM(to_char(ln_coil_thickness, '99999.99')) || '*ED';
    i := i + 1;
    x12_table(i) := 'MEA*PD*TH*' ||
		    TRIM(to_char(ln_coil_thickness * 25.4, '99999.99')) ||
		    '*MB';
    i := i + 1;

    SELECT ss.ref_order_abc_num, ss.ref_order_abc_item
      INTO ll_ref_order_abc_num, ll_ref_order_abc_item
      FROM sheet_skid ss
     WHERE ss.sheet_skid_num = item_rec.sheet_skid_num;

    SELECT sheet_type, NVL(theoretical_unit_wt, 0)
      INTO ls_sheet_type, lr_theo_unit_wt
      FROM order_item
     WHERE order_abc_num = ll_ref_order_abc_num
       AND order_item_num = ll_ref_order_abc_item;

    CASE TRIM(upper(ls_sheet_type))
      WHEN 'RECTANGLE' THEN
	SELECT t.rt_length, t.rt_width
	  INTO ln_length, ln_width
	  FROM rectangle t
	 WHERE t.order_abc_num = ll_ref_order_abc_num
	   AND t.order_item_num = ll_ref_order_abc_item;
      WHEN 'PARALLELOGRAM' THEN
	SELECT t.p_length, t.p_width
	  INTO ln_length, ln_width
	  FROM parallelogram t
	 WHERE t.order_abc_num = ll_ref_order_abc_num
	   AND t.order_item_num = ll_ref_order_abc_item;
      WHEN 'FENDER' THEN
	SELECT t.fe_length, t.fe_side
	  INTO ln_length, ln_width
	  FROM fender t
	 WHERE t.order_abc_num = ll_ref_order_abc_num
	   AND t.order_item_num = ll_ref_order_abc_item;
      WHEN 'CHEVRON' THEN
	SELECT t.ch_length, t.ch_width
	  INTO ln_length, ln_width
	  FROM chevron t
	 WHERE t.order_abc_num = ll_ref_order_abc_num
	   AND t.order_item_num = ll_ref_order_abc_item;
      WHEN 'CIRCLE' THEN
	SELECT t.c_diameter, t.c_diameter
	  INTO ln_length, ln_width
	  FROM circle t
	 WHERE t.order_abc_num = ll_ref_order_abc_num
	   AND t.order_item_num = ll_ref_order_abc_item;
      WHEN 'TRAPEZOID' THEN
	SELECT t.tr_long_length, t.tr_width
	  INTO ln_length, ln_width
	  FROM trapezoid t
	 WHERE t.order_abc_num = ll_ref_order_abc_num
	   AND t.order_item_num = ll_ref_order_abc_item;
      WHEN 'L.TRAPEZOID' THEN
	SELECT t.ltr_long_length, t.ltr_width
	  INTO ln_length, ln_width
	  FROM left_trapezoid t
	 WHERE t.order_abc_num = ll_ref_order_abc_num
	   AND t.order_item_num = ll_ref_order_abc_item;
      WHEN 'R.TRAPEZOID' THEN
	SELECT t.rtr_long_length, t.rtr_width
	  INTO ln_length, ln_width
	  FROM right_trapezoid t
	 WHERE t.order_abc_num = ll_ref_order_abc_num
	   AND t.order_item_num = ll_ref_order_abc_item;
      WHEN 'REINFORCEMENT' THEN
	SELECT t.re_length, t.re_width
	  INTO ln_length, ln_width
	  FROM reinforcement t
	 WHERE t.order_abc_num = ll_ref_order_abc_num
	   AND t.order_item_num = ll_ref_order_abc_item;
      WHEN 'LIFTGATE' THEN
	SELECT t.li_length, t.li_width
	  INTO ln_length, ln_width
	  FROM liftgate_shape t
	 WHERE t.order_abc_num = ll_ref_order_abc_num
	   AND t.order_item_num = ll_ref_order_abc_item;
      ELSE
	SELECT t.x_1, t.x_2
	  INTO ln_length, ln_width
	  FROM x1_shape t
	 WHERE t.order_abc_num = ll_ref_order_abc_num
	   AND t.order_item_num = ll_ref_order_abc_item;
    END CASE;

    x12_table(i) := 'MEA*PD*WD*' || TRIM(to_char(ln_width, '99999.99')) ||
		    '*ED';
    i := i + 1;

    x12_table(i) := 'MEA*PD*WD*' ||
		    TRIM(to_char(ln_width * 25.4, '99999.99')) || '*MB';
    i := i + 1;

    x12_table(i) := 'MEA*CT*LN*' || TRIM(to_char(ln_length, '99999.99')) ||
		    '*ED';
    i := i + 1;

    x12_table(i) := 'MEA*PD*LN*' ||
		    TRIM(to_char(ln_length * 25.4, '99999.99')) || '*MB'; -- Linear MillMeter
    i := i + 1;

   x12_table(i) := 'MEA*CT*NL*' || to_char(item_rec.prod_item_pieces) ||
		    '*PC';
    i := i + 1;

    x12_table(i) := 'MEA*WT*WT*' || to_char(item_rec.prod_item_pieces * lr_theo_unit_wt, '99999') ||
		    '*24';
    i := i + 1;

    x12_table(i) := 'MEA*WT*WT*' || to_char(item_rec.prod_item_pieces * lr_theo_unit_wt * 0.4536, '99999') || '*53';
    i := i + 1;

    x12_table(i) := 'MEA*WT*WT*' || to_char(item_rec.prod_item_net_wt) ||
		    '*01';
    i := i + 1;

    x12_table(i) := 'MEA*WT*WT*' ||
		    to_char(item_rec.prod_item_net_wt * 0.4536, '99999') || '*50';
    i := i + 1;



 --	  x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||'*LB*01';
 --	  i := i + 1;
 --	  x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) || '*PC';
--	  i := i + 1;
	item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, job_status
     INTO ld_scrap_870_date, li_scrap_job_done
     FROM ab_job
     WHERE ab_job_num = ll_cur_job;

     IF (ld_scrap_870_date is NULL) AND (li_scrap_job_done = 0) THEN  -- scrap not sent and job is done

      FOR scrap_rec IN aleris_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT coil_org_num, lot_num
	INTO ls_coil_org_num, ls_heat
	FROM coil
	WHERE coil_abc_num = scrap_rec.coil_abc_num;

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = ll_cur_job) and
	       (production_sheet_item.coil_abc_num = scrap_rec.coil_abc_num);


		ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*F';
		   i := i + 1;

		   x12_table(i) := 'PRF*' || ls_enduser_po || '***' || ls_today;
		   i := i +1;

		    x12_table(i) := 'PO1**1*UN***VO*' || ls_enduser_po ||
			  '*SN*' || ls_coil_org_num || '*HN*' || ls_heat || '***BP* ';
		     i := i + 1;

		    x12_table(i) := 'PID*S*MAC*ST*05***67';
		    i := i + 1;
		    x12_table(i) := 'PID*S*DAF*ST*3***72';
		     i := i + 1;
		    x12_table(i) := 'PID*S*DAC*ST*258***73';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*WT*' || to_char(ll_scrap_nw) || '*01';
		   i := i+1;
		   x12_table(i) := 'MEA*WT*WT*' || to_char(ll_scrap_nw * 0.4536, '99999') || '*50';
		   i := i+1;
		 END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent


     END LOOP;	 -- job loop

      x12_table(i) := 'CTT*' || to_char(li_hl01);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--	  edi_file	  := 's_aleris_' || to_char(ll_edi_file_id_aleris) ||
--			     '.870';
	 edi_file	 := edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

     --edi_file        := 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
      --  COMMIT;


 -- Release this commented section
 --    1. when testing the update portion of this stored procedure, or
 --    2. before releasing the SP to PROD.
 -- Patrick Reynolds May 23, 2016

     FOR m IN 0 .. k - 1 LOOP
       UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
	WHERE production_sheet_item.prod_item_num = item_num(m);
     END LOOP;

--	COMMIT;

       FOR m in 0..p - 1
	   LOOP
	       UPDATE ab_job set ab_job.scrap_870_date = sysdate
	       WHERE ab_job.ab_job_num = job_num(m);
	    END LOOP;

      commit;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ARCONIC_861_TEST"
(  as_bol	     in  inbound_shipment.bol%TYPE,
   ai_edi_file_id    in  inbound_shipment.edi_file_id%TYPE
)

IS

  /*
  This function creates Arconic EDI 861.
  edi_file_id and bol are from inbound_shipment table, received_time is generated the current moment by the system.
  This function will be called from Coil Receiving after a successful saving
  */

  type edi_861_tabletype is
     table of varchar2(32767) index by binary_integer;

  edi_861    edi_861_tabletype;
  j	     binary_integer;
  i	     integer;
  --skip_edi INTEGER := 1;

  --edi_file_prefix VARCHAR2(50) := 'S_arconic_861_'; --Production
  edi_file_prefix VARCHAR2(50) := 's_arconic_861_'; --Development

/*
  CURSOR shipment_cursor IS
    SELECT ss.bol, ss.edi_file_id
      FROM inbound_shipment_status   ss,
	   inbound_shipment	     s,
	   inbound_shipment_customer c
     WHERE ss.edi_file_id = s.edi_file_id
       AND ss.bol = s.bol
       AND s.ship_from = c.ship_from
       and s.bol = as_bol
       AND c.customer_id IN (2784) --ARCONIC-TN
       AND -- customers for 861
	   ss.status = 3;
*/

  /*cursor shipment_cursor is
  select bol, edi_file_id
  from inbound_shipment_status
  where status = 3 ;*/

  CURSOR coil_status_cursor(as_bol VARCHAR2) IS
    SELECT distinct status
      FROM inbound_coil_status
     WHERE bol = as_bol
     and edi_file_id = ai_edi_file_id;

  CURSOR bol_and_edi_file_id_cursor IS
    SELECT distinct
	   a.coil_number,
	   a.temper,
	   a.net_weight,
	   a.gross_weight,
	   a.lineal_feed,
	   a.coil_width,
	   a.coil_gauge,
	   a.density,
	   a.lot,
	   a.pack_id,
	   a.alloy,
	   a.ps_coil_number,
	   b.damaged_code,
	   b.damaged_fault
      FROM inbound_coil a, inbound_coil_status b
     WHERE a.bol = b.bol
       and a.edi_file_id = b.edi_file_id
       AND a.item_num = b.item_num
       and a.bol = as_bol
       AND a.edi_file_id = ai_edi_file_id ;

  li_coil_ready  INTEGER;
  li_gs_log	 INTEGER;
  li_st_log	 INTEGER;
  ls_today_short VARCHAR2(20);
  ls_today	 VARCHAR2(20);
  ls_now	 VARCHAR2(20);

  ld_received_time  DATE;
  ls_received_time  VARCHAR2(13);
  li_customer_id    INT;
  ls_vo 	    VARCHAR2(20);
  ls_coil_number    VARCHAR2(40);
  ls_ps_coil_number VARCHAR2(40);
  ls_temper	    VARCHAR2(8);
  ln_net_weight     NUMBER(8, 0);
  ln_gross_weight   NUMBER(8, 0);
  ln_lineal_feed    NUMBER(7, 2);
  ln_coil_width     NUMBER(7, 2);
  ln_coil_gauge     NUMBER(5, 4);
  ln_density	    NUMBER;
  ls_lot	    VARCHAR2(40);
  ls_pack_id	    VARCHAR2(40);
  ls_alloy	    VARCHAR2(40);
  ln_damage_fault   NUMBER(1);
  ln_damage_code    NUMBER(3);

  edi_location	  VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_handle utl_file.file_type;
  li_edi_861_id   INTEGER;
  ls_dun	  VARCHAR2(32);
  ls_ship_from	  VARCHAR2(40);

  coil_count INTEGER;

  li_coil_abc_num INTEGER;

  li_count INTEGER;

  ls_received_date  VARCHAR2(8);
  li_inbound_shipment_status  inbound_shipment_status.status%TYPE;


BEGIN

/*
    select    status
    into      li_inbound_shipment_status
    from      inbound_shipment_status
    where     bol = as_bol
    and       edi_file_id = ai_edi_file_id;

    if li_inbound_shipment_status = 1 then --861 already created
      return 1;
    end if;
*/

    li_coil_ready := 0;

    --if not all coils are imported or mark damaged yet, don't send them
    FOR coil_status_cloop IN coil_status_cursor(as_bol) loop
						--shipment_cloop.edi_file_id) LOOP
      IF (coil_status_cloop.status = 1 OR coil_status_cloop.status = 2) THEN
	--status 1:imported  2:marked damaged
	li_coil_ready := 1;
      ELSE
	li_coil_ready := 0;
      END IF;
      EXIT WHEN li_coil_ready = 0;
    END LOOP;

    coil_count := 0;
    j	       := 0;

    IF (li_coil_ready = 1) THEN
      SELECT edi_st_log_seq.nextval INTO li_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO li_gs_log FROM dual;
      ls_today_short := to_char(SYSDATE, 'yymmdd');
      ls_today	     := to_char(SYSDATE, 'yyyymmdd');
      ls_now	     := to_char(SYSDATE, 'hh24mi');

      SELECT distinct vo
	INTO ls_vo
	FROM inbound_shipment
       WHERE bol = as_bol;
	 --AND edi_file_id = shipment_cloop.edi_file_id;

      /*ld_received_time := sysdate;   --set the received time as current system time*/
      SELECT COUNT(*)
	INTO li_count
	FROM receiving_bol r
       WHERE r.bol = as_bol;

      IF li_count = 1 THEN
	SELECT distinct nvl(r.created_date, sysdate)
	  INTO ld_received_time
	  FROM receiving_bol r
	 WHERE r.bol = as_bol;
      ELSE
	ld_received_time := SYSDATE;
      END IF;

      SELECT distinct ship_from
	INTO ls_ship_from
	FROM inbound_shipment
       WHERE bol = as_bol;

      SELECT distinct customer_id
	INTO li_customer_id
	FROM inbound_shipment_customer
       WHERE ship_from = ls_ship_from;

      SELECT customer.customer_duns_number_string
	INTO ls_dun
	FROM customer
       WHERE customer.customer_id = li_customer_id;

      ls_received_time := to_char(ld_received_time, 'yyyymmdd*hh24mi'); --need this format in EDI861 file

      --Production
      --edi_861(j) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*' || rpad(ls_dun, 15, ' ') || '*' ||
      --		ls_received_time || '*U*00401*' ||
      --		lpad(to_char(li_gs_log), 9, '0') || '*0*P*>';

      --Development
      edi_861(j) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*ARNCQFMW	     *' ||
		      ls_received_time || '*U*00401*' ||
		      lpad(to_char(li_gs_log), 9, '0') || '*0*T*>';

      j := j + 1;

      --Production
      --edi_861(j) := 'GS*SH*R0P7A' || 'TN*961613887' || '*' || ls_today || '*' ||
      --		ls_now || '*' || to_char(ll_gs_log) || '*X*' || '004010';

      --Development
      edi_861(j) := 'GS*SH*2NDSFTP' || 'TN*ARNCQFMW' || '*' || ls_today || '*' ||
		     ls_now || '*' || to_char(li_gs_log) || '*X*' || '004010';
      j := j + 1;

      edi_861(j) := 'ST*861*' || li_st_log;
      j := j + 1;

      edi_861(j) := 'BRA*' || as_bol || '*' || ls_today ||
		    '*00*1*' || ls_now;
      j := j + 1;

      edi_861(j) := 'REF*MA*' || as_bol;
      j := j + 1;

      edi_861(j) := 'DTM*050*' || ls_received_time || '*ED';
      j := j + 1;

/*
      SELECT distinct ship_from
	INTO ls_ship_from
	FROM inbound_shipment
       WHERE bol = as_bol;

      SELECT distinct customer_id
	INTO li_customer_id
	FROM inbound_shipment_customer
       WHERE ship_from = ls_ship_from;

      SELECT customer.customer_duns_number_string
	INTO ls_dun
	FROM customer
       WHERE customer.customer_id = li_customer_id;
*/

      edi_861(j) := 'N1*MF**1*' || ls_dun; --Arconic DUNS
      j := j + 1;

      edi_861(j) := 'N1*OU**1*039630926'; --ALBL DUNS
      j := j + 1;

      /*if li_customer_id = 1153 then
	 ls_dun := '241003755';--'Novelis Kingston'
      elsif  li_customer_id = 1459 then
	 ls_dun := '003980216';--'Novelis Oswego'
      else
	 ls_dun := '241003755';
      end if;*/

      edi_861(j) := 'N1*SU**1*' || ls_dun;
      j := j + 1;

      FOR cloop IN bol_and_edi_file_id_cursor() LOOP
	ls_coil_number	  := cloop.coil_number;
	ls_temper	  := cloop.temper;
	ln_net_weight	  := cloop.net_weight;
	ln_gross_weight   := cloop.gross_weight;
	ln_lineal_feed	  := cloop.lineal_feed;
	ln_coil_width	  := cloop.coil_width;
	ln_coil_gauge	  := cloop.coil_gauge;
	ln_density	  := cloop.density;
	ls_lot		  := cloop.lot;
	ls_pack_id	  := cloop.pack_id;
	ls_alloy	  := cloop.alloy;
	ls_ps_coil_number := cloop.ps_coil_number;
	ln_damage_fault   := cloop.damaged_fault;
	ln_damage_code	  := cloop.damaged_code;

	IF (ls_ps_coil_number IS NULL) OR (length(ls_ps_coil_number) = 0) THEN
	  ls_ps_coil_number := ls_coil_number;
	END IF;

	edi_861(j) := 'RCD**1*UN';
	j := j + 1;

	edi_861(j) := 'LIN**VO*' || ls_vo || '*VN*01' || '*SN*' || ls_coil_number ||
		      '*HN*' || ls_lot;
	j := j + 1;
	edi_861(j) := 'PID*S*MAC*ST*01***67';
	j := j + 1;

	edi_861(j) := 'PID*S*MA*ST*7***70';
	j := j + 1;


	--add these two segments only for damaged coils
/*
	IF ln_damage_code <> 0 THEN
	  edi_861(j) := 'PID*S*DAC*ST*' || ln_damage_code;
	  j := j + 1;
	END IF;
	IF ln_damage_fault <> 0 THEN
	  edi_861(j) := 'PID*S*DAF*ST*' || ln_damage_fault;
	  j := j + 1;
	END IF;

	edi_861(j) := 'PID*S*QAS*ST*2';
	j := j + 1;

*/
	SELECT COUNT(*)
	  INTO li_count
	  FROM coil c
	 WHERE c.coil_org_num = ls_coil_number
	   --AND c.coil_mid_num = ls_pack_id
	   AND c.customer_id IN (li_customer_id);

	IF li_count = 1 THEN
	  SELECT nvl(c.coil_abc_num, 0)
	    INTO li_coil_abc_num
	    FROM coil c
	   WHERE c.coil_org_num = ls_coil_number
	     --AND c.coil_mid_num = ls_pack_id
	     AND c.customer_id IN (2784);
	ELSE
	  li_coil_abc_num := 0;
	END IF;

	edi_861(j) := 'REF*SE*' || li_coil_abc_num;
	j := j + 1;

	ls_received_date := to_char(ld_received_time, 'yyyymmdd');

	edi_861(j) := 'DTM*206*' || ls_received_date;
	j := j + 1;

	--edi_861(j) := 'REF*BM*' || shipment_cloop.bol;
	--j := j + 1;

	--edi_861(j) := 'REF*RV*' || ls_ps_coil_number;
	--j := j + 1;

	--edi_861(j) := 'PRF*' || ls_vo;
	--j := j + 1;

	edi_861(j) := 'MEA*WT**' || ln_net_weight || '*01';
	j := j + 1;

	edi_861(j) := 'MEA*WT**' || ln_gross_weight || '*24';
	j := j + 1;

	edi_861(j) := 'MEA*PD*TH*' || to_char(ln_coil_gauge, 'FM90.0000') || '*ED';
	j := j + 1;
	edi_861(j) := 'MEA*PD*WD*' || to_char(ln_coil_width, 'FM99990.0000') || '*ED';
	j := j + 1;

	edi_861(j) := 'MEA*PD*LN*' || ln_lineal_feed || '*LF';
	j := j + 1;

	coil_count := coil_count + 1;
      END LOOP;

      edi_861(j) := 'CTT*' || coil_count;
      j := j + 1;
      edi_861(j) := 'SE*' || to_char(j - 1) || '*' || li_st_log;
      j := j + 1;
      edi_861(j) := 'GE*1*' || li_gs_log;
      j := j + 1;
      edi_861(j) := 'IEA*1*' || lpad(to_char(li_gs_log), 9, '0');

      IF coil_count > 0 THEN
	--IF skip_edi = 0 THEN
	  SELECT edi_file_id_seq.nextval INTO li_edi_861_id FROM dual;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--	    edi_file	    := 's_Novelis_' || to_char(li_edi_861_id) || '.861';
	  edi_file	  := edi_file_prefix || to_char(li_edi_861_id) || '.edi';
	  edi_file_handle := utl_file.fopen(edi_location, edi_file, 'W');
	  --write edi to file
	  FOR i IN 0 .. j LOOP
	    utl_file.put_line(edi_file_handle, edi_861(i));
	  END LOOP;
	  utl_file.fclose(edi_file_handle);
	--END IF;

	/*--added by Victor Huang on 06/05 for function acknowlegement
	 INSERT INTO edi_fa(gs_num, duns_num, send_time,edi_file_name)
	 VALUES(li_gs_log, ls_dun, sysdate, edi_file);
	 COMMIT;
	*/
	--added by Victor Huang on 12/07 for verifying 997
/*
	INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (li_edi_861_id,
	   '039630926',
	   ls_dun,
	   li_gs_log,
	   li_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   li_customer_id,
	   li_st_log,
	   '861');
	--COMMIT;
*/

	edi_file	:= 'send_edi_log';
	edi_file_handle := utl_file.fopen(edi_location, edi_file, 'a');
	utl_file.put_line(edi_file_handle, 'Type: 861');
	utl_file.put_line(edi_file_handle,
			  'Sending Time: ' ||
			  to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
	utl_file.put_line(edi_file_handle,
			  'Interchange Control #: ' || li_gs_log);
	utl_file.put_line(edi_file_handle,
			  'Group Control #: ' || li_gs_log);
	utl_file.put_line(edi_file_handle, 'Set Control #: ' || li_st_log);
	utl_file.put_line(edi_file_handle, '');
	utl_file.put_line(edi_file_handle, '');
	utl_file.fclose(edi_file_handle);

/*
	UPDATE inbound_shipment_status
	   SET status = 1
	 WHERE bol = as_bol
	   AND edi_file_id = ai_edi_file_id;

	COMMIT;
*/

      END IF;
    END IF;
  --END LOOP; --loop end for edi_file_id/bol

  return;

EXCEPTION
  WHEN dup_val_on_index THEN
    ROLLBACK;
    RETURN;
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;

END edi_arconic_861_test;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ARCONIC_870" (al_ab_job_num ab_job.ab_job_num%TYPE)

IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';

  --edi_file_prefix VARCHAR2(50) := 'S_arconic_870_'; --Production
  edi_file_prefix VARCHAR2(50) := 's_arconic_870_'; --Development

  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;
  ls_today_2digits_year VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers

  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    --( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID in (2784) ) AND
    --( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    --( C.SCRAP_870_DATE is NULL ) AND
    --( SK.SKID_SHEET_STATUS in (0,2,4,12,13) );
    ( ab.ab_job_num = al_ab_job_num );

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     --WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
     --  AND (production_sheet_item.prod_item_edi870_date IS NULL)
     where (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id in (2784))
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = 215802)
       and ( ab_job.ab_job_num = al_ab_job_num );


       CURSOR alcan_scrap_870_cur IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = 215802)
	 AND (a.coil_abc_num = b.coil_abc_num);
	 --AND (a.scrap_870_date is NULL);

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;
    p		   := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 --(  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID in (2784) ) AND
	 --( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 --( COIL.SCRAP_870_DATE is NULL ) AND
	 --( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13) );
	 ( ab_job.ab_job_num = al_ab_job_num );

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      --Production
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*961613887      *' ||
      --		ls_today_2digits_year || '*' || ls_now || '*U*00401*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P*>';

      --Development
      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*ARNCQFMW	     *' ||
		      ls_today_2digits_year || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*T*>';

      i := i + 1;

      --Production
      --x12_table(1) := 'GS*SH*R0P7A' || 'TN*961613887' || '*' || ls_today || '*' ||
      --		ls_now || '*' || to_char(ll_gs_log) || '*X*' || '004010';

      --Development
      x12_table(1) := 'GS*SH*2NDSFTP' || 'TN*ARNCQFMW' || '*' || ls_today || '*' ||
		     ls_now || '*' || to_char(ll_gs_log) || '*X*' || '004010';

      i := i + 1;

      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;

	  coil_num(p) := ll_cur_coil;
	  p := p + 1;


	FOR item_rec IN alcan_870_cur LOOP   -- item loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	  SELECT nvl(customer_order.orig_customer_po, 'NA'),
		 nvl(order_item.cust_prod_line_id, 'NA'),
		 nvl(order_item.finished_goods_material_num, 'NA')
	  INTO ls_po, ls_cust_prod_line, ls_finished_goods
	  FROM	 order_item,
		 ab_job,
		 customer_order
	 WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	 AND (ab_job.order_abc_num = order_item.order_abc_num)
	 AND (ab_job.order_item_num = order_item.order_item_num)
	  AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     ld_scrap_870_date := null; --Alex Gerlants. 01/12/2019. Added to get through

     IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

      FOR scrap_rec IN alcan_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


	  ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



	  IF ll_scrap_nw > 0 then

	     li_hl01 := li_hl01 + 1;

	     x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
	     i := i + 1;

	     IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		i := i + 1;
	     END IF;

	     x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	      i := i + 1;

	      x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
	      i := i + 1;

	      x12_table(i) := 'PID*S*MA*ST*S';
	      i := i + 1;
	      x12_table(i) := 'PID*S*MAC*ST*05';
	       i := i + 1;
	      x12_table(i) := 'PID*S*PR*ST*19';
	       i := i + 1;

	     x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
	     i := i+1;
	   END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent
     END LOOP;	 -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id_aleris) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
--	   COMMIT;

     FOR m IN 0 .. k - 1 LOOP
       UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
	 WHERE production_sheet_item.prod_item_num = item_num(m);
     END LOOP;

--	COMMIT;


	FOR m in 0..p - 1 LOOP
		UPDATE coil
					SET coil.scrap_870_date = sysdate
		WHERE coil.coil_abc_num = coil_num(m);

	       UPDATE process_coil
					SET scrap_870_date = sysdate
		WHERE ( coil_abc_num = coil_num(m)) AND (scrap_870_date is NULL);

	 END LOOP;


	COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ARCONIC_870_04302019" (al_ab_job_num ab_job.ab_job_num%TYPE)

IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';

  --edi_file_prefix VARCHAR2(50) := 'S_arconic_870_'; --Production
  edi_file_prefix VARCHAR2(50) := 's_arconic_870_'; --Development

  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;
  ls_today_2digits_year VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers

  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    --( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID in (2784) ) AND
    --( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    --( C.SCRAP_870_DATE is NULL ) AND
    --( SK.SKID_SHEET_STATUS in (0,2,4,12,13) );
    ( ab.ab_job_num = al_ab_job_num );

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     --WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
     --  AND (production_sheet_item.prod_item_edi870_date IS NULL)
     where (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id in (2784))
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = 215802)
       and ( ab_job.ab_job_num = al_ab_job_num );


       CURSOR alcan_scrap_870_cur IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = 215802)
	 AND (a.coil_abc_num = b.coil_abc_num);
	 --AND (a.scrap_870_date is NULL);

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;
    p		   := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 --(  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID in (2784) ) AND
	 --( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 --( COIL.SCRAP_870_DATE is NULL ) AND
	 --( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13) );
	 ( ab_job.ab_job_num = al_ab_job_num );

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      --Production
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*961613887      *' ||
      --		ls_today_2digits_year || '*' || ls_now || '*U*00401*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P*>';

      --Development
      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*ARNCQFMW	     *' ||
		      ls_today_2digits_year || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*T*>';

      i := i + 1;

      --Production
      --x12_table(1) := 'GS*SH*R0P7A' || 'TN*961613887' || '*' || ls_today || '*' ||
      --		ls_now || '*' || to_char(ll_gs_log) || '*X*' || '004010';

      --Development
      x12_table(1) := 'GS*SH*2NDSFTP' || 'TN*ARNCQFMW' || '*' || ls_today || '*' ||
		     ls_now || '*' || to_char(ll_gs_log) || '*X*' || '004010';

      i := i + 1;

      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;

	  coil_num(p) := ll_cur_coil;
	  p := p + 1;


	FOR item_rec IN alcan_870_cur LOOP   -- item loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	  SELECT nvl(customer_order.orig_customer_po, 'NA'),
		 nvl(order_item.cust_prod_line_id, 'NA'),
		 nvl(order_item.finished_goods_material_num, 'NA')
	  INTO ls_po, ls_cust_prod_line, ls_finished_goods
	  FROM	 order_item,
		 ab_job,
		 customer_order
	 WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	 AND (ab_job.order_abc_num = order_item.order_abc_num)
	 AND (ab_job.order_item_num = order_item.order_item_num)
	  AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     ld_scrap_870_date := null; --Alex Gerlants. 01/12/2019. Added to get through

     IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

      FOR scrap_rec IN alcan_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


	  ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



	  IF ll_scrap_nw > 0 then

	     li_hl01 := li_hl01 + 1;

	     x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
	     i := i + 1;

	     IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		i := i + 1;
	     END IF;

	     x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	      i := i + 1;

	      x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
	      i := i + 1;

	      x12_table(i) := 'PID*S*MA*ST*S';
	      i := i + 1;
	      x12_table(i) := 'PID*S*MAC*ST*05';
	       i := i + 1;
	      x12_table(i) := 'PID*S*PR*ST*19';
	       i := i + 1;

	     x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
	     i := i+1;
	   END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent
     END LOOP;	 -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id_aleris) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
--	   COMMIT;

     FOR m IN 0 .. k - 1 LOOP
       UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
	 WHERE production_sheet_item.prod_item_num = item_num(m);
     END LOOP;

--	COMMIT;


	FOR m in 0..p - 1 LOOP
		UPDATE coil
					SET coil.scrap_870_date = sysdate
		WHERE coil.coil_abc_num = coil_num(m);

	       UPDATE process_coil
					SET scrap_870_date = sysdate
		WHERE ( coil_abc_num = coil_num(m)) AND (scrap_870_date is NULL);

	 END LOOP;


	COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ARCONIC_870_ALEX" IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/19/2018. Initial release
  --Copied from edi_alcan_870
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  --edi_file_prefix VARCHAR2(50) := 'S_arconic_870_';
  edi_file_prefix VARCHAR2(50) := 's_arconic_870_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  --ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  CURSOR cust_cur IS
    --SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers
    select customer_id from customer where lower(customer_short_name) like'%arconic%';

  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    ( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID = ll_customer_id ) AND
    ( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    ( C.SCRAP_870_DATE is NULL ) AND
    ( SK.SKID_SHEET_STATUS in (0,2,4,12,13)
    and (c.coil_abc_num = 103546) --Testing
    );

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = ll_cur_coil);

       CURSOR alcan_scrap_870_cur IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = ll_cur_coil)
	 AND (a.coil_abc_num = b.coil_abc_num)
	 AND (a.scrap_870_date is NULL);

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;
    p		   := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 ( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 ( COIL.SCRAP_870_DATE is NULL ) AND
	 ( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13)
	 and (coil.coil_abc_num = 103546) --Testing
	 );

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      --Original code
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*0015049350011G *' ||
      --		ls_today_4 || '*' || ls_now || '*U*00401*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';


      --Production
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *ZZ*ARNCQFMW      *' ||
      --		ls_today || '*' || ls_now || '*U*00200*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';

      --Development
      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*ARNCQFMW	    *' ||
		      ls_today || '*' || ls_now || '*U*00200*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*T**';

      i := i + 1;

      --Original code
      --x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
      --		ls_today || '*' || ls_now || '*' ||
      --		to_char(ll_gs_log) || '*X*' || '004010';


      --Production
      --x12_table(1) := 'GS*RC*039630926TTN*' || 'ARNCQFMW' || '*' || ls_today || '*' ||
      --		ls_now || '*' || to_char(ll_gs_log) || '*X*' || '002002';

      --Development
      x12_table(1) := 'GS*RC*2NDSFTPTN*' || 'ARNCQFMW' || '*' || ls_today || '*' ||
		      ls_now || '*' || to_char(ll_gs_log) || '*X*' || '002002';

      i := i + 1;

      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;

	  coil_num(p) := ll_cur_coil;
	  p := p + 1;


	FOR item_rec IN alcan_870_cur LOOP   -- item loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
		     ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	     AND (ab_job.order_abc_num = order_item.order_abc_num)
	     AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

      FOR scrap_rec IN alcan_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


		ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   END IF;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent
     END LOOP;	 -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
      /* Alex Gerlants. Commented out for testing. Begin

      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');


     FOR m IN 0 .. k - 1 LOOP
       UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id
	 WHERE production_sheet_item.prod_item_num = item_num(m);
     END LOOP;


     FOR m in 0..p - 1 LOOP
		UPDATE coil
					SET coil.scrap_870_date = sysdate
		WHERE coil.coil_abc_num = coil_num(m);

	       UPDATE process_coil
					SET scrap_870_date = sysdate
		WHERE ( coil_abc_num = coil_num(m)) AND (scrap_870_date is NULL);

      END LOOP;

      COMMIT;
      */ -- Alex Gerlants. Commented out for testing. End

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ARCONIC_870_ONE_JOB" IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 's_arconic_870_one_job_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  ls_today_2digits_year VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (2784); ---Add customer id here if you want to send 870 for more customers

  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    --( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID in (2784) ) AND
    --( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    --( C.SCRAP_870_DATE is NULL ) AND
    --( SK.SKID_SHEET_STATUS in (0,2,4,12,13) );
    ( ab.ab_job_num = 105938 );

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     --WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
     --  AND (production_sheet_item.prod_item_edi870_date IS NULL)
     where (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id in (2784))
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       --AND (production_sheet_item.coil_abc_num = 215802)
       and ( ab_job.ab_job_num = 105938 );


       CURSOR alcan_scrap_870_cur IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = ll_cur_coil)
	 AND (a.coil_abc_num = b.coil_abc_num);
	 --AND (a.scrap_870_date is NULL);

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;
    p		   := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 --(  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID in (2784) ) AND
	 --( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 --( COIL.SCRAP_870_DATE is NULL ) AND
	 --( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13) );
	 ( ab_job.ab_job_num = 105938 );

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

       --Production
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*961613887      *' ||
      --		ls_today_2digits_year || '*' || ls_now || '*U*00401*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P*>';

      --Development
      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*ARNCQFMW	     *' ||
		      ls_today_2digits_year || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*T*>';

      i := i + 1;

      --Alex Gerlants. 10/16/2018. Changed from "002002" to "004010"
      --Production
      --x12_table(1) := 'GS*SH*R0P7A' || 'TN*961613887' || '*' || ls_today || '*' ||
      --		ls_now || '*' || to_char(ll_gs_log) || '*X*' || '004010';

      --Development
      x12_table(1) := 'GS*SH*2NDSFTP' || 'TN*ARNCQFMW' || '*' || ls_today || '*' ||
		     ls_now || '*' || to_char(ll_gs_log) || '*X*' || '004010';

      i := i + 1;

      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;

	  coil_num(p) := ll_cur_coil;
	  p := p + 1;


	FOR item_rec IN alcan_870_cur LOOP   -- item loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
		     ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	     AND (ab_job.order_abc_num = order_item.order_abc_num)
	     AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     ld_scrap_870_date := null; --Alex Gerlants. 01/12/2019. Added to get through

     IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

      FOR scrap_rec IN alcan_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


		ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   END IF;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent
     END LOOP;	 -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id_aleris) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
/*
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
*/
--	   COMMIT;

     --FOR m IN 0 .. k - 1 LOOP
     --  UPDATE production_sheet_item
     --      SET prod_item_edi870_date = SYSDATE,
     -- 	 edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
     --    WHERE production_sheet_item.prod_item_num = item_num(m);
     --END LOOP;

--	COMMIT;

	/*
	FOR m in 0..p - 1 LOOP
		UPDATE coil
					SET coil.scrap_870_date = sysdate
		WHERE coil.coil_abc_num = coil_num(m);

	       UPDATE process_coil
					SET scrap_870_date = sysdate
		WHERE ( coil_abc_num = coil_num(m)) AND (scrap_870_date is NULL);

	 END LOOP;
	 */

	COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ARCONIC_870_REBAND" (al_ab_job_num ab_job.ab_job_num%TYPE)

IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   */



  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := dbo.get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;
  ld_job_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;
   ls_scrap_coil_org_num coil.coil_org_num%TYPE;

  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_start_nw coil.net_wt%TYPE;
  ll_scrap_end_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
  ll_process_quantity  coil.net_wt%TYPE;
  ll_process_end_wt  coil.net_wt%TYPE;
  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;
  ls_today_2digits_year VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (1153,1459,2582); ---Add customer id here if you want to send 870 for more customers

  CURSOR coil_cur IS
  SELECT UNIQUE COIL.COIL_ABC_NUM, AB_JOB.AB_JOB_NUM
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER,
	 PROCESS_COIL
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( COIL.COIL_ABC_NUM = PROCESS_COIL.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = PROCESS_COIL.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS = 7 ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 ( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 ( PROCESS_COIL.SCRAP_870_DATE is NULL ) AND
	 ( COIL.SCRAP_870_DATE is NULL ) AND
	 ( SHEET_SKID.SKID_SHEET_STATUS in (2,4,12,13) );

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num =
	   production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
 		   AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
		   AND (ab_job.order_abc_num = order_item.order_abc_num)
		   AND (ab_job.order_item_num = order_item.order_item_num)
      AND (production_sheet_item.coil_abc_num = ll_cur_coil)
      AND (production_sheet_item.ab_job_num = ll_cur_job);


  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;


BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER,
	 PROCESS_COIL
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( COIL.COIL_ABC_NUM = PROCESS_COIL.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = PROCESS_COIL.AB_JOB_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS = 7 ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 ( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 ( PROCESS_COIL.SCRAP_870_DATE is NULL ) AND
	 ( COIL.SCRAP_870_DATE is NULL ) AND
	 ( SHEET_SKID.SKID_SHEET_STATUS in (2,4,12,13) );

    IF (ll_item_count <> 0) THEN


      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      --Production
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*961613887      *' ||
      --		ls_today_2digits_year || '*' || ls_now || '*U*00401*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P*>';

      --Development
      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*ARNCQFMW	     *' ||
		      ls_today_2digits_year || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*T*>';

      i := i + 1;

      --Production
      --x12_table(1) := 'GS*SH*R0P7A' || 'TN*961613887' || '*' || ls_today || '*' ||
      --		ls_now || '*' || to_char(ll_gs_log) || '*X*' || '004010';

      --Development
      x12_table(1) := 'GS*SH*2NDSFTP' || 'TN*ARNCQFMW' || '*' || ls_today || '*' ||
		     ls_now || '*' || to_char(ll_gs_log) || '*X*' || '004010';

      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;
	  ll_cur_job := coil_rec.ab_job_num;



	FOR item_rec IN alcan_870_cur LOOP   -- item loop


	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
				       ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
			 AND (ab_job.order_abc_num = order_item.order_abc_num)
			 AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = ll_cur_job);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop


     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     SELECT scrap_870_date
     INTO ld_job_scrap_870_date
     FROM process_coil
     WHERE (coil_abc_num = ll_cur_coil) AND (ab_job_num = ll_cur_job);

     IF (ld_scrap_870_date is NULL) AND (ld_job_scrap_870_date is NULL) THEN  -- scrap not sent

	     SELECT b.coil_org_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
	   INTO ls_scrap_coil_org_num, ll_scrap_start_nw, ll_scrap_end_nw
	   FROM process_coil a, coil b
	   WHERE (b.coil_abc_num = ll_cur_coil)
	   AND (a.coil_abc_num = b.coil_abc_num)
	    AND (a.ab_job_num = ll_cur_job);

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = ll_cur_job) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


		ll_scrap_nw := ll_scrap_start_nw - ll_scrap_end_nw - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   END IF;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || ls_scrap_coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 END IF;

       END IF;	-- scrap not sent
     END LOOP;	 -- coil loop

      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= 'S_alcan_' || to_char(ll_edi_file_id_aleris) ||
			   '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE


      --For verifying 997
      /*INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
	COMMIT;
      */
      edi_file	      := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      FOR coil_rec IN coil_cur LOOP    -- coil loop date
	  UPDATE process_coil set scrap_870_date = sysdate
	  WHERE (coil_abc_num = coil_rec.coil_abc_num) AND (ab_job_num = coil_rec.ab_job_num);
     END LOOP;	 -- coil loop date

     commit;

     FOR m IN 0 .. k - 1 LOOP
       UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
	 WHERE production_sheet_item.prod_item_num = item_num(m);
     END LOOP;

     COMMIT;


    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ARCONIC_870_TEST" (al_ab_job_num ab_job.ab_job_num%TYPE)
IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata/arconic_test'; --Development
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR'); --Production

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 's_arconic_870_';	--Development
  --edi_file_prefix VARCHAR2(50) := 'S_arconic_870_';	       --Production
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(20); /* Alex Gerlants. Changed from (10) to (20) */
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_lot_num coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  li_coil_status   coil.coil_status%TYPE; /* Alex Gerlants. New variable */
  ls_today_2digits_year VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (2784);

/*
  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
where ab.ab_job_num = al_ab_job_num;
*/

/*
  cursor coil_cur is
  select distinct  process_coil.coil_abc_num
  from	 process_coil
  where  ab_job_num = al_ab_job_num;
*/
    cursor coil_cur is
    select distinct coil.coil_abc_num
    FROM "COIL",
	 "PRODUCTION_SHEET_ITEM",
	 "SHEET_SKID",
	 "SHEET_SKID_DETAIL",
	 "PROCESS_COIL"
   WHERE ( "COIL"."COIL_ABC_NUM" = "PRODUCTION_SHEET_ITEM"."COIL_ABC_NUM" ) and
	 ( "SHEET_SKID_DETAIL"."SHEET_SKID_NUM" = "SHEET_SKID"."SHEET_SKID_NUM" ) and
	 ( "SHEET_SKID_DETAIL"."PROD_ITEM_NUM" = "PRODUCTION_SHEET_ITEM"."PROD_ITEM_NUM" ) and
	 ( "COIL"."COIL_ABC_NUM" = "PROCESS_COIL"."COIL_ABC_NUM" ) and
	 ( "PRODUCTION_SHEET_ITEM"."AB_JOB_NUM" = "PROCESS_COIL"."AB_JOB_NUM" ) and
	 ( ( "PRODUCTION_SHEET_ITEM"."AB_JOB_NUM" = al_ab_job_num ) );

--  WHERE (AB.JOB_STATUS = 0) AND
--    ( C.COIL_STATUS IN (0, 3, 7) ) AND /* Alex Gerlants. Added "7" for Rebanded */
--    ( CO.ORIG_CUSTOMER_ID = ll_customer_id ) AND
--    ( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
--    ( C.SCRAP_870_DATE is NULL ) AND
--    ( SK.SKID_SHEET_STATUS in (0,2,4,12,13) );

  CURSOR cur_870 IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
where	 (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (coil.customer_id = ll_customer_id)
       and (ab_job.ab_job_num = al_ab_job_num);
       --and (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)); -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold;

/*
     WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = ll_cur_coil);
*/

       CURSOR scrap_cur_870 IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      b.lot_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (a.coil_abc_num = b.coil_abc_num)
       and   (b.coil_abc_num = ll_cur_coil)
       --AND   (a.scrap_870_date is NULL)
       ;


  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  cur_870%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  --FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    --ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;
    p		   := 0;

  select   customer_order.orig_customer_id
  into	   ll_customer_id
  from	   ab_job
	   join customer_order on customer_order.order_abc_num = ab_job.order_abc_num
  where    ab_job.ab_job_num = al_ab_job_num;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 (ab_job.ab_job_num = al_ab_job_num);
	 --and ( AB_JOB.JOB_STATUS = 0 ) and
	 --(COIL.COIL_STATUS in (0, 3, 7)) and
	 --( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13) );
/*
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS in (0, 3, 7) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 ( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 ( COIL.SCRAP_870_DATE is NULL ) AND
	 ( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13) );
*/

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;


      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      --Production
      --x12_table(i) := 'ISA*00*' ||
      --		'	   *00* 	 *01*039630926T     *09*961613887      *' ||
      --		ls_today_2digits_year || '*' || ls_now || '*U*00401*' ||
      --		lpad(to_char(ll_gs_log), 9, '0') || '*0*P*>';

      --Development
      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *ZZ*2NDSFTP	  *ZZ*ARNCQFMW	     *' ||
		      ls_today_2digits_year || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*T*>';

      i := i + 1;

      --Alex Gerlants. 10/16/2018. Changed from "002002" to "004010"
      --Production
      --x12_table(1) := 'GS*SH*R0P7A' || 'TN*961613887' || '*' || ls_today || '*' ||
      --		ls_now || '*' || to_char(ll_gs_log) || '*X*' || '004010';

      --Development
      x12_table(1) := 'GS*SH*2NDSFTP' || 'TN*ARNCQFMW' || '*' || ls_today || '*' ||
		     ls_now || '*' || to_char(ll_gs_log) || '*X*' || '004010';

      i := i + 1;

      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      --FOR coil_rec IN coil_cur LOOP	 -- coil loop
      --    ll_cur_coil := coil_rec.coil_abc_num;
      --
      --    coil_num(p) := ll_cur_coil;
      --    p := p + 1;


	FOR item_rec IN cur_870 LOOP   -- item loop

	      ll_cur_coil := item_rec.coil_abc_num;

	      coil_num(p) := ll_cur_coil;
	      p := p + 1;

	      li_hl01 := li_hl01 + 1;

	      x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	      i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
		     ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	     AND (ab_job.order_abc_num = order_item.order_abc_num)
	     AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	--x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	--i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	--x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) || '*NA';
	--i := i + 1;

	--x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	--i := i + 1;

	--x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
	--		    item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP';
	i := i + 1;

	x12_table(i) := 'REF*BT*' || item_rec.lot_num;
	i := i + 1;

	select	coil.coil_status
	into	li_coil_status
	from	coil
	where	coil.coil_abc_num = ll_cur_coil;

	if li_coil_status = 7 then
	   x12_table(i) := 'PID*S*MA*AA*7*' ||
			    to_char(item_rec.sheet_skid_display_num);
	   i := i + 1;
	else

	  IF item_rec.skid_sheet_status = 2 THEN --Ready
	    x12_table(i) := 'PID*S*MA*AA*1*' ||
			    to_char(item_rec.sheet_skid_display_num);
	    i := i + 1;
	  ELSIF item_rec.skid_sheet_status = 4 THEN --Onhold
	    x12_table(i) := 'PID*S*MA*AA*3*' ||
			    to_char(item_rec.sheet_skid_display_num);
	    i := i + 1;
	  ELSIF item_rec.skid_sheet_status = 12 THEN --Sample. Added for Arconic
	    x12_table(i) := 'PID*S*MA*AA*SAMPLE*' ||
			    to_char(item_rec.sheet_skid_display_num);
	    i := i + 1;
	  ELSIF item_rec.skid_sheet_status = 13 THEN --Partial-Rd
	    x12_table(i) := 'PID*S*MA*AA*8*' ||
			    to_char(item_rec.sheet_skid_display_num);
	    i := i + 1;
	  ELSE
	    x12_table(i) := 'PID*S*MA*AA*4*' ||
			    to_char(item_rec.sheet_skid_display_num);
	    i := i + 1;
	  END IF;
	end if;

	--x12_table(i) := 'PID*S*MAC*AA*01';
	--i := i + 1;

	if li_coil_status = 7 then
	   x12_table(i) := 'PID*S*PR*AA*18';
	else
	   x12_table(i) := 'PID*S*PR*AA*19';
	end if;
	i := i + 1;

	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

      for coil_rec in coil_cur loop    --New coil loop for scrap
	  ll_cur_coil := coil_rec.coil_abc_num;

	       SELECT scrap_870_date, coil_org_num, lot_num
	       INTO ld_scrap_870_date, ls_coil_org_num, ls_lot_num
	       FROM coil
	       WHERE coil_abc_num = ll_cur_coil;

	       IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

		FOR scrap_rec IN scrap_cur_870 LOOP    -- scrap loop

		  --scrap info

		  SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
		  into ll_prime_nw
		   FROM production_sheet_item
		   WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
			 (production_sheet_item.coil_abc_num = ll_cur_coil);


			  ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



			  IF ll_scrap_nw > 0 then

			     li_hl01 := li_hl01 + 1;

			     x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
			     i := i + 1;

			     IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
				x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
				i := i + 1;
			     END IF;

			     x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
			      i := i + 1;

			      x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
			      i := i + 1;

			      x12_table(i) := 'REF*BT*' || scrap_rec.lot_num;
			      i := i + 1;

			      x12_table(i) := 'PID*S*MA*AA*S';
			      i := i + 1;
			      x12_table(i) := 'PID*S*MAC*AA*05';
			       i := i + 1;
			      x12_table(i) := 'PID*S*PR*AA*19';
			       i := i + 1;

			     x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
			     i := i+1;
			   END IF;

		      END LOOP;  -- scrap loop
		    END IF;  -- scrap not sent
      end loop; --New coil loop for scrap
     --END LOOP;   -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

/*
      insert into outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');

	for m in 0 .. k - 1 loop
	   update production_sheet_item
	   set	  prod_item_edi870_date = SYSDATE,
		  edi_file_id_870 = ll_edi_file_id
	   where  production_sheet_item.prod_item_num = item_num(m);
	end loop;

	for m in 0..p - 1 loop
	    select  coil.coil_status
	    into    li_coil_status
	    from    coil
	    where   coil.coil_abc_num = coil_num(m);

	    if li_coil_status <> 7 then
		update coil
		set    coil.scrap_870_date = sysdate
		where  coil.coil_abc_num = coil_num(m);
	    end if;

	    update process_coil
					  set	 scrap_870_date = sysdate
	    where  (coil_abc_num = coil_num(m)) and (scrap_870_date is null);

	  end loop;

	commit;
*/

    end if; --end if in select count(*)

    /* Alex Gerlants. 07/25/2017. Begin */
    --Check for rejected coils without sheets, just scrap,
    --and create 870 if these coils are found.
    --edi_alcan_870_rej_coils(ll_customer_id);
    /* Alex Gerlants. 07/25/2017. End */


  --END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."EDI_ARCONIC_870_TEST2" IS

  /*
  /*
   Aluminum Blanking: DUNS:039630926	 EDI ID:039630926T	  QUALIFIER: 01
   Customer: Aleris(1980) DUNS:964790856     EDI ID:964790856	   QUALIFIER: ZZ

   End User: Aleris, Customer ID 1980
   */

  --Alex Gerlants. 11/15/2016. Commented out, and added the line after.
  --edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_loc VARCHAR2(50) := get_edi_destination('EDI_DIR');

  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 's_arconic2_870_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  customer.customer_id%TYPE;
  ll_cur_coil	  coil.coil_abc_num%TYPE;

--  ll_cur_job ab_job.ab_job_num%TYPE;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI');

  ls_po VARCHAR2(20);
  ls_finished_goods VARCHAR2(32);
  ls_cust_prod_line VARCHAR2(8);

  ld_scrap_870_date ab_job.scrap_870_date%TYPE;

  ls_coil_org_num coil.coil_org_num%TYPE;
  ls_heat coil.lot_num%TYPE;

--  ll_ref_order_abc_num sheet_skid.ref_order_abc_num%TYPE;
--  ll_ref_order_abc_item sheet_skid.ref_order_abc_item%TYPE;
--  ls_sheet_type order_item.sheet_type%TYPE;

  ll_prime_nw coil.net_wt%TYPE;
  ll_scrap_nw coil.net_wt%TYPE;
--  ll_process_quantity  coil.net_wt%TYPE;
--  ll_process_end_wt  coil.net_wt%TYPE;
--  lr_theo_unit_wt order_item.theoretical_unit_wt%TYPE;

  --ll_edi_file_id integer;
  ll_edi_file_id_aleris INTEGER;

  ll_item_count INTEGER;

  li_hl01 INTEGER;
  li_hllin INTEGER;

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (2784); ---Add customer id here if you want to send 870 for more customers

  CURSOR coil_cur IS
  SELECT UNIQUE C.COIL_ABC_NUM
  FROM SHEET_SKID_DETAIL SKD
    JOIN SHEET_SKID SK ON SKD.SHEET_SKID_NUM = SK.SHEET_SKID_NUM
    JOIN PRODUCTION_SHEET_ITEM PSI ON SKD.PROD_ITEM_NUM = PSI.PROD_ITEM_NUM
    JOIN COIL C ON PSI.COIL_ABC_NUM = C.COIL_ABC_NUM
    JOIN AB_JOB AB ON SK.AB_JOB_NUM = AB.AB_JOB_NUM
    JOIN CUSTOMER_ORDER CO ON CO.ORDER_ABC_NUM = AB.ORDER_ABC_NUM
  WHERE (AB.JOB_STATUS = 0) AND
    ( C.COIL_STATUS IN (0, 3) ) AND
    ( CO.ORIG_CUSTOMER_ID = ll_customer_id ) AND
    ( PSI.PROD_ITEM_EDI870_DATE is NULL ) AND
    ( C.SCRAP_870_DATE is NULL ) AND
    ( SK.SKID_SHEET_STATUS in (0,2,4,12,13, 16) ) --Alex Gerlants. 03/22/2019. Added new status 16-Hold For Cert
    and ( SK.ab_job_num = 105938 );

  CURSOR alcan_870_cur IS
   SELECT production_sheet_item.ab_job_num,
	   production_sheet_item.coil_abc_num,
	   production_sheet_item.prod_item_pieces,
	   production_sheet_item.prod_item_num,
	   sheet_skid.sheet_skid_num,
	   production_sheet_item.prod_item_net_wt,
	   sheet_skid.skid_sheet_status,
	   sheet_skid.sheet_skid_display_num,
	   sheet_skid.sheet_net_wt,
	   sheet_skid.skid_pieces,
	   coil.coil_org_num,
	   coil.lot_num,
	   nvl(coil.consumed_coil_num, ' ') consumed_coil,
	   nvl(coil.material_num, ' ') material_num,
	   nvl(customer_order.sales_order, ' ') sales_order,
	   nvl(customer_order.orig_customer_po, 'NA') customer_po,
	   nvl(order_item.enduser_part_num, ' ') enduser_parts,
	   nvl(order_item.cust_prod_line_id, 'NA') customer_line_id,
	   nvl(order_item.finished_goods_material_num, 'NA') finished_goods,
	   (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	   NULL done
      FROM sheet_skid,
	   production_sheet_item,
	   sheet_skid_detail,
	   coil,
	   order_item,
	   ab_job,
	   customer_order
     WHERE (sheet_skid.skid_sheet_status IN (0, 2, 4, 13, 12, 16)) -- 2: Ready; 8: Warehouse Ready; 13: Partial Ready; 7: Partial; 12: Sample; 4: onhold
								    --Alex Gerlants. 03/22/2019. Added new status 16-Hold For Cert
       AND (production_sheet_item.prod_item_edi870_date IS NULL)
       AND (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num)
       AND (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num)
       AND (coil.coil_abc_num = production_sheet_item.coil_abc_num)
       AND (coil.customer_id = ll_customer_id)
       AND (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
       AND (production_sheet_item.ab_job_num = ab_job.ab_job_num)
       AND (ab_job.order_abc_num = order_item.order_abc_num)
       AND (ab_job.order_item_num = order_item.order_item_num)
       AND (production_sheet_item.coil_abc_num = ll_cur_coil)
       and ( sheet_skid.ab_job_num = 105938 );

       CURSOR alcan_scrap_870_cur IS
       SELECT a.coil_abc_num,
	      b.coil_org_num,
	      a.ab_job_num,
	      nvl(b.material_num, ' ') material_num,
	       NVL(a.process_quantity, 0) process_quan,
	       NVL(a.process_end_wt, 0) process_end_wt
       FROM process_coil a, coil b
       WHERE (b.coil_abc_num = ll_cur_coil)
	 AND (a.coil_abc_num = b.coil_abc_num)
	 AND (a.scrap_870_date is NULL);

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;

  item_rec  alcan_870_cur%ROWTYPE;
  coil_rec  coil_cur%ROWTYPE;

  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;

  TYPE coil_num_type IS TABLE OF coil.coil_abc_num%type INDEX BY BINARY_INTEGER;
  coil_num coil_num_type;
  p binary_integer :=0;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;
    p		   := 0;

  SELECT count(COIL.COIL_ABC_NUM)
  INTO ll_item_count
    FROM AB_JOB,
	 COIL,
	 PRODUCTION_SHEET_ITEM,
	 SHEET_SKID,
	 SHEET_SKID_DETAIL,
	 CUSTOMER_ORDER
   WHERE ( SHEET_SKID_DETAIL.SHEET_SKID_NUM = SHEET_SKID.SHEET_SKID_NUM ) and
	 ( SHEET_SKID_DETAIL.PROD_ITEM_NUM = PRODUCTION_SHEET_ITEM.PROD_ITEM_NUM ) and
	 ( COIL.COIL_ABC_NUM = PRODUCTION_SHEET_ITEM.COIL_ABC_NUM ) and
	 ( AB_JOB.AB_JOB_NUM = SHEET_SKID.AB_JOB_NUM ) and
	 ( AB_JOB.ORDER_ABC_NUM = CUSTOMER_ORDER.ORDER_ABC_NUM ) and
	 ( AB_JOB.JOB_STATUS = 0 ) AND
	 (  COIL.COIL_STATUS in (0, 3) ) AND
	 ( CUSTOMER_ORDER.ORIG_CUSTOMER_ID = ll_customer_id ) AND
	 ( PRODUCTION_SHEET_ITEM.PROD_ITEM_EDI870_DATE is NULL ) AND
	 ( COIL.SCRAP_870_DATE is NULL ) AND
	 ( SHEET_SKID.SKID_SHEET_STATUS in (0, 2,4,12,13, 16) ) --Alex Gerlants. 03/22/2019. Added new status 16-Hold For Cert
	 and ( sheet_skid.ab_job_num = 105938 );

    IF (ll_item_count <> 0) THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926';
      i := i + 1;

      li_hl01 := 0;

      FOR coil_rec IN coil_cur LOOP    -- coil loop
	  ll_cur_coil := coil_rec.coil_abc_num;

	  coil_num(p) := ll_cur_coil;
	  p := p + 1;


	FOR item_rec IN alcan_870_cur LOOP   -- item loop

	li_hl01 := li_hl01 + 1;

	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	      SELECT nvl(customer_order.orig_customer_po, 'NA'),
		     nvl(order_item.cust_prod_line_id, 'NA'),
		     nvl(order_item.finished_goods_material_num, 'NA')
	      INTO ls_po, ls_cust_prod_line, ls_finished_goods
	      FROM   order_item,
		     ab_job,
		     customer_order
	     WHERE (ab_job.order_abc_num = customer_order.order_abc_num)
	     AND (ab_job.order_abc_num = order_item.order_abc_num)
	     AND (ab_job.order_item_num = order_item.order_item_num)
	      AND (ab_job.ab_job_num = item_rec.ab_job_num);

	IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
	   x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
	   i := i + 1;
	END IF;

	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.prod_item_num);
	i := i + 1;


	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	x12_table(i) := 'REF*RV*' || to_char(item_rec.prod_item_num) ||
			'*NA';
	i := i + 1;

	x12_table(i) := 'REF*IX*' || to_char(item_rec.consumed_coil);
	i := i + 1;

	x12_table(i) := 'PO1**1*UN****' || '***SN*' ||
			  item_rec.coil_org_num || '***VP*' || item_rec.finished_goods;
	i := i + 1;

	IF item_rec.skid_sheet_status = 2 THEN
	  x12_table(i) := 'PID*S*MA*ST*1*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 4 THEN
	  x12_table(i) := 'PID*S*MA*ST*3*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	ELSIF item_rec.skid_sheet_status = 13 THEN
	  x12_table(i) := 'PID*S*MA*ST*8*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	 ELSE
	  x12_table(i) := 'PID*S*MA*ST*4*' ||
			  to_char(item_rec.sheet_skid_display_num);
	  i := i + 1;
	END IF;

	x12_table(i) := 'PID*S*MAC*ST*01';
	i := i + 1;
	x12_table(i) := 'PID*S*PR*ST*19';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.prod_item_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' || to_char(item_rec.skid_gross_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.prod_item_pieces) ||
			'*PC';
	i := i + 1;

	 item_num(k) := item_rec.prod_item_num;
	k := k + 1;

      END LOOP;  -- item loop

     SELECT scrap_870_date, coil_org_num, lot_num
     INTO ld_scrap_870_date, ls_coil_org_num, ls_heat
     FROM coil
     WHERE coil_abc_num = ll_cur_coil;

     IF (ld_scrap_870_date is NULL) THEN  -- scrap not sent

      FOR scrap_rec IN alcan_scrap_870_cur LOOP    -- scrap loop

	--scrap info

	SELECT NVL(sum(production_sheet_item.prod_item_net_wt),0)
	into ll_prime_nw
	 FROM production_sheet_item
	 WHERE (production_sheet_item.ab_job_num = scrap_rec.ab_job_num) and
	       (production_sheet_item.coil_abc_num = ll_cur_coil);


		ll_scrap_nw := scrap_rec.process_quan - scrap_rec.process_end_wt - ll_prime_nw;



		IF ll_scrap_nw > 0 then

		   li_hl01 := li_hl01 + 1;

		   x12_table(i) := 'HL*' || to_char(li_hl01) || '*' || to_char(li_hllin) || '*I';
		   i := i + 1;

		   IF (ls_po <> ls_finished_goods) AND (ls_po <> 'NA' ) THEN
		      x12_table(i) := 'PRF*' || ls_po || '****' || ls_cust_prod_line;
		      i := i + 1;
		   END IF;

		   x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
		    i := i + 1;

		    x12_table(i) := 'PO1**1*UN****' || '***SN*' || scrap_rec.coil_org_num ;
		    i := i + 1;

		    x12_table(i) := 'PID*S*MA*ST*S';
		    i := i + 1;
		    x12_table(i) := 'PID*S*MAC*ST*05';
		     i := i + 1;
		    x12_table(i) := 'PID*S*PR*ST*19';
		     i := i + 1;

		   x12_table(i) := 'MEA*WT*N*' || to_char(ll_scrap_nw) || '*LB*01';
		   i := i+1;
		 END IF;

	END LOOP;  -- scrap loop
      END IF;  -- scrap not sent
     END LOOP;	 -- coil loop
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval
	  INTO ll_edi_file_id_aleris
	  FROM dual;
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_aleris) || '.edi';
     -- edi_file	:= 's_alcan_' || to_char(ll_edi_file_id_aleris) || '.870';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));

	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      --edi_file	:= 'send_edi_log'; /* Alex Gerlants. 04/14/2017. Commented out. */
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      --For verifying 997
      INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (ll_edi_file_id_aleris,
	   '039630926',
	   su_duns,
	   ll_gs_log,
	   ll_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   ll_customer_id,
	   ll_st_log,
	   '870');
--	   COMMIT;

     FOR m IN 0 .. k - 1 LOOP
       UPDATE production_sheet_item
	   SET prod_item_edi870_date = SYSDATE,
	       edi_file_id_870 = ll_edi_file_id_aleris /* Alex Gerlants. 09/06/2016. New column */
	 WHERE production_sheet_item.prod_item_num = item_num(m);
    END LOOP;

--	COMMIT;

	FOR m in 0..p - 1 LOOP
		UPDATE coil
					SET coil.scrap_870_date = sysdate
		WHERE coil.coil_abc_num = coil_num(m);

	       UPDATE process_coil
					SET scrap_870_date = sysdate
		WHERE ( coil_abc_num = coil_num(m)) AND (scrap_870_date is NULL);

	     END LOOP;

	COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_846_CLEVELAND_CLIFF_CCSC"
is

--return number is

  edi_file_prefix		VARCHAR2(50) := 's_cliffs_ccsc_846_';
  ls_duns			customer.customer_duns_number%TYPE;
  ls_coil_classification	varchar2(3);
  --ls_coil_classification_qas	  varchar2(3);
  --li_skid_status_albl 	  sheet_skid.skid_sheet_status%TYPE;
  --ls_skid_status_cliff	  varchar2(3);
  --ls_skid_prod_desc_code	  varchar2(3);
  --li_scrap_status_albl	  sheet_skid.skid_sheet_status%TYPE;
  --ls_scrap_status_cliff	  varchar2(3);
  li_coil_status		coil.coil_status%TYPE;
  ls_coil_status_cliff		varchar2(3);
  ll_coil_length		number(8);
  ls_duns_cliff 		varchar2(32);
  ls_duns_albl			varchar2(32);
  ll_long_part_length		number(16,5);
  ll_scrap_skid_num		scrap_skid.scrap_skid_num%TYPE;
  --li_scrap_type_albl		  scrap_skid.scrap_type%TYPE;
  --ls_scrap_type_cliff 	  varchar2(3);
  --ll_coil_od			  number(8);
  --ll_coil_id			  number(8);
  ls_coil_od			char(9);
  ls_coil_id			char(9);

  li_gs_log			INTEGER;
  li_st_log			INTEGER;
  ls_today_short		VARCHAR2(20);
  ls_today			VARCHAR2(20);
  ls_now			VARCHAR2(20);
  li_coil_count 		int := 0;
  --ls_coil_count_string	  varchar2(32);
  li_skid_count 		int := 0;
  li_scrap_skid_count		int := 0;
  li_edi_846_id 		int;
  ls_vendor_item_num		varchar2(4);
  ls_coil_process_date		char(12);
  ls_qa_status_date		char(12);
  ls_coil_org_num		coil.coil_org_num%TYPE;
  ll_coil_abc_num		coil.coil_abc_num%TYPE;
  li_count			number;
  ls_production_desc_code	coil.production_desc_code%TYPE;    --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY
  --ls_production_desc_code	  varchar2(12); --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY
  ls_table67_mat_class_skid	abis_x12_skid.table67_material_class%TYPE;
  ls_table70_mat_status_skid	abis_x12_skid.table70_material_status_op%TYPE;
  ls_table67_mat_class_coil	abis_x12_coil.table67_material_class%TYPE;
  ls_table70_mat_status_coil	abis_x12_coil.table70_material_status_op%TYPE;
  ls_table67_mat_class_scrap	abis_scrap_type_x12.table67_material_class%TYPE;
  ls_table70_mat_status_scrap	abis_scrap_status_x12.table70_material_status_op%TYPE;
  ls_lot_num			coil.lot_num%TYPE;
  --li_skid_count_string	  varchar(32);
  --li_scrap_skid_count_string	  varchar(32);
  li_item_count 		number(6);
  ls_item_count_string		varchar(32);

  cursor skid_cursor is
  select production_sheet_item.prod_item_num,
	 sheet_skid.sheet_skid_num,
	 production_sheet_item.prod_item_net_wt,
	 production_sheet_item.prod_item_pieces,
	 sheet_skid.skid_sheet_status,
	 sheet_skid.skid_pieces,
	 sheet_skid.skid_date,
	 (sheet_skid.sheet_net_wt + sheet_skid.sheet_tare_wt) skid_gross_wt,
	 coil.coil_abc_num,
	 coil.coil_org_num,
	 coil.coil_gauge,
	 coil.coil_width,
	 NVL(coil.coil_mid_num, 'NA') coil_mid_num,
	 NVL(coil.part_num, 'NA') part_num,
	 NVL(coil.supplier_sales_num, 'NA') supplier_sales_num,
	 NVL(coil.purchase_order_num, 'NA') purchase_order_num,
	 NVL(coil.lot_num, 'NA') lot_num,

	 --nvl(coil.production_desc_code, 'NA') production_desc_code,
	 (
	    select   distinct nvl(production_desc_code, 'NA')
	    from     inbound_coil
	    where    coil_number = coil.coil_org_num
	 ) production_desc_code,

	 --nvl(coil.vo, 'NA') vo,
	 (
	    select   distinct nvl(vo, 'NA')
	    from     inbound_coil
	    where    coil_number = coil.coil_org_num
	 ) vo,

	 --nvl(coil.customer_po, 'NA') customer_po,
	 (
	    select   distinct nvl(customer_po, 'NA')
	    from     inbound_coil
	    where    coil_number = coil.coil_org_num
	 ) customer_po,

	 customer_order.orig_customer_po,
	 order_item.enduser_part_num,
	 abis_x12_skid.table67_material_class,
	 abis_x12_skid.table70_material_status_op,
	 coil.net_wt_balance,
	 coil.net_wt,
	 coil.lfeed
  from	 sheet_skid
	 join sheet_skid_detail on sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num
	 join production_sheet_item on sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num
	 join coil on coil.coil_abc_num = production_sheet_item.coil_abc_num
	 join ab_job on ab_job.ab_job_num = sheet_skid.ab_job_num
	 join customer_order on customer_order.order_abc_num = ab_job.order_abc_num
	 join order_item on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
	 left outer join abis_x12_skid on abis_x12_skid.abis_skid_status = sheet_skid.skid_sheet_status
  where  coil.customer_id = 3061
  and	 sheet_skid.skid_sheet_status in (16, 1, 4, 7, 13, 5, 2, 12, 8, 15, 10) --Skid status: 2:Ready; 4:OnHold; 8:Wh-ready; 10:wh-sort;  13:Partial Ready; 16:Hold For Cert
  order by sheet_skid.sheet_skid_num;

  skid_rec skid_cursor%ROWTYPE;

