  from coil c, sheet_skid ss, production_sheet_item psi, sheet_skid_detail ssd
  where c.coil_abc_num = psi.coil_abc_num and
	psi.prod_item_num = ssd.prod_item_num and
	ssd.sheet_skid_num = ss.sheet_skid_num and
	c.coil_status = 0 and	 -- coil status: 0:Done; 1:InProcess; 2:New; 3:Rejected; 4:OhHold; 6:Returned; 7:Rebanded  11:QAOnHold
	ss.skid_sheet_status <> 0 and
	c.customer_id = al_customer_id	 ;  */

  type edi_846_tabletype is table of varchar2(32767) index by binary_integer;
  edi_846 edi_846_tabletype;

  j binary_integer := 0;
  i integer := 0;



  --edi_file_prefix VARCHAR2(50) := 'S_novelis_kingston_';


--  li_coil_abc_num coil.coil_abc_num%type;
--  ls_coil_org_num coil.coil_org_num%type;
--  ls_coil_mid_num coil.coil_mid_num%type;
--  ls_part_num coil.part_num%type;
--  ls_supplier_sales_num coil.supplier_sales_num%type;
--  ls_purchase_order_num coil.purchase_order_num%type;
--  li_total_skid_net_wt sheet_skid.sheet_net_wt%type;
--  li_total_skid_tare_wt sheet_skid.sheet_tare_wt%type;
--  li_total_net_wt coil.net_wt%type;
--  li_total_gross_wt coil.net_wt%type;

  edi_location varchar2(50) := '/templar/templar/incoming/senddata';
  edi_file varchar2 (50) := 'edi_out.txt';
  edi_file_handle UTL_FILE.FILE_TYPE;

   -- `005159199' Cleveland-Cliffs Steel LLC (Indiana Harbor)
   -- `613460476' Cleveland-Cliffs Kote Inc.
   -- `003913423' Cleveland-Cliffs Burns Harbor LLC
   -- `122373918' Cleveland-Cliffs Cleveland Works LLC

begin
   li_item_count := 0;

   select customer_duns_number
   into   ls_duns
   from   customer
   where  customer_id = 3061;

   SELECT EDI_ST_LOG_SEQ.NEXTVAL INTO li_st_log FROM dual;
   SELECT EDI_GS_LOG_SEQ.NEXTVAL INTO li_gs_log FROM dual;
   ls_today_short := to_char(SYSDATE, 'yymmdd');
   ls_today := to_char(SYSDATE, 'yyyymmdd');
   ls_now := to_char(SYSDATE, 'hh24mi');

   --Production
   edi_846(j) := 'ISA*00*	   *00* 	 *01*039630926T     *01*606072130      *'
    ||	ls_today_short	|| '*' ||  ls_now  || '*U*00401*' ||
		     lpad(to_char(li_gs_log),9,'0') || '*0*P*|' || '~'; j := j + 1;

   --Development
   --edi_846(j) := 'ISA*00*	     *00*	   *ZZ*2NDSFTP	      *01*606072130	 *'
   -- ||  ls_today_short  || '*' ||  ls_now  || '*U*00401*' ||
   --		       lpad(to_char(li_gs_log),9,'0') || '*0*T*:' || '~'; j := j + 1;

   --Production
   edi_846(j) := 'GS*IB*039630926T*606072130*' ||  ls_today  || '*' || ls_now || '*' || li_gs_log || '*X*004010' || '~'; j := j + 1;

   --Development
   --edi_846(j) := 'GS*IB*2NDSFTP*606072130*' ||  ls_today  || '*' || ls_now || '*' || li_gs_log || '*X*004010'; j := j + 1;

   edi_846(j) := 'ST*846*' || li_st_log || '~'; j := j + 1;
   edi_846(j) := 'BIA*00*AA*' || li_st_log || '*' || ls_today  || '*' || ls_now || '~'; j := j + 1;
   edi_846(j) := 'DTM*184*' || ls_today || '*' || ls_now || '*ET' || '~'; j := j + 1;

   ls_duns_cliff := '606072130';
   edi_846(j) := 'N1*SU**1'  ||  ls_duns || '*' || ls_duns_cliff || '~'; j := j + 1; -- 'MF': Steel Producer; ls_duns: Customer DUNS

   ls_duns_albl := '039630926';
   edi_846(j) := 'N1*OU**1*' || ls_duns_albl || '~'; j := j + 1;     --'OU': Outside Processor;  '03-963-0926': ABCo's DUNS#

   --return 1; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY

/*
   open skid_cursor;
   fetch skid_cursor
   into skid_rec;

   open scrap_cursor;
   fetch scrap_cursor
   into scrap_rec;

   open coil_cursor;
   fetch coil_cursor
   into coil_rec;
*/

   --*********** Sheet skids *************************************


   --This loop is for TEST ONLY
   --for skid_rec in skid_cursor loop
   --  li_skid_count := li_skid_count + 1;
   --end loop;

   --edi_846(j) := '*** Skid Count: ' || to_char(li_skid_count) || '   TEST ONLY TEST ONLY TEST ONLY'; j := j + 1;

   --edi_846(j) := '---------------------- Beginning of skid ----------------------------------'; j := j + 1;

   for skid_rec in skid_cursor loop
     li_skid_count := li_skid_count + 1;
     li_item_count := li_item_count + 1;
     --ls_item_count_string := to_char(li_item_count, '0009');
     ls_item_count_string := to_char(li_item_count);

     ls_table67_mat_class_skid := skid_rec.table67_material_class;
     ls_table70_mat_status_skid := skid_rec.table70_material_status_op;
     ls_lot_num := skid_rec.lot_num;

      --edi_846(j) := 'LIN**PO*' || skid_rec.purchase_order_num || '*BP*' || skid_rec.part_num || '*IN*' || skid_rec.prod_item_num || '*VN*' || skid_rec.coil_org_num || '*PK*' || skid_rec.sheet_skid_num || '*VO*' || skid_rec.supplier_sales_num; j := j + 1;
      --edi_846(j) := 'LIN*0001*VO*' || skid_rec.orig_customer_po || '*PO*' || '01' || '*SN*' || skid_rec.coil_org_num || '*HN*' || ls_lot_num; j := j + 1;
      edi_846(j) := 'LIN*' || trim(ls_item_count_string) || '*VO*' || skid_rec.vo || '*PO*' || skid_rec.customer_po || '*SN*' || skid_rec.coil_org_num || '~'; j := j + 1;

      --li_skid_status_albl := skid_rec.skid_sheet_status;

      --edi_846(j) := '*** Skid Status: ' || to_char(li_skid_status_albl); j := j + 1;

      --if li_skid_status_albl <> 4 then --OnHold
      --Table AISI STEEL CODE TABLE #70 (Material Status-OP Codes). For PID*S*MA

      --Email from Lisa received on Mon 5/18/2026 2:14 PM
      --Remove PID06 from PID*S*MA and *MAC segments
      --edi_846(j) := 'PID*S*MAC*ST*' || ls_table67_mat_class_skid || '***67'; j := j + 1; --01: Prime (sheet skid) from AISI material classification code table 67. '67': Table 67
      edi_846(j) := 'PID*S*MAC*ST*' || ls_table67_mat_class_skid || '~'; j := j + 1; --01: Prime (sheet skid) from AISI material classification code table 67. '67': Table 67

      --edi_846(j) := 'PID*S*MA*ST*' || ls_table70_mat_status_skid || '***70' ; j := j + 1; --Table AISI STEEL CODE TABLE #70 (Material Status-OP Codes)
      edi_846(j) := 'PID*S*MA*ST*' || ls_table70_mat_status_skid || '~' ; j := j + 1; --Table AISI STEEL CODE TABLE #70 (Material Status-OP Codes)
      --else --li_skid_status_albl = 4 - 'OnHold'
       -- ls_skid_status_cliff := '2';	 --'Hold for QA Release' from table 68
       -- edi_846(j) := 'PID*S*QAS*ST*' || ls_skid_status_cliff || '***68'; j := j + 1;
      --end if;

      edi_846(j) := 'MEA*WT*WT*' || skid_rec.prod_item_net_wt || '*01' || '~'; j := j + 1;     --'01' means LBS
      --edi_846(j) := 'MEA*WT*WT*' || skid_rec.prod_item_net_wt || '*24'; j := j + 1;	  --'24' means Theo LBS
      --edi_846(j) := 'MEA*PD*G*' || skid_rec.skid_gross_wt || '*LB'; j := j + 1;
      --edi_846(j) := 'MEA*PD*TH*' || to_char(skid_rec.coil_gauge) || '*ED'; j := j + 1;  --'ED' means Inches, Decimal-Nominal
      --edi_846(j) := 'MEA*PD*WD*' || to_char(skid_rec.coil_width) || '*IN'; j := j + 1;  --'IN' means Inches

      --ll_coil_length := (skid_rec.net_wt_balance / skid_rec.net_wt) * skid_rec.lfeed;

      select   f_get_long_length_4order_item(order_item.order_abc_num, order_item.order_item_num)
      into     ll_long_part_length
      from     sheet_skid
	       join ab_job on ab_job.ab_job_num = sheet_skid.ab_job_num
	       join order_item on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
      where    sheet_skid.sheet_skid_num = skid_rec.sheet_skid_num;

      --************ Incorrect. Should be part length... I guess
      --edi_846(j) := 'MEA*PD*LN*' || to_char(ll_coil_length) || '*LF'; j := j + 1;	     --'LF' means LInear Feet
      --edi_846(j) := 'MEA*PD*LN*' || to_char(ll_long_part_length) || '*IN'; j := j + 1;    --'IN' means Inches

      --edi_846(j) := 'MEA*CT*NL*' || to_char(skid_rec.prod_item_pieces) || '*PC'; j := j + 1; --'PC' means pieces
      --edi_846(j) := 'DTM*009*' || to_char(skid_rec.skid_date, 'YYYYMMDD*HHMI') || '*ET'; j := j + 1;
      edi_846(j) := 'DTM*206*' || ls_today || '*' || ls_now || '*ET' || '~'; j := j + 1;
      --edi_846(j) := 'DTM*105*' || ls_today; j := j + 1;
      edi_846(j) := 'REF*SE*' || to_char(skid_rec.sheet_skid_num) || '~'; j := j + 1;

      --edi_846(j) := 'QTY*01*1'; j := j + 1;

      --edi_846(j) := '--------------------------------------------------------------------'; j := j + 1;

   end loop; --for skid_rec in skid_cursor loop

   --edi_846(j) := '---------------------- End of skid ----------------------------------'; j := j + 1;


   --*********** Scrap skids *************************************

   --This loop is for TEST ONLY


   --This loop is for test only
   --for scrap_rec in scrap_cursor loop
   --  li_scrap_skid_count := li_scrap_skid_count + 1;
   --end loop;

   --edi_846(j) := '*** Scrap Skid Count: ' || to_char(li_scrap_skid_count) || '   TEST ONLY TEST ONLY TEST ONLY'; j := j + 1;


   /*
   for scrap_rec in scrap_cursor loop
      li_scrap_skid_count := li_scrap_skid_count + 1;
      li_item_count := li_item_count + 1;
      --ls_item_count_string := to_char(li_item_count, '0009');
      ls_item_count_string := to_char(li_item_count);

      ll_scrap_skid_num := scrap_rec.scrap_skid_num;
      ls_table67_mat_class_scrap := scrap_rec.table67_material_class;
      ls_table70_mat_status_scrap := scrap_rec.table70_material_status_op;
      ls_lot_num := scrap_rec.lot_num;

      --edi_846(j) := 'LIN**PO*' || scrap_rec.purchase_order_num || '*BP*' || scrap_rec.part_num || '*IN*' || scrap_rec.prod_item_num || '*VN*' || scrap_rec.coil_org_num || '*PK*' || scrap_rec.sheet_skid_num || '*VO*' || scrap_rec.supplier_sales_num; j := j + 1;
      --edi_846(j) := 'LIN*0001*VO*' || scrap_rec.orig_customer_po || '*VN*' || '01' || '*SN*' || scrap_rec.coil_org_num || '*HN*' || ls_lot_num; j := j + 1;
      --edi_846(j) := 'LIN*' || trim(ls_item_count_string) || '*VO*' || scrap_rec.orig_customer_po || '*VN*' || '01' || '*SN*' || scrap_rec.coil_org_num; j := j + 1;
      edi_846(j) := 'LIN*' || trim(ls_item_count_string) || '*VO*' || scrap_rec.vo || '*PO*' || scrap_rec.customer_po || '*SN*' || scrap_rec.coil_org_num || '~'; j := j + 1;

      --edi_846(j) := '*** Scrap Skid Type: ' || to_char(scrap_rec.scrap_type) || '   Scrap Skid Status: ' || to_char(scrap_rec.skid_scrap_status) || '   TEST ONLY TEST ONLY TEST ONLY'; j := j + 1;

      --li_scrap_type_albl := scrap_rec.scrap_type;
      --ls_scrap_type_cliff := ls_table67_mat_class_scrap;

      --Email from Lisa received on Mon 5/18/2026 2:14 PM
      --Remove PID06 from PID*S*MA and *MAC segments
      --edi_846(j) := 'PID*S*MAC*ST*' || ls_table67_mat_class_scrap || '***67'; j := j + 1; --01: Prime (sheet skid) from AISI material classification code table 67. '67': Table 67
      edi_846(j) := 'PID*S*MAC*ST*' || '13' || '~'; j := j + 1; --01: Prime (sheet skid) from AISI material classification code table 67. '67': Table 67

      --li_scrap_status_albl := scrap_rec.skid_scrap_status;
      --ls_scrap_status_cliff := ls_table70_mat_status_scrap;
      --edi_846(j) := 'PID*S*MA*ST*' || ls_table70_mat_status_scrap || '***70'; j := j + 1; --Table AISI STEEL CODE TABLE #70 (Material Status-OP Codes)
      edi_846(j) := 'PID*S*MA*ST*' || 'S' || '~'; j := j + 1; --Table AISI STEEL CODE TABLE #70 (Material Status-OP Codes)
      --else --li_skid_status_albl = 4 - 'OnHold'
      --  ls_scrap_status_cliff := 'E';   --'Hold for QA Release' from table 68
      --  edi_846(j) := 'PID*S*QAS*ST*' || ls_scrap_status_cliff || '***68'; j := j + 1;
      --end if;


      edi_846(j) := 'MEA*WT*WT*' || scrap_rec.return_item_net_wt || '*01' || '~'; j := j + 1;	  --'01' means LBS
      --edi_846(j) := 'MEA*WT*WT*' || scrap_rec.return_item_net_wt || '*24'; j := j + 1;     --'24' means Theo LBS
      --edi_846(j) := 'MEA*PD*G*' || (to_char(scrap_rec.scrap_net_wt + scrap_tare_wt)) || '*LB'; j := j + 1;
      --edi_846(j) := 'MEA*PD*TH*' || to_char(scrap_rec.coil_gauge) || '*ED'; j := j + 1;  --'ED' means Inches, Decimal-Nominal
      --edi_846(j) := 'MEA*PD*WD*' || to_char(scrap_rec.coil_width) || '*IN'; j := j + 1;  --'IN' means Inches

      ll_coil_length := scrap_rec.net_wt_balance / (scrap_rec.coil_width * scrap_rec.coil_gauge);

      ll_long_part_length := 0; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY

      select max(f_get_long_length_4order_item(order_item.order_abc_num, order_item.order_item_num))
      into   ll_long_part_length
      from   return_scrap_item
	     join ab_job on ab_job.ab_job_num = return_scrap_item.ab_job_num
	     join customer_order on customer_order.order_abc_num = ab_job.order_abc_num
	     join order_item on order_item.order_abc_num = ab_job.order_abc_num and order_item.order_item_num = ab_job.order_item_num
	     join scrap_skid_detail on return_scrap_item.return_scrap_item_num = scrap_skid_detail.return_scrap_item_num
	     join scrap_skid on scrap_skid.scrap_skid_num = scrap_skid_detail.scrap_skid_num
      where  scrap_skid.scrap_skid_num = scrap_rec.scrap_skid_num
      and    return_scrap_item.return_scrap_item_num = scrap_rec.return_scrap_item_num;

      --************ Incorrect. Should be part length... I guess
      --edi_846(j) := 'MEA*PD*LN*' || to_char(ll_coil_length) || '*LF'; j := j + 1;	     --'LF' means LInear Feet
      --edi_846(j) := 'MEA*PD*LN*' || to_char(ll_long_part_length) || '*IN'; j := j + 1;    --'IN' means Inches

      --There are no pieces for a scrap skid
      --edi_846(j) := 'MEA*CT*NL*' || to_char(scrap_rec.skid_pieces) || '*PC'; j := j + 1; --'PC' means pieces	???????????
      --edi_846(j) := 'DTM*009*' || to_char(scrap_rec.return_item_date, 'YYYYMMDD*HHMI') || '*ET'; j := j + 1;
      edi_846(j) := 'DTM*206*' || ls_today || '*' || ls_now || '*ET' || '~'; j := j + 1;
      --edi_846(j) := 'DTM*105*' || ls_today; j := j + 1;
      edi_846(j) := 'REF*SE*' || to_char(scrap_rec.scrap_skid_num) || '~'; j := j + 1;

      --edi_846(j) := 'QTY*01*1'; j := j + 1;


   end loop; --for scrap_rec in skid_cursor loop
   */


   --This loop is for TEST ONLY
   --for coil_rec in coil_cursor loop
   --  li_coil_count := li_coil_count + 1;
   --end loop;

   --edi_846(j) := '*** Coil Count: ' || to_char(li_coil_count) || '   TEST ONLY TEST ONLY TEST ONLY'; j := j + 1;

   --edi_846(j) := '---------------------- Beginning of coil ----------------------------------'; j := j + 1;

   for coil_rec in coil_cursor loop
     li_coil_count := li_coil_count + 1;
     li_item_count := li_item_count + 1;
     --ls_item_count_string := to_char(li_item_count, '0009');
     ls_item_count_string := to_char(li_item_count);

     ls_coil_org_num := coil_rec.coil_org_num;
     ll_coil_abc_num := coil_rec.coil_abc_num;
     ls_production_desc_code := coil_rec.production_desc_code;
     --ls_production_desc_code := '?'; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY
     --select to_char(li_coil_count, '0009') into ls_coil_count_string from dual;
     ls_vendor_item_num := '01';
     ls_table67_mat_class_coil := coil_rec.table67_material_class;
     ls_table70_mat_status_coil := coil_rec.table70_material_status_op;

     --edi_846(j) := 'LIN*' || ls_coil_count_string || '*VO*' || coil_rec.purchase_order_num || '*VN*' || ls_vendor_item_num || '*SN*' || coil_rec.coil_org_num || '*HN*' || coil_rec.lot_num; j := j + 1;
     edi_846(j) := 'LIN*' || trim(ls_item_count_string) || '*VO*' || coil_rec.vo || '*PO*' || coil_rec.customer_po || '*SN*' || coil_rec.coil_org_num || '~'; j := j + 1;

      --Coils data
      li_coil_status := coil_rec.coil_status;

      --edi_846(j) := 'Coil Status: ' || to_char(li_coil_status) || '  <== TEST ONLY TEST ONLY TEST ONLY '; j := j + 1;

      if li_coil_status <> 2 then --New
	ls_coil_classification := ls_table67_mat_class_coil;	 --Table 67
	ls_coil_status_cliff := ls_table70_mat_status_coil;	 --Table 70
      else
	ls_coil_classification := ls_production_desc_code;  --Table 67


	select	 count(*)
	into	 li_count
	from	 process_coil
	where	 coil_abc_num = ll_coil_abc_num;


	--ls_coil_classification := ls_production_desc_code;  --Table 67

	--li_count := 0; --TEST ONLY TEST ONLY TEST ONLY TEST ONLY TEST ONLY

	if li_count > 0 then --coil is assigned to a job
	  ls_coil_status_cliff := 'C';	      --Table 70. Coil is assigned to a job
	  --ls_coil_classification_qas := 'N/A';--Table 68
	else
	  ls_coil_status_cliff := 'Q';	      --Table 70. Coil is not assigned to a job
	  --ls_coil_classification_qas := 'N/A';--Table 68
	end if;
      end if;

      --edi_846(j) := '*** ALBL coil status: ' || to_char(li_coil_status) || '	 TEST ONLY TEST ONLY TEST ONLY'; j := j + 1;

      --Email from Lisa received on Mon 5/18/2026 2:14 PM
      --Remove PID06 from PID*S*MA and *MAC segments
      --if ls_coil_classification <> 'N/A' then
	--edi_846(j) := 'PID*S*MAC*ST*' || trim(ls_production_desc_code) || '***67'; j := j + 1; --Table 67
	edi_846(j) := 'PID*S*MAC*ST*' || trim(ls_production_desc_code) || '~'; j := j + 1; --Table 67
      --end if;

      --if ls_coil_status_cliff <> 'N/A' then
	--edi_846(j) := 'PID*S*MA*ST*' || trim(ls_coil_status_cliff) || '***70'; j := j + 1;	--Table 70
	edi_846(j) := 'PID*S*MA*ST*' || trim(ls_coil_status_cliff) || '~'; j := j + 1;	  --Table 70
      --end if;

      --if ls_coil_classification_qas <> 'N/A' then
      --  edi_846(j) := 'PID*S*QAS*ST*' || ls_coil_classification_qas || '***68'; j := j + 1;  --Table 68
      --end if;

      edi_846(j) := 'MEA*WT*WT*' || to_char(coil_rec.net_wt_balance) || '*01' || '~'; j := j + 1;  --'01' means LBS
      --edi_846(j) := 'MEA*WT*WT*' || to_char(coil_rec.net_wt_balance) || '*24'; j := j + 1;  --'24' means Theoretical Pounds
      --edi_846(j) := 'MEA*PD*TH*' || to_char(coil_rec.coil_gauge) || '*ED'; j := j + 1;  --'ED' means Inches, Decimal-Nominal
      --edi_846(j) := 'MEA*PD*WD*' || to_char(coil_rec.coil_width) || '*E8'; j := j + 1;  --'ED' means Inches, Decimal-Actual
      --edi_846(j) := 'QTY*01*1'; j := j + 1;

      --ll_coil_length := coil_rec.net_wt_balance / (coil_rec.coil_width * coil_rec.coil_gauge);
      --ll_coil_length := (coil_rec.net_wt_balance / coil_rec.net_wt) * coil_rec.lfeed;
      --edi_846(j) := 'MEA*PD*LN*' || to_char(ll_coil_length) || '*LF'; j := j + 1;  --'LF' means Lineal Feet

      --We don't have info for the 2 lines below
      ls_coil_od := 'Not On DB';
      ls_coil_id := 'Not On DB';
      --edi_846(j) := 'MEA*PD*OD*' || to_char(ll_coil_od) || '*ED'; j := j + 1;  --'ED' means Inches, Decimal-Nominal
      --edi_846(j) := 'MEA*PD*OD*' || ls_coil_od || '*ED'; j := j + 1;	--'ED' means Inches, Decimal-Nominal
      --edi_846(j) := 'MEA*PD*ID*' || to_char(ll_coil_id) || '*ED'; j := j + 1;  --'ED' means Inches, Decimal-Nominal
      --edi_846(j) := 'MEA*PD*OD*' || ls_coil_id || '*ED'; j := j + 1;	--'ED' means Inches, Decimal-Nominal

      if coil_rec.coil_status = 2 then
	select to_char(coil_entry_date, 'YYYYMMD*HHMI'), to_char(coil_entry_date, 'YYYYMMD*HHMI')
	into   ls_coil_process_date, ls_qa_status_date
	from   coil
	where  coil_abc_num = coil_rec.coil_abc_num;
      else
	select to_char(max(coil_track_date), 'YYYYMMD*HHMI'), to_char(max(coil_track_date), 'YYYYMMD')
	into   ls_coil_process_date, ls_qa_status_date
	from   coil_track
	where  coil_abc_num = coil_rec.coil_abc_num;
      end if;

      --edi_846(j) := 'DTM*009*' || ls_coil_process_date || '*ET'; j := j + 1;	--'009' means Process. ET' means Eastern Time
      edi_846(j) := 'DTM*206*' || ls_today || '*' || ls_now || '*ET' || '~'; j := j + 1;  --'206' means OP Status. ET' means Eastern Time
      --edi_846(j) := 'DTM*105*' || to_char(sysdate, 'YYYYMMDD'); j := j + 1;		--'105' means QA Status
      edi_846(j) := 'REF*SE*' || to_char(coil_rec.coil_abc_num) || '~'; j := j + 1;

      --edi_846(j) := '--------------------------------------------------------------------'; j := j + 1;

   end loop; --for coil_rec in coil_cursor loop

   --edi_846(j) := '---------------------- End of coil ----------------------------------'; j := j + 1;

   edi_846(j) := 'CTT*' || to_char(li_coil_count + li_skid_count + li_scrap_skid_count) || '~'; j := j + 1;
   edi_846(j) := 'SE*' || to_char(j-1) || '*' || li_st_log || '~'; j := j + 1;
   edi_846(j) := 'GE*1*' || li_gs_log || '~'; j := j + 1;
   edi_846(j) := 'IEA*1*' || LPAD(to_char(li_gs_log),9,'0') || '~';

   --if li_coil_count > 0 or li_skid_count > 0 or li_scrap_skid_count > 0 then
   if li_item_count > 0 then
     SELECT edi_file_id_seq.NEXTVAL INTO li_edi_846_id FROM DUAL;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--     edi_file := 'S_novelis_kingston_' || to_char(li_edi_846_id) || '.846';
     edi_file := edi_file_prefix || to_char(li_edi_846_id) || '.edi';
     edi_file_handle := utl_file.fopen(edi_location,edi_file,'W');
     --write edi to file
     FOR i IN 0..j LOOP
	 utl_file.put_line(edi_file_handle,edi_846(i));
	 END LOOP;
     utl_file.fclose(edi_file_handle);

     -- for verifying 997
      /*INSERT INTO outbound_edi_transaction(edi_file_id,duns_from,duns_to,interchange_control_number,
      group_control_number,transaction_time,edi_file_name,fa_receive_status,customer_id,set_control_num,transaction_type_id)
      VALUES(li_edi_846_id,'039630926',ls_duns,li_gs_log,li_gs_log, sysdate, edi_file,0,al_customer_id,li_st_log,'846');
      COMMIT;*/

      /*edi_file := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_location,edi_file,'a');
      utl_file.put_line(edi_file_handle,'Type: 846');
      utl_file.put_line(edi_file_handle,'Sending Time: ' || to_char(sysdate, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,'Interchange Control #: ' || li_gs_log);
      utl_file.put_line(edi_file_handle,'Group Control #: ' || li_gs_log);
      utl_file.put_line(edi_file_handle,'Set Control #: ' || li_st_log);
      utl_file.put_line(edi_file_handle,'');
      utl_file.put_line(edi_file_handle,'');
      utl_file.fclose(edi_file_handle);*/

      commit;
    else
      SELECT edi_file_id_seq.NEXTVAL INTO li_edi_846_id FROM DUAL;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--     edi_file := 'S_novelis_kingston_' || to_char(li_edi_846_id) || '.846';
     edi_file := edi_file_prefix || to_char(li_edi_846_id) || '.edi';
     edi_file_handle := utl_file.fopen(edi_location,edi_file,'W');
     --write edi to file
     utl_file.put_line(edi_file_handle,'Nothing to report.');
     utl_file.fclose(edi_file_handle);
    end if;


  --return 1;

  EXCEPTION
     WHEN dup_val_on_index then
     rollback;
     return;
     WHEN UTL_FILE.INVALID_PATH THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
     WHEN UTL_FILE.INVALID_MODE THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN UTL_FILE.INVALID_OPERATION THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN UTL_FILE.WRITE_ERROR THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN OTHERS THEN
     UTL_FILE.FCLOSE_ALL;
      RETURN;


  --return 1;
end p_846_cleveland_cliff_ccsc;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_CHECK_997" is

Cursor cur IS
SELECT *
FROM 		outbound_edi_transaction;

type line_tabletype is table of varchar2(32767) index by binary_integer;
line line_tabletype;
j binary_integer := 0;
i int;
li_edi_file_id int;
li_icn int;
ld_transaction_time date;
edi_location varchar2(50):='/templar/templar/incoming/senddata';
edi_file varchar2 (50) := 'check_997.log';
edi_file_handle UTL_FILE.FILE_TYPE;

begin

for cur_rec in cur loop
       if cur_rec.fa_received_time is null  then
	   if (sysdate - cur_rec.transaction_time > 0.083333 and --2 hours
	      sysdate - cur_rec.transaction_time < 1) then

	      line(j):= 'EDI_FILE_ID: '||cur_rec.edi_file_id||', '||'ICN: '||cur_rec.interchange_control_number||
			', '||'TRANSCATION_TIME: '||to_char(cur_rec.transaction_time, 'MM/DD/YY HH24:MI')||', '||
			'TRANSACTION_TYPE_ID: '|| cur_rec.transaction_type_id;
	      j := j + 1;
	   end if;
       end if;
end loop;

if j > 0 then
  edi_file_handle :=utl_file.fopen(edi_location,edi_file,'W');

  FOR i IN 0..j-1 LOOP
      utl_file.put_line(edi_file_handle,line(i));
    END LOOP;

  utl_file.fclose(edi_file_handle);
end if;

end P_CHECK_997;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_CHECK_SHIFT_END" is

li_i shift.dt_total%type ;
Cursor cur_shift IS
SELECT shift.shift_num
FROM shift
where shift.end_time is null and
shift.start_time is not null and
sysdate - shift.planned_ending_time > 0.105;

begin
  --li_i := 1;
  for cur_rec in cur_shift
  loop
      li_i := update_shift_dt_total( cur_rec.shift_num );
      update shift
      set shift.end_time = shift.planned_ending_time, shift.dt_total = li_i
      where shift.shift_num = cur_rec.shift_num;

      update line_current_status
      set line_current_status.scrap_skid_num = null,
	  line_current_status.sheet_skid_num = null,
	  line_current_status.coil_abc_num = null,
	  line_current_status.ab_job_num = null,
	  line_current_status.shift_num = null
      where line_current_status.shift_num = cur_rec.shift_num;
  end loop;
  commit;


end p_check_shift_end;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_CHECK_STATUS_UNMATCHED_COIL" is

Cursor cur IS
SELECT c.CUSTOMER_ID,cu.CUSTOMER_SHORT_NAME, p.AB_JOB_NUM, c.COIL_ABC_NUM, c.NET_WT, c.NET_WT_BALANCE, c.COIL_STATUS, p.PROCESS_COIL_STATUS, p.PROCESS_DATE
FROM PROCESS_COIL p, COIL c, customer cu
WHERE c.CUSTOMER_ID = cu.CUSTOMER_ID
and c.COIL_ABC_NUM  = p.COIL_ABC_NUM
AND c.COIL_STATUS <> 0
AND p.PROCESS_COIL_STATUS = 0;

type line_tabletype is table of varchar2(32767) index by binary_integer;
line line_tabletype;
j binary_integer := 0;
i int;
coil_count int := 0;

log_file_location varchar2(50):='/export/home/oracle9i';
--log_file_location varchar2(50):='/export/home/oracle11g';
log_file varchar2 (50) := 'check_status_unmatched_coil.log';
log_file_handle UTL_FILE.FILE_TYPE;

begin

SELECT count(*) into coil_count
FROM PROCESS_COIL p, COIL c, customer cu
WHERE c.CUSTOMER_ID = cu.CUSTOMER_ID
and c.COIL_ABC_NUM  = p.COIL_ABC_NUM
AND c.COIL_STATUS <> 0
AND p.PROCESS_COIL_STATUS = 0;

if coil_count > 0 then
  for cur_rec in cur loop
	 line(j):= 'COIL_ID: '||to_char(cur_rec.coil_abc_num)||', '||'ABC_JOB_NUM: '||cur_rec.ab_job_num||
			  ', '||'CUSTOMER_NAME: '||cur_rec.customer_short_name||';';
	 j := j + 1;
  end loop;

  log_file_handle :=utl_file.fopen(log_file_location,log_file,'W');

  FOR i IN 0..j-1 LOOP
	utl_file.put_line(log_file_handle,line(i));
  END LOOP;

  utl_file.fclose(log_file_handle);
end if;

end p_check_status_unmatched_coil;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_COILS_WEIGHT_ZEROED_OUT"
       (
	  adt_date_from     date,
	  adt_date_to	    date
       )
is

/*

--drop table coils_weight_zeroed_out

-- Create table
create table coils_weight_zeroed_out
(
  ab_job_num	number(8),
  coil_abc_num	  number(8),
  coil_net_wt	  number(8),
  sum_process_wt  number(10)

)
tablespace SILVERDOME
  pctfree 10
  initrans 1
  maxtrans 255
  storage
  (
    initial 64K
    next 1M
    minextents 1
    maxextents unlimited
  );

create function test_cursor
	    return sys_refcursor
	    is
		    c_result sys_refcursor;
	    begin
		    open c_result for
		    select * from dual;
		    return c_result;
	    end;
*/

ls_customer_name	 customer.customer_short_name%TYPE;
ll_coil_abc_num 	 coil.coil_abc_num%TYPE;
ll_ab_job_num		 ab_job.ab_job_num%TYPE;
ll_coil_net_wt		 coil.net_wt%TYPE;
ll_sum_process_wt	 process_coil.process_quantity%TYPE;
--ls_edi_file		   varchar(50) := 'coils_zeroed_out.txt';
edi_file_handle 	 utl_file.file_type;
--ls_edi_loc		   varchar(500) := '/templar/templar/alex';
ls_line_desc		 line.line_desc%TYPE;
ld_time_date_finished	 ab_job.time_date_finished%TYPE;

  cursor coils_cur is
    select   customer.customer_short_name customer_name,
	     coil.coil_abc_num coil_abc_num,
	     coil.net_wt coil_net_wt,
	     sum(process_coil.process_quantity) sum_process_wt
    from     process_coil
	     join coil on coil.coil_abc_num = process_coil.coil_abc_num
	     join customer on customer.customer_id = coil.customer_id
    where    process_coil_status = 0
    and      process_coil.process_date between adt_date_from and adt_date_to
    group by customer.customer_short_name,
	     coil.coil_abc_num,
	     coil.net_wt
    having   sum(process_coil.process_quantity) > coil.net_wt
    order by customer.customer_short_name,
	     coil.coil_abc_num desc;

  coils_rec coils_cur%ROWTYPE;

  cursor process_coils_cur is
    select   ab_job.ab_job_num,
	     ab_job.time_date_finished,
	     line.line_desc
    from     process_coil
	     join ab_job on ab_job.ab_job_num = process_coil.ab_job_num
	     join line on line.line_num = ab_job.line_num
    where    coil_abc_num = ll_coil_abc_num;

  process_coils_rec process_coils_cur%ROWTYPE;

begin
  delete from coils_weight_zeroed_out;

  --edi_file_handle := utl_file.fopen('/tmp', 'coils.csv', 'W'); --Alex Gerlants. Commented out
								 --because it fails on new server 1.240

  --utl_file.put_line(edi_file_handle, 'Run Time: ' || to_char(sysdate, 'MM/DD/YY HH24:MI'));
  --utl_file.put_line(edi_file_handle, 'Date From: ' || to_char(adt_date_from) || '  Date To: ' || to_char(adt_date_to));
  --utl_file.put_line(edi_file_handle, 'Coils Zeroed Out Report');

  --utl_file.put_line(edi_file_handle, 'Job Num   Coil ABC Num	  Coil Net Wt	 Processed Wt');

  for coils_rec in coils_cur loop
    ls_customer_name := coils_rec.customer_name;
    ll_coil_abc_num := coils_rec.coil_abc_num;
    ll_coil_net_wt := coils_rec.coil_net_wt;
    ll_sum_process_wt := coils_rec.sum_process_wt;

    for process_coils_rec in process_coils_cur loop
      ll_ab_job_num := process_coils_rec.ab_job_num;
      ls_line_desc := process_coils_rec.line_desc;
      ld_time_date_finished := process_coils_rec.time_date_finished;

      --utl_file.put_line(edi_file_handle, to_char(ll_ab_job_num) || '	   ' || to_char(ll_coil_abc_num) || '		' || to_char(ll_coil_net_wt) || '	    ' || to_char(ll_sum_process_wt));

      insert into coils_weight_zeroed_out values
	 (
	    ls_customer_name,
	    ll_coil_abc_num,
	    ll_ab_job_num,
	    ll_coil_net_wt,
	    ll_sum_process_wt,
	    ls_line_desc,
	    ld_time_date_finished
	  );
    end loop;
  end loop;

  commit;

  --utl_file.fclose(edi_file_handle);
end;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_COILS_WEIGHT_ZEROED_OUT_0313"
       (
	  adt_date_from     date,
	  adt_date_to	    date
       )
is

/*

--drop table coils_weight_zeroed_out

-- Create table
create table coils_weight_zeroed_out
(
  ab_job_num	number(8),
  coil_abc_num	  number(8),
  coil_net_wt	  number(8),
  sum_process_wt  number(10)

)
tablespace SILVERDOME
  pctfree 10
  initrans 1
  maxtrans 255
  storage
  (
    initial 64K
    next 1M
    minextents 1
    maxextents unlimited
  );

create function test_cursor
	    return sys_refcursor
	    is
		    c_result sys_refcursor;
	    begin
		    open c_result for
		    select * from dual;
		    return c_result;
	    end;
*/

ls_customer_name	 customer.customer_short_name%TYPE;
ll_coil_abc_num 	 coil.coil_abc_num%TYPE;
ll_ab_job_num		 ab_job.ab_job_num%TYPE;
ll_coil_net_wt		 coil.net_wt%TYPE;
ll_sum_process_wt	 process_coil.process_quantity%TYPE;
--ls_edi_file		   varchar(50) := 'coils_zeroed_out.txt';
edi_file_handle 	 utl_file.file_type;
--ls_edi_loc		   varchar(500) := '/templar/templar/alex';

  cursor coils_cur is
    select   customer.customer_short_name customer_name,
	     coil.coil_abc_num coil_abc_num,
	     coil.net_wt coil_net_wt,
	     sum(process_coil.process_quantity) sum_process_wt
    from     process_coil
	     join coil on coil.coil_abc_num = process_coil.coil_abc_num
	     join customer on customer.customer_id = coil.customer_id
    where    process_coil_status = 0
    and      process_coil.process_date between adt_date_from and adt_date_to
    group by customer.customer_short_name,
	     coil.coil_abc_num,
	     coil.net_wt
    having   sum(process_coil.process_quantity) > coil.net_wt
    order by customer.customer_short_name,
	     coil.coil_abc_num desc;

  coils_rec coils_cur%ROWTYPE;

  cursor process_coils_cur is
    select   ab_job_num
    from     process_coil
    where    coil_abc_num = ll_coil_abc_num;

  process_coils_rec process_coils_cur%ROWTYPE;

begin
  delete from coils_weight_zeroed_out;

  edi_file_handle := utl_file.fopen('/tmp', 'coils.csv', 'W');

  --utl_file.put_line(edi_file_handle, 'Run Time: ' || to_char(sysdate, 'MM/DD/YY HH24:MI'));
  --utl_file.put_line(edi_file_handle, 'Date From: ' || to_char(adt_date_from) || '  Date To: ' || to_char(adt_date_to));
  --utl_file.put_line(edi_file_handle, 'Coils Zeroed Out Report');

  --utl_file.put_line(edi_file_handle, 'Job Num   Coil ABC Num	  Coil Net Wt	 Processed Wt');

  for coils_rec in coils_cur loop
    ls_customer_name := coils_rec.customer_name;
    ll_coil_abc_num := coils_rec.coil_abc_num;
    ll_coil_net_wt := coils_rec.coil_net_wt;
    ll_sum_process_wt := coils_rec.sum_process_wt;

    for process_coils_rec in process_coils_cur loop
      ll_ab_job_num := process_coils_rec.ab_job_num;

      --utl_file.put_line(edi_file_handle, to_char(ll_ab_job_num) || '	   ' || to_char(ll_coil_abc_num) || '		' || to_char(ll_coil_net_wt) || '	    ' || to_char(ll_sum_process_wt));

      insert into coils_weight_zeroed_out
	 (
	    customer_name,
	    coil_abc_num,
	    ab_job_num,
	    coil_net_wt,
	    sum_process_wt
	 )
      values
	 (
	    ls_customer_name,
	    ll_coil_abc_num,
	    ll_ab_job_num,
	    ll_coil_net_wt,
	    ll_sum_process_wt
	  );
    end loop;
  end loop;

  commit;

  --utl_file.fclose(edi_file_handle);
end;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_COILS_WEIGHT_ZEROED_OUT_SAVE"
       (
	  adt_date_from     date,
	  adt_date_to	    date
       )
is

/*

--drop table coils_weight_zeroed_out

-- Create table
create table coils_weight_zeroed_out
(
  ab_job_num	number(8),
  coil_abc_num	  number(8),
  coil_net_wt	  number(8),
  sum_process_wt  number(10)

)
tablespace SILVERDOME
  pctfree 10
  initrans 1
  maxtrans 255
  storage
  (
    initial 64K
    next 1M
    minextents 1
    maxextents unlimited
  );

create function test_cursor
	    return sys_refcursor
	    is
		    c_result sys_refcursor;
	    begin
		    open c_result for
		    select * from dual;
		    return c_result;
	    end;
*/

ls_customer_name	 customer.customer_short_name%TYPE;
ll_coil_abc_num 	 coil.coil_abc_num%TYPE;
ll_ab_job_num		 ab_job.ab_job_num%TYPE;
ll_coil_net_wt		 coil.net_wt%TYPE;
ll_sum_process_wt	 process_coil.process_quantity%TYPE;
--ls_edi_file		   varchar(50) := 'coils_zeroed_out.txt';
edi_file_handle 	 utl_file.file_type;
--ls_edi_loc		   varchar(500) := '/templar/templar/alex';
ls_line_desc		 line.line_desc%TYPE;
ld_time_date_finished	 ab_job.time_date_finished%TYPE;

  cursor coils_cur is
    select   customer.customer_short_name customer_name,
	     coil.coil_abc_num coil_abc_num,
	     coil.net_wt coil_net_wt,
	     sum(process_coil.process_quantity) sum_process_wt
    from     process_coil
	     join coil on coil.coil_abc_num = process_coil.coil_abc_num
	     join customer on customer.customer_id = coil.customer_id
    where    process_coil_status = 0
    and      process_coil.process_date between adt_date_from and adt_date_to
    group by customer.customer_short_name,
	     coil.coil_abc_num,
	     coil.net_wt
    having   sum(process_coil.process_quantity) > coil.net_wt
    order by customer.customer_short_name,
	     coil.coil_abc_num desc;

  coils_rec coils_cur%ROWTYPE;

  cursor process_coils_cur is
    select   ab_job.ab_job_num,
	     ab_job.time_date_finished,
	     line.line_desc
    from     process_coil
	     join ab_job on ab_job.ab_job_num = process_coil.ab_job_num
	     join line on line.line_num = ab_job.line_num
    where    coil_abc_num = ll_coil_abc_num;

  process_coils_rec process_coils_cur%ROWTYPE;

begin
  delete from coils_weight_zeroed_out;

  edi_file_handle := utl_file.fopen('/tmp', 'coils.csv', 'W');

  --utl_file.put_line(edi_file_handle, 'Run Time: ' || to_char(sysdate, 'MM/DD/YY HH24:MI'));
  --utl_file.put_line(edi_file_handle, 'Date From: ' || to_char(adt_date_from) || '  Date To: ' || to_char(adt_date_to));
  --utl_file.put_line(edi_file_handle, 'Coils Zeroed Out Report');

  --utl_file.put_line(edi_file_handle, 'Job Num   Coil ABC Num	  Coil Net Wt	 Processed Wt');

  for coils_rec in coils_cur loop
    ls_customer_name := coils_rec.customer_name;
    ll_coil_abc_num := coils_rec.coil_abc_num;
    ll_coil_net_wt := coils_rec.coil_net_wt;
    ll_sum_process_wt := coils_rec.sum_process_wt;

    for process_coils_rec in process_coils_cur loop
      ll_ab_job_num := process_coils_rec.ab_job_num;
      ls_line_desc := process_coils_rec.line_desc;
      ld_time_date_finished := process_coils_rec.time_date_finished;

      --utl_file.put_line(edi_file_handle, to_char(ll_ab_job_num) || '	   ' || to_char(ll_coil_abc_num) || '		' || to_char(ll_coil_net_wt) || '	    ' || to_char(ll_sum_process_wt));

      insert into coils_weight_zeroed_out values
	 (
	    ls_customer_name,
	    ll_coil_abc_num,
	    ll_ab_job_num,
	    ll_coil_net_wt,
	    ll_sum_process_wt,
	    ls_line_desc,
	    ld_time_date_finished
	  );
    end loop;
  end loop;

  commit;

  --utl_file.fclose(edi_file_handle);
end;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_CREATE_EDI_861_4CONSTELLIUM" IS
  /*
  This function creates ALCAN EDI861s for all edi_file_id/bol, which has not been sent yet but had all
  coils processed (either imported or marked damaged). It also sends the edi with a shipment received time.
  Then updates the inbound_shipment_status table.

  edi_file_id and bol are from inbound_shipment table, received_time is generated the current moment by the system.

  This function will be called from the cron job in the OS, runs periodically.
  */

  TYPE edi_861_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  edi_861 edi_861_tabletype;
  j	  BINARY_INTEGER;
  i	  INTEGER;
  --edi_file_prefix VARCHAR2(50) := 'S_edi_';
  edi_file_prefix VARCHAR2(50) := 'alex_edi_';

  --collect all not-sent-yet record in inbound_shipment_status
  CURSOR not_sent_cursor IS
    SELECT ss.bol, ss.edi_file_id
      FROM inbound_shipment_status   ss,
	   inbound_shipment	     s,
	   inbound_shipment_customer c
     WHERE ss.edi_file_id = s.edi_file_id
       AND ss.bol = s.bol
       AND s.ship_from = c.ship_from
       AND c.customer_id in (select customer_id from customer where lower(customer_full_name) like '%constellium%')
       AND -- customers for 861
	   ss.status = 3;
  /*cursor not_sent_cursor is
  select bol, edi_file_id
  from inbound_shipment_status
  where status = 3 ;*/

  CURSOR coil_status_cursor(par_bol VARCHAR2, par_edi_file_id INTEGER) IS
    SELECT status
      FROM inbound_coil_status
     WHERE bol = par_bol
       AND edi_file_id = par_edi_file_id;

  CURSOR bol_and_edi_file_id_cursor(par_bol	    VARCHAR2,
				    par_edi_file_id INTEGER) IS
    SELECT a.coil_number,
	   a.temper,
	   a.net_weight,
	   a.gross_weight,
	   a.lineal_feed,
	   a.coil_width,
	   a.coil_gauge,
	   a.density,
	   a.lot,
	   a.pack_id,
	   a.alloy,
	   a.ps_coil_number,
	   b.damaged_code,
	   b.damaged_fault
      FROM inbound_coil a, inbound_coil_status b
     WHERE a.bol = par_bol
       AND a.edi_file_id = par_edi_file_id
       AND a.bol = b.bol
       AND a.edi_file_id = b.edi_file_id
       AND a.item_num = b.item_num;

  li_coil_ready  INTEGER;
  li_gs_log	 INTEGER;
  li_st_log	 INTEGER;
  ls_today_short VARCHAR2(20);
  ls_today	 VARCHAR2(20);
  ls_now	 VARCHAR2(20);

  ld_received_time  DATE;
  ls_received_time  VARCHAR2(13);
  li_customer_id    INT;
  ls_po 	    VARCHAR2(20);
  ls_part_num	    VARCHAR2(40);
  ls_coil_number    VARCHAR2(40);
  ls_ps_coil_number VARCHAR2(40);
  ls_temper	    VARCHAR2(8);
  ln_net_weight     NUMBER(8, 0);
  ln_gross_weight   NUMBER(8, 0);
  ln_lineal_feed    NUMBER(7, 2);
  ln_coil_width     NUMBER(7, 2);
  ln_coil_gauge     NUMBER(5, 4);
  ln_density	    NUMBER;
  ls_lot	    VARCHAR2(40);
  ls_pack_id	    VARCHAR2(40);
  ls_alloy	    VARCHAR2(40);
  ln_damage_fault   NUMBER(1);
  ln_damage_code    NUMBER(3);

--  edi_location    VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_location	  VARCHAR2(50) := get_edi_destination('EDI_DIR'); -- 11/15/2016 Patrick Reynolds
  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_handle utl_file.file_type;
  li_edi_861_id   INTEGER;
  ls_dun	  VARCHAR2(32);
  ls_ship_from	  VARCHAR2(40);

  coil_count INTEGER;

  li_coil_abc_num INTEGER;

  li_count INTEGER;
BEGIN
  --create one EDI861 file for each selected edi_file_id/bol.
  FOR not_sent_cloop IN not_sent_cursor LOOP

    li_coil_ready := 0;

    --if not all coils are imported or mark damaged yet, don't send them
    FOR coil_status_cloop IN coil_status_cursor(not_sent_cloop.bol,
						not_sent_cloop.edi_file_id) LOOP
      IF (coil_status_cloop.status = 1 OR coil_status_cloop.status = 2) THEN
	--status 1:imported  2:marked damaged
	li_coil_ready := 1;
      ELSE
	li_coil_ready := 0;
      END IF;
      EXIT WHEN li_coil_ready = 0;
    END LOOP;

    coil_count := 0;
    j	       := 0;

    IF (li_coil_ready = 1) THEN
      SELECT edi_st_log_seq.nextval INTO li_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO li_gs_log FROM dual;
      ls_today_short := to_char(SYSDATE, 'yymmdd');
      ls_today	     := to_char(SYSDATE, 'yyyymmdd');
      ls_now	     := to_char(SYSDATE, 'hh24mi');

      SELECT po, part_number
	INTO ls_po, ls_part_num
	FROM inbound_shipment
       WHERE bol = not_sent_cloop.bol
	 AND edi_file_id = not_sent_cloop.edi_file_id;

      /*ld_received_time := sysdate;   --set the received time as current system time*/
      SELECT COUNT(*)
	INTO li_count
	FROM receiving_bol r
       WHERE r.bol = not_sent_cloop.bol;

      IF li_count = 1 THEN
	SELECT nvl(r.received_date, SYSDATE)
	  INTO ld_received_time
	  FROM receiving_bol r
	 WHERE r.bol = not_sent_cloop.bol;
      ELSE
	ld_received_time := SYSDATE;
      END IF;

      ls_received_time := to_char(ld_received_time, 'yyyymmdd*hh24mi'); --need this format in EDI861 file

      --edi_861(j) := 'ISA*00*		*00*	      *01*039630926T	 *ZZ*043207177	    *' ||
      --	      ls_today_short || '*' || ls_now || '*U*00200*' ||
      --	      lpad(to_char(li_gs_log), 9, '0') || '*0*P*>';

      edi_861(j) := 'ISA*00*	      *00*	    *01*039630926T     *ZZ*043207177	  *' ||
		    ls_today_short || '*' || ls_now || '*U*00200*' ||
		    lpad(to_char(li_gs_log), 9, '0') || '*0*T*>';

      j := j + 1;
      edi_861(j) := 'GS*RC*039630926T*043207177*' || ls_today || '*' ||
		    ls_now || '*' || li_gs_log || '*X*004010';
      j := j + 1;
      edi_861(j) := 'ST*861*' || li_st_log;
      j := j + 1;
      edi_861(j) := 'BRA*' || not_sent_cloop.bol || '*' || ls_today ||
		    '*00*1*' || ls_now;
      j := j + 1;
      edi_861(j) := 'REF*BM*' || not_sent_cloop.bol;
      j := j + 1;
      edi_861(j) := 'DTM*050*' || ls_received_time || '*ED';
      j := j + 1;
      edi_861(j) := 'N1*OU**1*039630926';
      j := j + 1;
      edi_861(j) := 'N1*MF*Constellium*1*043207177';
      j := j + 1;

      SELECT ship_from
	INTO ls_ship_from
	FROM inbound_shipment
       WHERE edi_file_id = not_sent_cloop.edi_file_id
	 AND bol = not_sent_cloop.bol;
      SELECT customer_id
	INTO li_customer_id
	FROM inbound_shipment_customer
       WHERE ship_from = ls_ship_from;

      SELECT customer.customer_duns_number_string
	INTO ls_dun
	FROM customer
       WHERE customer.customer_id = li_customer_id;

      /*if li_customer_id = 1153 then
	 ls_dun := '241003755';--'Novelis Kingston'
      elsif  li_customer_id = 1459 then
	 ls_dun := '003980216';--'Novelis Oswego'
      else
	 ls_dun := '241003755';
      end if;*/

      edi_861(j) := 'N1*SU**1*' || ls_dun;
      j := j + 1;

      FOR cloop IN bol_and_edi_file_id_cursor(not_sent_cloop.bol,
					      not_sent_cloop.edi_file_id) LOOP
	ls_coil_number	  := cloop.coil_number;
	ls_temper	  := cloop.temper;
	ln_net_weight	  := cloop.net_weight;
	ln_gross_weight   := cloop.gross_weight;
	ln_lineal_feed	  := cloop.lineal_feed;
	ln_coil_width	  := cloop.coil_width;
	ln_coil_gauge	  := cloop.coil_gauge;
	ln_density	  := cloop.density;
	ls_lot		  := cloop.lot;
	ls_pack_id	  := cloop.pack_id;
	ls_alloy	  := cloop.alloy;
	ls_ps_coil_number := cloop.ps_coil_number;
	ln_damage_fault   := cloop.damaged_fault;
	ln_damage_code	  := cloop.damaged_code;

	IF (ls_ps_coil_number IS NULL) OR (length(ls_ps_coil_number) = 0) THEN
	  ls_ps_coil_number := ls_coil_number;
	END IF;

	edi_861(j) := 'RCD**1*CX';
	j := j + 1;
	edi_861(j) := 'LIN**VO*' || ls_po || '*BP*' || ls_part_num ||
		      '*HN*' || ls_lot || '*SN*' || ls_coil_number;
	j := j + 1;
	edi_861(j) := 'PID*S*MAC*ST*01';
	j := j + 1;
	edi_861(j) := 'PID*S*MA*ST*7';
	j := j + 1;

	--add these two segments only for damaged coils
	IF ln_damage_code <> 0 THEN
	  edi_861(j) := 'PID*S*DAC*ST*' || ln_damage_code;
	  j := j + 1;
	END IF;
	IF ln_damage_fault <> 0 THEN
	  /* DAF??? */
	  edi_861(j) := 'PID*S*DAF*ST*' || ln_damage_fault;
	  j := j + 1;
	END IF;

	edi_861(j) := 'PID*S*QAS*ST*2';
	j := j + 1;

	SELECT COUNT(*)
	  INTO li_count
	  FROM coil c
	 WHERE c.coil_org_num = ls_coil_number
	   AND c.coil_mid_num = ls_pack_id
	   AND c.customer_id = 1980;

	IF li_count = 1 THEN
	  SELECT nvl(c.coil_abc_num, 0)
	    INTO li_coil_abc_num
	    FROM coil c
	   WHERE c.coil_org_num = ls_coil_number
	     AND c.coil_mid_num = ls_pack_id
	     AND c.customer_id = 1980;
	ELSE
	  li_coil_abc_num := 0;
	END IF;

	edi_861(j) := 'REF*SE*' || to_char(li_coil_abc_num);
	j := j + 1;
	edi_861(j) := 'REF*RV*' || ls_ps_coil_number;
	j := j + 1;
	edi_861(j) := 'PRF*' || ls_po;
	j := j + 1;
	edi_861(j) := 'MEA*WT*WT*' || ln_net_weight || '*01';
	j := j + 1;
	edi_861(j) := 'MEA*WT**' || ln_gross_weight || '*24';
	j := j + 1;
	edi_861(j) := 'MEA*PD*TH*' || to_char(ln_coil_gauge, 'FM90.0000') ||
		      '*IN';
	j := j + 1;
	edi_861(j) := 'MEA*PD*WD*' ||
		      to_char(ln_coil_width, 'FM99990.0000') || '*IN';
	j := j + 1;
	edi_861(j) := 'MEA*CT**' || ln_lineal_feed || '*LF';
	j := j + 1;

	coil_count := coil_count + 1;
      END LOOP;

      edi_861(j) := 'CTT*' || coil_count;
      j := j + 1;
      edi_861(j) := 'SE*' || to_char(j - 1) || '*' || li_st_log;
      j := j + 1;
      edi_861(j) := 'GE*1*' || li_gs_log;
      j := j + 1;
      edi_861(j) := 'IEA*1*' || lpad(to_char(li_gs_log), 9, '0');

      IF coil_count > 0 THEN
	SELECT edi_file_id_seq.nextval INTO li_edi_861_id FROM dual;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--	edi_file	:= 's_edi_' || to_char(li_edi_861_id) || '.861';
	edi_file	:= edi_file_prefix || to_char(li_edi_861_id) || '.edi';
	edi_file_handle := utl_file.fopen(edi_location, edi_file, 'W');
	--write edi to file
	FOR i IN 0 .. j LOOP
	  utl_file.put_line(edi_file_handle, edi_861(i));
	END LOOP;
	utl_file.fclose(edi_file_handle);

	/*--added by Victor Huang on 06/05 for function acknowlegement
	 INSERT INTO edi_fa(gs_num, duns_num, send_time,edi_file_name)
	 VALUES(li_gs_log, ls_dun, sysdate, edi_file);
	 COMMIT;
	*/
	--added by Victor Huang on 12/07 for verifying 997
	INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (li_edi_861_id,
	   '039630926',
	   ls_dun,
	   li_gs_log,
	   li_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   li_customer_id,
	   li_st_log,
	   '861');
	COMMIT;

	edi_file	:= 'send_edi_log';
	edi_file_handle := utl_file.fopen(edi_location, edi_file, 'a');
	utl_file.put_line(edi_file_handle, 'Type: 861');
	utl_file.put_line(edi_file_handle,
			  'Sending Time: ' ||
			  to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
	utl_file.put_line(edi_file_handle,
			  'Interchange Control #: ' || li_gs_log);
	utl_file.put_line(edi_file_handle,
			  'Group Control #: ' || li_gs_log);
	utl_file.put_line(edi_file_handle, 'Set Control #: ' || li_st_log);
	utl_file.put_line(edi_file_handle, '');
	utl_file.put_line(edi_file_handle, '');
	utl_file.fclose(edi_file_handle);

	UPDATE inbound_shipment_status
	   SET status = 1
	 WHERE bol = not_sent_cloop.bol
	   AND edi_file_id = not_sent_cloop.edi_file_id;

	COMMIT;
      END IF;
    END IF;
  END LOOP; --loop end for edi_file_id/bol

  RETURN;

EXCEPTION
  WHEN dup_val_on_index THEN
    ROLLBACK;
    RETURN;
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;

END p_create_edi_861_4constellium;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_CREATE_EDI_861_FOR_ALERIS" IS
  /*
  This function creates ALCAN EDI861s for all edi_file_id/bol, which has not been sent yet but had all
  coils processed (either imported or marked damaged). It also sends the edi with a shipment received time.
  Then updates the inbound_shipment_status table.

  edi_file_id and bol are from inbound_shipment table, received_time is generated the current moment by the system.

  This function will be called from the cron job in the OS, runs periodically.
  */

  TYPE edi_861_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  edi_861 edi_861_tabletype;
  j	  BINARY_INTEGER;
  i	  INTEGER;
  edi_file_prefix VARCHAR2(50) := 'S_edi_';

  --collect all not-sent-yet record in inbound_shipment_status
  CURSOR not_sent_cursor IS
    SELECT ss.bol, ss.edi_file_id
      FROM inbound_shipment_status   ss,
	   inbound_shipment	     s,
	   inbound_shipment_customer c
     WHERE ss.edi_file_id = s.edi_file_id
       AND ss.bol = s.bol
       AND s.ship_from = c.ship_from
       AND c.customer_id = 1980
       AND -- customers for 861
	   ss.status = 3;
  /*cursor not_sent_cursor is
  select bol, edi_file_id
  from inbound_shipment_status
  where status = 3 ;*/

  CURSOR coil_status_cursor(par_bol VARCHAR2, par_edi_file_id INTEGER) IS
    SELECT status
      FROM inbound_coil_status
     WHERE bol = par_bol
       AND edi_file_id = par_edi_file_id;

  CURSOR bol_and_edi_file_id_cursor(par_bol	    VARCHAR2,
				    par_edi_file_id INTEGER) IS
    SELECT a.coil_number,
	   a.temper,
	   a.net_weight,
	   a.gross_weight,
	   a.lineal_feed,
	   a.coil_width,
	   a.coil_gauge,
	   a.density,
	   a.lot,
	   a.pack_id,
	   a.alloy,
	   a.ps_coil_number,
	   b.damaged_code,
	   b.damaged_fault
      FROM inbound_coil a, inbound_coil_status b
     WHERE a.bol = par_bol
       AND a.edi_file_id = par_edi_file_id
       AND a.bol = b.bol
       AND a.edi_file_id = b.edi_file_id
       AND a.item_num = b.item_num;

  li_coil_ready  INTEGER;
  li_gs_log	 INTEGER;
  li_st_log	 INTEGER;
  ls_today_short VARCHAR2(20);
  ls_today	 VARCHAR2(20);
  ls_now	 VARCHAR2(20);

  ld_received_time  DATE;
  ls_received_time  VARCHAR2(13);
  li_customer_id    INT;
  ls_po 	    VARCHAR2(20);
  ls_part_num	    VARCHAR2(40);
  ls_coil_number    VARCHAR2(40);
  ls_ps_coil_number VARCHAR2(40);
  ls_temper	    VARCHAR2(8);
  ln_net_weight     NUMBER(8, 0);
  ln_gross_weight   NUMBER(8, 0);
  ln_lineal_feed    NUMBER(7, 2);
  ln_coil_width     NUMBER(7, 2);
  ln_coil_gauge     NUMBER(5, 4);
  ln_density	    NUMBER;
  ls_lot	    VARCHAR2(40);
  ls_pack_id	    VARCHAR2(40);
  ls_alloy	    VARCHAR2(40);
  ln_damage_fault   NUMBER(1);
  ln_damage_code    NUMBER(3);

  edi_location	  VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_handle utl_file.file_type;
  li_edi_861_id   INTEGER;
  ls_dun	  VARCHAR2(32);
  ls_ship_from	  VARCHAR2(40);

  coil_count INTEGER;

  li_coil_abc_num INTEGER;

  li_count INTEGER;
BEGIN
  --create one EDI861 file for each selected edi_file_id/bol.
  FOR not_sent_cloop IN not_sent_cursor LOOP

    li_coil_ready := 0;

    --if not all coils are imported or mark damaged yet, don't send them
    FOR coil_status_cloop IN coil_status_cursor(not_sent_cloop.bol,
						not_sent_cloop.edi_file_id) LOOP
      IF (coil_status_cloop.status = 1 OR coil_status_cloop.status = 2) THEN
	--status 1:imported  2:marked damaged
	li_coil_ready := 1;
      ELSE
	li_coil_ready := 0;
      END IF;
      EXIT WHEN li_coil_ready = 0;
    END LOOP;

    coil_count := 0;
    j	       := 0;

    IF (li_coil_ready = 1) THEN
      SELECT edi_st_log_seq.nextval INTO li_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO li_gs_log FROM dual;
      ls_today_short := to_char(SYSDATE, 'yymmdd');
      ls_today	     := to_char(SYSDATE, 'yyyymmdd');
      ls_now	     := to_char(SYSDATE, 'hh24mi');

      SELECT po, part_number
	INTO ls_po, ls_part_num
	FROM inbound_shipment
       WHERE bol = not_sent_cloop.bol
	 AND edi_file_id = not_sent_cloop.edi_file_id;

      /*ld_received_time := sysdate;   --set the received time as current system time*/
      SELECT COUNT(*)
	INTO li_count
	FROM receiving_bol r
       WHERE r.bol = not_sent_cloop.bol;

      IF li_count = 1 THEN
	SELECT nvl(r.received_date, SYSDATE)
	  INTO ld_received_time
	  FROM receiving_bol r
	 WHERE r.bol = not_sent_cloop.bol;
      ELSE
	ld_received_time := SYSDATE;
      END IF;

      ls_received_time := to_char(ld_received_time, 'yyyymmdd*hh24mi'); --need this format in EDI861 file

      edi_861(j) := 'ISA*00*	      *00*	    *01*039630926T     *ZZ*964790856	  *' ||
		    ls_today_short || '*' || ls_now || '*U*00200*' ||
		    lpad(to_char(li_gs_log), 9, '0') || '*0*P*>';
      j := j + 1;
      edi_861(j) := 'GS*RC*039630926T*964790856*' || ls_today || '*' ||
		    ls_now || '*' || li_gs_log || '*X*004010';
      j := j + 1;
      edi_861(j) := 'ST*861*' || li_st_log;
      j := j + 1;
      edi_861(j) := 'BRA*' || not_sent_cloop.bol || '*' || ls_today ||
		    '*00*1*' || ls_now;
      j := j + 1;
      edi_861(j) := 'REF*BM*' || not_sent_cloop.bol;
      j := j + 1;
      edi_861(j) := 'DTM*050*' || ls_received_time || '*ED';
      j := j + 1;
      edi_861(j) := 'N1*OU**1*039630926';
      j := j + 1;
      edi_861(j) := 'N1*MF*Aleris*1*964790856';
      j := j + 1;

      SELECT ship_from
	INTO ls_ship_from
	FROM inbound_shipment
       WHERE edi_file_id = not_sent_cloop.edi_file_id
	 AND bol = not_sent_cloop.bol;
      SELECT customer_id
	INTO li_customer_id
	FROM inbound_shipment_customer
       WHERE ship_from = ls_ship_from;

      SELECT customer.customer_duns_number_string
	INTO ls_dun
	FROM customer
       WHERE customer.customer_id = li_customer_id;

      /*if li_customer_id = 1153 then
	 ls_dun := '241003755';--'Novelis Kingston'
      elsif  li_customer_id = 1459 then
	 ls_dun := '003980216';--'Novelis Oswego'
      else
	 ls_dun := '241003755';
      end if;*/

      edi_861(j) := 'N1*SU**1*' || ls_dun;
      j := j + 1;

      FOR cloop IN bol_and_edi_file_id_cursor(not_sent_cloop.bol,
					      not_sent_cloop.edi_file_id) LOOP
	ls_coil_number	  := cloop.coil_number;
	ls_temper	  := cloop.temper;
	ln_net_weight	  := cloop.net_weight;
	ln_gross_weight   := cloop.gross_weight;
	ln_lineal_feed	  := cloop.lineal_feed;
	ln_coil_width	  := cloop.coil_width;
	ln_coil_gauge	  := cloop.coil_gauge;
	ln_density	  := cloop.density;
	ls_lot		  := cloop.lot;
	ls_pack_id	  := cloop.pack_id;
	ls_alloy	  := cloop.alloy;
	ls_ps_coil_number := cloop.ps_coil_number;
	ln_damage_fault   := cloop.damaged_fault;
	ln_damage_code	  := cloop.damaged_code;

	IF (ls_ps_coil_number IS NULL) OR (length(ls_ps_coil_number) = 0) THEN
	  ls_ps_coil_number := ls_coil_number;
	END IF;

	edi_861(j) := 'RCD**1*CX';
	j := j + 1;
	edi_861(j) := 'LIN**VO*' || ls_po || '*BP*' || ls_part_num ||
		      '*HN*' || ls_lot || '*SN*' || ls_coil_number;
	j := j + 1;
	edi_861(j) := 'PID*S*MAC*ST*01';
	j := j + 1;
	edi_861(j) := 'PID*S*MA*ST*7';
	j := j + 1;

	--add these two segments only for damaged coils
	IF ln_damage_code <> 0 THEN
	  edi_861(j) := 'PID*S*DAC*ST*' || ln_damage_code;
	  j := j + 1;
	END IF;
	IF ln_damage_fault <> 0 THEN
	  /* DAF??? */
	  edi_861(j) := 'PID*S*DAF*ST*' || ln_damage_fault;
	  j := j + 1;
	END IF;

	edi_861(j) := 'PID*S*QAS*ST*2';
	j := j + 1;

	SELECT COUNT(*)
	  INTO li_count
	  FROM coil c
	 WHERE c.coil_org_num = ls_coil_number
	   AND c.coil_mid_num = ls_pack_id
	   AND c.customer_id = 1980;

	IF li_count = 1 THEN
	  SELECT nvl(c.coil_abc_num, 0)
	    INTO li_coil_abc_num
	    FROM coil c
	   WHERE c.coil_org_num = ls_coil_number
	     AND c.coil_mid_num = ls_pack_id
	     AND c.customer_id = 1980;
	ELSE
	  li_coil_abc_num := 0;
	END IF;

	edi_861(j) := 'REF*SE*' || to_char(li_coil_abc_num);
	j := j + 1;
	edi_861(j) := 'REF*RV*' || ls_ps_coil_number;
	j := j + 1;
	edi_861(j) := 'PRF*' || ls_po;
	j := j + 1;
	edi_861(j) := 'MEA*WT*WT*' || ln_net_weight || '*01';
	j := j + 1;
	edi_861(j) := 'MEA*WT**' || ln_gross_weight || '*24';
	j := j + 1;
	edi_861(j) := 'MEA*PD*TH*' || to_char(ln_coil_gauge, 'FM90.0000') ||
		      '*IN';
	j := j + 1;
	edi_861(j) := 'MEA*PD*WD*' ||
		      to_char(ln_coil_width, 'FM99990.0000') || '*IN';
	j := j + 1;
	edi_861(j) := 'MEA*CT**' || ln_lineal_feed || '*LF';
	j := j + 1;

	coil_count := coil_count + 1;
      END LOOP;

      edi_861(j) := 'CTT*' || coil_count;
      j := j + 1;
      edi_861(j) := 'SE*' || to_char(j - 1) || '*' || li_st_log;
      j := j + 1;
      edi_861(j) := 'GE*1*' || li_gs_log;
      j := j + 1;
      edi_861(j) := 'IEA*1*' || lpad(to_char(li_gs_log), 9, '0');

      IF coil_count > 0 THEN
	SELECT edi_file_id_seq.nextval INTO li_edi_861_id FROM dual;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--	edi_file	:= 's_edi_' || to_char(li_edi_861_id) || '.861';
	edi_file	:= edi_file_prefix || to_char(li_edi_861_id) || '.edi';
	edi_file_handle := utl_file.fopen(edi_location, edi_file, 'W');
	--write edi to file
	FOR i IN 0 .. j LOOP
	  utl_file.put_line(edi_file_handle, edi_861(i));
	END LOOP;
	utl_file.fclose(edi_file_handle);

	/*--added by Victor Huang on 06/05 for function acknowlegement
	 INSERT INTO edi_fa(gs_num, duns_num, send_time,edi_file_name)
	 VALUES(li_gs_log, ls_dun, sysdate, edi_file);
	 COMMIT;
	*/
	--added by Victor Huang on 12/07 for verifying 997
	INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (li_edi_861_id,
	   '039630926',
	   ls_dun,
	   li_gs_log,
	   li_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   li_customer_id,
	   li_st_log,
	   '861');
	COMMIT;

	edi_file	:= 'send_edi_log';
	edi_file_handle := utl_file.fopen(edi_location, edi_file, 'a');
	utl_file.put_line(edi_file_handle, 'Type: 861');
	utl_file.put_line(edi_file_handle,
			  'Sending Time: ' ||
			  to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
	utl_file.put_line(edi_file_handle,
			  'Interchange Control #: ' || li_gs_log);
	utl_file.put_line(edi_file_handle,
			  'Group Control #: ' || li_gs_log);
	utl_file.put_line(edi_file_handle, 'Set Control #: ' || li_st_log);
	utl_file.put_line(edi_file_handle, '');
	utl_file.put_line(edi_file_handle, '');
	utl_file.fclose(edi_file_handle);

	UPDATE inbound_shipment_status
	   SET status = 1
	 WHERE bol = not_sent_cloop.bol
	   AND edi_file_id = not_sent_cloop.edi_file_id;

	COMMIT;
      END IF;
    END IF;
  END LOOP; --loop end for edi_file_id/bol

  RETURN;

EXCEPTION
  WHEN dup_val_on_index THEN
    ROLLBACK;
    RETURN;
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;

END p_create_edi_861_for_aleris;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_CREATE_EDI_861_FOR_ALL" IS
  /*
  This function creates ALCAN EDI861s for all edi_file_id/bol, which have not been sent yet but had all
  coils processed (either imported or marked damaged). It also send the edi with a shipment received time.
  Then it updates the inbound_shipment_status table.

  edi_file_id and bol are from inbound_shipment table, received_time is generated the current moment by the system.

  This function will be called from the cron job in the OS, runs periodically.
  */

  TYPE edi_861_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  edi_861 edi_861_tabletype;
  j	  BINARY_INTEGER;
  i	  INTEGER;
  skip_edi INTEGER := 1;
  edi_file_prefix VARCHAR2(50) := 'S_Novelis_';

  --collect all not-sent-yet record in inbound_shipment_status
  CURSOR not_sent_cursor IS
    SELECT ss.bol, ss.edi_file_id
      FROM inbound_shipment_status   ss,
	   inbound_shipment	     s,
	   inbound_shipment_customer c
     WHERE ss.edi_file_id = s.edi_file_id
       AND ss.bol = s.bol
       AND s.ship_from = c.ship_from
       AND c.customer_id IN (1153, 1459, 2582)
       AND -- customers for 861
	   ss.status = 3;
  /*cursor not_sent_cursor is
  select bol, edi_file_id
  from inbound_shipment_status
  where status = 3 ;*/

  CURSOR coil_status_cursor(par_bol VARCHAR2, par_edi_file_id INTEGER) IS
    SELECT status
      FROM inbound_coil_status
     WHERE bol = par_bol
       AND edi_file_id = par_edi_file_id;

  CURSOR bol_and_edi_file_id_cursor(par_bol	    VARCHAR2,
				    par_edi_file_id INTEGER) IS
    SELECT a.coil_number,
	   a.temper,
	   a.net_weight,
	   a.gross_weight,
	   a.lineal_feed,
	   a.coil_width,
	   a.coil_gauge,
	   a.density,
	   a.lot,
	   a.pack_id,
	   a.alloy,
	   a.ps_coil_number,
	   b.damaged_code,
	   b.damaged_fault
      FROM inbound_coil a, inbound_coil_status b
     WHERE a.bol = par_bol
       AND a.edi_file_id = par_edi_file_id
       AND a.bol = b.bol
       AND a.edi_file_id = b.edi_file_id
       AND a.item_num = b.item_num;

  li_coil_ready  INTEGER;
  li_gs_log	 INTEGER;
  li_st_log	 INTEGER;
  ls_today_short VARCHAR2(20);
  ls_today	 VARCHAR2(20);
  ls_now	 VARCHAR2(20);

  ld_received_time  DATE;
  ls_received_time  VARCHAR2(13);
  li_customer_id    INT;
  ls_po 	    VARCHAR2(20);
  ls_coil_number    VARCHAR2(40);
  ls_ps_coil_number VARCHAR2(40);
  ls_temper	    VARCHAR2(8);
  ln_net_weight     NUMBER(8, 0);
  ln_gross_weight   NUMBER(8, 0);
  ln_lineal_feed    NUMBER(7, 2);
  ln_coil_width     NUMBER(7, 2);
  ln_coil_gauge     NUMBER(5, 4);
  ln_density	    NUMBER;
  ls_lot	    VARCHAR2(40);
  ls_pack_id	    VARCHAR2(40);
  ls_alloy	    VARCHAR2(40);
  ln_damage_fault   NUMBER(1);
  ln_damage_code    NUMBER(3);

  edi_location	  VARCHAR2(50) := '/templar/templar/incoming/senddata';
  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_handle utl_file.file_type;
  li_edi_861_id   INTEGER;
  ls_dun	  VARCHAR2(32);
  ls_ship_from	  VARCHAR2(40);

  coil_count INTEGER;

  li_coil_abc_num INTEGER;

  li_count INTEGER;
BEGIN
  --create one EDI861 file for each selected edi_file_id/bol.
  FOR not_sent_cloop IN not_sent_cursor LOOP

    li_coil_ready := 0;

    --if not all coils are imported or mark damaged yet, don't send them
    FOR coil_status_cloop IN coil_status_cursor(not_sent_cloop.bol,
						not_sent_cloop.edi_file_id) LOOP
      IF (coil_status_cloop.status = 1 OR coil_status_cloop.status = 2) THEN
	--status 1:imported  2:marked damaged
	li_coil_ready := 1;
      ELSE
	li_coil_ready := 0;
      END IF;
      EXIT WHEN li_coil_ready = 0;
    END LOOP;

    coil_count := 0;
    j	       := 0;

    IF (li_coil_ready = 1) THEN
      SELECT edi_st_log_seq.nextval INTO li_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO li_gs_log FROM dual;
      ls_today_short := to_char(SYSDATE, 'yymmdd');
      ls_today	     := to_char(SYSDATE, 'yyyymmdd');
      ls_now	     := to_char(SYSDATE, 'hh24mi');

      SELECT po
	INTO ls_po
	FROM inbound_shipment
       WHERE bol = not_sent_cloop.bol
	 AND edi_file_id = not_sent_cloop.edi_file_id;

      /*ld_received_time := sysdate;   --set the received time as current system time*/
      SELECT COUNT(*)
	INTO li_count
	FROM receiving_bol r
       WHERE r.bol = not_sent_cloop.bol;

      IF li_count = 1 THEN
	SELECT nvl(r.received_date, SYSDATE)
	  INTO ld_received_time
	  FROM receiving_bol r
	 WHERE r.bol = not_sent_cloop.bol;
      ELSE
	ld_received_time := SYSDATE;
      END IF;

      ls_received_time := to_char(ld_received_time, 'yyyymmdd*hh24mi'); --need this format in EDI861 file

      edi_861(j) := 'ISA*00*	      *00*	    *01*039630926T     *09*0015049350011G *' ||
		    ls_today_short || '*' || ls_now || '*U*00200*' ||
		    lpad(to_char(li_gs_log), 9, '0') || '*0*P**';
      j := j + 1;
      edi_861(j) := 'GS*RC*039630926T*0015049350011G*' || ls_today || '*' ||
		    ls_now || '*' || li_gs_log || '*X*004010';
      j := j + 1;
      edi_861(j) := 'ST*861*' || li_st_log;
      j := j + 1;
      edi_861(j) := 'BRA*' || not_sent_cloop.bol || '*' || ls_today ||
		    '*00*1*' || ls_now;
      j := j + 1;
      edi_861(j) := 'DTM*050*' || ls_received_time || '*ED';
      j := j + 1;
      edi_861(j) := 'N1*OU**1*039630926';
      j := j + 1;

      SELECT ship_from
	INTO ls_ship_from
	FROM inbound_shipment
       WHERE edi_file_id = not_sent_cloop.edi_file_id
	 AND bol = not_sent_cloop.bol;
      SELECT customer_id
	INTO li_customer_id
	FROM inbound_shipment_customer
       WHERE ship_from = ls_ship_from;

      SELECT customer.customer_duns_number_string
	INTO ls_dun
	FROM customer
       WHERE customer.customer_id = li_customer_id;

      /*if li_customer_id = 1153 then
	 ls_dun := '241003755';--'Novelis Kingston'
      elsif  li_customer_id = 1459 then
	 ls_dun := '003980216';--'Novelis Oswego'
      else
	 ls_dun := '241003755';
      end if;*/

      edi_861(j) := 'N1*SU**1*' || ls_dun;
      j := j + 1;

      FOR cloop IN bol_and_edi_file_id_cursor(not_sent_cloop.bol,
					      not_sent_cloop.edi_file_id) LOOP
	ls_coil_number	  := cloop.coil_number;
	ls_temper	  := cloop.temper;
	ln_net_weight	  := cloop.net_weight;
	ln_gross_weight   := cloop.gross_weight;
	ln_lineal_feed	  := cloop.lineal_feed;
	ln_coil_width	  := cloop.coil_width;
	ln_coil_gauge	  := cloop.coil_gauge;
	ln_density	  := cloop.density;
	ls_lot		  := cloop.lot;
	ls_pack_id	  := cloop.pack_id;
	ls_alloy	  := cloop.alloy;
	ls_ps_coil_number := cloop.ps_coil_number;
	ln_damage_fault   := cloop.damaged_fault;
	ln_damage_code	  := cloop.damaged_code;

	IF (ls_ps_coil_number IS NULL) OR (length(ls_ps_coil_number) = 0) THEN
	  ls_ps_coil_number := ls_coil_number;
	END IF;

	edi_861(j) := 'RCD**1*CX';
	j := j + 1;
	edi_861(j) := 'LIN**VO*' || ls_po || '*SN*' || ls_coil_number ||
		      '*HN*' || ls_lot || '*PK*' || ls_pack_id;
	j := j + 1;
	edi_861(j) := 'PID*S*MAC*ST*01';
	j := j + 1;
	edi_861(j) := 'PID*S*MA*ST*7';
	j := j + 1;

	--add these two segments only for damaged coils
	IF ln_damage_code <> 0 THEN
	  edi_861(j) := 'PID*S*DAC*ST*' || ln_damage_code;
	  j := j + 1;
	END IF;
	IF ln_damage_fault <> 0 THEN
	  /* DAF??? */
	  edi_861(j) := 'PID*S*DAF*ST*' || ln_damage_fault;
	  j := j + 1;
	END IF;

	edi_861(j) := 'PID*S*QAS*ST*2';
	j := j + 1;

	SELECT COUNT(*)
	  INTO li_count
	  FROM coil c
	 WHERE c.coil_org_num = ls_coil_number
	   AND c.coil_mid_num = ls_pack_id
	   AND c.customer_id IN (1153, 1459);

	IF li_count = 1 THEN
	  SELECT nvl(c.coil_abc_num, 0)
	    INTO li_coil_abc_num
	    FROM coil c
	   WHERE c.coil_org_num = ls_coil_number
	     AND c.coil_mid_num = ls_pack_id
	     AND c.customer_id IN (1153, 1459);
	ELSE
	  li_coil_abc_num := 0;
	END IF;

	edi_861(j) := 'REF*SE*' || li_coil_abc_num;
	j := j + 1;
	edi_861(j) := 'REF*BM*' || not_sent_cloop.bol;
	j := j + 1;
	edi_861(j) := 'REF*RV*' || ls_ps_coil_number;
	j := j + 1;
	edi_861(j) := 'PRF*' || ls_po;
	j := j + 1;
	edi_861(j) := 'MEA*WT**' || ln_net_weight || '*01';
	j := j + 1;
	edi_861(j) := 'MEA*WT**' || ln_gross_weight || '*24';
	j := j + 1;
	edi_861(j) := 'MEA*PD*TH*' || to_char(ln_coil_gauge, 'FM90.0000') ||
		      '*IN';
	j := j + 1;
	edi_861(j) := 'MEA*PD*WD*' ||
		      to_char(ln_coil_width, 'FM99990.0000') || '*IN';
	j := j + 1;
	edi_861(j) := 'MEA*CT**' || ln_lineal_feed || '*LF';
	j := j + 1;

	coil_count := coil_count + 1;
      END LOOP;

      edi_861(j) := 'CTT*' || coil_count;
      j := j + 1;
      edi_861(j) := 'SE*' || to_char(j - 1) || '*' || li_st_log;
      j := j + 1;
      edi_861(j) := 'GE*1*' || li_gs_log;
      j := j + 1;
      edi_861(j) := 'IEA*1*' || lpad(to_char(li_gs_log), 9, '0');

      IF coil_count > 0 THEN
	IF skip_edi = 0 THEN
	  SELECT edi_file_id_seq.nextval INTO li_edi_861_id FROM dual;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--	    edi_file	    := 's_Novelis_' || to_char(li_edi_861_id) || '.861';
	  edi_file	  := edi_file_prefix || to_char(li_edi_861_id) || '.edi';
	  edi_file_handle := utl_file.fopen(edi_location, edi_file, 'W');
	  --write edi to file
	  FOR i IN 0 .. j LOOP
	    utl_file.put_line(edi_file_handle, edi_861(i));
	  END LOOP;
	  utl_file.fclose(edi_file_handle);
	END IF;

	/*--added by Victor Huang on 06/05 for function acknowlegement
	 INSERT INTO edi_fa(gs_num, duns_num, send_time,edi_file_name)
	 VALUES(li_gs_log, ls_dun, sysdate, edi_file);
	 COMMIT;
	*/
	--added by Victor Huang on 12/07 for verifying 997
	INSERT INTO outbound_edi_transaction
	  (edi_file_id,
	   duns_from,
	   duns_to,
	   interchange_control_number,
	   group_control_number,
	   transaction_time,
	   edi_file_name,
	   fa_receive_status,
	   customer_id,
	   set_control_num,
	   transaction_type_id)
	VALUES
	  (li_edi_861_id,
	   '039630926',
	   ls_dun,
	   li_gs_log,
	   li_gs_log,
	   SYSDATE,
	   edi_file,
	   0,
	   li_customer_id,
	   li_st_log,
	   '861');
	COMMIT;

	edi_file	:= 'send_edi_log';
	edi_file_handle := utl_file.fopen(edi_location, edi_file, 'a');
	utl_file.put_line(edi_file_handle, 'Type: 861');
	utl_file.put_line(edi_file_handle,
			  'Sending Time: ' ||
			  to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
	utl_file.put_line(edi_file_handle,
			  'Interchange Control #: ' || li_gs_log);
	utl_file.put_line(edi_file_handle,
			  'Group Control #: ' || li_gs_log);
	utl_file.put_line(edi_file_handle, 'Set Control #: ' || li_st_log);
	utl_file.put_line(edi_file_handle, '');
	utl_file.put_line(edi_file_handle, '');
	utl_file.fclose(edi_file_handle);

	UPDATE inbound_shipment_status
	   SET status = 1
	 WHERE bol = not_sent_cloop.bol
	   AND edi_file_id = not_sent_cloop.edi_file_id;

	COMMIT;
      END IF;
    END IF;
  END LOOP; --loop end for edi_file_id/bol

  RETURN;

EXCEPTION
  WHEN dup_val_on_index THEN
    ROLLBACK;
    RETURN;
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;

END p_create_edi_861_for_all;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_EDI_846_FOR_NOVELIS_KINGSTON" is
/*
This procedure creates EDI846 (Inventory Advice) for Novelis Kingston, which includes Novelis's coil information.
This procedure will be called from the cron job in the OS, runs periodically.
*/



  type edi_846_tabletype is table of varchar2(32767) index by binary_integer;
  edi_846 edi_846_tabletype;
  j binary_integer := 0;
  i integer := 0;
  edi_file_prefix VARCHAR2(50) := 'S_novelis_kingston_';

  li_customer_id int := 1153;	       --Novelis Kingston : 1153
				       --Novelis Oswego : 1459
  ls_duns varchar2(16) := '241003755'; --'241003755':Novelis Kingston's DUNS#
				       --'003980216':Novelis Oswego's DUNS#

  ls_coil_status varchar2(2);
--  ls_skid_status varchar2(2);

  cursor coil_cursor is
  select c.coil_abc_num, c.coil_org_num, NVL(c.coil_mid_num, 'NA') coil_mid_num, NVL(c.part_num, 'NA') part_num, NVL(c.supplier_sales_num, 'NA') supplier_sales_num, NVL(c.purchase_order_num, 'NA') purchase_order_num,  c.net_wt_balance, c.coil_status
  from coil c
  where -- c.coil_status not in (0, 10) and
	c.coil_status in (1, 2, 3, 4, 7, 11) and    -- coil status: 0:Done; 1:InProcess; 2:New; 3:Rejected; 4:OhHold; 6:Returned; 7:Rebanded; 10:Gone;	11:QAOnHold
	c.customer_id = li_customer_id	 ;

  cursor skid_cursor is
  select psi.prod_item_num,
	 ss.sheet_skid_num,
	 psi.prod_item_net_wt,
	 ss.skid_sheet_status,
	(ss.sheet_net_wt + ss.sheet_tare_wt) skid_gross_wt,
	 c.coil_abc_num, c.coil_org_num, NVL(c.coil_mid_num, 'NA') coil_mid_num, NVL(c.part_num, 'NA') part_num, NVL(c.supplier_sales_num, 'NA') supplier_sales_num, NVL(c.purchase_order_num, 'NA') purchase_order_num
  from coil c, sheet_skid ss, production_sheet_item psi, sheet_skid_detail ssd
  where c.coil_abc_num = psi.coil_abc_num and
	psi.prod_item_num = ssd.prod_item_num and
	ssd.sheet_skid_num = ss.sheet_skid_num and
	ss.skid_sheet_status in (2, 4, 13) and	--Skid status: 2:Ready; 4:OnHold; 13:Partial Ready
	c.customer_id = li_customer_id	 ;


  /*cursor coil_cursor_donebutnotshipped is
  select distinct c.coil_abc_num, c.coil_org_num, NVL(c.coil_mid_num, 'NA') coil_mid_num, NVL(c.part_num, 'NA') part_num, NVL(c.supplier_sales_num, 'NA') supplier_sales_num, NVL(c.purchase_order_num, 'NA') purchase_order_num,  c.net_wt_balance, c.coil_status
  from coil c, sheet_skid ss, production_sheet_item psi, sheet_skid_detail ssd
  where c.coil_abc_num = psi.coil_abc_num and
	psi.prod_item_num = ssd.prod_item_num and
	ssd.sheet_skid_num = ss.sheet_skid_num and
	c.coil_status = 0 and	 -- coil status: 0:Done; 1:InProcess; 2:New; 3:Rejected; 4:OhHold; 6:Returned; 7:Rebanded  11:QAOnHold
	ss.skid_sheet_status <> 0 and
	c.customer_id = li_customer_id	 ;  */


  li_gs_log INTEGER;
  li_st_log INTEGER;
  ls_today_short VARCHAR2(20);
  ls_today VARCHAR2(20);
  ls_now VARCHAR2(20);

--  li_coil_abc_num coil.coil_abc_num%type;
--  ls_coil_org_num coil.coil_org_num%type;
--  ls_coil_mid_num coil.coil_mid_num%type;
--  ls_part_num coil.part_num%type;
--  ls_supplier_sales_num coil.supplier_sales_num%type;
--  ls_purchase_order_num coil.purchase_order_num%type;
--  li_total_skid_net_wt sheet_skid.sheet_net_wt%type;
--  li_total_skid_tare_wt sheet_skid.sheet_tare_wt%type;
--  li_total_net_wt coil.net_wt%type;
--  li_total_gross_wt coil.net_wt%type;

  edi_location varchar2(50) := '/templar/templar/incoming/senddata';
  edi_file varchar2 (50) := 'edi_out.txt';
  edi_file_handle UTL_FILE.FILE_TYPE;

  li_coil_count int := 0;
  li_edi_846_id int;

begin

   SELECT EDI_ST_LOG_SEQ.NEXTVAL INTO li_st_log FROM dual;
   SELECT EDI_GS_LOG_SEQ.NEXTVAL INTO li_gs_log FROM dual;
   ls_today_short := to_char(SYSDATE, 'yymmdd');
   ls_today := to_char(SYSDATE, 'yyyymmdd');
   ls_now := to_char(SYSDATE, 'hh24mi');

   edi_846(j) := 'ISA*00*	   *00* 	 *01*039630926T     *09*0015049350011G *'
    ||	ls_today_short	|| '*' ||  ls_now  || '*U*00401*' || LPAD(to_char(li_gs_log),9,'0') || '*0*P*:'; j := j + 1;
   edi_846(j) := 'GS*IB*039630926T*0015049350011G*' ||	ls_today  || '*' || ls_now || '*' || li_gs_log || '*X*004010'	; j := j + 1;
   edi_846(j) := 'ST*846*' || li_st_log ; j := j + 1;
   edi_846(j) := 'BIA*00*IP*' || li_st_log || '*' || ls_today; j := j + 1;
   edi_846(j) := 'N1*OU**92*039630926'; j := j + 1;    --'039630926': ABCo's DUNS#
   edi_846(j) := 'N1*SU**92*'  ||  ls_duns; j := j + 1;

   for cloop in coil_cursor loop
    --Coils data

    --edi_846(j) := 'LIN**PO*' || cloop.purchase_order_num || '*BP*' || cloop.part_num || '*IN*' || cloop.coil_org_num || '*VN*' || cloop.coil_org_num || '*PK*' || cloop.coil_mid_num || '*VO*' || cloop.supplier_sales_num; j := j + 1;
    case cloop.coil_status
      when 3 then	  -- 3:Rejeced
	   ls_coil_status := '2';
	   edi_846(j) := 'LIN**PO*' || cloop.purchase_order_num || '*BP*' || cloop.part_num || '*IN*' || cloop.coil_abc_num || '*VN*' || cloop.coil_org_num || '*PK*' || cloop.coil_mid_num || '*VO*' || cloop.supplier_sales_num; j := j + 1;
      when 7 then	-- 7:Rebanded
	   ls_coil_status := '7';
	   edi_846(j) := 'LIN**PO*' || cloop.purchase_order_num || '*BP*' || cloop.part_num || '*IN*' || cloop.coil_abc_num || '*VN*' || cloop.coil_org_num || '*PK*' || cloop.coil_abc_num || '*VO*' || cloop.supplier_sales_num; j := j + 1;
      else
	   ls_coil_status := 'Q';
	   edi_846(j) := 'LIN**PO*' || cloop.purchase_order_num || '*BP*' || cloop.part_num || '*IN*' || cloop.coil_abc_num || '*VN*' || cloop.coil_org_num || '*PK*' || cloop.coil_mid_num || '*VO*' || cloop.supplier_sales_num; j := j + 1;
    end case;	   -- 7: In process; Q: Not Scheduled; M: Return Material to Mill; 2: Hold for Inspection
    edi_846(j) := 'PID*S*MA*ST*' || ls_coil_status; j := j + 1;
    edi_846(j) := 'MEA*PD*N*' || cloop.net_wt_balance || '*LB'; j := j + 1;
    edi_846(j) := 'MEA*PD*G*' || cloop.net_wt_balance || '*LB'; j := j + 1;
    edi_846(j) := 'QTY*01*1'; j := j + 1;

    li_coil_count := li_coil_count + 1;
   end loop;

   for cloop_donebutnotshipped in skid_cursor loop
   /*for cloop_donebutnotshipped in coil_cursor_donebutnotshipped loop
    --Coils data

    select sum(ss.sheet_net_wt) into li_total_skid_net_wt
    from sheet_skid ss, sheet_skid_detail ssd, production_sheet_item psi
    where ss.sheet_skid_num = ssd.sheet_skid_num and
	  ssd.prod_item_num = psi.prod_item_num and
	  ss.skid_sheet_status <> 0 and
	  psi.coil_abc_num = cloop_donebutnotshipped.coil_abc_num;

    select sum(ss.sheet_tare_wt) into li_total_skid_tare_wt from sheet_skid ss, sheet_skid_detail ssd, production_sheet_item psi
    where ss.sheet_skid_num = ssd.sheet_skid_num and
	  ssd.prod_item_num = psi.prod_item_num and
	  ss.skid_sheet_status <> 0 and
	  psi.coil_abc_num = cloop_donebutnotshipped.coil_abc_num;

    edi_846(j) := 'LIN**PO*' || cloop_donebutnotshipped.purchase_order_num || '*BP*' || cloop_donebutnotshipped.part_num || '*IN*' || cloop_donebutnotshipped.coil_abc_num || '*VN*' || cloop_donebutnotshipped.coil_org_num || '*PK*' || cloop_donebutnotshipped.coil_abc_num || '*VO*' || cloop_donebutnotshipped.supplier_sales_num; j := j + 1;
    edi_846(j) := 'PID*S*MA*ST*8'; j := j + 1;	 -- 8: processing complete
    edi_846(j) := 'QTY*01*1'; j := j + 1;
    li_total_net_wt := cloop_donebutnotshipped.net_wt_balance + li_total_skid_net_wt;
    edi_846(j) := 'MEA*PD*N*' || li_total_net_wt || '*LB'; j := j + 1;
    li_total_gross_wt := cloop_donebutnotshipped.net_wt_balance + li_total_skid_net_wt + li_total_skid_tare_wt;
    edi_846(j) := 'MEA*PD*G*' || li_total_gross_wt || '*LB'; j := j + 1;

    li_coil_count := li_coil_count + 1;   */

    edi_846(j) := 'LIN**PO*' || cloop_donebutnotshipped.purchase_order_num || '*BP*' || cloop_donebutnotshipped.part_num || '*IN*' || cloop_donebutnotshipped.prod_item_num || '*VN*' || cloop_donebutnotshipped.coil_org_num || '*PK*' || cloop_donebutnotshipped.sheet_skid_num || '*VO*' || cloop_donebutnotshipped.supplier_sales_num; j := j + 1;
    /*case cloop_donebutnotshipped.skid_sheet_status
      when 2 then ls_skid_status := '1';
      when 4 then ls_skid_status := '3';
      when 13 then ls_skid_status := '8';     /
    end case;	   --Skid status: 2:Ready; 4:OnHold; 13:Partial Ready
    edi_846(j) := 'PID*S*MA*ST*'  ||  ls_skid_status; j := j + 1;   -- 8: processing complete  */
    edi_846(j) := 'PID*S*MA*ST*7';j := j + 1;
    edi_846(j) := 'MEA*PD*N*' || cloop_donebutnotshipped.prod_item_net_wt || '*LB'; j := j + 1;
    edi_846(j) := 'MEA*PD*G*' || cloop_donebutnotshipped.skid_gross_wt || '*LB'; j := j + 1;
    edi_846(j) := 'QTY*01*1'; j := j + 1;

    li_coil_count := li_coil_count + 1;
   end loop;

   --edi_846(j) := 'CTT*' || li_coil_count; j := j + 1;
   edi_846(j) := 'SE*' || to_char(j-1) || '*' || li_st_log; j := j + 1;
   edi_846(j) := 'GE*1*' || li_gs_log; j := j + 1;
   edi_846(j) := 'IEA*1*' || LPAD(to_char(li_gs_log),9,'0');

   if li_coil_count > 0 then
     SELECT edi_file_id_seq.NEXTVAL INTO li_edi_846_id FROM DUAL;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--     edi_file := 'S_novelis_kingston_' || to_char(li_edi_846_id) || '.846';
     edi_file := edi_file_prefix || to_char(li_edi_846_id) || '.edi';
     edi_file_handle := utl_file.fopen(edi_location,edi_file,'W');
     --write edi to file
     FOR i IN 0..j LOOP
	 utl_file.put_line(edi_file_handle,edi_846(i));
	 END LOOP;
     utl_file.fclose(edi_file_handle);

     -- for verifying 997
      /*INSERT INTO outbound_edi_transaction(edi_file_id,duns_from,duns_to,interchange_control_number,
      group_control_number,transaction_time,edi_file_name,fa_receive_status,customer_id,set_control_num,transaction_type_id)
      VALUES(li_edi_846_id,'039630926',ls_duns,li_gs_log,li_gs_log, sysdate, edi_file,0,li_customer_id,li_st_log,'846');
      COMMIT;*/

      /*edi_file := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_location,edi_file,'a');
      utl_file.put_line(edi_file_handle,'Type: 846');
      utl_file.put_line(edi_file_handle,'Sending Time: ' || to_char(sysdate, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,'Interchange Control #: ' || li_gs_log);
      utl_file.put_line(edi_file_handle,'Group Control #: ' || li_gs_log);
      utl_file.put_line(edi_file_handle,'Set Control #: ' || li_st_log);
      utl_file.put_line(edi_file_handle,'');
      utl_file.put_line(edi_file_handle,'');
      utl_file.fclose(edi_file_handle);*/

      commit;
    end if;


  return;

  EXCEPTION
     WHEN dup_val_on_index then
     rollback;
     return ;
     WHEN UTL_FILE.INVALID_PATH THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
     WHEN UTL_FILE.INVALID_MODE THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
    WHEN UTL_FILE.INVALID_OPERATION THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
    WHEN UTL_FILE.WRITE_ERROR THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
    WHEN OTHERS THEN
     UTL_FILE.FCLOSE_ALL;
      RETURN ;

end p_edi_846_for_novelis_kingston;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_EDI_846_FOR_NOVELIS_OSWEGO" is
/*
This procedure creates EDI846 (Inventory Advice) for Novelis Kingston, which includes Novelis's coil information.
This procedure will be called from the cron job in the OS, runs periodically.
*/



  type edi_846_tabletype is table of varchar2(32767) index by binary_integer;
  edi_846 edi_846_tabletype;
  j binary_integer := 0;
  i integer := 0;
  edi_file_prefix VARCHAR2(50) := 'S_novelis_oswego_';

  li_customer_id int := 1459;	       --Novelis Kingston : 1153
				       --Novelis Oswego : 1459
  ls_duns varchar2(16) := '003980216'; --'241003755':Novelis Kingston's DUNS#
				       --'003980216':Novelis Oswego's DUNS#

  ls_coil_status varchar2(2);
--  ls_skid_status varchar2(2);

  cursor coil_cursor is
  select c.coil_abc_num, c.coil_org_num, NVL(c.coil_mid_num, 'NA') coil_mid_num, NVL(c.part_num, 'NA') part_num, NVL(c.supplier_sales_num, 'NA') supplier_sales_num, NVL(c.purchase_order_num, 'NA') purchase_order_num,  c.net_wt_balance, c.coil_status
  from coil c
  where -- c.coil_status not in (0, 10) and
	c.coil_status in (1, 2, 3, 4, 7, 11) and    -- coil status: 0:Done; 1:InProcess; 2:New; 3:Rejected; 4:OhHold; 6:Returned; 7:Rebanded; 10:Gone;	11:QAOnHold
	c.customer_id = li_customer_id	 ;

  cursor skid_cursor is
  select psi.prod_item_num,
	 ss.sheet_skid_num,
	 psi.prod_item_net_wt,
	 ss.skid_sheet_status,
	(ss.sheet_net_wt + ss.sheet_tare_wt) skid_gross_wt,
	 c.coil_abc_num, c.coil_org_num, NVL(c.coil_mid_num, 'NA') coil_mid_num, NVL(c.part_num, 'NA') part_num, NVL(c.supplier_sales_num, 'NA') supplier_sales_num, NVL(c.purchase_order_num, 'NA') purchase_order_num
  from coil c, sheet_skid ss, production_sheet_item psi, sheet_skid_detail ssd
  where c.coil_abc_num = psi.coil_abc_num and
	psi.prod_item_num = ssd.prod_item_num and
	ssd.sheet_skid_num = ss.sheet_skid_num and
	ss.skid_sheet_status in (2, 4, 13) and	--Skid status: 2:Ready; 4:OnHold; 13:Partial Ready
	c.customer_id = li_customer_id	 ;


  /*cursor coil_cursor_donebutnotshipped is
  select distinct c.coil_abc_num, c.coil_org_num, NVL(c.coil_mid_num, 'NA') coil_mid_num, NVL(c.part_num, 'NA') part_num, NVL(c.supplier_sales_num, 'NA') supplier_sales_num, NVL(c.purchase_order_num, 'NA') purchase_order_num,  c.net_wt_balance, c.coil_status
  from coil c, sheet_skid ss, production_sheet_item psi, sheet_skid_detail ssd
  where c.coil_abc_num = psi.coil_abc_num and
	psi.prod_item_num = ssd.prod_item_num and
	ssd.sheet_skid_num = ss.sheet_skid_num and
	c.coil_status = 0 and	 -- coil status: 0:Done; 1:InProcess; 2:New; 3:Rejected; 4:OhHold; 6:Returned; 7:Rebanded  11:QAOnHold
	ss.skid_sheet_status <> 0 and
	c.customer_id = li_customer_id	 ;  */


  li_gs_log INTEGER;
  li_st_log INTEGER;
  ls_today_short VARCHAR2(20);
  ls_today VARCHAR2(20);
  ls_now VARCHAR2(20);

--  li_coil_abc_num coil.coil_abc_num%type;
--  ls_coil_org_num coil.coil_org_num%type;
--  ls_coil_mid_num coil.coil_mid_num%type;
--  ls_part_num coil.part_num%type;
--  ls_supplier_sales_num coil.supplier_sales_num%type;
--  ls_purchase_order_num coil.purchase_order_num%type;
--  li_total_skid_net_wt sheet_skid.sheet_net_wt%type;
--  li_total_skid_tare_wt sheet_skid.sheet_tare_wt%type;
--  li_total_net_wt coil.net_wt%type;
--  li_total_gross_wt coil.net_wt%type;

  edi_location varchar2(50):='/templar/templar/incoming/senddata';
  edi_file varchar2 (50) := 'edi_out.txt';
  edi_file_handle UTL_FILE.FILE_TYPE;

  li_coil_count int := 0;
  li_edi_846_id int;

begin

   SELECT EDI_ST_LOG_SEQ.NEXTVAL INTO li_st_log FROM dual;
   SELECT EDI_GS_LOG_SEQ.NEXTVAL INTO li_gs_log FROM dual;
   ls_today_short := to_char(SYSDATE, 'yymmdd');
   ls_today := to_char(SYSDATE, 'yyyymmdd');
   ls_now := to_char(SYSDATE, 'hh24mi');

   edi_846(j):= 'ISA*00*	  *00*		*01*039630926T	   *09*0015049350011G *'
    ||	ls_today_short	|| '*' ||  ls_now  || '*U*00401*' || LPAD(to_char(li_gs_log),9,'0') || '*0*P*:'; j := j + 1;
   edi_846(j):= 'GS*IB*039630926T*0015049350011G*' ||  ls_today  || '*' || ls_now || '*' || li_gs_log || '*X*004010'   ; j :=j + 1;
   edi_846(j):= 'ST*846*' || li_st_log ; j :=j + 1;
   edi_846(j):= 'BIA*00*IP*' || li_st_log || '*' || ls_today; j := j + 1;
   edi_846(j):= 'N1*OU**92*039630926'; j := j + 1;    --'039630926': ABCo's DUNS#
   edi_846(j):= 'N1*SU**92*'  ||  ls_duns; j := j + 1;

   for cloop in coil_cursor loop
    --Coils data

    --edi_846(j):= 'LIN**PO*' || cloop.purchase_order_num || '*BP*' || cloop.part_num || '*IN*' || cloop.coil_org_num || '*VN*' || cloop.coil_org_num || '*PK*' || cloop.coil_mid_num || '*VO*' || cloop.supplier_sales_num; j := j + 1;
    case cloop.coil_status
      when 3 then	  -- 3:Rejeced
	   ls_coil_status := '2';
	   edi_846(j):= 'LIN**PO*' || cloop.purchase_order_num || '*BP*' || cloop.part_num || '*IN*' || cloop.coil_abc_num || '*VN*' || cloop.coil_org_num || '*PK*' || cloop.coil_mid_num || '*VO*' || cloop.supplier_sales_num; j := j + 1;
      when 7 then	-- 7:Rebanded
	   ls_coil_status := '7';
	   edi_846(j):= 'LIN**PO*' || cloop.purchase_order_num || '*BP*' || cloop.part_num || '*IN*' || cloop.coil_abc_num || '*VN*' || cloop.coil_org_num || '*PK*' || cloop.coil_abc_num || '*VO*' || cloop.supplier_sales_num; j := j + 1;
      else
	   ls_coil_status := 'Q';
	   edi_846(j):= 'LIN**PO*' || cloop.purchase_order_num || '*BP*' || cloop.part_num || '*IN*' || cloop.coil_abc_num || '*VN*' || cloop.coil_org_num || '*PK*' || cloop.coil_mid_num || '*VO*' || cloop.supplier_sales_num; j := j + 1;
    end case;	   -- 7: In process; Q: Not Scheduled; M: Return Material to Mill; 2: Hold for Inspection
    edi_846(j):= 'PID*S*MA*ST*' || ls_coil_status; j := j + 1;
    edi_846(j):= 'MEA*PD*N*' || cloop.net_wt_balance || '*LB'; j := j + 1;
    edi_846(j):= 'MEA*PD*G*' || cloop.net_wt_balance || '*LB'; j := j + 1;
    edi_846(j):= 'QTY*01*1'; j := j + 1;

    li_coil_count := li_coil_count + 1;
   end loop;

   for cloop_donebutnotshipped in skid_cursor loop
   /*for cloop_donebutnotshipped in coil_cursor_donebutnotshipped loop
    --Coils data

    select sum(ss.sheet_net_wt) into li_total_skid_net_wt
    from sheet_skid ss, sheet_skid_detail ssd, production_sheet_item psi
    where ss.sheet_skid_num = ssd.sheet_skid_num and
	  ssd.prod_item_num = psi.prod_item_num and
	  ss.skid_sheet_status <> 0 and
	  psi.coil_abc_num = cloop_donebutnotshipped.coil_abc_num;

    select sum(ss.sheet_tare_wt) into li_total_skid_tare_wt from sheet_skid ss, sheet_skid_detail ssd, production_sheet_item psi
    where ss.sheet_skid_num = ssd.sheet_skid_num and
	  ssd.prod_item_num = psi.prod_item_num and
	  ss.skid_sheet_status <> 0 and
	  psi.coil_abc_num = cloop_donebutnotshipped.coil_abc_num;

    edi_846(j):= 'LIN**PO*' || cloop_donebutnotshipped.purchase_order_num || '*BP*' || cloop_donebutnotshipped.part_num || '*IN*' || cloop_donebutnotshipped.coil_abc_num || '*VN*' || cloop_donebutnotshipped.coil_org_num || '*PK*' || cloop_donebutnotshipped.coil_abc_num || '*VO*' || cloop_donebutnotshipped.supplier_sales_num; j := j + 1;
    edi_846(j):= 'PID*S*MA*ST*8'; j := j + 1;	-- 8: processing complete
    edi_846(j):= 'QTY*01*1'; j := j + 1;
    li_total_net_wt := cloop_donebutnotshipped.net_wt_balance + li_total_skid_net_wt;
    edi_846(j):= 'MEA*PD*N*' || li_total_net_wt || '*LB'; j := j + 1;
    li_total_gross_wt := cloop_donebutnotshipped.net_wt_balance + li_total_skid_net_wt + li_total_skid_tare_wt;
    edi_846(j):= 'MEA*PD*G*' || li_total_gross_wt || '*LB'; j := j + 1;

    li_coil_count := li_coil_count + 1;   */

    edi_846(j):= 'LIN**PO*' || cloop_donebutnotshipped.purchase_order_num || '*BP*' || cloop_donebutnotshipped.part_num || '*IN*' || cloop_donebutnotshipped.prod_item_num || '*VN*' || cloop_donebutnotshipped.coil_org_num || '*PK*' || cloop_donebutnotshipped.sheet_skid_num || '*VO*' || cloop_donebutnotshipped.supplier_sales_num; j := j + 1;
    /*case cloop_donebutnotshipped.skid_sheet_status
      when 2 then ls_skid_status := '1';
      when 4 then ls_skid_status := '3';
      when 13 then ls_skid_status := '8';     /
    end case;	   --Skid status: 2:Ready; 4:OnHold; 13:Partial Ready
    edi_846(j):= 'PID*S*MA*ST*'  ||  ls_skid_status; j := j + 1;   -- 8: processing complete  */
    edi_846(j):= 'PID*S*MA*ST*7';j := j + 1;
    edi_846(j):= 'MEA*PD*N*' || cloop_donebutnotshipped.prod_item_net_wt || '*LB'; j := j + 1;
    edi_846(j):= 'MEA*PD*G*' || cloop_donebutnotshipped.skid_gross_wt || '*LB'; j := j + 1;
    edi_846(j):= 'QTY*01*1'; j := j + 1;

    li_coil_count := li_coil_count + 1;
   end loop;

   --edi_846(j):= 'CTT*' || li_coil_count; j := j + 1;
   edi_846(j):= 'SE*' || to_char(j-1) || '*' || li_st_log; j := j + 1;
   edi_846(j):= 'GE*1*' || li_gs_log; j := j + 1;
   edi_846(j):= 'IEA*1*' || LPAD(to_char(li_gs_log),9,'0');

   if li_coil_count > 0 then
     SELECT edi_file_id_seq.NEXTVAL INTO li_edi_846_id FROM DUAL;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--     edi_file := 's_novelis_oswego_' || to_char(li_edi_846_id) || '.846';
     edi_file := edi_file_prefix || to_char(li_edi_846_id) || '.edi';
     edi_file_handle :=utl_file.fopen(edi_location,edi_file,'W');
     --write edi to file
     FOR i IN 0..j LOOP
	 utl_file.put_line(edi_file_handle,edi_846(i));
	 END LOOP;
     utl_file.fclose(edi_file_handle);

     -- for verifying 997
      /*INSERT INTO outbound_edi_transaction(edi_file_id,duns_from,duns_to,interchange_control_number,
      group_control_number,transaction_time,edi_file_name,fa_receive_status,customer_id,set_control_num,transaction_type_id)
      VALUES(li_edi_846_id,'039630926',ls_duns,li_gs_log,li_gs_log, sysdate, edi_file,0,li_customer_id,li_st_log,'846');
      COMMIT;*/

      /*edi_file := 'send_edi_log';
      edi_file_handle :=utl_file.fopen(edi_location,edi_file,'a');
      utl_file.put_line(edi_file_handle,'Type: 846');
      utl_file.put_line(edi_file_handle,'Sending Time: ' || to_char(sysdate, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,'Interchange Control #: ' || li_gs_log);
      utl_file.put_line(edi_file_handle,'Group Control #: ' || li_gs_log);
      utl_file.put_line(edi_file_handle,'Set Control #: ' || li_st_log);
      utl_file.put_line(edi_file_handle,'');
      utl_file.put_line(edi_file_handle,'');
      utl_file.fclose(edi_file_handle);*/

      commit;
    end if;


  return;

  EXCEPTION
     WHEN dup_val_on_index then
     rollback;
     return ;
     WHEN UTL_FILE.INVALID_PATH THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
     WHEN UTL_FILE.INVALID_MODE THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
    WHEN UTL_FILE.INVALID_OPERATION THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
    WHEN UTL_FILE.WRITE_ERROR THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
    WHEN OTHERS THEN
     UTL_FILE.FCLOSE_ALL;
      RETURN ;

end p_edi_846_for_novelis_oswego;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_EDI_870_COIL_STATUS_NOVELIS" IS

Cursor coil_cur IS
select e.coil_abc_num, e.coil_status_change_date
from edi_870_coil_status e
--where e.edi_870_date is null;
where e.coil_abc_num = 84723;

li_return INT;
BEGIN

for coil_rec in coil_cur loop

li_return := F_EDI_870_COIL_STATUS_NOVELIS(coil_rec.coil_abc_num, coil_rec.coil_status_change_date);

end loop;

END P_EDI_870_COIL_STATUS_NOVELIS;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_EDI_NOVELIS_SCRAP_870" IS
  --BEGIN
  /*
  Aluminum Blanking: Ford Suppler Code: ZZ R0P7A
		     DUNS: 01 039630926T
  Customer: ALCAN(34,35,10,1153)
  Alcan Rolled Product	  X.121        0015049350011G
  Kingston Duns: 241003755
  */

  edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';

  --v_edi_text_alcan varchar2(32767);
  -- edi_loc varchar2(50):='/tmp';
  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 'S_novelis_scrap_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  INTEGER := 1153;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;
  --ll_bsn_log integer;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI'); -- time in 24 hours format....Tony

  ls_po VARCHAR2(20);

  --ll_edi_file_id integer;
  ll_edi_file_id_alcan INTEGER;

  ll_item_count INTEGER;
  ls_alloy	scrap_skid.scrap_alloy2%TYPE;
  --li_customer_id shipment.customer_id%TYPE;
  --li_des_sh_cust_id shipment.des_sh_cust_id%TYPE;

  li_hl01 INTEGER;
  /* Dec 23rd 02 changed by tony for re-assigned skid with other order
  Cursor alcan_870_cur IS
  SELECT   production_sheet_item.AB_JOB_NUM,
	   production_sheet_item.prod_item_pieces,
	   SHEET_SKID.SHEET_SKID_NUM,
	   production_sheet_item.prod_item_net_wt,
	   SHEET_SKID.SKID_SHEET_STATUS,
	   coil.coil_org_num,
	   NVL(customer_order.sales_order, 'NA') sales_order,
	   NVL(customer_order.orig_customer_po, 'NA') customer_po,
	   (SHEET_SKID.SHEET_NET_WT + SHEET_SKID.SHEET_TARE_WT) skid_gross_wt,
	   NULL Done
  FROM	   SHEET_SKID, production_sheet_item, sheet_skid_detail,coil,ab_job, customer_order
  WHERE        (sheet_skid.skid_sheet_status in ( 2, 4, 13)) and
	       (production_sheet_item.prod_item_edi870_date is NULL ) and
	       (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num) and
	       (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num) and
	       (coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
	       (coil.customer_id = 1153) and
	       (production_sheet_item.ab_job_num = ab_job.ab_job_num) and
	       (ab_job.order_abc_num = customer_order.order_abc_num) ;


  */

  --Begin of change

  CURSOR cust_cur IS
    SELECT customer_id
      FROM customer
     WHERE customer_id IN (1153, 1459, 2582); ---Add customer id here if you want to send 870 for more customers

  --End of change by tony

  CURSOR c_novelis_scrap_pack_870 IS
    SELECT return_scrap_item.return_scrap_item_num,
	   return_scrap_item.coil_abc_num,
	   return_scrap_item.ab_job_num,
	   return_scrap_item.return_item_net_wt,
	   return_scrap_item.return_item_date,
	   return_scrap_item.scrap_item_pieces,
	   scrap_skid.scrap_skid_num,
	   scrap_skid.scrap_skid_display_num,
	   scrap_skid.customer_id,
	   scrap_skid.scrap_temper,
	   scrap_skid.scrap_alloy2,
	   scrap_skid.scrap_net_wt,
	   scrap_skid.scrap_tare_wt,
	   scrap_skid.skid_scrap_status,
	   scrap_skid.scrap_date,
	   scrap_skid.scrap_cust_po
      FROM return_scrap_item, scrap_skid, scrap_skid_detail
     WHERE (return_scrap_item.scrap_item_870_date IS NULL AND
	   return_scrap_item.scrap_870_icn IS NULL)
       AND scrap_skid.customer_id = ll_customer_id
       AND scrap_skid.skid_scrap_status IN (2, 4, 13)
       AND return_scrap_item.return_scrap_item_num =
	   scrap_skid_detail.return_scrap_item_num
       AND scrap_skid.scrap_skid_num = scrap_skid_detail.scrap_skid_num;

  --Type skidinfo_tabletype IS table of alcan_870_cur%ROWTYPE INDEX by binary_integer;
  --skidinfo_table skidinfo_tabletype;

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;
  --item_rec alcan_870_cur%rowtype;
  --scrap_item_rec c_novelis_scrap_pack_870%rowtype;
  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;
  --TYPE scrap_item_type IS TABLE OF return_scrap_item.return_scrap_item_num%type INDEX BY BINARY_INTEGER;
  --scrap_item_num scrap_item_type;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;

    SELECT COUNT(*)
      INTO ll_item_count
      FROM return_scrap_item, scrap_skid, scrap_skid_detail
     WHERE (return_scrap_item.scrap_item_870_date IS NULL AND
	   return_scrap_item.scrap_870_icn IS NULL)
       AND scrap_skid.customer_id = ll_customer_id
       AND scrap_skid.skid_scrap_status IN (2, 4, 13)
       AND return_scrap_item.return_scrap_item_num =
	   scrap_skid_detail.return_scrap_item_num
       AND scrap_skid.scrap_skid_num = scrap_skid_detail.scrap_skid_num;
    -- if ll_item_count = 0 then return 100; end if;   -- nothing to send

    IF ll_item_count > 0 THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
--	x12_table(i) := 'N1*SU**1*' || su_duns || '*NA'; - by james 11/6/2013
      x12_table(i) := 'N1*SU**1*' || su_duns;
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926T';
      i := i + 1;

      --open alcan_870_cur;
      --fetch alcan_870_cur INTO item_rec;
      --close alcan_870_cur;

      li_hl01 := 1;

      FOR item_rec IN c_novelis_scrap_pack_870 LOOP
	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	-- No need for this part due to the change in alcan_870_cur   ---------By Tony 04-29-03

	-- Referece PO and Sales order via Ref_order due to coil reassigning	Bing on Sep 5, 2002
	/*
	  SELECT
	       NVL(customer_order.sales_order, 'NA') INTO item_rec.sales_order
	  FROM	 SHEET_SKID, customer_order
	  WHERE       (customer_order.order_abc_num = sheet_skid.ref_order_abc_num)  and
		      (sheet_skid.sheet_skid_num = item_rec.sheet_skid_num);

	  SELECT
	       NVL(customer_order.orig_customer_po, 'NA') INTO item_rec.customer_po
	  FROM	       SHEET_SKID, customer_order
	  WHERE       (customer_order.order_abc_num = sheet_skid.ref_order_abc_num)  and
		      (sheet_skid.sheet_skid_num = item_rec.sheet_skid_num);
	*/

	-- End of change tony 04-29-03

	-- Trunc PO by Bing on Jan 11, 2001
	ls_alloy := item_rec.scrap_alloy2;

	--SELECT NVL(ALCAN_SCRAP_PO, '6800'||ls_alloy) into ls_po
	--FROM ALLOY_TYPE
	--WHERE ALLOY = upper(rtrim(ltrim(ls_alloy))) and CUSTOMER_ID = ll_customer_id;

	ls_alloy := upper(ltrim(rtrim(ls_alloy)));
	--Change this to real PO later
	ls_po := 'NA';
	--Tony
	x12_table(i) := 'PRF*' || ls_po || '****NA';
	i := i + 1;
	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;
	-- Nov 21 03, change per Alcan	---tony
	--x12_table(i) := 'REF*SE*' ||item_rec.coil_org_num ||'-'||to_char(item_rec.sheet_skid_num); i := i+1;
	x12_table(i) := 'DTM*ZZZ*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' ||
			to_char(item_rec.scrap_skid_display_num);
	i := i + 1;
	--x12_table(i) := 'REF*SE*' || 'NA'; i := i+1;
	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	-- Nov 21 03, change per Alcan	---tony
	--x12_table(i) := 'REF*RV*' ||item_rec.coil_org_num || to_char(item_rec.sheet_skid_num) ||'*NA'; i := i+1;

	--Testing
	x12_table(i) := 'REF*RV*' ||
			to_char(item_rec.return_scrap_item_num) || '*NA';
	i := i + 1;
	--x12_table(i) := 'REF*RV*' || 'NA' ||'*NA'; i := i+1;

	--06/05/03 Don't send PO106 AND PO107 incase non sales order available as per Julia
	--IF item_rec.sales_order = ' ' THEN
	--   x12_table(i) := 'PO1**1*UN****' || '***SN*' ||item_rec.Scrap_Skid_Num ; i := i+1;
	x12_table(i) := 'PO1**1*UN****' || '***SN*' || 'NA';
	i := i + 1;
	--ELSE
	--    x12_table(i) := 'PO1**1*UN***VO*' || item_rec.sales_order ||'***SN*' ||item_rec.coil_org_num; i := i+1;
	--END IF;

	-- Added partial ready(13), On-hold(4) by Bing Feb-26-2002
	--IF item_rec.skid_sheet_status = 2 then
	x12_table(i) := 'PID*S*55***' || ls_alloy;
	i := i + 1;
	x12_table(i) := 'PID*S*MAC*ST*03';
	i := i + 1;

	x12_table(i) := 'PID*S*MA*ST*Z*' ||
			to_char(item_rec.scrap_skid_display_num);
	i := i + 1;
	--ELSIF item_rec.skid_sheet_status = 13 then
	--x12_table(i) := 'PID*S*MA*ST*8*' || to_char(item_rec.sheet_skid_num) || '*NA'; i := i+1;
	--ELSE
	--x12_table(i) := 'PID*S*MA*ST*3*' || to_char(item_rec.sheet_skid_num) || '*NA'; i := i+1;
	--END IF;

	x12_table(i) := 'PID*S*PR*ST*99';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.scrap_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' ||
			to_char(item_rec.scrap_net_wt +
				item_rec.scrap_tare_wt) || '*LB*01';
	i := i + 1;
	--    x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.scrap_item_pieces ) || '*PC'; i:= i+1;

	li_hl01 := li_hl01 + 1;

	item_num(k) := item_rec.return_scrap_item_num;
	k := k + 1;

      END LOOP;
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval INTO ll_edi_file_id_alcan FROM dual;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--	  edi_file	  := 'S_novelis_scrap_' ||
--			     to_char(ll_edi_file_id_alcan) || '.870';
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_alcan) || '.edi';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));
	  -- v_edi_text_alcan:=v_edi_text_alcan||x12_table(j)||CHR(10);
	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      /* --added by Victor Huang on 06/05 for function acknowlegement
      INSERT INTO edi_fa(gs_num, duns_num, send_time,edi_file_name)
      VALUES(ll_gs_log, su_duns, sysdate, edi_file);
      COMMIT;*/

      --added by Victor Huang on 12/07 for verifying 997
      INSERT INTO outbound_edi_transaction
	(edi_file_id,
	 duns_from,
	 duns_to,
	 interchange_control_number,
	 group_control_number,
	 transaction_time,
	 edi_file_name,
	 fa_receive_status,
	 customer_id,
	 set_control_num,
	 transaction_type_id)
      VALUES
	(ll_edi_file_id_alcan,
	 '039630926',
	 su_duns,
	 ll_gs_log,
	 ll_gs_log,
	 SYSDATE,
	 edi_file,
	 0,
	 ll_customer_id,
	 ll_st_log,
	 '870');
      COMMIT;

      edi_file	      := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      /*
      UPDATE production_sheet_item
	 SET prod_item_edi870_date= SYSDATE

	 WHERE	production_sheet_item.prod_item_num in
	       ( select production_sheet_item.prod_item_num from SHEET_SKID, production_sheet_item, sheet_skid_detail,coil, customer_order
		  where
		 (production_sheet_item.prod_item_edi870_date is NULL ) and
		 (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num) and
		 (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num) and
		 (sheet_skid.skid_sheet_status in (2, 4, 13)) and
		 (coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
		 (coil.customer_id = ll_customer_id) and
		 (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
	       );

      */
      FOR m IN 0 .. k - 1 LOOP
	UPDATE return_scrap_item
	   SET return_scrap_item.scrap_item_870_date = SYSDATE,
	       return_scrap_item.scrap_870_icn	     = ll_gs_log
	 WHERE return_scrap_item.return_scrap_item_num = item_num(m);
      END LOOP;

      COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
END;
--END p_edi_novelis_scrap_870;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_EDI_NOVELIS_SCRAP_870_ORIG" IS
  --BEGIN
  /*
  Aluminum Blanking: Ford Suppler Code: ZZ R0P7A
		     DUNS: 01 039630926T
  Customer: ALCAN(34,35,10,1153)
  Alcan Rolled Product	  X.121        0015049350011G
  Kingston Duns: 241003755
  */

  edi_loc VARCHAR2(50) := '/templar/templar/incoming/senddata';

  --v_edi_text_alcan varchar2(32767);
  -- edi_loc varchar2(50):='/tmp';
  edi_file	  VARCHAR2(50) := 'edi_out.txt';
  edi_file_prefix VARCHAR2(50) := 'S_novelis_scrap_';
  edi_file_handle utl_file.file_type;
  su_duns	  VARCHAR2(10);
  ll_customer_id  INTEGER := 1153;

  ll_gs_log INTEGER;
  ll_st_log INTEGER;
  --ll_bsn_log integer;

  ls_today   VARCHAR2(20) := to_char(SYSDATE, 'YYYYMMDD');
  ls_today_4 VARCHAR2(20) := to_char(SYSDATE, 'YYMMDD');
  ls_now     VARCHAR2(20) := to_char(SYSDATE, 'HH24MI'); -- time in 24 hours format....Tony

  ls_po VARCHAR2(20);

  --ll_edi_file_id integer;
  ll_edi_file_id_alcan INTEGER;

  ll_item_count INTEGER;
  ls_alloy	scrap_skid.scrap_alloy2%TYPE;
  --li_customer_id shipment.customer_id%TYPE;
  --li_des_sh_cust_id shipment.des_sh_cust_id%TYPE;

  li_hl01 INTEGER;
  /* Dec 23rd 02 changed by tony for re-assigned skid with other order
  Cursor alcan_870_cur IS
  SELECT   production_sheet_item.AB_JOB_NUM,
	   production_sheet_item.prod_item_pieces,
	   SHEET_SKID.SHEET_SKID_NUM,
	   production_sheet_item.prod_item_net_wt,
	   SHEET_SKID.SKID_SHEET_STATUS,
	   coil.coil_org_num,
	   NVL(customer_order.sales_order, 'NA') sales_order,
	   NVL(customer_order.orig_customer_po, 'NA') customer_po,
	   (SHEET_SKID.SHEET_NET_WT + SHEET_SKID.SHEET_TARE_WT) skid_gross_wt,
	   NULL Done
  FROM	   SHEET_SKID, production_sheet_item, sheet_skid_detail,coil,ab_job, customer_order
  WHERE        (sheet_skid.skid_sheet_status in ( 2, 4, 13)) and
	       (production_sheet_item.prod_item_edi870_date is NULL ) and
	       (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num) and
	       (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num) and
	       (coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
	       (coil.customer_id = 1153) and
	       (production_sheet_item.ab_job_num = ab_job.ab_job_num) and
	       (ab_job.order_abc_num = customer_order.order_abc_num) ;


  */

  --Begin of change

  CURSOR cust_cur IS
    SELECT customer_id FROM customer WHERE customer_id IN (1153, 1459); ---Add customer id here if you want to send 870 for more customers

  --End of change by tony

  CURSOR c_novelis_scrap_pack_870 IS
    SELECT return_scrap_item.return_scrap_item_num,
	   return_scrap_item.coil_abc_num,
	   return_scrap_item.ab_job_num,
	   return_scrap_item.return_item_net_wt,
	   return_scrap_item.return_item_date,
	   return_scrap_item.scrap_item_pieces,
	   scrap_skid.scrap_skid_num,
	   scrap_skid.customer_id,
	   scrap_skid.scrap_temper,
	   scrap_skid.scrap_alloy2,
	   scrap_skid.scrap_net_wt,
	   scrap_skid.scrap_tare_wt,
	   scrap_skid.skid_scrap_status,
	   scrap_skid.scrap_date,
	   scrap_skid.scrap_cust_po
      FROM return_scrap_item, scrap_skid, scrap_skid_detail
     WHERE (return_scrap_item.scrap_item_870_date IS NULL AND
	   return_scrap_item.scrap_870_icn IS NULL)
       AND scrap_skid.customer_id = ll_customer_id
       AND scrap_skid.skid_scrap_status IN (2, 4, 13)
       AND return_scrap_item.return_scrap_item_num =
	   scrap_skid_detail.return_scrap_item_num
       AND scrap_skid.scrap_skid_num = scrap_skid_detail.scrap_skid_num;

  --Type skidinfo_tabletype IS table of alcan_870_cur%ROWTYPE INDEX by binary_integer;
  --skidinfo_table skidinfo_tabletype;

  TYPE store_tabletype IS TABLE OF VARCHAR2(32767) INDEX BY BINARY_INTEGER;
  x12_table store_tabletype;
  i	    BINARY_INTEGER := 0;
  --item_rec alcan_870_cur%rowtype;
  --scrap_item_rec c_novelis_scrap_pack_870%rowtype;
  TYPE prod_item_type IS TABLE OF production_sheet_item.prod_item_num%TYPE INDEX BY BINARY_INTEGER;
  item_num prod_item_type;
  k	   BINARY_INTEGER := 0;
  --TYPE scrap_item_type IS TABLE OF return_scrap_item.return_scrap_item_num%type INDEX BY BINARY_INTEGER;
  --scrap_item_num scrap_item_type;

BEGIN

  FOR cust_rec IN cust_cur LOOP
    --- Outer loop of customer_id
    ll_customer_id := cust_rec.customer_id;
    i		   := 0;
    k		   := 0;

    SELECT COUNT(*)
      INTO ll_item_count
      FROM return_scrap_item, scrap_skid, scrap_skid_detail
     WHERE (return_scrap_item.scrap_item_870_date IS NULL AND
	   return_scrap_item.scrap_870_icn IS NULL)
       AND scrap_skid.customer_id = ll_customer_id
       AND scrap_skid.skid_scrap_status IN (2, 4, 13)
       AND return_scrap_item.return_scrap_item_num =
	   scrap_skid_detail.return_scrap_item_num
       AND scrap_skid.scrap_skid_num = scrap_skid_detail.scrap_skid_num;
    -- if ll_item_count = 0 then return 100; end if;   -- nothing to send

    IF ll_item_count > 0 THEN

      SELECT edi_st_log_seq.nextval INTO ll_st_log FROM dual;
      SELECT edi_gs_log_seq.nextval INTO ll_gs_log FROM dual;

      SELECT customer.customer_duns_number_string
	INTO su_duns
	FROM customer
       WHERE customer.customer_id = ll_customer_id;

      x12_table(i) := 'ISA*00*' ||
		      ' 	 *00*	       *01*039630926T	  *09*0015049350011G *' ||
		      ls_today_4 || '*' || ls_now || '*U*00401*' ||
		      lpad(to_char(ll_gs_log), 9, '0') || '*0*P**';
      i := i + 1;
      x12_table(i) := 'GS*RS*039630926T*' || '001504935001' || '*' ||
		      ls_today || '*' || ls_now || '*' ||
		      to_char(ll_gs_log) || '*X*' || '004010';
      i := i + 1;
      x12_table(i) := 'ST*870*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'BSR*2*PP*' || to_char(ll_st_log) || '*' || ls_today ||
		      '***' || ls_now || '*****';
      i := i + 1;
      x12_table(i) := 'DTM*009*' || ls_today || '*' || ls_now;
      i := i + 1;
      x12_table(i) := 'N1*SU**1*' || su_duns || '*NA';
      i := i + 1;
      x12_table(i) := 'N1*OU*ALUMINUM BLANKING/MI*1*039630926T';
      i := i + 1;

      --open alcan_870_cur;
      --fetch alcan_870_cur INTO item_rec;
      --close alcan_870_cur;

      li_hl01 := 1;

      FOR item_rec IN c_novelis_scrap_pack_870 LOOP
	x12_table(i) := 'HL*' || to_char(li_hl01) || '**I';
	i := i + 1;

	-- No need for this part due to the change in alcan_870_cur   ---------By Tony 04-29-03

	-- Referece PO and Sales order via Ref_order due to coil reassigning	Bing on Sep 5, 2002
	/*
	  SELECT
	       NVL(customer_order.sales_order, 'NA') INTO item_rec.sales_order
	  FROM	 SHEET_SKID, customer_order
	  WHERE       (customer_order.order_abc_num = sheet_skid.ref_order_abc_num)  and
		      (sheet_skid.sheet_skid_num = item_rec.sheet_skid_num);

	  SELECT
	       NVL(customer_order.orig_customer_po, 'NA') INTO item_rec.customer_po
	  FROM	       SHEET_SKID, customer_order
	  WHERE       (customer_order.order_abc_num = sheet_skid.ref_order_abc_num)  and
		      (sheet_skid.sheet_skid_num = item_rec.sheet_skid_num);
	*/

	-- End of change tony 04-29-03

	-- Trunc PO by Bing on Jan 11, 2001
	ls_alloy := item_rec.scrap_alloy2;

	--SELECT NVL(ALCAN_SCRAP_PO, '6800'||ls_alloy) into ls_po
	--FROM ALLOY_TYPE
	--WHERE ALLOY = upper(rtrim(ltrim(ls_alloy))) and CUSTOMER_ID = ll_customer_id;

	ls_alloy := upper(ltrim(rtrim(ls_alloy)));
	--Change this to real PO later
	ls_po := 'NA';
	--Tony
	x12_table(i) := 'PRF*' || ls_po || '****NA';
	i := i + 1;
	x12_table(i) := 'DTM*206*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;
	-- Nov 21 03, change per Alcan	---tony
	--x12_table(i) := 'REF*SE*' ||item_rec.coil_org_num ||'-'||to_char(item_rec.sheet_skid_num); i := i+1;
	x12_table(i) := 'DTM*ZZZ*' || ls_today || '*' || ls_now || '*ED';
	i := i + 1;

	x12_table(i) := 'REF*SE*' || to_char(item_rec.scrap_skid_num);
	i := i + 1;
	--x12_table(i) := 'REF*SE*' || 'NA'; i := i+1;
	x12_table(i) := 'REF*MI*' || to_char(item_rec.ab_job_num);
	i := i + 1;

	-- Nov 21 03, change per Alcan	---tony
	--x12_table(i) := 'REF*RV*' ||item_rec.coil_org_num || to_char(item_rec.sheet_skid_num) ||'*NA'; i := i+1;

	--Testing
	x12_table(i) := 'REF*RV*' ||
			to_char(item_rec.return_scrap_item_num) || '*NA';
	i := i + 1;
	--x12_table(i) := 'REF*RV*' || 'NA' ||'*NA'; i := i+1;

	--06/05/03 Don't send PO106 AND PO107 incase non sales order available as per Julia
	--IF item_rec.sales_order = ' ' THEN
	--   x12_table(i) := 'PO1**1*UN****' || '***SN*' ||item_rec.Scrap_Skid_Num ; i := i+1;
	x12_table(i) := 'PO1**1*UN****' || '***SN*' || 'NA';
	i := i + 1;
	--ELSE
	--    x12_table(i) := 'PO1**1*UN***VO*' || item_rec.sales_order ||'***SN*' ||item_rec.coil_org_num; i := i+1;
	--END IF;

	-- Added partial ready(13), On-hold(4) by Bing Feb-26-2002
	--IF item_rec.skid_sheet_status = 2 then
	x12_table(i) := 'PID*S*55***' || ls_alloy;
	i := i + 1;
	x12_table(i) := 'PID*S*MAC*ST*03';
	i := i + 1;

	x12_table(i) := 'PID*S*MA*ST*Z*' ||
			to_char(item_rec.scrap_skid_num);
	i := i + 1;
	--ELSIF item_rec.skid_sheet_status = 13 then
	--x12_table(i) := 'PID*S*MA*ST*8*' || to_char(item_rec.sheet_skid_num) || '*NA'; i := i+1;
	--ELSE
	--x12_table(i) := 'PID*S*MA*ST*3*' || to_char(item_rec.sheet_skid_num) || '*NA'; i := i+1;
	--END IF;

	x12_table(i) := 'PID*S*PR*ST*99';
	i := i + 1;
	x12_table(i) := 'MEA*WT*N*' || to_char(item_rec.scrap_net_wt) ||
			'*LB*01';
	i := i + 1;
	x12_table(i) := 'MEA*WT*G*' ||
			to_char(item_rec.scrap_net_wt +
				item_rec.scrap_tare_wt) || '*LB*01';
	i := i + 1;
	--    x12_table(i) := 'MEA*CT*NA*' || to_char(item_rec.scrap_item_pieces ) || '*PC'; i:= i+1;

	li_hl01 := li_hl01 + 1;

	item_num(k) := item_rec.return_scrap_item_num;
	k := k + 1;

      END LOOP;
      x12_table(i) := 'CTT*' || to_char(li_hl01 - 1);
      i := i + 1;
      x12_table(i) := 'SE*' || to_char(i - 1) || '*' || to_char(ll_st_log);
      i := i + 1;
      x12_table(i) := 'GE*1*' || to_char(ll_gs_log);
      i := i + 1;
      x12_table(i) := 'IEA*1*' || lpad(to_char(ll_gs_log), 9, '0');

      -- Write EDI to file

      IF li_hl01 > 1 THEN
	-- WRITE EDI FILE ONLY IF ITEM > 0
	SELECT edi_file_id_seq.nextval INTO ll_edi_file_id_alcan FROM dual;
-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--	edi_file	:= 'S_novelis_scrap_' ||
--			   to_char(ll_edi_file_id_alcan) || '.870';
	edi_file	:= edi_file_prefix || to_char(ll_edi_file_id_alcan) || '.edi';
	edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'W');

	FOR j IN 0 .. i LOOP
	  utl_file.put_line(edi_file_handle, x12_table(j));
	  -- v_edi_text_alcan:=v_edi_text_alcan||x12_table(j)||CHR(10);
	END LOOP;
	utl_file.fclose(edi_file_handle);
      END IF; -- END WRITING EDI FILE

      /* --added by Victor Huang on 06/05 for function acknowlegement
      INSERT INTO edi_fa(gs_num, duns_num, send_time,edi_file_name)
      VALUES(ll_gs_log, su_duns, sysdate, edi_file);
      COMMIT;*/

      --added by Victor Huang on 12/07 for verifying 997
      INSERT INTO outbound_edi_transaction
	(edi_file_id,
	 duns_from,
	 duns_to,
	 interchange_control_number,
	 group_control_number,
	 transaction_time,
	 edi_file_name,
	 fa_receive_status,
	 customer_id,
	 set_control_num,
	 transaction_type_id)
      VALUES
	(ll_edi_file_id_alcan,
	 '039630926',
	 su_duns,
	 ll_gs_log,
	 ll_gs_log,
	 SYSDATE,
	 edi_file,
	 0,
	 ll_customer_id,
	 ll_st_log,
	 '870');
      COMMIT;

      edi_file	      := 'send_edi_log';
      edi_file_handle := utl_file.fopen(edi_loc, edi_file, 'a');
      utl_file.put_line(edi_file_handle, 'Type: 870');
      utl_file.put_line(edi_file_handle,
			'Sending Time: ' ||
			to_char(SYSDATE, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,
			'Interchange Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Group Control #: ' || ll_gs_log);
      utl_file.put_line(edi_file_handle, 'Set Control #: ' || ll_st_log);
      utl_file.put_line(edi_file_handle, '');
      utl_file.put_line(edi_file_handle, '');
      utl_file.fclose(edi_file_handle);

      /*
      UPDATE production_sheet_item
	 SET prod_item_edi870_date= SYSDATE

	 WHERE	production_sheet_item.prod_item_num in
	       ( select production_sheet_item.prod_item_num from SHEET_SKID, production_sheet_item, sheet_skid_detail,coil, customer_order
		  where
		 (production_sheet_item.prod_item_edi870_date is NULL ) and
		 (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num) and
		 (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num) and
		 (sheet_skid.skid_sheet_status in (2, 4, 13)) and
		 (coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
		 (coil.customer_id = ll_customer_id) and
		 (sheet_skid.ref_order_abc_num = customer_order.order_abc_num)
	       );

      */
      FOR m IN 0 .. k - 1 LOOP
	UPDATE return_scrap_item
	   SET return_scrap_item.scrap_item_870_date = SYSDATE,
	       return_scrap_item.scrap_870_icn	     = ll_gs_log
	 WHERE return_scrap_item.return_scrap_item_num = item_num(m);
      END LOOP;

      COMMIT;

    END IF; --end if in select count(*)

  END LOOP; ------ End of outer loop customer_id

EXCEPTION
  WHEN utl_file.invalid_path THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_mode THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.invalid_operation THEN
    utl_file.fclose_all;
    RETURN;
  WHEN utl_file.write_error THEN
    utl_file.fclose_all;
    RETURN;
  WHEN OTHERS THEN
    utl_file.fclose_all;
    RETURN;
    -- END;
END p_edi_novelis_scrap_870_orig;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_EDI_WISE_870" is
/*Send 870 to Wise Alloys LLC
Customer_id = 1364
*/
/*
If sucess, then return 1
If fail, return the coil_abc_num that fails
*/
li_rc integer := 0;
li_count integer:=0;
ll_customer_id integer :=1364;

--As per customer's request, one 870 file contains skids under one coil
Cursor cur_coil_abc_num IS
SELECT distinct coil.coil_abc_num
FROM 		SHEET_SKID, production_sheet_item, sheet_skid_detail,coil
WHERE	     (sheet_skid.skid_sheet_status in ( 2, 4)) and
	     (production_sheet_item.prod_item_edi870_date is NULL ) and
	     (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num) and
			       (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num) and
			       (coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
	     (coil.customer_id = ll_customer_id);

begin

SELECT count(*) into li_count
FROM 		SHEET_SKID, production_sheet_item, sheet_skid_detail,coil
WHERE	     (sheet_skid.skid_sheet_status in ( 2, 4)) and
	     (production_sheet_item.prod_item_edi870_date is NULL ) and
	     (sheet_skid.sheet_skid_num = sheet_skid_detail.sheet_skid_num) and
			       (sheet_skid_detail.prod_item_num = production_sheet_item.prod_item_num) and
			       (coil.coil_abc_num = production_sheet_item.coil_abc_num ) and
	     (coil.customer_id = ll_customer_id);

if li_count <> 0 then
   for coil_abc_num_rec in cur_coil_abc_num loop
       --As per customer's request, one 870 file contains skids under one coil
       li_rc := f_edi_wise_870_by_coil(coil_abc_num_rec.coil_abc_num);
       /*
       if li_rc <> 1 then
       return ;
       end if;
       */
   end loop;

end if;

end P_EDI_WISE_870;
/


