  CREATE OR REPLACE PROCEDURE "DBO"."P_RECOVERY_REPORT" ( p_date in varchar2, p_customer_id in varchar2) -- p_date in "MM-DD-YYYY"; p_customer_id: 0 for All customers

is
    l_output	    utl_file.file_type;
    l_theCursor     integer default dbms_sql.open_cursor;
    l_columnValue   varchar2(2000);
    l_status	    integer;
    l_colCnt	    number default 0;
    l_separator     varchar2(10) default '';
    l_cnt	    number default 0;
    l_dir	    varchar2(256) := '/tmp';
    l_filename	    varchar2(256) := 'recovery_report.csv';
    l_csv_separator varchar2(1):= ',';
    l_query	    varchar2(2000);
    l_customer_name varchar2(32);
    l_customer_id   customer.customer_id%type;

begin
    l_customer_id := to_number(p_customer_id);
    if l_customer_id = 0 then
      l_customer_name := 'ALL';
    else
      select c.customer_short_name into l_customer_name
      from customer c
      where c.customer_id = l_customer_id;
    end if;

    l_customer_name := trim(l_customer_name);
    l_filename := 'recovery_report_' || p_date || '_' || l_customer_name||'.csv';


    l_query := 'select cu1.customer_short_name, j.job_done_time, c.coil_org_num, c.lot_num, Null, j.ab_job_num, o.orig_customer_po,  cu2.customer_short_name, i.material_end_use, Null, l.line_desc, c.coil_alloy2, c.coil_temper, c.coil_gauge, c.coil_width, f_get_part_length_per_job(j.ab_job_num), (select process_quantity from process_coil where coil_abc_num = c.coil_abc_num and ab_job_num = j.ab_job_num), f_get_coil_ship_wt(c.coil_abc_num, j.ab_job_num), f_get_coil_rebanded_wt(c.coil_abc_num, process_quantity), f_get_coil_rejected_wt(c.coil_abc_num, process_quantity) '||
	       ' from coil c, ab_job j, process_coil p, customer_order o, order_item i, customer cu1, customer cu2, line l'||
	       ' where (j.order_item_num = i.order_item_num and j.order_abc_num = i.order_abc_num)'||
	       ' and i.order_abc_num = o.order_abc_num'||
	       ' and o.orig_customer_id = cu1.customer_id'||
	       ' and o.enduser_id = cu2.customer_id'||
	       ' and c.coil_abc_num = p.coil_abc_num'||
	       ' and j.ab_job_num = p.ab_job_num'||
	       ' and l.line_num = j.line_num'||
	       ' and TO_CHAR(j.job_done_time, ''MM-DD-YYYY'') = ''' || p_date || ''''||
	       ' order by cu1.customer_short_name, j.job_done_time, c.coil_org_num, j.ab_job_num';

    if l_customer_id <> 0
    then l_query := l_query || 'and o.orig_customer_id = ' || p_customer_id;
    end if;

    l_output := utl_file.fopen( l_dir, l_filename, 'w' );

    utl_file.put_line(l_output, 'Customer Name, Process Date, Coil#, Coil Lot#, Pack#, AB Job#, Customer PO#, End User,  Material End Use, Product Type, BL#, Alloy, Temper, Gauge, Width, Length, Coil Begin WT, Total Ship WT, Reband WT, Reject WT');

    dbms_sql.parse(  l_theCursor,  l_query, dbms_sql.native );

    for i in 1 .. 255 loop
	begin
	    dbms_sql.define_column( l_theCursor, i, l_columnValue, 2000 );
	    l_colCnt := i;
	exception
	    when others then
		if ( sqlcode = -1007 ) then exit;
		else
		    raise;
		end if;
	end;
    end loop;

    dbms_sql.define_column( l_theCursor, 1, l_columnValue, 2000 );

    l_status := dbms_sql.execute(l_theCursor);

    loop
	exit when ( dbms_sql.fetch_rows(l_theCursor) <= 0 );
	l_separator := '';
	for i in 1 .. l_colCnt loop
	    dbms_sql.column_value( l_theCursor, i, l_columnValue );
	    utl_file.put( l_output, l_separator || l_columnValue );
	    l_separator := l_csv_separator;
	end loop;
	utl_file.new_line( l_output );
	l_cnt := l_cnt+1;
    end loop;
    dbms_sql.close_cursor(l_theCursor);

    utl_file.fclose( l_output );

end P_RECOVERY_REPORT;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_RECOVERY_REPORT_A_C" ( p_date in varchar2, p_customer_id in varchar2) -- p_date in "MM-DD-YYYY"; p_customer_id: 0 for All customers

is
    l_output	    utl_file.file_type;
    l_output_kingston_auto utl_file.file_type;
    l_theCursor     integer default dbms_sql.open_cursor;
    l_columnValue   varchar2(2000);
    l_status	    integer;
    l_colCnt	    number default 0;
    l_separator     varchar2(10) default '';
    l_cnt	    number default 0;
    l_dir	    varchar2(256) := '/tmp';
    l_filename	    varchar2(256) := 'recovery_report.csv';
    l_filename_kingston_auto varchar2(256) := 'recovery_report_kingston_auto.csv';
    l_csv_separator varchar2(1):= ',';
    l_query	    varchar2(2000);
    l_customer_name varchar2(32);
    l_customer_id   customer.customer_id%type;

   cursor select_cursor is
	       select cu1.customer_short_name customer_short_name, cu1.customer_id customer_id, j.job_done_time job_done_time, c.coil_org_num coil_org_num, c.lot_num lot_num, j.ab_job_num ab_job_num, o.orig_customer_po orig_customer_po,  cu2.customer_short_name end_user, cu2.customer_id end_user_id, i.material_end_use material_end_use, l.line_desc line_desc, c.coil_alloy2 coil_alloy2, c.coil_temper coil_temper, c.coil_gauge coil_gauge, c.coil_width coil_width, f_get_part_length_per_job(j.ab_job_num) length, (select process_quantity from process_coil where coil_abc_num = c.coil_abc_num and ab_job_num = j.ab_job_num) begin_wt, NVL(f_get_coil_ship_wt(c.coil_abc_num, j.ab_job_num),0) ship_wt, f_get_coil_rebanded_wt(c.coil_abc_num, process_quantity) reband_wt, f_get_coil_rejected_wt(c.coil_abc_num, process_quantity) reject_wt
	       from coil c, ab_job j, process_coil p, customer_order o, order_item i, customer cu1, customer cu2, line l
	       where (j.order_item_num = i.order_item_num and j.order_abc_num = i.order_abc_num)
	       and i.order_abc_num = o.order_abc_num
	       and o.orig_customer_id = cu1.customer_id
	       and o.enduser_id = cu2.customer_id
	       and c.coil_abc_num = p.coil_abc_num
	       and j.ab_job_num = p.ab_job_num
	       and l.line_num = j.line_num
	       --and c.net_wt > 0	    --excluding warehouse coil
	       and TO_CHAR(j.job_done_time, 'MM-DD-YYYY') =  p_date
	       order by cu1.customer_short_name, c.coil_org_num, j.ab_job_num;

    ls_customer_name_cur customer.customer_short_name%type := '';
    li_customer_id_cur customer.customer_id%type :=0;
    ldt_process_date_cur ab_job.due_date%type := sysdate;
    ls_coil_org_num_cur coil.coil_org_num%type := '';
    ls_coil_lot_cur coil.lot_num%type := '';
    li_ab_job_num_cur coil.coil_abc_num%type := 0;
    ls_ab_job_num_cur varchar2(64) := ''; --used for combined AB_Job# of multi jobs
    ls_po_cur customer_order.orig_customer_po%type := '';
    ls_end_user_cur customer.customer_short_name%type := '';
    li_end_user_id_cur customer.customer_id%type := 0;
    ls_material_end_use_cur order_item.material_end_use%type := '';
    ls_bl_desc_cur line.line_desc%type := '';
    ls_alloy_cur coil.coil_alloy2%type := '';
    ls_temper_cur coil.coil_temper%type := '';
    li_gauge_cur coil.coil_gauge%type := 0;
    li_width_cur coil.coil_width%type := 0;
    li_length_cur int := 0;
    li_begin_wt_cur coil.net_wt%type := 0;
    li_total_wt_cur coil.net_wt%type := 0;
    li_reband_wt_cur coil.net_wt%type := 0;
    ls_reband_wt_cur varchar2(64) := '';      --used for combined reband wt
    li_reject_wt_cur coil.net_wt%type := 0;
    ls_reject_wt_cur varchar2(64) := '';      --used for combined reject wt

    ls_customer_name_pre customer.customer_short_name%type := '';
    li_customer_id_pre customer.customer_id%type :=0;
    ldt_process_date_pre ab_job.due_date%type := sysdate;
    ls_coil_org_num_pre coil.coil_org_num%type := '';
    ls_coil_lot_pre coil.lot_num%type := '';
    li_ab_job_num_pre coil.coil_abc_num%type := 0;
    ls_ab_job_num_pre varchar2(64) := ''; --used for combined AB_Job# of multi jobs
    ls_po_pre customer_order.orig_customer_po%type := '';
    ls_end_user_pre customer.customer_short_name%type := '';
    li_end_user_id_pre customer.customer_id%type := 0;
    ls_material_end_use_pre order_item.material_end_use%type := '';
    ls_bl_desc_pre line.line_desc%type := '';
    ls_alloy_pre coil.coil_alloy2%type := '';
    ls_temper_pre coil.coil_temper%type := '';
    li_gauge_pre coil.coil_gauge%type := 0;
    li_width_pre coil.coil_width%type := 0;
    li_length_pre int := 0;
    li_begin_wt_pre coil.net_wt%type := 0;
    li_total_wt_pre coil.net_wt%type := 0;
    li_reband_wt_pre coil.net_wt%type := 0;
    ls_reband_wt_pre varchar2(64) := '';     --used for combined reband wt
    li_reject_wt_pre coil.net_wt%type := 0;
    ls_reject_wt_pre varchar2(64) := '';     --used for combined reject wt

begin
    l_customer_id := to_number(p_customer_id);
    if l_customer_id = 0 then
      l_customer_name := 'ALL';
    else
      select c.customer_short_name into l_customer_name
      from customer c
      where c.customer_id = l_customer_id;
    end if;

    l_customer_name := trim(l_customer_name);
    l_filename := 'recovery_report_' || p_date || '_' || l_customer_name||'.csv';
    l_filename_kingston_auto := 'recovery_report_' || p_date || '_Novelis_Kingston_auto.csv';
    l_output := utl_file.fopen( l_dir, l_filename, 'w' );
    l_output_kingston_auto := utl_file.fopen( l_dir, l_filename_kingston_auto, 'w' );

    utl_file.put_line(l_output, 'Customer Name, Process Date, Coil#, Coil Lot#, Pack#, AB Job#, Customer PO#, End User,  Material End Use, Product Type, BL#, Alloy, Temper, Gauge, Width, Length, Coil Begin WT, Total Ship WT, Reband WT, Reject WT');
    utl_file.put_line(l_output_kingston_auto, 'Customer Name, Process Date, Coil#, Coil Lot#, Pack#, AB Job#, Customer PO#, End User,  Material End Use, Product Type, BL#, Alloy, Temper, Gauge, Width, Length, Coil Begin WT, Total Ship WT, Reband WT, Reject WT');

    for cloop in select_cursor loop
      --data get from last row
      ls_customer_name_pre := ls_customer_name_cur;
      li_customer_id_pre := li_customer_id_cur;
      ldt_process_date_pre := ldt_process_date_cur;
      ls_coil_org_num_pre := ls_coil_org_num_cur;
      ls_coil_lot_pre := ls_coil_lot_cur;
      li_ab_job_num_pre := li_ab_job_num_cur;
      ls_ab_job_num_pre := ls_ab_job_num_cur;
      ls_po_pre := ls_po_cur;
      ls_end_user_pre := ls_end_user_cur;
      li_end_user_id_pre := li_end_user_id_cur;
      ls_material_end_use_pre := ls_material_end_use_cur;
      ls_bl_desc_pre :=ls_bl_desc_cur;
      ls_alloy_pre := ls_alloy_cur;
      ls_temper_pre := ls_temper_cur;
      li_gauge_pre := li_gauge_cur ;
      li_width_pre := li_width_cur;
      li_length_pre := li_length_cur;
      li_begin_wt_pre  := li_begin_wt_cur;
      li_total_wt_pre := li_total_wt_cur ;
      li_reband_wt_pre := li_reband_wt_cur;
      ls_reband_wt_pre := ls_reband_wt_cur;
      li_reject_wt_pre := li_reject_wt_cur;
      ls_reject_wt_pre := ls_reject_wt_cur;

      --data get from current row
      ls_customer_name_cur := cloop.customer_short_name;
      li_customer_id_cur := cloop.customer_id;
      ldt_process_date_cur := cloop.job_done_time;
      ls_coil_org_num_cur := cloop.coil_org_num;
      ls_coil_lot_cur := cloop.lot_num;
      li_ab_job_num_cur := cloop.ab_job_num;
      ls_ab_job_num_cur := to_char(li_ab_job_num_cur);
      ls_po_cur := cloop.orig_customer_po;
      ls_end_user_cur :=cloop.end_user;
      li_end_user_id_cur := cloop.end_user_id;
      ls_material_end_use_cur :=cloop.material_end_use;
      ls_bl_desc_cur :=cloop.line_desc;
      ls_alloy_cur :=cloop.coil_alloy2;
      ls_temper_cur :=cloop.coil_temper;
      li_gauge_cur :=cloop.coil_gauge ;
      li_width_cur :=cloop.coil_width;
      li_length_cur :=cloop.length;
      li_begin_wt_cur  :=cloop.begin_wt;
      li_total_wt_cur :=cloop.ship_wt ;
      li_reband_wt_cur :=cloop.reband_wt;
      ls_reband_wt_cur := to_char(li_reband_wt_cur);
      li_reject_wt_cur :=cloop.reject_wt;
      ls_reject_wt_cur := to_char(li_reject_wt_cur);

     --check if coil_org_nums are the same
     if ls_coil_org_num_pre = ls_coil_org_num_cur then
	--combine data from jobs
	ls_ab_job_num_cur := ls_ab_job_num_pre ||'/'|| ls_ab_job_num_cur;
	if li_reband_wt_cur > li_reband_wt_pre then    --get the least reband wt for the coil
	  li_reband_wt_cur := li_reband_wt_pre;
	end if;
	ls_reband_wt_cur := to_char(li_reband_wt_cur);
	--ls_reband_wt_cur := ls_reband_wt_pre ||'/'|| ls_reband_wt_cur;
	if li_reject_wt_cur > li_reject_wt_pre then    --get the least reject wt for the coil
	  li_reject_wt_cur := li_reject_wt_pre;
	end if;
	--ls_reject_wt_cur := ls_reject_wt_pre ||'/'|| ls_reject_wt_cur;
	ls_reject_wt_cur := to_char(li_reject_wt_cur);
	li_total_wt_cur := li_total_wt_pre + li_total_wt_cur;

	--get largest begin wt for coil
	if li_begin_wt_cur <= li_begin_wt_pre then
	   li_begin_wt_cur := li_begin_wt_pre;
	end if;

      else

	--if li_total_wt_pre <> 0 then
	if li_begin_wt_pre <> 0 then
	   if li_customer_id_pre = 1153 and li_end_user_id_pre in (1191,2294,1754,2186,2243,1031,2529,2158,2542,2472,2313,2402,2298,2305,1752,1456,2415,1251,2414,2408,1379,1271,1579,1268,2539,1342,1476,2362,71,2413,1711,182,2496,1921,1549,2514,2470,2360,1864,1840,2079,1112,2181,2495,70,2164,2406,2386,1074,2382,2381,2447,2358,1715,1037,1153,1532,1967,2133,2424,2367,1350,2487,1687,1651,1674,1089,1206,1761,79) then
	       utl_file.put_line(l_output_kingston_auto, ls_customer_name_pre||','||to_char(ldt_process_date_pre, 'MM-DD-YY')||','||ls_coil_org_num_pre||','||ls_coil_lot_pre||','||' '||','||ls_ab_job_num_pre||','||ls_po_pre||','||ls_end_user_pre||','||ls_material_end_use_pre||','||' '||','||ls_bl_desc_pre||','||ls_alloy_pre||','||ls_temper_pre||','||to_char(li_gauge_pre)||','||to_char(li_width_pre)||','||to_char(li_length_pre)||','||to_char(li_begin_wt_pre)||','||to_char(li_total_wt_pre)||','||ls_reband_wt_pre||','||ls_reject_wt_pre);
	   else
	       utl_file.put_line(l_output, ls_customer_name_pre||','||to_char(ldt_process_date_pre, 'MM-DD-YY')||','||ls_coil_org_num_pre||','||ls_coil_lot_pre||','||' '||','||ls_ab_job_num_pre||','||ls_po_pre||','||ls_end_user_pre||','||ls_material_end_use_pre||','||' '||','||ls_bl_desc_pre||','||ls_alloy_pre||','||ls_temper_pre||','||to_char(li_gauge_pre)||','||to_char(li_width_pre)||','||to_char(li_length_pre)||','||to_char(li_begin_wt_pre)||','||to_char(li_total_wt_pre)||','||ls_reband_wt_pre||','||ls_reject_wt_pre);
	   end if;
	end if;

      end if;

    end loop;

	--if li_total_wt_cur <> 0 then
	if li_begin_wt_cur <> 0 then
	   if li_customer_id_pre = 1153 and li_end_user_id_pre in (1191,2294,1754,2186,2243,1031,2529,2158,2542,2472,2313,2402,2298,2305,1752,1456,2415,1251,2414,2408,1379,1271,1579,1268,2539,1342,1476,2362,71,2413,1711,182,2496,1921,1549,2514,2470,2360,1864,1840,2079,1112,2181,2495,70,2164,2406,2386,1074,2382,2381,2447,2358,1715,1037,1153,1532,1967,2133,2424,2367,1350,2487,1639,2351,2042,1617,2437,2281,2527,1591,2452,1594,110,2523,1687,1651,1674,1089,1206,1761,79) then
	     utl_file.put_line(l_output_kingston_auto, ls_customer_name_cur||','||to_char(ldt_process_date_cur, 'MM-DD-YY')||','||ls_coil_org_num_cur||','||ls_coil_lot_cur||','||' '||','||ls_ab_job_num_cur||','||ls_po_cur||','||ls_end_user_cur||','||ls_material_end_use_cur||','||' '||','||ls_bl_desc_cur||','||ls_alloy_cur||','||ls_temper_cur||','||to_char(li_gauge_cur)||','||to_char(li_width_cur)||','||to_char(li_length_cur)||','||to_char(li_begin_wt_cur)||','||to_char(li_total_wt_cur)||','||ls_reband_wt_cur||','||ls_reject_wt_cur);
	   else
	     utl_file.put_line(l_output, ls_customer_name_cur||','||to_char(ldt_process_date_cur, 'MM-DD-YY')||','||ls_coil_org_num_cur||','||ls_coil_lot_cur||','||' '||','||ls_ab_job_num_cur||','||ls_po_cur||','||ls_end_user_cur||','||ls_material_end_use_cur||','||' '||','||ls_bl_desc_cur||','||ls_alloy_cur||','||ls_temper_cur||','||to_char(li_gauge_cur)||','||to_char(li_width_cur)||','||to_char(li_length_cur)||','||to_char(li_begin_wt_cur)||','||to_char(li_total_wt_cur)||','||ls_reband_wt_cur||','||ls_reject_wt_cur);
	   end if;
	end if;

    utl_file.fclose( l_output);
    utl_file.fclose( l_output_kingston_auto);

end P_RECOVERY_REPORT_A_C;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_SEND_EMAIL_COIL_DEFECT"

(
   ls_coil_org_num varchar2
)
is
  l_mailhost	VARCHAR2(64) := 'db01.albl.com';
  l_from	VARCHAR2(64) := 'COIL_RECEIVED_WITH_DEFECT_NOTIFICATION@ALBL.COM';
  --l_to	  VARCHAR2(64) := 'vhuang@albl.com';

  l_mail_conn	UTL_SMTP.connection;
BEGIN
  l_mail_conn := UTL_SMTP.open_connection(l_mailhost, 25);
  UTL_SMTP.helo(l_mail_conn, l_mailhost);
  UTL_SMTP.mail(l_mail_conn, l_from);
  UTL_SMTP.rcpt(l_mail_conn, 'vhuang@albl.com');
  UTL_SMTP.rcpt(l_mail_conn, 'rsedam@albl.com');
  UTL_SMTP.rcpt(l_mail_conn, 'dpolking@albl.com');
  UTL_SMTP.rcpt(l_mail_conn, 'cbeamer@albl.com');
  UTL_SMTP.rcpt(l_mail_conn, 'mmillis@albl.com');
  UTL_SMTP.rcpt(l_mail_conn, 'celliott@albl.com');


  UTL_SMTP.open_data(l_mail_conn);

  UTL_SMTP.write_data(l_mail_conn, 'Coil Received With Defect Notification: Customer Coil # ' || ls_coil_org_num || '.' || Chr(13));
  UTL_SMTP.write_data(l_mail_conn, 'Please follow up accordingly.' || Chr(13));
  UTL_SMTP.write_data(l_mail_conn, 'Notification Time: ' || TO_CHAR(SYSDATE, 'MM/DD/YYYY, HH24:MI' ) || '.' || Chr(13));

  UTL_SMTP.close_data(l_mail_conn);

  UTL_SMTP.quit(l_mail_conn);
END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."P_SEND_EMAIL_JOB_DONE"

(
   li_ab_job integer
)
is
  l_mailhost	VARCHAR2(64) := 'db01.albl.com';
