  UTL_SMTP.close_data(l_mail_conn);

  UTL_SMTP.quit(l_mail_conn);
END;

/


  CREATE OR REPLACE PROCEDURE "DBO"."P_SQL_TO_CSV" ( p_query	 in varchar2,
				      p_separator in varchar2 default ',',
				      p_dir	  in varchar2 ,
				      p_filename  in varchar2 )

is
    l_output	    utl_file.file_type;
    l_theCursor     integer default dbms_sql.open_cursor;
    l_columnValue   varchar2(2000);
    l_status	    integer;
    l_colCnt	    number default 0;
    l_separator     varchar2(10) default '';
    l_cnt	    number default 0;
begin
    l_output := utl_file.fopen( p_dir, p_filename, 'w' );

    dbms_sql.parse(  l_theCursor,  p_query, dbms_sql.native );

    for i in 1 .. 255 loop
	begin
	    dbms_sql.define_column( l_theCursor, i, l_columnValue, 2000 );
	    l_colCnt := i;
	exception
	    when others then
		if ( sqlcode = -1007 ) then exit;
		else
		    raise;
		end if;
	end;
    end loop;

    dbms_sql.define_column( l_theCursor, 1, l_columnValue, 2000 );

    l_status := dbms_sql.execute(l_theCursor);

    loop
	exit when ( dbms_sql.fetch_rows(l_theCursor) <= 0 );
	l_separator := '';
	for i in 1 .. l_colCnt loop
	    dbms_sql.column_value( l_theCursor, i, l_columnValue );
	    utl_file.put( l_output, l_separator || l_columnValue );
	    l_separator := p_separator;
	end loop;
	utl_file.new_line( l_output );
	l_cnt := l_cnt+1;
    end loop;
    dbms_sql.close_cursor(l_theCursor);

    utl_file.fclose( l_output );

end P_SQL_TO_CSV;
/


  CREATE OR REPLACE PROCEDURE "DBO"."REPLICATE_COIL_DATA" IS
--v_status integer;
--v_customer_id number(6,0);
--v_coil_abc_num NUMBER(6,0);
--v_coil_org_num varchar2(100);
--v_alloy2 varchar2(50);
--v_coil_temper varchar2
out_file  UTL_FILE.File_Type;
  CURSOR coil_cursor IS
  SELECT coil_abc_num,
	 customer_id,
	 coil_org_num,
	 coil_alloy2,
	 coil_temper
  FROM coil
  WHERE (customer_id=35 or customer_id =1153);-- and replicate <> 1;
  coil_rec coil_cursor%rowtype;
BEGIN
-- Beginning of the procedure

 -- SELECT coil_abc_num
--	  INTO v_coil_abc_num
--  FROM coil
--     WHERE (customer_id=35 or customer_id =1153) and replicate <> 1;
--	IF NOT SQL%FOUND THEN
--	   RETURN;
--	END IF;

    open coil_cursor;
    fetch coil_cursor into coil_rec;
    if coil_cursor%NOTFOUND THEN
    close coil_cursor;
    return;
    else
    close coil_cursor;
    end if;

--  v_status:=0;
  out_file:= UTL_FILE.FOPEN('/tmp','coil_info','w');


  for cur_record in coil_cursor loop
       UTL_FILE.PUT_LINE(out_file,to_char(cur_record.coil_abc_num)||','||to_char(cur_record.customer_id)||','
	 ||cur_record.coil_org_num||','
	 ||cur_record.coil_alloy2||','||cur_record.coil_temper||',');
  end loop;
     UTL_FILE.FFLUSH(out_file);
     UTL_FILE.FCLOSE(out_file);
  IF coil_cursor%ISOPEN THEN
	close coil_cursor;
      END IF;



   EXCEPTION
     WHEN UTL_FILE.INVALID_PATH THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
     WHEN UTL_FILE.INVALID_MODE THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN UTL_FILE.INVALID_OPERATION THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN UTL_FILE.WRITE_ERROR THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN;
    WHEN OTHERS THEN
     UTL_FILE.FCLOSE_ALL;
      RETURN;

END;
/


  CREATE OR REPLACE PROCEDURE "DBO"."SEND_MAIL"
(
   p_to        in  varchar2,
   p_from      in  varchar2,
   p_message   in  varchar2,
   p_smtp_host in  varchar2,
   p_smtp_port in  number default 25
)

as
   l_mail_conn	 UTL_SMTP.connection;

begin
  l_mail_conn := UTL_SMTP.open_connection(p_smtp_host, p_smtp_port);
  UTL_SMTP.helo(l_mail_conn, p_smtp_host);
  UTL_SMTP.mail(l_mail_conn, p_from);
  UTL_SMTP.rcpt(l_mail_conn, p_to);
  UTL_SMTP.data(l_mail_conn, p_message || UTL_TCP.crlf || UTL_TCP.crlf);
  UTL_SMTP.quit(l_mail_conn);

end send_mail;
/


  CREATE OR REPLACE PROCEDURE "DBO"."T_EDI_846_FOR_NOVELIS_KINGSTON" is
/*
This procedure creates EDI846 (Inventory Advice) for Novelis Kingston, which includes Novelis's coil information.
This procedure will be called from the cron job in the OS, runs periodically.
*/



  type edi_846_tabletype is table of varchar2(32767) index by binary_integer;
  edi_846 edi_846_tabletype;
  j binary_integer := 0;
  i integer := 0;
  edi_file_prefix VARCHAR2(50) := 'S_novelis_kingston_';

  li_customer_id int := 1153;	       --Novelis Kingston : 1153
				       --Novelis Oswego : 1459
  ls_duns varchar2(16) := '241003755'; --'241003755':Novelis Kingston's DUNS#
				       --'003980216':Novelis Oswego's DUNS#

  ls_coil_status varchar2(2);
  ls_skid_status varchar2(2);

  cursor coil_cursor is
  select c.coil_abc_num, c.coil_org_num, NVL(c.coil_mid_num, 'NA') coil_mid_num, NVL(c.part_num, 'NA') part_num, NVL(c.supplier_sales_num, 'NA') supplier_sales_num, NVL(c.purchase_order_num, 'NA') purchase_order_num,  c.net_wt_balance, c.coil_status
  from coil c
  where -- c.coil_status not in (0, 10) and
	c.coil_status in (1, 2, 3, 4, 7, 11) and    -- coil status: 0:Done; 1:InProcess; 2:New; 3:Rejected; 4:OhHold; 6:Returned; 7:Rebanded; 10:Gone;	11:QAOnHold
	c.customer_id = li_customer_id	 ;

  cursor skid_cursor is
  select psi.prod_item_num,
	 ss.sheet_skid_num,
	 psi.prod_item_net_wt,
	 ss.skid_sheet_status,
	(ss.sheet_net_wt + ss.sheet_tare_wt) skid_gross_wt,
	 c.coil_org_num, NVL(c.coil_mid_num, 'NA') coil_mid_num, NVL(c.part_num, 'NA') part_num, NVL(c.supplier_sales_num, 'NA') supplier_sales_num, NVL(c.purchase_order_num, 'NA') purchase_order_num
  from coil c, sheet_skid ss, production_sheet_item psi, sheet_skid_detail ssd
  where c.coil_abc_num = psi.coil_abc_num and
	psi.prod_item_num = ssd.prod_item_num and
	ssd.sheet_skid_num = ss.sheet_skid_num and
	ss.skid_sheet_status in (2, 4, 13) and	--Skid status: 2:Ready; 4:OnHold; 13:Partial Ready
	c.customer_id = li_customer_id	 ;


  /*cursor coil_cursor_donebutnotshipped is
  select distinct c.coil_abc_num, c.coil_org_num, NVL(c.coil_mid_num, 'NA') coil_mid_num, NVL(c.part_num, 'NA') part_num, NVL(c.supplier_sales_num, 'NA') supplier_sales_num, NVL(c.purchase_order_num, 'NA') purchase_order_num,  c.net_wt_balance, c.coil_status
  from coil c, sheet_skid ss, production_sheet_item psi, sheet_skid_detail ssd
  where c.coil_abc_num = psi.coil_abc_num and
	psi.prod_item_num = ssd.prod_item_num and
	ssd.sheet_skid_num = ss.sheet_skid_num and
	c.coil_status = 0 and	 -- coil status: 0:Done; 1:InProcess; 2:New; 3:Rejected; 4:OhHold; 6:Returned; 7:Rebanded  11:QAOnHold
	ss.skid_sheet_status <> 0 and
	c.customer_id = li_customer_id	 ;  */


  li_gs_log INTEGER;
  li_st_log INTEGER;
  ls_today_short VARCHAR2(20);
  ls_today VARCHAR2(20);
  ls_now VARCHAR2(20);

--  li_coil_abc_num coil.coil_abc_num%type;
--  ls_coil_org_num coil.coil_org_num%type;
--  ls_coil_mid_num coil.coil_mid_num%type;
--  ls_part_num coil.part_num%type;
--  ls_supplier_sales_num coil.supplier_sales_num%type;
--  ls_purchase_order_num coil.purchase_order_num%type;
--  li_total_skid_net_wt sheet_skid.sheet_net_wt%type;
--  li_total_skid_tare_wt sheet_skid.sheet_tare_wt%type;
--  li_total_net_wt coil.net_wt%type;
--  li_total_gross_wt coil.net_wt%type;

  edi_location varchar2(50):='/templar/templar/incoming/senddata';
  edi_file varchar2 (50) := 'edi_out.txt';
  edi_file_handle UTL_FILE.FILE_TYPE;

  li_coil_count int := 0;
  li_edi_846_id int;

begin

   SELECT EDI_ST_LOG_SEQ.NEXTVAL INTO li_st_log FROM dual;
   SELECT EDI_GS_LOG_SEQ.NEXTVAL INTO li_gs_log FROM dual;
   ls_today_short := to_char(SYSDATE, 'yymmdd');
   ls_today := to_char(SYSDATE, 'yyyymmdd');
   ls_now := to_char(SYSDATE, 'hh24mi');

   edi_846(j):= 'ISA*00*	  *00*		*01*039630926T	   *09*0015049350011G *'
    ||	ls_today_short	|| '*' ||  ls_now  || '*U*00401*' || LPAD(to_char(li_gs_log),9,'0') || '*0*T*:'; j := j + 1;
   edi_846(j):= 'GS*IB*039630926T*0015049350011G*' ||  ls_today  || '*' || ls_now || '*' || li_gs_log || '*X*004010'   ; j :=j + 1;
   edi_846(j):= 'ST*846*' || li_st_log ; j :=j + 1;
   edi_846(j):= 'BIA*00*IP*' || li_st_log || '*' || ls_today; j := j + 1;
   edi_846(j):= 'N1*OU**92*039630926'; j := j + 1;    --'039630926': ABCo's DUNS#
   edi_846(j):= 'N1*SU**92*'  ||  ls_duns; j := j + 1;

   for cloop in coil_cursor loop
    --Coils data

    edi_846(j):= 'LIN**PO*' || cloop.purchase_order_num || '*BP*' || cloop.part_num || '*IN*' || cloop.coil_abc_num || '*VN*' || cloop.coil_org_num || '*PK*' || cloop.coil_abc_num || '*VO*' || cloop.supplier_sales_num; j := j + 1;
    case cloop.coil_status
      when 1 then ls_coil_status := '7';
      when 2 then ls_coil_status := 'Q';
      when 3 then ls_coil_status := 'M';
      when 4 then ls_coil_status := '2';
      when 7 then ls_coil_status := '7';
      when 11 then ls_coil_status := '2';
    end case;	   -- 7: In process; Q: Not Scheduled; M: Return Material to Mill; 2: Hold for Inspection
    edi_846(j):= 'PID*S*MA*ST*' || ls_coil_status; j := j + 1;
    edi_846(j):= 'MEA*PD*N*' || cloop.net_wt_balance || '*LB'; j := j + 1;
    edi_846(j):= 'MEA*PD*G*' || cloop.net_wt_balance || '*LB'; j := j + 1;
    edi_846(j):= 'QTY*01*1'; j := j + 1;

    li_coil_count := li_coil_count + 1;
   end loop;

   for cloop_donebutnotshipped in skid_cursor loop
   /*for cloop_donebutnotshipped in coil_cursor_donebutnotshipped loop
    --Coils data

    select sum(ss.sheet_net_wt) into li_total_skid_net_wt
    from sheet_skid ss, sheet_skid_detail ssd, production_sheet_item psi
    where ss.sheet_skid_num = ssd.sheet_skid_num and
	  ssd.prod_item_num = psi.prod_item_num and
	  ss.skid_sheet_status <> 0 and
	  psi.coil_abc_num = cloop_donebutnotshipped.coil_abc_num;

    select sum(ss.sheet_tare_wt) into li_total_skid_tare_wt from sheet_skid ss, sheet_skid_detail ssd, production_sheet_item psi
    where ss.sheet_skid_num = ssd.sheet_skid_num and
	  ssd.prod_item_num = psi.prod_item_num and
	  ss.skid_sheet_status <> 0 and
	  psi.coil_abc_num = cloop_donebutnotshipped.coil_abc_num;

    edi_846(j):= 'LIN**PO*' || cloop_donebutnotshipped.purchase_order_num || '*BP*' || cloop_donebutnotshipped.part_num || '*IN*' || cloop_donebutnotshipped.coil_abc_num || '*VN*' || cloop_donebutnotshipped.coil_org_num || '*PK*' || cloop_donebutnotshipped.coil_abc_num || '*VO*' || cloop_donebutnotshipped.supplier_sales_num; j := j + 1;
    edi_846(j):= 'PID*S*MA*ST*8'; j := j + 1;	-- 8: processing complete
    edi_846(j):= 'QTY*01*1'; j := j + 1;
    li_total_net_wt := cloop_donebutnotshipped.net_wt_balance + li_total_skid_net_wt;
    edi_846(j):= 'MEA*PD*N*' || li_total_net_wt || '*LB'; j := j + 1;
    li_total_gross_wt := cloop_donebutnotshipped.net_wt_balance + li_total_skid_net_wt + li_total_skid_tare_wt;
    edi_846(j):= 'MEA*PD*G*' || li_total_gross_wt || '*LB'; j := j + 1;

    li_coil_count := li_coil_count + 1;   */

    edi_846(j):= 'LIN**PO*' || cloop_donebutnotshipped.purchase_order_num || '*BP*' || cloop_donebutnotshipped.part_num || '*IN*' || cloop_donebutnotshipped.prod_item_num || '*VN*' || cloop_donebutnotshipped.coil_org_num || '*PK*' || cloop_donebutnotshipped.sheet_skid_num || '*VO*' || cloop_donebutnotshipped.supplier_sales_num; j := j + 1;
    case cloop_donebutnotshipped.skid_sheet_status
      when 2 then ls_skid_status := '1';
      when 4 then ls_skid_status := '3';
      when 13 then ls_skid_status := '8';
    end case;	   --Skid status: 2:Ready; 4:OnHold; 13:Partial Ready
    edi_846(j):= 'PID*S*MA*ST*'  ||  ls_skid_status; j := j + 1;   -- 8: processing complete
    edi_846(j):= 'MEA*PD*N*' || cloop_donebutnotshipped.prod_item_net_wt || '*LB'; j := j + 1;
    edi_846(j):= 'MEA*PD*G*' || cloop_donebutnotshipped.skid_gross_wt || '*LB'; j := j + 1;
    edi_846(j):= 'QTY*01*1'; j := j + 1;

    li_coil_count := li_coil_count + 1;
   end loop;

   --edi_846(j):= 'CTT*' || li_coil_count; j := j + 1;
   edi_846(j):= 'SE*' || to_char(j-1) || '*' || li_st_log; j := j + 1;
   edi_846(j):= 'GE*1*' || li_gs_log; j := j + 1;
   edi_846(j):= 'IEA*1*' || LPAD(to_char(li_gs_log),9,'0');

   if li_coil_count > 0 then
     SELECT edi_file_id_seq.NEXTVAL INTO li_edi_846_id FROM DUAL;

-- Changed file suffix on 07/27/2016 to accomodate GXS change to SFTP - Patrick Reynolds
--   edi_file := 's_novelis_kingston_' || to_char(li_edi_846_id) || '.846';
     edi_file := edi_file_prefix || to_char(li_edi_846_id) || '.edi';

     edi_file_handle :=utl_file.fopen(edi_location,edi_file,'W');
     --write edi to file
     FOR i IN 0..j LOOP
	 utl_file.put_line(edi_file_handle,edi_846(i));
	 END LOOP;
     utl_file.fclose(edi_file_handle);

     -- for verifying 997
      INSERT INTO outbound_edi_transaction(edi_file_id,duns_from,duns_to,interchange_control_number,
      group_control_number,transaction_time,edi_file_name,fa_receive_status,customer_id,set_control_num,transaction_type_id)
      VALUES(li_edi_846_id,'039630926',ls_duns,li_gs_log,li_gs_log, sysdate, edi_file,0,li_customer_id,li_st_log,'846');
      COMMIT;

      edi_file := 'send_edi_log';
      edi_file_handle :=utl_file.fopen(edi_location,edi_file,'a');
      utl_file.put_line(edi_file_handle,'Type: 846');
      utl_file.put_line(edi_file_handle,'Sending Time: ' || to_char(sysdate, 'MM/DD/YY HH24:MI'));
      utl_file.put_line(edi_file_handle,'Interchange Control #: ' || li_gs_log);
      utl_file.put_line(edi_file_handle,'Group Control #: ' || li_gs_log);
      utl_file.put_line(edi_file_handle,'Set Control #: ' || li_st_log);
      utl_file.put_line(edi_file_handle,'');
      utl_file.put_line(edi_file_handle,'');
      utl_file.fclose(edi_file_handle);

      commit;
    end if;


  return;

  EXCEPTION
     WHEN dup_val_on_index then
     rollback;
     return ;
     WHEN UTL_FILE.INVALID_PATH THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
     WHEN UTL_FILE.INVALID_MODE THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
    WHEN UTL_FILE.INVALID_OPERATION THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
    WHEN UTL_FILE.WRITE_ERROR THEN
      UTL_FILE.FCLOSE_ALL;
      RETURN ;
    WHEN OTHERS THEN
     UTL_FILE.FCLOSE_ALL;
      RETURN ;
end t_edi_846_for_novelis_kingston;
/


  CREATE OR REPLACE PROCEDURE "DBO"."UPDATE_COIL_FROM_PROCESS_COIL" is

CURSOR c_coil_abc_num is
SELECT c.COIL_ABC_NUM, p.ab_job_num
FROM PROCESS_COIL p, COIL c
WHERE c.COIL_ABC_NUM  = p.COIL_ABC_NUM
AND c.COIL_STATUS <> 0
AND p.PROCESS_COIL_STATUS = 0;

ll_coil_abc_num long;
li_coil_status int;
li_system_log_key_num int;
begin

for c_coil_abc_num_rec in c_coil_abc_num loop
	-- update coil status to 'DONE'
	UPDATE COIL
	SET COIL.NET_WT_BALANCE = 0, COIL.COIL_STATUS = 0
	WHERE COIL.COIL_ABC_NUM = c_coil_abc_num_rec.coil_abc_num;
	--log record
	SELECT system_log_id_seq.NEXTVAL INTO li_system_log_key_num FROM dual;
	insert into system_log(system_log_key_num, system_log_timestamp, system_log_contents)
	values (li_system_log_key_num, sysdate, 'Update_coil_from_process_coil procedure run on ' || sysdate || ' for Coil# ' || ll_coil_abc_num || ' in Job# ' ||
      c_coil_abc_num_rec.ab_job_num);
end loop;
commit;

end update_coil_from_process_coil;
/


  CREATE OR REPLACE PROCEDURE "DBO"."UPDATE_SCRAP_FROM_WORKSHEET" (coil_num  in coil.coil_abc_num%type) is
       cursor cur_worksheet is
	      SELECT COIL_ABC_NUM,
		     AB_JOB_NUM,
		     SCRAP_ITEM_TYPE,
		     SCRAP_ITEM_OD,
		     SCRAP_ITEM_MILL,
		     SUM(SCRAP_ITEM_PIECE) tot_scrap_pcs,
		     SUM(SCRAP_ITEM_NET_WT) tot_scrap_nw
	      FROM QUALITY_SCRAP_WORKSHEET
	      WHERE COIL_ABC_NUM = coil_num
	      GROUP BY COIL_ABC_NUM, AB_JOB_NUM, SCRAP_ITEM_TYPE, SCRAP_ITEM_OD, SCRAP_ITEM_MILL;
begin
  delete quality_coil_eval_scrap
   where quality_coil_eval_scrap.coil_abc_num = coil_num ;
  FOR ws_rec IN cur_worksheet LOOP
      insert into quality_coil_eval_scrap
		    (coil_abc_num,
		     ab_job_num,
		     scrap_item_type,
		     scrap_item_piece,
		     scrap_item_net_wt,
		     scrap_item_od,
		     scrap_item_mill)
      values
	(coil_num, ws_rec.ab_job_num, ws_rec.scrap_item_type, ws_rec.tot_scrap_pcs, ws_rec.tot_scrap_nw,
	 ws_rec.scrap_item_od, ws_rec.scrap_item_mill );
  END LOOP;
  commit;
end UPDATE_SCRAP_FROM_WORKSHEET;
/


  CREATE OR REPLACE PROCEDURE "DBO"."UPDATE_SCRAP_SKID_FROM_QUALITY" (coil_num	in coil.coil_abc_num%type,
							   shift_num in shift.shift_num%type) is
  li_i	     integer;
  skid_num   scrap_skid.scrap_skid_num%type;
  job_num    ab_job.ab_job_num%type;
  item_count integer;
  item_num   integer;
  skid_nw_sum integer;
  Cursor cur_skid IS
    SELECT DISTINCT SCRAP_SKID_NUM
      FROM QUALITY_SCRAP_WORKSHEET
     WHERE COIL_ABC_NUM = coil_num
       and SCRAP_SKID_NUM is not null;
  CURSOR cur_skid_job(c_skid integer) is
    Select DISTINCT ab_job_num
      FROM quality_scrap_worksheet
     WHERE scrap_skid_num = c_skid;
  pcs_job    integer;
  net_wt_job integer;

begin

  FOR skid_rec IN cur_skid LOOP
    skid_num := skid_rec.SCRAP_SKID_NUM;
    FOR job_rec in cur_skid_job(skid_num) loop
      job_num := job_rec.ab_job_num;
      select sum(scrap_item_piece), sum(scrap_item_net_wt)
	into pcs_job, net_wt_job
	from quality_scrap_worksheet
       where coil_abc_num = coil_num
	 and ab_job_num = job_num
	 and scrap_skid_num = skid_num;

      select count(*)
	into item_count
	from return_scrap_item, scrap_skid_detail
       where return_scrap_item.coil_abc_num = coil_num
	 and return_scrap_item.ab_job_num = job_num
	 and scrap_skid_detail.return_scrap_item_num =
	     return_scrap_item.return_scrap_item_num
	 and scrap_skid_detail.scrap_skid_num = skid_num;

      if item_count = 1 THEN
	select scrap_skid_detail.return_scrap_item_num
	  into item_num
	  from return_scrap_item, scrap_skid_detail
	 where return_scrap_item.coil_abc_num = coil_num
	   and return_scrap_item.ab_job_num = job_num
	   and scrap_skid_detail.return_scrap_item_num =
	       return_scrap_item.return_scrap_item_num
	   and scrap_skid_detail.scrap_skid_num = skid_num;

	update return_scrap_item
	   set return_scrap_item.return_item_net_wt = net_wt_job,
	       return_scrap_item.scrap_item_pieces  = pcs_job,
	       return_scrap_item.return_item_date   = sysdate,
	       return_scrap_item.shift_num	    = shift_num
	 where return_scrap_item.return_scrap_item_num = item_num;

      else
	-- if not do insert
	select return_scrap_item_id_seq.nextval into item_num from dual;
	insert into return_scrap_item
	  (return_scrap_item.return_scrap_item_num,
	   return_scrap_item.coil_abc_num,
	   return_scrap_item.ab_job_num,
	   return_scrap_item.return_item_net_wt,
	   return_scrap_item.return_item_date,
	   return_scrap_item.return_item_notes,
	   return_scrap_item.scrap_item_pieces,
	   return_scrap_item.shift_num)
	values
	  (item_num,
	   coil_num,
	   job_num,
	   net_wt_job,
	   sysdate,
	   'DAS',
	   pcs_job,
	   shift_num);

	insert into scrap_skid_detail
	  (scrap_skid_detail.scrap_skid_num,
	   scrap_skid_detail.return_scrap_item_num)
	values
	  (skid_num, item_num);
	li_i := 0;
      end if;
    end loop;
    --To do list update skid netwt from all items
    select SUM(return_scrap_item.return_item_net_wt)
      into skid_nw_sum
      from return_scrap_item, scrap_skid_detail
     where return_scrap_item.return_scrap_item_num = scrap_skid_detail.return_scrap_item_num and
	   scrap_skid_detail.scrap_skid_num = skid_num ;
    update scrap_skid
       set scrap_skid.scrap_net_wt = skid_nw_sum
     where scrap_skid.scrap_skid_num = skid_num;

    commit;
  END LOOP;
end UPDATE_SCRAP_SKID_FROM_QUALITY;
/


  CREATE OR REPLACE PROCEDURE "DBO"."UPDATE_SHEET_SKID_WT" (skid_id in sheet_skid.sheet_skid_num%type, new_wt in sheet_skid.sheet_net_wt%type ) is
--skid_old_wt sheet_skid.sheet_net_wt%type;
item_wt production_sheet_item.prod_item_net_wt%type;
item_num production_sheet_item.prod_item_num%type;

begin
  --select NVL(sheet_skid.sheet_net_wt,0) into skid_old_wt
  --FROM SHEET_SKID
  --WHERE sheet_skid.sheet_skid_num = skid_id;

  SELECT MAX( SHEET_SKID_DETAIL.PROD_ITEM_NUM ) into item_num
  FROM SHEET_SKID_DETAIL
  WHERE SHEET_SKID_DETAIL.SHEET_SKID_NUM = skid_id;

  SELECT NVL(SUM(production_sheet_item.prod_item_net_wt), 0 ) into item_wt
  FROM production_sheet_item
  WHERE (production_sheet_item.prod_item_num in
  ( SELECT sheet_skid_detail.prod_item_num
    FROM sheet_skid_detail
    WHERE sheet_skid_detail.sheet_skid_num = skid_id)) and
    (production_sheet_item.prod_item_num <> item_num) ;

    update sheet_skid
    set sheet_skid.sheet_net_wt = new_wt
    where sheet_skid.sheet_skid_num = skid_id;
    item_wt := new_wt - item_wt;

    update production_sheet_item
    set production_sheet_item.prod_item_net_wt = item_wt
    where production_sheet_item.prod_item_num = item_num ;

    commit;

end UPDATE_SHEET_SKID_WT;
/


  CREATE OR REPLACE PROCEDURE "DBO"."UPDATE_SHIFT_COIL" (coil_num  in coil.coil_abc_num%type, shift_num in shift.shift_num%type) is
       job_num	  ab_job.ab_job_num%type;
       skid_wt sheet_skid.sheet_net_wt%type;
       scrap_wt sheet_skid.sheet_net_wt%type;
       process_w sheet_skid.sheet_net_wt%type;
       CURSOR cur_job is
       Select DISTINCT ab_job_num
	      FROM shift_coil
	      WHERE shift_coil.shift_num = shift_num and
		    shift_coil.coil_abc_num = coil_num ;

begin
  --job_num    ab_job.ab_job_num%type;
  skid_wt := 0;
  scrap_wt := 0;
  FOR job_rec in cur_job loop
      job_num := job_rec.ab_job_num;
      select NVL(sum( production_sheet_item.prod_item_net_wt ),0) into skid_wt
      from production_sheet_item
      where production_sheet_item.ab_job_num = job_num and
	    production_sheet_item.coil_abc_num = coil_num and
	    production_sheet_item.shift_num = shift_num;
      select NVL(sum( return_scrap_item.return_item_net_wt ),0) into scrap_wt
      from return_scrap_item
      where return_scrap_item.ab_job_num = job_num and
	    return_scrap_item.coil_abc_num = coil_num and
	    return_scrap_item.shift_num = shift_num;
      process_w := skid_wt + scrap_wt;
      update shift_coil
      set shift_coil.process_wt = process_w
      where shift_coil.shift_num = shift_num and
	    shift_coil.ab_job_num = job_num and
	    shift_coil.coil_abc_num = coil_num;
  End loop;
  commit;
end update_shift_coil;
/


  CREATE OR REPLACE TRIGGER "DBO"."COIL_HISTORY_LOG"
  after update on coil
  for each row

declare
  -- local variables here
  li_coil integer;
  li_job integer;
  --li_shift_coil integer;
  counts integer;
  li_err_seq integer;
  li_line_num integer;
  cursor distinct_job_cursor(li_coil_id integer ) is
	 SELECT DISTINCT PRODUCTION_SHEET_ITEM.AB_JOB_NUM, AB_JOB.LINE_NUM
	 FROM PRODUCTION_SHEET_ITEM, AB_JOB
	 WHERE PRODUCTION_SHEET_ITEM.AB_JOB_NUM = AB_JOB.AB_JOB_NUM and COIL_ABC_NUM = li_coil_id and AB_JOB.LINE_NUM in (6,7);

begin
  if (:new.coil_status != :old.coil_status or :new.net_wt_balance != :old.net_wt_balance ) then
     insert into coil_track (coil_abc_num,coil_track_date,
	    coil_pre_status, coil_cur_status, coil_pre_netwt,
	    coil_cur_netwt, coil_modified_by, coil_pre_location, coil_cur_location)
	    values (:old.coil_abc_num, sysdate, :old.coil_status, :new.coil_status, :old.net_wt_balance, :new.net_wt_balance, USER,'','');
       if ( :new.coil_status != :old.coil_status and :new.coil_status = 0 ) then
	  li_coil := :new.coil_abc_num;
	  FOR c_job IN distinct_job_cursor(li_coil ) LOOP
	      li_job := c_job.ab_job_num;
	      li_line_num := c_job.line_num;

	      SELECT COUNT(*) INTO counts
	       FROM shift_coil
	       WHERE shift_coil.ab_job_num = li_job and shift_coil.coil_abc_num = li_coil;
	      if counts < 1 then
		 SELECT error_evt_seq.nextval INTO li_err_seq from dual;
		 INSERT INTO error_evt (error_evt_id, evt_time, error_type_id, error_user,error_comment, line_id, shift_id, coil_abc_num, ab_job_num, sheet_skid_num, scrap_skid_num, dt_instance_num, opc_item, title, message, script, line_in_script, db_error_code,db_error_text )
		 values(li_err_seq, sysdate, 1, 'dbo', 'DAS operator missed job or coil', li_line_num,null,li_coil,li_job,null,null,null,null,null,null,null,null,null,null  );
	      end if;
	  END LOOP;
       end if;
  end if;
  --commit;
end coil_history_log;

/
ALTER TRIGGER "DBO"."COIL_HISTORY_LOG" ENABLE;


